\title{Random Variables, Conditional Independence and Categories of Abstract Sample Spaces}

\author{\IEEEauthorblockN{Dario Stein}
\IEEEauthorblockA{\textit{iHub}, \textit{Radboud Universiteit Nijmegen}\\
Nijmegen, The Netherlands \\
ORCID 0009-0002-1445-4508}
