\item \emph{relative positivity}: if $f : A \to X \otimes Y$ has a $p$-almost surely deterministic marginal, then $f \ase{p} \langle \pi_X \circ f, \pi_2 \circ f \rangle$
\end{enumerate}

\subsection{Probability Spaces, Couplings, Sample Spaces}

\noindent Let $\C$ be a Markov category with conditionals. 

\begin{definition}[Probability spaces]
We define the category $\P(\C)$ of probability spaces as follows
\begin{enumerate}
	\item A \emph{probability space} in $\C$ is a pair $\sp \Omega = (\Omega,p)$ of an object $\Omega$ and a state $p : I \to \Omega$
	\item  A morphism of probability spaces $(\Omega,p) \to (\Omega',q)$ is an equivalence class $[f]_p$ of morphisms $f : \Omega \to \Omega'$, up to $p$-almost sure equality, which preserve the state, i.e. satisfy $f \circ p = q$.
	\item Composition is composition in $\C$ on representatives, which is well-defined because $[f]_{gp} \circ [g]_p = [f \circ g]_p$.
\end{enumerate}
\end{definition}

\noindent In abstract terms, almost sure equality defines a congruence relation on the slice category $I/\C$, and $\P(\C)$ the quotient under this congruence. By slight abuse of notation, we will simply write $f$ instead of $[f]$. The construction $\P(\C)$ is known under the names $\catname{ProbStoch}(\C)$, $\catname{PS}$, or $\mathcal S$ in \cite{fritz2019synthetic,ensarguet2023categorical,parzygnat2023axioms}. 

Central to our development is the subcategory $\S(\C)$ of $\P(\C)$ where morphisms are restricted to the almost surely deterministic ones. This category has not been named in the literature, and we will call it \emph{sample spaces} here. Thus while `probability space' and `sample space' are synonymous for objects $(\Omega,p)$, not every morphism of probability spaces is a morphism of sample spaces. 

\begin{definition}[Sample spaces]
The category of sample spaces is defined as the wide subcategory $\S(\C) \subseteq \P(\C)$ consisting of the morphisms $f : (\Omega,p) \to (\Omega',q)$ which are $p$-almost surely deterministic. 
\end{definition}

\noindent For brevity, when speaking about morphisms of probability spaces, we will shorten `$p$-almost surely deterministic' to `deterministic' (as the $p$ can be read off from the domain probability space). We will also refer to those morphisms as \emph{maps} of sample spaces, as opposed to \emph{channels} which may be nondeterministic (i.e. lie in $\P(\C)$). We will now establish some basic structural properties of the categories $\P(\C)$ and $\S(\C)$ which will be of constant use in what follows. 

\begin{proposition}[\!\!\!{\cite[Section~13]{fritz2019synthetic}}]
The category $\P(\C)$ is semicartesian monoidal with $(X,p) \otimes (Y,q) = (X \otimes Y, p \otimes q)$. Bayesian inversion $f \mapsto f^\dagger$ is a contravariant involutive functor on $\P(\C)$ making it a dagger category (e.g. \cite{karvonen2019way})
\end{proposition}

\noindent In particular, the chain rule for Bayesian inversion
\[ (g \circ f)^\dagger_p \,\ase{gfp}\, f^\dagger_p \circ g^\dagger_{fp} \]
simplifies to mere contravariance $(g \circ f)^\dagger = f^\dagger \circ g^\dagger$ when formulated in the category $\P(\C)$. We recall some terminology in dagger categories: A morphism $f : X \to Y$ is called
\begin{itemize}
\item an \emph{isometry} if $f^\dagger \circ f = \id_X$ 
\item a \emph{co-isometry} if $f \circ f^\dagger = \id_Y$
\item \emph{unitary} if it is both isometry and co-isometry (it is an isomorphism with $f^{-1} = f^\dagger$).
\end{itemize}
An equivalence of dagger categories (dagger equivalence) consists of dagger-preserving functors and natural isomorphisms $FG \cong 1$, $GF \cong 1$ with unitary components \cite{karvonen2019way}.

It is well-known that $\P(\C)$ is dagger equivalent to the category of \emph{couplings} (sometimes \emph{kernels}, \emph{joint distributions}) where morphisms $(X,p) \to (Y,q)$ are states $\gamma : I \to X \otimes Y$ with $\pi_1 \circ \gamma = p$ and $\pi_2 \circ \gamma = q$ \cite[Remark~12.10]{fritz2019synthetic}. The dagger on couplings is given by composing with the swap isomorphism $\gamma \mapsto \sigma_{X,Y} \circ \gamma$. 

\begin{proposition}\label{prop:det_coiso}
The following are equivalent for a morphism $f$ in $\P(\C)$
\begin{enumerate}
\item $f$ is deterministic
\item $f$ is a co-isometry, i.e. satisfies $f \circ f^\dagger = \id$
\item $f$ is split epic 
\end{enumerate}
Furthermore, if $f \circ g$ is deterministic, so is $f$. 
\end{proposition}
\begin{proof}
The equivalence of the first two statements is \cite[Proposition~2.5]{ensarguet2023categorical}, and co-isometries are split epic. The statement $f \circ g$ deterministic $\Rightarrow$ $f$ deterministic is precisely \cite[Remark~13.17]{fritz2019synthetic}. In particular, if $f$ is split epic then $f \circ g = \id$ is deterministic, so $f$ is deterministic.
\end{proof}

It follows that $\S(\C)$ can be identified as the subcategory of co-isometries of $\P(\C)$. By the last point, every isomorphism in $\P(\C)$ is unitary and deterministic, hence lies in $\S(\C)$: That means if two probability spaces are isomorphic, they are also isomorphic \emph{as sample spaces}. 

\begin{proposition}\label{prop:sc_monic}
The category $\S(\C)$ is semicartesian monoidal. Every morphism in $\S(\C)$ is epic. The canonical projections $\sp X \leftarrow \sp X \otimes \sp Y \rightarrow \sp Y$ are jointly monic. 
\end{proposition}

\begin{example}\label{ex:extension}
The projection map $\pi_1 : (X \otimes Y,p) \to (X,p_X)$ serves as our prototypical intuition for a map of sample spaces. We can think of it as describing a consistent \emph{extension} of the sample space $(X,p_X)$ to a larger sample space (this perspective is important in Section~\ref{sec:sheaves}).
\end{example}

\noindent In contrast to Proposition~\ref{prop:sc_monic}, the canonical projections are generally \emph{not} jointly monic in $\P(\C)$. This can however be remedied for channels that have a deterministic marginal:

\begin{lemma}\label{lem:relpos} 
In a commuting diagram in $\P(\C)$, 
% https://q.uiver.app/#
\[\begin{tikzcd}
	&& {\sp \Omega} \\
	\\
	{\sp Y} && {\sp X \otimes \sp Y} && {\sp X}
	\arrow["g"', curve={height=12pt}, from=1-3, to=3-1]
	\arrow[shift right, from=1-3, to=3-3]
	\arrow["{\phi,\psi}", shift left, from=1-3, to=3-3]
	\arrow["f", curve={height=-12pt}, from=1-3, to=3-5]
	\arrow["{\pi_2}"', from=3-3, to=3-1]
	\arrow["{\pi_1}", from=3-3, to=3-5]
\end{tikzcd}\]
if either $f$ or $g$ is deterministic, then $\phi = \psi$. 
\end{lemma}
\begin{proof}
This is an application of relative positivity. The maps $\phi$ has a deterministic marginal $f$, hence it is almost surely equal to the tupling of its marginals, i.e. $\phi \ase{\stat{\Omega}} \langle f,g \rangle$. The same is true for $\psi$, $\phi \ase{\stat{\Omega}} \psi$. 
\end{proof}

\section{Examples}\label{sec:examples}

\noindent We will now recover concrete descriptions of the categories $\P(\C)$ and $\S(\C)$ for our example Markov categories, up to equivalence of (dagger) categories. An important aid is Proposition~\ref{prop:faithful}, which enables us to drop almost sure equivalence classes in many cases.

\begin{definition}
A probability space $(\Omega,p)$ is \emph{faithful} if for all $f,g : \Omega \to X$, $f \ase p g$ implies $f = g$. 
\end{definition}
\noindent We consider the full subcategories $\P_f(\C)$ and $\S_f(\C)$ whose objects are faithful probability spaces. Those are considerably easier to work with, as we no longer need to take equivalence classes of morphisms, and almost sure determinism coincides with plain determinism.

\begin{proposition}\label{prop:faithful}
The following are equivalent
\begin{enumerate}
\item every probability space is isomorphic to a faithful one
\item the inclusions $\P_f(\C) \to \P(\C)$ and $\S_f(\C) \to \S(\C)$ are part of an equivalence of (dagger) categories
\item every state $p : I \to X$ has a \emph{split support} in the sense of \cite{fritz2023absolute,stein2021structural}, i.e. there are morphisms $i : S \to X$, $\pi : X \to S$ such that
\begin{itemize}
\item $\pi i = \id_S$
\item $i \pi \ase{p} \id_X$
\item for all $f,g : X \to Y$, $f \ase{p} g \Leftrightarrow fi=gi$
\end{itemize}
\end{enumerate}
\end{proposition}
\begin{proof}
In Section~\ref{app:markov}.
\end{proof}

\noindent The `support-inclusion' $i : S \to X$ identifies the support of the distribution $p$, in the sense that $p$-almost sure equality can be tested by pulling back along $i$. A probability space is faithful if its distribution is supported on all of $X$. 

All our example categories except $\borelstoch$ are known to have split supports of states \cite{fritz2023absolute}; in those cases, we obtain the following descriptions:

\begin{proposition}[Discrete probability]\phantom{We have}
\begin{enumerate}
\item A probability space $(\Omega,p)$ in $\finstoch$ is faithful iff $p(\omega) > 0$ for all $\omega \in \Omega$
\item The category $\P(\finstoch)$ is dagger equivalent to the category of faithful probability spaces $(\Omega,p)$, where morphisms are stochastic matrices preserving the state. This was known as $\mathscr S^+(\catname{FinStoch})$ in \cite{parzygnat2024reversing}.
\item  The category $\S(\finstoch)$ is equivalent to $\catname{FinProb}$ of \cite{simpson:independence}: objects are faithful probability spaces, and morphisms $(\Omega,p) \to (\Omega',q)$ are (necessarily surjective) functions $f : \Omega \to \Omega'$ with
\[ q(\omega') = \sum_{\omega \in f^{-1}(\omega')} p(\omega) \]
\end{enumerate}
\end{proposition}

\begin{proposition}[Nondeterminism]\phantom{We have}
	\begin{enumerate}
		\item A sample space $(X,R)$ with $\emptyset \neq R \subseteq X$ in $\setmulti$ is faithful iff $R=X$. 
		\item The category $\P(\setmulti)$ is dagger equivalent to the category $\catname{TotRel}$ of nonempty sets and total relations. Dagger is the relational converse.
		\item The category $\S(\setmulti)$ is equivalent to the category $\surj$ of nonempty sets and surjections \cite{simpson:independence}.
	\end{enumerate}
\end{proposition}

\noindent For Gaussian probability, we obtain an elegant characterization of sample spaces in terms of the following concepts of linear algebra. Recall that a matrix $A \in \R^{n \times m}$ is called
\begin{enumerate}
\item an \emph{isometry} if $||Ax||=||x||$ for all $x \in \R^m$ where $||-||$ is Euclidean distance. Equivalently, $A^TA=I_m$.
\item a \emph{co-isometry} if $A^T$ is an isometry (i.e. $AA^T = I_n$)
\item a \emph{contraction} if $||Ax|| \leq ||x||$ for all $x \in \R^m$. 
\end{enumerate}
Isometries, co-isometries and contractions form respective subcategories $\iso,\coiso,\con$ of the category $\catname{Mat}$ whose objects are natural numbers and morphisms are matrices. Transposition defines an isomorphism $\iso^\op \cong \coiso$, and a $\dagger$-structure on $\con$.

\begin{proposition}[Gaussian probability]\label{prop:s_gauss} \phantom{We have}
\begin{enumerate}
\item A sample space $(\R^n,\mathcal N(\mu,\Sigma))$ in $\gauss$ is faithful iff $\Sigma$ has full rank, i.e. is positive definite. Every such sample space is isomorphic to a \emph{standard sample space} of the form $(\R^n, \mathcal N(0,I_n))$ by means of Cholesky decomposition, i.e. a factorization $\Sigma = LL^T$.
\item The category $\P(\gauss)$ is dagger equivalent to $\con$.
\item The category $\S(\gauss)$ is equivalent to $\coiso$. 
\end{enumerate}
\end{proposition}
\begin{proof}[Proof sketch]
Because of state preservation, a measure preserving Gaussian channel between standard sample spaces $(\R^m,\N(0,I_m)) \to (\R^n,\N(0,I_n))$ is a tuple $(A,0,\Sigma)$ with $AA^T + \Sigma = I_n$. This condition is equivalent to $A$ being a contraction, and the channel is deterministic iff $\Sigma = 0$, i.e. $AA^T = I_n$, meaning $A$ is a coisometry. The full proof is elaborated in Section~\ref{sec:gaussian}.
\end{proof}


\begin{proposition}[Fresh name generation]\phantom{We have}
\begin{enumerate}
\item A sample space $(X,W)$ in $\strongname$ consists of a strong nominal set $X$ and an orbit $W \subseteq X$. The sample space is faithful iff $W = X$
\item Each sample space is isomorphic to one of the form $(\rep n, \rep n)$ for $n \in \mathbb N$
\item The category $\S(\strongname)$ is equivalent to $\inj^\op$, the opposite category of finite sets and injections.
\end{enumerate}
\end{proposition}
\begin{proof}
Elaborated in Section~\ref{sec:nom}.
\end{proof}

\noindent We remark that in $\borelstoch$, not every sample space is isomorphic to a faithful one, so we don't obtain a simplified description via Proposition~\ref{prop:faithful}. We simply work with the definition of $\S(\borelstoch)$ as-is. We remark that $\S(\borelstoch)$ is equivalent to the category $\mathbb{SBP}_0$ considered by Simpson in \cite{simpson:atomic}. The latter category is defined slightly differently, and the two definition can be shown equivalent because $\borelstoch$ is \emph{a.s.-compatibly representable} in the sense of \cite{fritz2023representable}.

\section{The Independence Structure on Sample Spaces}\label{sec:independence_structure}

\noindent Now that we have introduced and characterized categories of sample spaces $\S(\C)$, we can study notions of conditional independence on them. We will recall Simpson's axioms for independent pullbacks, show that they apply to our categories $\S(\C)$, and recover the independence structures given in the examples in \cite{simpson:independence}. The independence structure will play a crucial role when using $\S(\C)$ as a site for probability sheaves in Section~\ref{sec:sheaves}.

