\section{Probability Sheaves and Random Variables}\label{sec:sheaves}

We can now begin to recreate Simpson's treatment of probability sheaves \cite{simpson2017probability,simpson:atomic} in our abstract setup. As before, $\C$ is a Markov category with conditionals, and $\S(\C)$ its category of sample spaces.

A \emph{probability presheaf} is a functor $P : \S(\C)^\op \to \set$. Concretely such a presheaf $P$ consists of a family of sets $P(\sp \Omega)$ indexed over sample spaces. If $\pi : \sp{\Omega'} \to \sp{\Omega}$ is a morphism in $\S(\C)$ and $x \in P(\sp \Omega)$ is an element, then we denote the functorial action of $P$ as 
\[ x \cdot \pi \defeq P(\pi)(x) \in F(\sp \Omega') \]
In accordance with Example~\ref{ex:extension}, we can see this action as an extension of the element $x$ to the larger sample space $\sp{\Omega'}$. A morphism of presheaves $f : P \to Q$ is a natural transformation; the naturality condition says that $f$ is equivariant with respect to the extension action: for all $x \in P(\sp \Omega)$ and $\pi : \sp{\Omega'} \to \sp{\Omega}$ we have $f_{\sp{\Omega'}}(x \cdot \pi) = f_{\sp \Omega}(x) \cdot \pi$. We write $\psh(\S(\C))$ for the topos of probability presheaves. 

\subsection{Presheaf of Random Elements}

\noindent For any set $A$, we write $\disc{A}$ for the constant presheaf with $\disc{A}(\sp{\Omega}) = A$. Unlike constant presheaves, the notion of \emph{random element} depends on the underlying sample space $\sp{\Omega}$. We formalize this as follows:

\begin{definition}
For each object $V$ of $\C$, we define a presheaf $\rv(V) : \S(\C)^\op \to \set$ of \emph{random elements} valued in $V$, as 
\begin{enumerate}
\item $\rv(V)(\Omega,p) \defeq \{ [X] : \Omega \to V \emph{ $p$-a.s. det } \}$ consists of $p$-almost sure equivalence classes of $p$-almost-surely deterministic morphisms in $\C$. 
\item the extension action is given by precomposition on representatives. If $X : \Omega \to V$ and $\pi : \sp{\Omega'} \to \sp{\Omega}$, then
\[ [X] \cdot \pi \defeq [X \circ \pi] \]
\end{enumerate}
\end{definition}

\begin{example}
For our example categories, the presheaves of random elements take the following simple forms
\begin{enumerate}
\item for $V \in \finstoch$, $\Omega \in \catname{FinProb}$, 
\[ \rv(V)(\sp{\Omega}) \cong \{ X : \Omega \to V \text{ any function } \} \]
\item for $V \in \setmulti$, $\Omega \in \surj$,
\[ \rv(V)(\Omega) \cong \{ X : \Omega \to V \text{ any function } \} \] 
\item for $V \in \borelstoch$, $\sp \Omega \in \S(\borelstoch)$,
\[ \rv(V)(\sp{\Omega}) \cong \{ X : \Omega \to V \text{ measurable } \} \]
\item for $\R^n \in \gauss$, $\R^m \in \coiso$,
\[ \rv(\R^n)(\R^m) \cong \{ X : \R^m \to \R^n \text{ affine-linear } \} \] 
\item for $V \in \strongname$, $K \in \catname{FinInj}^\op$, 
\[ \rv(V)(K) \cong \{ f : \rep{K} \to V \text{ equivariant } \}\]
\end{enumerate}
\end{example}

\begin{example}
We have a well-defined natural transformation $\mathrm{Law} : \rv(V) \to \disc{\C(I,V)}$ which assigns a random element $[X] : \Omega \to V$ to its law, by $\mathrm{Law}_{\sp \Omega}([X]) = X \circ p_{\Omega}$.
\end{example}

\noindent The presheaf $\rv(V)$ is closely related to the representable presheaves on $\S(\C)$: If $\sp{\Omega'}$ is a sample space, then $\y(\sp{\Omega'}) = \S(\C)(-,\sp{\Omega'})$ is a sub-presheaf of $\rv(\Omega')$ consisting of those random elements whose law is equal to $p_{\Omega'}$. Conversely, $\rv(V)$ is isomorphic to the coproduct of representables
\[ \rv(V) \cong \bigsqcup_{p : I \to V} \S(\C)(-, (V,p)) \]

\begin{proposition}
The random element construction defines a functor $\rv : \C_\det \to \psh(\S(\C))$ where $\C_\det \subseteq \C$ is the subcategory of deterministic morphisms. For $h : V \to W$ deterministic we define the natural transformation
\[ \rv(h) : \rv(V) \to \rv(W), \quad \rv(h)([X])_{\sp \Omega} \defeq [h \circ X] \]
\noindent Furthermore the tensor product on $\C_{\det}$ is a cartesian product, and the $\rv$ functor preserves it
\[ \rv(U \otimes V) \cong \rv(U) \times \rv(V) \]
\end{proposition}

\subsection{Sheaf Conditions}

\noindent In this section, we will show that the presheaves $\rv(V)$ and $\S(\C)(-,\sp{\Omega})$ are always \emph{sheaves} with respect to the \emph{atomic topology} on $\S(\C)$. This makes the Grothendieck topos of atomic sheaves $\sh(\S(\C))$ a natural setting for categorical probability. Sheaf conditions guarantee a well-behaved interplay between the values that a presheaf $P$ takes on different sample spaces $\sp{\Omega}$, and are intimately related with the independence structure (Propositions~\ref{prop:sheaf_pullback}, \ref{prop:sheaf_pushout}). Simpson has extensively studied the logical structure of atomic sheaves and their relationship with independence in \cite{simpson:atomic}.

Here, we will only introduce what is strictly needed about atomic topologies, following \cite{simpson:atomic}. For a general introduction to sheaf toposes, we refer to \cite{maclane2012sheaves}. The atomic topology is the Grothendieck topology where every singleton family $\{ \sp{\Omega'} \xrightarrow{\pi} \sp{\Omega} \}$ is covering. For this topology to be well-defined, one requires the \emph{right Ore condition}: every cospan can be completed to a commuting square. We have established this for $\S(\C)$ in (IP5). 

Let $P : \S(\C)^\op \to \set$ be a presheaf and $\pi : \sp{\Omega'} \to \sp{\Omega}$ be map in $\S(\C)$. An element $y \in P(\sp{\Omega'})$ is called $\pi$-invariant if for any parallel pair of maps $\rho, \rho' : \sp{\Omega''} \to \sp{\Omega'}$ with $\pi \circ \rho = \pi \circ \rho'$, we have $y \cdot \rho = y \cdot \rho'$.

\begin{definition}
A presheaf $P \in \psh(\S(\C))$ is \emph{separated} if for all $\pi : \sp{\Omega'} \to \sp{\Omega}$ and $x,y \in P(\sp{\Omega})$, if $x \cdot \pi = y \cdot \pi$ then $x=y$. 
\end{definition}

\begin{definition}
A presheaf $P \in \psh(\S(\C))$ is an \emph{atomic sheaf} if for every map $\pi : \sp{\Omega'} \to \sp{\Omega}$ and every $\pi$-invariant $y \in P(\sp{\Omega'})$, there is a unique $x \in P(\sp{\Omega})$ with $y = x \cdot \pi$. 
\end{definition}

\begin{proposition}
The presheaves $\rv(V)$ and $\y(\sp{\Omega'})$ are separated. 
\end{proposition}
\begin{proof}
Let $X,Y : \sp{\Omega} \to V$ be almost surely deterministic and let $\pi : \sp{\Omega'} \to \sp{\Omega}$ be an extension such that $X \circ \pi \ase{\sp{\Omega'}} Y \circ \pi$. By almost-sure determinism of $\pi$, we reason $X \ase{\sp{\Omega}} Y$ as
\[ \tikzfigscaled{separation} \]
The presheaf $\y(\sp{\Omega'})$ is separated as a sub-presheaf of the separated presheaf $\rv(\Omega')$. 
\end{proof}

\noindent The following helpful characterization relates $\pi$-invariant random elements to the notion of \emph{conditional expectation operators}. In categorical probability theory, conditional expectations can be identified with the composites $e = \pi^\dagger \circ \pi$ induced by almost-surely deterministic maps $\pi$ \cite{ensarguet2023categorical,perrone2024convergence}. The channel $e$ is a \emph{dagger idempotent}, meaning $e \circ e = e$ and $e^\dagger = e$. 

\begin{proposition}\label{prop:invariant}
Let $\pi : \sp{\Omega'} \to \sp{\Omega}$. A random element $Y \in \rv(V)(\sp{\Omega'})$ is $\pi$-invariant if and only if it satisfies $Y \ase{\sp{\Omega'}} Y \circ e$, where $e = \pi^\dagger \circ \pi$ is the conditional expectation associated with $\pi$.
\end{proposition}
\begin{proof}
Necessity is clear; if $Y \ase{\sp{\Omega'}} Y \circ \pi^\dagger \circ \pi$ and $\rho,\rho'$ are given with $\pi \circ \rho \ase{\sp{\Omega''}} \pi \circ \rho'$, then $Y \circ \rho \ase{\sp{\Omega''}} Y \circ \pi^\dagger \circ \pi \circ \rho \ase{\sp{\Omega''}} Y \circ \pi^\dagger \circ \pi \circ \rho' \ase{\sp{\Omega''}} Y \circ \rho'$, showing that $Y$ is $\pi$-invariant as an element of $\rv(V)$. For sufficiency, we apply $\pi$-invariance to the pair of projections $\rho_1, \rho_2 : (\Omega' \otimes \Omega',\psi) \to (\Omega',q)$, where $\psi = \langle \id, e \rangle \circ p_{\Omega'}$. 
\begin{enumerate}
\item $\rho_1,\rho_2$ are measure-preserving, because $e$ is an endomorphism on $\sp{\Omega'} \to \sp{\Omega'}$, hence $e \circ p_{\Omega'} = p_{\Omega'}$. 
\item we need to check that $\pi \rho_1 \ase \psi \pi \rho_2$. This simplifies to verifying that
	\[ \tikzfigscaled{glue_proj_inv} \]
	For this, it suffices to note that $\langle \id, \pi \rangle \circ e \ase{\sp{\Omega'}} \langle e, \pi \rangle$ by relative positivity. This is related to $e$ being a \emph{strong idempotent} in the sense of \cite[Definition~4.11]{fritz2023absolute}.
\item from $\pi$-invariance, we now obtain that $Y \circ \rho_1 \ase{\psi} Y \circ \rho_2$, which means
\[ \tikzfigscaled{glue_y_inv} \]
\noindent Marginalizing the middle wire gives $Y \ase{\sp{\Omega'}} Y \circ e$ as desired. \qedhere
\end{enumerate}
