\title{CPN-Py: A Python-Based Tool \\ for Modeling and Analyzing Colored Petri Nets}
\titlerunning{CPN-Py: A Python-Based Tool for CPNs}

\author{
Alessandro Berti\inst{1}\orcidlink{0000-0002-3279-4795},
Wil M. P. van der Aalst\inst{1}\orcidlink{0000-0002-0955-6940}
}
