\begin{lemma}[From Multivariate Trace to Univariate Variance]
\label{lem: variance_prob_bound}
Let $G$ be hypercubic lattice of dimension $d$ and some resolution. Taking vector $\vec u$ from $G$ uniformly at random, we find that for $t > 0$:
\begin{equation}
    \mathbb{P}_{\vec u \sim G} \left[\Var{\expval{\vec u, \vec{\RV{X}}}} \geqslant t \right] \leqslant 2e^{-\frac{t}{D \tr \Sigma}} 
\end{equation}
$\mathbb{P}_{\vec u \in G}$ is the probability when taking $\vec u \in G$ uniformly at random, $D$ is some global constant whose exact value can be easily found. 
\end{lemma}
\begin{proof}
For all $\vec u \in G$, we find that:
\begin{equation}
    \Var \expval{\vec u, \vec{\RV{X}}} = \vec u^T \Sigma \vec u
\end{equation}
Since $\Sigma$ is non-negative, consider a set of orthonormal eigenvectors of $\Sigma$, the $j$-th of which we label $\vec v_j$ with eigenvalue $\lambda_j$. Then we know that:
\begin{equation}
\label{eq: var_formula}
 \Var \expval{\vec u, \vec{\RV{X}}} = \vec u^T \Sigma \vec u  = \sum_{j=1}^d \lambda_j \expval{\vec v_j, \vec u}^2
\end{equation}
Fix $j \in [d]$. We know that when taking $\vec u$ uniformly at random from $G$, $\mathbb{E}_{\vec u \sim G}\left[\expval{\vec v_j,\vec u}\right] = 0$. Since $\normtwo{\vec v_j} = 1$, we can apply Hoeffding's inequality to get:
\begin{equation}
    \mathbb{P}_{\vec u \sim G} \left[\left|\expval{\vec v_j, \vec u}\right| \geqslant x\right] \leqslant 2e^{-2x^2}
\end{equation}
for all $x > 0$, where we used the fact that $G \subseteq \left(-\frac{1}{2}, \frac{1}{2}\right)^d$. In statistical jargon, the variable $\expval{\vec v_j, \vec u}$ is sub-Gaussian. 

Now we have wrote the variable of interest as linear combination of squares of sub-Gaussian variables, we will use results on sub-Gaussian and sub-exponential random variables to refine our claims. Since definitions are inconsistent across different sources, we will use the definitions in Ref.~\cite{Vershynin_2018}. \footnote{Other sources include lecture notes as in Refs.~\cite{Rinaldo_2018, Rinaldo_2019}.} 

Note that each of $\expval{\vec v_j, \vec u}$ are sub-Gaussian with the parameter as defined in Proposition 2.5.2 in Ref.~\cite{Vershynin_2018} being some constant.Therefore, $\expval{\vec v_j, \vec u}^2$ is sub-exponential with the parameter defined as in Proposition 2.7.1 being a constant. Thus, for each $j$, for all $0 \leqslant g \leqslant \frac{1}{D_1}$, where $D_1 > 0$ is some constant, we find:
\begin{equation}
    \expect{e^{g\expval{\vec v_j, \vec u}^2}} \leqslant e^{D_1 g}
\end{equation}
Rewrote the above sentence such that the variable of interest is rescaled to $\lambda_j \expval{\vec v_j, \vec u}^2$, we found that 
\begin{equation}
    \forall  g \in \left[0,\frac{1}{D_1 \lambda_j}\right] \quad \expect{e^{g \lambda_j \expval{\vec v_j, \vec u}^2}} \leqslant e^{D_1\lambda_j g}
\end{equation}
Now, we define $a_j = \frac{\sum_{j=1}^d \lambda_j}{\lambda_j} = \frac{\tr \Sigma}{\lambda_j}$. This way we have $\sum_{j=1}^d \frac{1}{a_j} = 1$. Thus, we can apply H\"{o}lder's inequality generalized for multiple variables:
\begin{equation}
    \begin{aligned}
        \expect{e^{g \Var \expval{\vec u, \vec{\RV{X}}}}} & = \expect{e^{g \sum_{j=1}^d \lambda_j \expval{\vec v_j, \vec u}^2}} = \expect{\prod_{j=1}^d e^{g \lambda_j \expval{\vec v_j, \vec u}^2}} \\
        & \leqslant \prod_{j=1}^d \expect{\left(e^{g \lambda_j \expval{\vec v_j, \vec u}^2}\right)^{a_i}}^{\frac{1}{a_i}} = \prod_{j=1}^d \expect{e^{g a_j \lambda_j \expval{\vec v_j, \vec u}^2}}^{\frac{1}{a_i}} \\
        & \leqslant \prod_{j=1}^d \left(e^{D_1 \lambda_j g a_j}\right)^{\frac{1}{a_j}} = \prod_{j=1}^d e^{D_1 \lambda_j g} = e^{g D_1 \left(\sum_{j=1}^d \lambda_j\right)} = e^{g D_1 \tr \Sigma}
    \end{aligned}  
\end{equation}
We have not specified the range of $g$. First, $g \geqslant 0$. Then, we have picked $a_j$ such that for the above steps to work, for all $j$, $g a_j \leqslant \frac{1}{\lambda_j}$, i.e., $g \leqslant \frac{1}{\lambda_j a_j} = \frac{1}{\tr \Sigma}$. 

From here, it's easy to see that $\Var \expval{\vec u, \vec{\RV{X}}}$ is also sub-exponential with parameter $O(\tr \Sigma)$. \footnote{The lecture notes in \cite{Rinaldo_2018} seems to give a even better statement directly, but the author did not show any proof so we will ignore that statement.} Then we can use another equivalent definition for sub-exponential random variable to see that there is some constant $D$ such that:
\begin{equation}
    \mathbb{P}_{\vec u \sim G} \left[\Var{\expval{\vec u, \vec{\RV{X}}}} \geqslant t \right] \leqslant 2e^{-\frac{t}{D \tr \Sigma}} 
\end{equation}
The exact value for $D_1$ and hence $D$ can be evaluated from steps in Ref.~\cite{Vershynin_2018}. One might be able to further refine these parameters with more careful analysis. 
\end{proof}

Using similar ideas for the univariate mean value estimator, we construct a simple algorithm for estimating the mean. First, Algorithm~\ref{alg: refinement} attempts to refine our current knowledge of the mean. 


\begin{algorithm}
\caption{\label{alg: refinement}Refinement Step of Simple Multivariate Mean Estimator}
\KwData{Access to Quantum Experiment for Random Variable $\vec{\RV{X}}$, accuracy parameter $\varepsilon \geqslant 0$, confidence parameter $0 < \delta < 1$}
\KwResult{A mean estimate $\vec{\tilde{\mu}}$}
$N \leftarrow 2^{\left\lceil \log_2 \frac{16\pi}{\varepsilon} \right\rceil}$\;
$M \leftarrow 2 \left\lceil \frac{18 \ln\frac{d}{\delta} - 1}{2} \right\rceil + 1$\;
Initialize an array of vectors $\vec{\mu'}$ of length $M$ \;
\For{$\ell \leftarrow 1$ \KwTo $M$}{
    Initialize state $\ket{\psi} = \frac{1}{N^{\frac{d}{2}}} \sum_{\vec u \in G} \ket{\vec u} \ket{\bm{1}} \quad \in \mathcal{H}_G \otimes \mathcal{H}_\Omega$ where $G$ is the hypercubic lattice of dimension $d$ and resolution $N$\;
    Construct $\mathcal{G}$, the Grover operator on random variable $2 \arctan\left(\frac{1}{2}\truncate{\expval{\vec u, \vec{\RV{X}}}}{\frac{1}{\lambda \varepsilon}}\right)$ where $\vec u$ is fetched from $\mathcal{H}_G$ as a control register and $\lambda = \frac{5}{4 - 5\left(\frac{\sqrt{10}}{360}d^\frac{1}{4}\right)^2}$ \;
    Run multidimensional phase estimation algorithm on $\mathcal{G}$ (i.e., replace $U^N$ in Algorithm~\ref{alg: phase_estimation} with $\mathcal{G}^N$) with $\mathcal{H}_\Omega$ register treated as ancilla. Let the result be $\vec x$. Append $2\pi \vec x$ to $\vec{\mu}'$, i.e., $\vec{\mu}'_\ell \leftarrow 2 \pi \vec x$\;
}
Initialize output vector $\vec{\tilde{\mu}}$ of dimension $d$\;
\For{$\alpha \leftarrow 1$ \KwTo $d$}{
    $\tilde{\mu}^\alpha \leftarrow \text{ median of } \left\{\ell \in [M]: \mu'^\alpha_\ell \right\}$\;
}
Output $\vec{\tilde{\mu}}$\;
\end{algorithm}

To clarify, in Algorithm~\ref{alg: refinement}, $\mathcal{G} = \mathcal{R}\mathcal{O}$ where $\mathcal{R}$ is the reflection gate on $\mathcal{H}_\Omega$ and $\mathcal{O}$ is a univariate phase oracle controlled by $\mathcal{H}_G$, as:
\begin{equation}
    \mathcal{O}\ket{\vec u}\ket{k} = e^{i \expval{\vec u, \vec{\mathcal{X}_k}}} \ket{\vec u} \ket{k}
\end{equation}
Thus we run phase estimation treating $\mathcal{H}_\Omega$ as an ancilla register. It can been seen that the multidimensional phase estimation in Algorithm~\ref{alg: phase_estimation} functions as usual with additional ancillas, except that in Theorem~\ref{thm: phase_estimation} the quantum states will be the full state of the system to account for entangled disturbances on ancilla. Here in Theorem~\ref{thm: refinement} we formally prove the validity of the algorithm.

\begin{theorem}[Correctness of Multivariate Refinement Step, Algorithm~\ref{alg: refinement}]
\label{thm: refinement}
Consider a multivariate random variable $\vec{\RV{X}}$ with covariance matrix $\Sigma$. When it satisfy
\begin{itemize}
    \item $\norm{\expect{\vec{\RV{X}}}}_\infty \leqslant \sqrt{d}\varepsilon$ \footnote{The reader can intuitively understand this as $\norm{\expect{\vec{\RV{X}}}}_\infty \leqslant \varepsilon$. We wrote $\norm{\expect{\vec{\RV{X}}}}_\infty \leqslant \sqrt{d}\varepsilon$ as a slight generalization, for later convenience for the proof of Theorem~\ref{thm: con_sim_estimator}.};
    \item $\tr \Sigma \leqslant \left(\frac{1}{120 d^{\frac{1}{4}}}\sqrt{\frac{1}{10D}}\right)^2$;
\end{itemize}
where $\varepsilon \leqslant \frac{1}{900 d^{\frac{3}{4}}}$, $D$ is the constant in Lemma~\ref{lem: variance_prob_bound}.
We claim that the algorithm returns an estimate $\vec{\tilde{\mu}}$ such that
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}} }_\infty \leqslant \frac{\varepsilon}{2}} \geqslant 1 - \delta 
\end{equation}
\end{theorem}
\begin{proof}
Let $G$ be hypercubic lattice of dimension $d$ with resolution $N$ as specified in Algorithm~\ref{alg: refinement}.


As just discussed in the main text, Theorem~\ref{thm: phase_estimation} still holds, except that the quantum states involved are now the full state of the system with extra registers. When we run multidimensional phase estimation on $\mathcal{G}$ as defined in Algorithm~\ref{alg: refinement}, before the QFT step, we achieve a state
\begin{equation}
    \ket{\varphi'} = \frac{1}{N^{\frac{d}{2}}} \sum_{\vec u \in G} \ket{\vec{u}} \left(\mathcal{G}_{\vec u}^N \ket{\bm{1}}\right)
\end{equation}
where $\mathcal{G}_{\vec u}$ is the Grover operator for random variable $2 \arctan \left( \frac{1}{2} \expval{\vec u, \vec{\RV{X}}} \right)$ with each $\vec u \in G$. We aim to approximate the following:
\begin{equation}
    \ket{\varphi} = \frac{1}{N^{\frac{d}{2}}} \sum_{\vec u \in G} \ket{\vec{u}} \left(e^{i N\expval{\vec u, \expect{\vec{\RV{X}}}}} \ket{\bm{1}}\right)
\end{equation}
These states differ by:
\begin{equation}
    \label{eq: refinement_diff}
    \norm{\ket{\varphi'} - \ket{\varphi}}^2 = \frac{1}{|G|} \sum_{\vec u \in G} \norm{\mathcal{G}_{\vec u}^N \ket{\bm{1}} - e^{i N \expval{\vec u, \expect{\vec{\RV{X}}}}} \ket{1}}^2 
\end{equation}
as $|G| = N^d$. 

Now we obtain the following results:
\begin{itemize}
    \item By Lemma~\ref{lem: variance_prob_bound} we find that 
    \begin{equation}
        \mathbb{P}_{\vec u \in G}\left[\Var\expval{\vec u, \vec{\RV{X}}} \geqslant \left(\frac{1}{120d^\frac{1}{4}} \right)^2 \right] \geqslant 2 e^{-10}
    \end{equation}
    \item Using Hoeffding's inequality similar as in Lemma~\ref{lem: variance_prob_bound}, since $\frac{1}{|G|}\sum_{\vec u \in G} \expval{\vec u, \expect{\vec{\RV{X}}}} = 0$, we know that 
    \begin{equation}
        \label{eq: refinement_Hoeffding}
        \mathbb{P}_{\vec u \in G} \left[ \expval{\vec u, \expect{\vec{\RV{X}}}} \geqslant 2.5 \sqrt{d} \varepsilon \right] \geqslant 2 e^{- \frac{ 12.5 d \varepsilon^2}{d \varepsilon^2}} = 2 e^{-12.5}
    \end{equation}
    where we also note that $2.5 \sqrt{d} \varepsilon \leqslant \frac{1}{360d^\frac{1}{4}}$.
\end{itemize}

Using union bound, we know that for at least $1 - 2(e^{-10}+e^{-12}) \geqslant 1 - 9.83 \times 10^{-5}$ of all $\vec u \in G$, we must have:
\begin{itemize}
    \item $\expval{\vec u, \vec{\expect{\RV{X}}}} < 2.5 \sqrt{d} \varepsilon \leqslant \frac{1}{360d^\frac{1}{4}}$;
    \item $\Var\expval{\vec u, \vec{\RV{X}}} < \left(\frac{1}{120d^\frac{1}{4}}\right)^2$ which implies that $\expval{\vec u, \expect{\vec{\RV{X}}}}^2 < \left(\frac{1}{360d^\frac{1}{4}}\right)^2 + \left(\frac{1}{120d^\frac{1}{4}}\right)^2 = \left(\frac{\sqrt{10}}{360d^\frac{1}{4}}\right)^2$.
\end{itemize}
In this case, Theorem~\ref{thm: alpha_RV_diff} holds with $(\varepsilon, s_0)$ replaced by $\left(2.5 \sqrt{d} \varepsilon, \frac{\sqrt{10}}{360d^\frac{1}{4}}\right)$. So we find:
\begin{equation}
    \label{eq: refinement_bound_u_1}
    \norm{\mathcal{G}_{\vec u}^N \ket{\bm{1}} - e^{i \expval{\vec u, \expect{\vec{\RV{X}}}}} \ket{1}}^2 \leqslant 4.166 \times 10^{-3}
\end{equation}
where we used the fact that $N \leqslant 2 \times \frac{16 \pi}{\varepsilon}$, so we plug in $N \varepsilon \geqslant 36\pi \times 2.5 \sqrt{d}$.

When $\vec u$ is not nice enough and our assumptions no longer hold we use a generous bound:
\begin{equation}
    \label{eq: refinement_bound_u_2}
    \norm{\mathcal{G}_{\vec u}^N \ket{\bm{1}} - e^{i N \expval{\vec u, \expect{\vec{\RV{X}}}}} \ket{1}}^2 \leqslant 4
\end{equation}

Combine Eqs.~(\ref{eq: refinement_diff}, \ref{eq: refinement_bound_u_1}, and \ref{eq: refinement_bound_u_2}) we obtain:
\begin{equation}
    \label{eq: refinement_diff_bound}
    \norm{\ket{\varphi'}-\ket{\varphi}} \leqslant 4.166 \times 10^{-3} +9.83 \times 10^{-5} \times 4  \leqslant 4.56 \times 10^{-3} < \left(\frac{1}{12}\right)^2
\end{equation}

This result, combined with Theorem~\ref{thm: phase_estimation}, Corollary~\ref{cry: phase_estimation} more specifically, implies that for each $l$, at the end of phase estimation step, $\mu'_\ell$ satisfy
\begin{equation}
    \forall \alpha \in [d] \quad \mathbb{P} \left[\left|\frac{\left(\mu'_\ell\right)^\alpha}{2\pi} - \frac{\expect{\RV{X}^\alpha}}{2\pi}\right| > \frac{4}{N}\right] \leqslant \frac{1}{3}
\end{equation}

Because we have picked $N \geqslant \frac{16\pi}{\varepsilon}$ we know $\frac{4}{N} \leqslant \frac{1}{4\pi} \varepsilon$. Thus, for all $\alpha \in [d]$,
\begin{equation}
    \begin{multlined}
       \mathbb{P} \left[\left|\left(\mu'_\ell\right)^\alpha -\expect{\RV{X}^\alpha}\right| > \frac{1}{2} \varepsilon\right]  =  \mathbb{P} \left[\left|\frac{\left(\mu'_\ell\right)^\alpha}{2\pi} - \frac{\expect{\RV{X}^\alpha}}{2\pi}\right| > \frac{1}{4\pi} \varepsilon \right] \\
        \leqslant \mathbb{P}  \left[\left|\frac{\left(\mu'_\ell\right)^\alpha}{2\pi} - \frac{\expect{\RV{X}^\alpha}}{2\pi}\right| > \frac{4}{N} \right] \leqslant \frac{1}{3}
    \end{multlined}
\end{equation}
That is, the subroutine returns an accurate estimate with \begin{equation}
    \prob{\left|\left(\mu'_\ell\right)^\alpha -\expect{\RV{X}^\alpha}\right| \leqslant \frac{1}{2} \varepsilon} \geqslant \frac{2}{3}
\end{equation} 

By taking Theorem~\ref{thm: median}, with parameter $\delta$ replaced by our $\frac{\delta}{d}$ we obtain:
% **** This is a proof for median theorem essentially. Dropped (might need to be careful about \leq vs < )*****
% The remaining part of the algorithm is merely a standard technique to amplify the success probability. For the sake of correctness, we will still prove it as follows:

% Fix $\alpha \in d$. For $\ell \in [M]$, consider indicator random variable $n^\alpha_\ell$ \footnote{here the probability space is not $\Omega$ but from quantum measurements, so I will not use bold italic font} with
% \begin{equation}
%     n^\alpha_\ell = \begin{cases}
%         1 & \left|\left(\mu'_\ell\right)^\alpha -\expect{\RV{X}^\alpha}\right| \leqslant \frac{1}{2} \varepsilon \\
%         0 & \text{otherwise} 
%     \end{cases}
% \end{equation}
