% \begin{equation}
%     \begin{multlined}
%         \prob{n^\alpha < \frac{M}{2}} \leqslant \prob{n^\alpha < \expect{n} - \frac{M}{6}} \\
%         \leqslant e^{-\frac{2 \times \left(\frac{M}{6}\right)^2}{M}} \leqslant e^{-\frac{M}{18}} \leqslant \frac{\delta}{d}
