% \begin{equation}
%     \mathbb{P}[\left|\tilde{\mu}^\alpha - \expect{\RV{X}^\alpha} \right| > \frac{\varepsilon}{2}] \leqslant \prob{n^\alpha < \frac{M}{2}} \leqslant \frac{\delta}{d}
