\begin{equation}
     \mathbb{P}[\left|\tilde{\mu}^\alpha - \expect{\RV{X}^\alpha} \right| > \frac{\varepsilon}{2}] \leqslant \frac{\delta}{d}
\end{equation}
Use union bound to combine all dimensions $\alpha \in [d]$, we conclude:
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\varepsilon}{2}} \geqslant 1 - \delta 
\end{equation}

\end{proof}

Following Remark~\ref{remark: alpha_RV} we conclude
\begin{remark}[Complexity of Multivariate Refinement Step, Algorithm~\ref{alg: refinement}]
    \label{remark: sim_refinement_complexity}
    Algorithm~\ref{alg: refinement} uses $O\left(\frac{1}{\varepsilon}\log\frac{d}{\delta}\right)$ quantum experiments to $\vec{\RV{X}}$.
\end{remark}

In a fashion extremely similar to what was discussed in Section~\ref{sec: uni_estimator}, we construct a multivariate mean value estimator as found in Algorithm~\ref{alg: con_sim_estimator}.

\begin{algorithm}
\caption{\label{alg: con_sim_estimator} Constrained Simple Multivariate Mean Value Estimator}
\KwData{Access to Quantum Experiment to Multivariate Random Variable $\vec{\RV{X}}$, number of trials used $n \in \mathbb{N}^+$, variance ($\sqrt{\tr \Sigma}$) bound $\sigma_0 \geqslant 0$, mean bound $0 \leqslant \varepsilon_0 \leqslant \frac{2}{15}\sqrt{10D} \sigma_0$, confidence parameter $0 < \delta < 1$}
\KwResult{An mean value estimate $\vec{\tilde{\mu}}$}
$K \leftarrow 120 d^{\frac{1}{4}}\sqrt{10D}$\;
$M \leftarrow \left\lceil\log_2 \frac{n \varepsilon_0}{\sigma_0}\right\rceil$ \;
Set array $\varepsilon'$ of length $M$ with  $\varepsilon'_\ell = \frac{\varepsilon_0}{2^{\ell-1} K \sigma_0} \forall \ell \in [M]$\;
Set array $\delta'$ of length $M$ via Theorem~\ref{thm: log_log} according to array $\varepsilon'$ with parameters $(\delta,R)$ set to $(\delta,2)$\;
$\vec{\tilde{\mu}} \leftarrow 0$ \;
\For{$\ell = 1$ \KwTo $M$}{
    $\vec{\mu}_\ell \leftarrow$ result of calling Algorithm~\ref{alg: refinement} on $\frac{\vec{\RV{X}}-\vec{\tilde{\mu}}}{K \sigma_0}$ with parameters $(\varepsilon, \delta)$ set to $(\varepsilon'_\ell, \delta'_\ell)$ \;
    $\vec{\tilde{\mu}} \leftarrow \vec{\tilde{\mu}} + K \sigma_0 \vec{\mu}_\ell$\; 
}
Output $\tilde{\mu}$\;
\end{algorithm}
\begin{theorem}[Complexity of Algorithm~\ref{alg: con_sim_estimator}]
\label{thm: con_sim_estimator}
When $\vec{\RV{X}}$, with covariance matrix $\Sigma$, satisfy
\begin{itemize}
    \item $\tr \Sigma \leqslant \sigma_0$;
    \item $\normtwo{\expect{\vec{\RV{X}}}} \leqslant \varepsilon_0 \leqslant \frac{2}{15}\sqrt{10D} \sigma_0$;
\end{itemize}
Then Algorithm~\ref{alg: con_sim_estimator} returns a mean estimate $\vec{\tilde{\mu}}$ such that 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sigma_0}{n}} \geqslant 1 - \delta
\end{equation}

\end{theorem}

\begin{proof}

The proof is nearly identical to that of Theorem~\ref{thm: uni_estimator} with only a few tweaks.

Define $\vec{\tilde{\mu}}_\ell$ to be the value of $\vec{\tilde{\mu}}$ after the $\ell$-th time Algorithm~\ref{alg: uni_refinement} is called. $\vec{\tilde{\mu}}_0 = 0$. 
$\forall \ell \in [M]$, consider random variable $\vec{\RV{Y}}_\ell = \frac{\vec{\RV{X}}-\vec{\tilde{\mu}}_{\ell-1}}{K \sigma_0}$ \footnote{$\ell$ is array index. There is your beloved index confusion.}, say it has covariance matrix $\Sigma_\ell$. We can see that $\tr \Sigma_\ell \leqslant \left(\frac{1}{120 d^{\frac{1}{4}}\sqrt{10D}}\right)^2$. 

For the $\ell$-th time Algorithm~\ref{alg: uni_refinement} is called, if $\ell = 1$ define success condition as:
\begin{equation}
    P_1 \equiv \left(\norm{\vec{\tilde{\mu}}_1 - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2} \sigma_0 \varepsilon'_1\right)
\end{equation}
Just as what was done in proof for Theorem~\ref{thm: uni_estimator}, for $\ell > 1$, define success condition as the following:
\begin{equation}
    P_\ell \equiv \begin{cases}
        \norm{\vec{\tilde{\mu}}_\ell - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2} \sigma_0 \varepsilon'_\ell & \left(\norm{\vec{\tilde{\mu}}_{\ell-1} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2} \sigma_0 \varepsilon'_{\ell-1}\right) \\
        \text{true} & \text{otherwise} \\
    \end{cases} 
\end{equation}
This gives two key properties:
\begin{itemize}
    \item By assumption on $\vec{\RV{X}}$ and our specific pick of $K$, $\expect{\frac{\vec{\RV{X}}}{K\sigma_0}} \leqslant \frac{\varepsilon_0}{K \sigma_0} \leqslant \frac{1}{900d^{\frac{1}{4}}}$, so Theorem~\ref{thm: refinement} holds with parameters $(\varepsilon, \delta)$ replaced with $( \frac{\varepsilon_0}{K\sigma_0}, \delta'_1)$, so we know that 
    \begin{equation}
        \mathbb{P}[P_1] = \prob{\norm{\vec{\tilde{\mu}}_1 - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2} \sigma_0 \varepsilon'_1} = \prob{\norm{\vec{\mu}_1 - \expect{\frac{\vec{\RV{X}}}{K\sigma_0}}}_\infty \leqslant \frac{\varepsilon_0}{2} } \geqslant 1 - \delta'_1 
    \end{equation}
    \item Consider $\ell \in [M-1]$. Assume $\norm{\vec{\tilde{\mu}}_\ell - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2} \sigma_0 \varepsilon'_\ell$. Then $\norm{\frac{\expect{\vec{\RV{X}}} - \vec{\tilde{\mu}}_\ell}{K\sigma_0}}_\infty \leqslant \frac{\varepsilon'_\ell}{2} = \varepsilon'_{\ell+1}$ which means that $\normtwo{\frac{\expect{\vec{\RV{X}}} - \vec{\tilde{\mu}}_\ell}{K\sigma_0}} \leqslant \sqrt{d}\varepsilon'_{\ell+1} \leqslant \frac{1}{900d^{\frac{1}{4}}}$. So Theorem~\ref{thm: uni_refinement} holds with parameters $(\varepsilon, \delta)$ replaced with $(\varepsilon'_{\ell+1}, \delta'_{\ell+1})$, so we know that 
    \begin{equation}
        \begin{aligned}         
            \prob{\norm{\vec{\tilde{\mu}}_{\ell+1} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{K}{2}\sigma_0 \varepsilon'_{\ell+1} } &   = \prob{\norm{K \sigma_0 \vec{\mu}_{\ell+1} - \expect{\vec{\RV{X}} - \vec{\tilde{\mu}}_\ell}}\infty\leqslant \frac{K}{2} \sigma_0 \varepsilon'_{\ell+1} } \\
                & = \prob{\norm{\vec{\mu}_{\ell+1} - \expect{\frac{\vec{\RV{X}}-\vec{\tilde{\mu}}_\ell}{K\sigma_0}}}_\infty \leqslant \frac{\varepsilon'_{\ell+1}}{2} } \geqslant 1 - \delta'_{\ell+1}
            \end{aligned} 
    \end{equation}
\end{itemize}
From the definition of our success condition $\{P_\ell\}$, we know that at $\ell$-th time Algorithm~\ref{alg: uni_refinement} is called it always succeeds with probability at least $1 - \delta_\ell$. Thus, we can use Theorem~\ref{thm: log_log} to know that
\begin{equation}
    \prob{P_1 \wedge P_2 \wedge \cdots P_M} \geqslant 1 - \delta
\end{equation}
But $P_1 \wedge P_2 \wedge \cdots P_M$ implies (due to our pick of $M$)
\begin{equation}
    \norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant 2 \sigma_0 \varepsilon'_M = \frac{\varepsilon_0}{2^M} \leqslant \frac{\sigma_0}{n}
\end{equation}
That is, we find that:
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sigma_0}{n}} \geqslant 1 - \delta
\end{equation}
\end{proof}


The complexity is given by
\begin{theorem}[Complexity of Algorithm~\ref{alg: con_sim_estimator}]
    \label{thm: con_sim_complexity}
    The algorithm always uses $O\left(n d^\frac{1}{4} \log \frac{d}{\delta} \right)$ access to quantum experiment to return the result. In terms of quantum memory (outside all potential ancillas) it needs 1 register for results of quantum experiment. 
\end{theorem}
\begin{proof}
We have:
\begin{equation}
\frac{1}{\varepsilon'_M} = \frac{2^{M-1}K \sigma_0}{\varepsilon_0}  \in \frac{\sigma_0}{\varepsilon_0} \times O\left(\frac{n\varepsilon_0}{\sigma_0}\right) \times O\left( d^{\frac{1}{4}}\right) = O\left(n d^\frac{1}{4}\right)
\end{equation}
With the complexity statement in Remark~\ref{remark: sim_refinement_complexity} and Theorem~\ref{thm: log_log}, we thus confirms that the algorithm uses $ O\left(n d^\frac{1}{4} \log \frac{d}{\delta}\right)$ calls to the quantum experiment.

In terms of memory, we get to reuse the quantum registers whenever a quantum subroutine is called, so it's $O(1)$.
\end{proof}

Algorithm~\ref{alg: con_sim_estimator} gives an estimator without any $\log$ scalling on $n$. However, it scales badly with respect to $d$. The key reason is due to the extra $\sqrt{d}$ factor when we go from the accuracy parameter $\varepsilon$ for each dimension, to $2.5 \sqrt{d} \varepsilon$ as the accuracy parameter for the combined random variable $\expval{\vec u, \vec{\RV{X}}}$ at the Grover operator level. Since our Grover operator has an intrinsic uncertainty in the phase $\propto O(s_0^2 \varepsilon)$ where $\varepsilon$ is now replaced with $O(\sqrt{d} \varepsilon)$. We are thus forced to reduce $s_0$ to accommodate. 

\subsection{Meticulous Estimator}
\label{sec: mer_estimator}

The problems we just discussed also hints to a valid solution to get rid of the polynomial overhead in $d$. By converting the univariate mean value estimator in Algorithm~\ref{alg: uni_esimator} to a quantum circuit, one can obtain a unitary that approximates $e^{i N\expval{\vec u, \expect{\vec{\RV{X}}}}}$ arbitrarily close with few assumptions. 

By Remark~\ref{remark: uni_hybird} and Theorem~\ref{thm: c_to_q}, with $O(n)$ access to the quantum experiment of some univariate random variable $\RV{X}$, for some random variable $\RV{X}$, variance bound $\sigma_0 \geqslant 0$, mean bound $0 \leqslant \varepsilon_0 \leqslant \frac{1}{3}\sigma_0$, and $0 < \delta < 1$, we can construct unitary $U$ on $\mathcal{H}_\Omega' \otimes \mathcal{H}_\text{output}$ with:
\begin{equation}
    U\ket{0}\ket{0} = \sum_{j \in \Omega'} \sqrt{q_j} \ket{\lambda_j} \ket{y_j}
\end{equation}
where $\Omega'$ is some probability space corresponding measurements results during the execution of the algorithms, $y_j$ corresponds to instances of a random variable $\bm{y}$. Thus $U$ ``output'' a mean value estimate in the sense of the following lemma,
\begin{lemma}[Quantizing the Constrained Classical Univariate Estimator, Algorithm~\ref{alg: uni_esimator}]
\label{lem: c_to_q_uni}
For $\bm{y}, \Omega'$ that we just defined above, if the random variable $\RV{X}$ satisfy:
\begin{itemize}
    \item $\Var{\RV{X}} \leqslant \sigma_0^2$.
    \item $\expect{\RV{X}} \leqslant \varepsilon_0 \leqslant \frac{1}{3} \sigma_0$\; 
\end{itemize}
The unitary we constructed satisfy
\begin{equation}
   \mathbb{P}_{\Omega'}\left[\left|\bm{y} - \mathbb{E}[\RV{X}]\right| \leqslant \frac{\sigma_0}{n}\right] \geqslant 1 - \delta
\end{equation}
where $\mathbb{P}_{\Omega'}$ indicates that the probability is taken over $\Omega'$.
\end{lemma}

Given some integer $N$, we can also generate a phase operator $\mathcal{Q}$ that converts output register's value into a phase:
\begin{equation}
    \mathcal{Q}\ket{z} = e^{iNz} \ket{z}.
\end{equation}
From these unitaries we construct:
\begin{equation}
    V = U^\dag \left( I \otimes \mathcal{Q} \right) U
\end{equation}
The claim is that $V$ approximates a phase oracle to produce $e^{i N \expect{\RV{X}}}$, as found in the following theorem.
\begin{theorem}[Approximating the Phase Unitary using Quantum Subroutine]
\label{thm: uni_approx_phase}
Given some small constant $\xi > 0$, $N \in \mathbb{N}^+, \sigma_0 \geqslant 0$. We feed to $U$ with parameters $(n, \sigma_0, \varepsilon_0, \delta)$ replaced with $\left(\ceil{\frac{3N \sigma_0}{2\xi}}, \sigma_0, \varepsilon_0, \frac{1}{9}\xi^2\right)$, and we feed in $N$ to construction of $\mathcal{Q}$. 

Then, when the random variable $\RV{X}$ satisfy:
\begin{itemize}
    \item $\Var{\RV{X}} \leqslant \sigma_0^2$.
    \item $\expect{\RV{X}} \leqslant \varepsilon_0 \leqslant \frac{1}{3} \sigma_0$\; 
\end{itemize}
We find:
\begin{equation}
   \norm{V\ket{0}\ket{0} - e^{i N \expect{\RV{X}}} \ket{0} \ket{0}} \leqslant \xi
\end{equation}

\end{theorem}
\begin{proof}
Consider only the action of $(I \otimes \mathcal{Q}) U$, it produces a state:
\begin{equation}
\label{eq: uni_phase_proof_1}
\ket{\psi} = (I \otimes \mathcal{Q}) U \ket{0}\ket{0} = \sum_{j \in \Omega'} \sqrt{q_j} e^{i N y_j} \ket{\lambda_j} \ket{y_j}
\end{equation}
We want this state to be:
\begin{equation}
\label{eq: uni_phase_proof_2}
\ket{\varphi} = (I \otimes \mathcal{Q}) U \ket{0}\ket{0} = \sum_{j \in \Omega'} \sqrt{q_j} e^{i N \expect{\RV{X}}} \ket{\lambda_j} \ket{y_j} 
\end{equation}
We can see that $U^\dag \ket{\varphi} = e^{i N \expect{\RV{X}}} \ket{0}\ket{0}$. So:
\begin{equation}
\label{eq: uni_phase_proof_3}
\norm{V\ket{0}\ket{0} - e^{i N \expect{\RV{X}}} \ket{0} \ket{0}} = \norm{\ket{\psi} - \ket{\varphi}}
\end{equation}
Square on both side of Eq.~(\ref{eq: uni_phase_proof_3}) and plug in definitions in Eqs.~(\ref{eq: uni_phase_proof_1} and \ref{eq: uni_phase_proof_2}) we obtain:

\begin{equation}
\begin{aligned}
 \norm{V\ket{0}\ket{0} - e^{i N \expect{\RV{X}}} \ket{0} \ket{0}}^2 & = \norm{\sum_{j \in \Omega'} \sqrt{q_j} \left( e^{iN y_j} - e^{i N \expect{\RV{X}}}\right) \ket{\lambda_j} \ket{y_j}}^2 \\
& = \sum_{j \in \Omega'} q_j \left( e^{iN y_j} - e^{i N \expect{\RV{X}}}\right)^2
\end{aligned}
\end{equation}
where we used the fact that $\lambda_j$ are orthogonal vectors. 

By Lemma~\ref{lem: c_to_q_uni}, we know that for at least $1 - \delta$ of all times 
\begin{equation}
    \left|e^{iN y_j} - e^{i N \expect{\RV{X}}}\right| \leqslant N \left|y_j - \expect{\RV{X}}\right| \leqslant \frac{N \sigma_0}{n}
\end{equation}

For the other situations we can use a generous bound of 
\begin{equation}
    \left|e^{iN y_j} - e^{i N \expect{\RV{X}}}\right| \leqslant 2
\end{equation}
Combined we obtain
\begin{equation}
\hphantom{{}={}} \norm{V\ket{0}\ket{0} - e^{i N \expect{\RV{X}}} \ket{0} \ket{0}}^2 \leqslant 4 \delta + \left( \frac{N \sigma_0 }{n}\right)^2
\end{equation}

If we plug in $\delta = \frac{1}{9} \xi^2$ and $n \geqslant \frac{3N \sigma_0 }{2\xi}$, we will produce a bound:
\begin{equation}
\hphantom{{}={}} \norm{V\ket{0}\ket{0} - e^{i N \expect{\RV{X}}} \ket{0} \ket{0}}^2 \leqslant 2 \left(\frac{2}{3}\xi\right)^2 \leqslant \xi^2
\end{equation}
thus completing the proof. 
\end{proof}

But what's the cost of $V$? Here we see that while the time complexity becomes trivial, the space complexity will be dominated by the number of quantum subroutines being called, i.e., the number of phase estimations as what we have been tracking throughout Sec.~\ref{sec: uni_estimator}. 
\begin{theorem}[Cost of Phase Unitary from Quantizing Classical Univariate Estimator]
\label{thm: cost_V}
The unitary $V$ using parameters given in Theorem~\ref{thm: uni_approx_phase} costs $O\left(\ceil{\frac{N \sigma_0}{\xi}} \log \frac{1}{\chi}\right)$ in terms of accesses to quantum experiments. It also needs to allocate $O\left(\log \ceil{\frac{N \sigma_0}{\xi}} \left(\log \log \ceil{\frac{N \sigma_0}{\xi}} + \log \frac{1}{\xi}\right) \right)$ entangled quantum registers for quantum experiments alone. \footnote{Similarly as how we define big-$O$ notation with $\delta$ present in Footnote~\ref{footnote: O_with_delta}, we only care about the limit $\chi \to 0$ when using big-$O$ notation, this means that when appearing inside big-$O$, we may set, say, $\chi < c < 1$ for some constant $c$.}
\end{theorem}
\begin{proof}
By Remark~\ref{remark: uni_hybird} and Theorem~\ref{thm: c_to_q}, we can translate the complexities found in Theorem~\ref{thm: uni_complexity} accordingly to here. Notice that the quantum subrountine in the hybird algorithm is essentially phase estimation, so the number of phase estimations called translate into the number of registers needed for the quantized circuit. 
\end{proof}

With accesses to $V$ we can construct a multivariate mean value estimator by running phase estimation:
\begin{algorithm}
\caption{\label{alg: con_mer_estimator} Constrained Meticulous Multivariate Mean Estimator}
\KwData{Accesses to quantum experiment for random variable $\vec{\RV{X}}$, (not exactly) number of trails $n \in \mathbb{R}^+$, variance ($\sqrt{\Tr \Sigma}$) bound $\sigma_0 \geqslant 0$, mean bound $0 \leqslant \varepsilon_0 \leqslant \frac{2}{15}\sqrt{10D} \sigma_0$ \footnote{This parameter serves no purpose at all for this algorithm. We treat it as an input parameter to match up with Algorithm~\ref{alg: con_sim_estimator}.}, accuracy parameter $0 < \delta < 1$, assuming $n \geqslant \frac{\ln{\frac{d}{\delta}}}{\sqrt{\ln d}}$}
\KwResult{A mean estimate $\vec{\tilde{\mu}}$}
$K \leftarrow \sqrt{10D}\sigma_0$ \;
$N \leftarrow 2^{\ceil{\log_2 \left(8 \pi n\sqrt{10D}\right)}}$\;
$M \leftarrow 2 \left\lceil \frac{18 \ln\frac{d}{\delta} - 1}{2} \right\rceil + 1$\;
Initialize an array of vectors $\vec{\mu}'$ of length $M$\;
\For{$\ell \leftarrow 1$ \KwTo $M$}{
    Set unitary $V$ using parameters given in Theorem~\ref{thm: uni_approx_phase} but
    \begin{itemize}
        \item we use quantum experiments to random variable $\expval{\vec u, \frac{\vec{\RV{X}}}{K}}$ in place of $\RV{X}$, where $\vec u$ is fetched from $\mathcal{H}_G$ as a control register
        \item Replace parameters $\left(\sigma_0, N, \xi\right)$ with $\left(1, N, \frac{1}{13}\right)$\;
    \end{itemize}
    Run multidimensional phase estimation with controlled-$V$ in place of $U^N$ on register $\mathcal{H}_{G}$, where $G$ is hypercubic lattice of resolution $N$. Let the result be $\vec x$. Append $2\pi K \vec x$ to $\vec{\mu}'$, i.e., $\vec{\mu}'_\ell \leftarrow 2 \pi K \vec x$\;
}
Initialize output vector $\vec{\tilde{\mu}}$ of dimension $d$\;
\For{$\alpha \leftarrow 1$ \KwTo $d$}{
    $\tilde{\mu}^\alpha \leftarrow \text{ median of } \left\{\ell \in [M]: \mu'^\alpha_\ell \right\}$\;
}
Output $\vec{\tilde{\mu}}$\;

\end{algorithm}


\begin{theorem}[Correctness of Algorithm~\ref{alg: con_mer_estimator}]
\label{thm: con_mer_estimator}
When $\vec{\RV{X}}$, with covariance matrix $\Sigma$, satisfy
\begin{itemize}
    \item $\tr \Sigma \leqslant \sigma_0$;
    \item $\normtwo{\expect{\vec{\RV{X}}}} \leqslant \varepsilon_0 \leqslant \frac{2}{15}\sqrt{10D} \sigma_0$;
\end{itemize}
Then Algorithm~\ref{alg: con_mer_estimator} returns a mean estimate $\vec{\tilde{\mu}}$ such that 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sigma_0}{n}} \geqslant 1 - \delta
\end{equation}
\end{theorem}
\begin{proof}
Similar to the proof in Theorem~\ref{thm: refinement}, when we run multidimensional phase estimation on with $V$ instead, before the QFT step, we achieve a state
\begin{equation}
    \ket{\psi} = \frac{1}{N^{\frac{d}{2}}} \sum_{\vec u \in G} \ket{\vec{u}} \left(\mathcal{V}_{\vec u} \ket{0}\ket{0}\right)
\end{equation}
where $\mathcal{V}_{\vec u}$ is unitary $V$ as discussed in main text except for random variable $\expval{\vec u, \frac{\vec{\RV{X}}}{K}}$. We wish to achieve a state:
\begin{equation}
    \ket{\varphi} = \frac{1}{N^{\frac{d}{2}}} \sum_{\vec u \in G} \ket{\vec{u}} \left(e^{i N \expval{\vec u, \frac{\vec{\RV{X}}}{K}}} \ket{0}\ket{0}\right)
\end{equation}
These states differ by:
\begin{equation}
    \label{eq: mer_diff}
    \norm{\ket{\varphi'} - \ket{\varphi}}^2 = \frac{1}{|G|} \sum_{\vec u \in G} \norm{V_{\vec u} \ket{0}\ket{0} - e^{i N \expval{\vec u, \expect{\frac{\vec{\RV{X}}}{K}}}}  \ket{0}\ket{0}}^2 
\end{equation}

Use Lemma~\ref{lem: variance_prob_bound} we know that:
\begin{equation}
    \mathbb{P}_{\vec u \sim G_N}\left[\Var{\expval{\vec u, \vec{\RV{X}}}} \geqslant \left(\sqrt{10D} \tr \Sigma\right)^2\right] \leqslant 2 e^{-10}
\end{equation}
From Hoeffding's inequality we also find:
\begin{equation}
    \mathbb{P}_{\vec u \sim G_N}\left[\left|\expect{\expval{\vec u, \vec{\RV{X}}}}\right| \leqslant \frac{1}{3}\sqrt{10D} \tr \Sigma\right] \leqslant 2 e^{-12.5}
\end{equation}

By union bound, this means that for probability at least $1 - 2 (e^{-10} + e^{-12.5})$ of all $\vec u \in G$ we have 
\begin{itemize}
    \item $\Var{\expval{\vec u, \vec{\RV{X}}}} < \left(\sqrt{10D} \tr \Sigma\right)^2$;
    \item $\left|\expect{\expval{\vec u, \vec{\RV{X}}}}\right| < \frac{1}{3}\sqrt{10D} \tr \Sigma$;
\end{itemize}
Our selection of $K$ ensures that:
\begin{itemize}
    \item $\Var{\expval{\vec u, \frac{\vec{\RV{X}}}{K}}} < 1$;
    \item $\left|\expect{\expval{\vec u, \frac{\vec{\RV{X}}}{K}}}\right| < \frac{1}{3}$;
\end{itemize}
So Theorem~\ref{thm: uni_approx_phase} applies with parameters $(\sigma_0, N, \chi)$ replaced with $(1, N, \frac{1}{13})$ (and $\RV{X}$ replaced with $\expval{\vec u, \frac{\vec{\RV{X}}}{K}}$ which gives 
\begin{equation}
    \norm{V_{\vec u} \ket{0}\ket{0} - e^{i N \expval{\vec u, \expect{\frac{\vec{\RV{X}}}{K}}}  \ket{0}\ket{0}}}^2 \leqslant \left(\frac{1}{13}\right)^2
\end{equation}

When the nice constraints are not satisfied, we use a generous bound of 
\begin{equation}
    \norm{V_{\vec u} \ket{0}\ket{0} - e^{i N \expval{\vec u, \expect{\frac{\vec{\RV{X}}}{K}}}}  \ket{0}\ket{0}}^2 \leqslant 4
\end{equation}
Add these results into Eq.~(\ref{eq: mer_diff}) we find:
\begin{equation}
\norm{\ket{\varphi'} - \ket{\varphi}}^2 \leqslant \left(\frac{1}{13}\right)^2 + 2\left(e^{-10}+e^{-12.5}\right) \times 4 < 6.311\times 10^{-3} < \left(\frac{1}{12}\right)^2 
\end{equation}

So Theorem~\ref{thm: phase_estimation} and Corollary~\ref{cry: phase_estimation} holds, which means that for each dimension $\alpha \in [d]$, for each $\ell \in [M]$, with probability at least $\frac{2}{3}$ we have:
\begin{equation}
\left|\frac{\left(\mu'_\ell\right)^\alpha}{2\pi K} - \frac{1}{2\pi}\expect{\frac{\RV{X}^\alpha}{K}}\right| \leqslant \frac{4}{N}
\end{equation}
which means that:
\begin{equation}
\left|\left(\mu'_\ell\right)^\alpha -\expect{\RV{X}^\alpha}\right| \leqslant \frac{8\pi K}{N} 
\end{equation}
Due to our pick of $N$ such that $N \geqslant \frac{8 \pi}{n}\sqrt{10D}$ we get:
\begin{equation}
    \label{eq: mer_proof}
    \left|\left(\mu'_\ell\right)^\alpha -\expect{\RV{X}^\alpha}\right| \leqslant \frac{\sigma_0}{n}
\end{equation}

By taking a coordinate-wise median, Theorem~\ref{thm: median}, we obtain $\vec{\tilde{\mu}}$ such that:
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} -\expect{\vec{\RV{X}}}}_{\infty} \leqslant \frac{\sigma_0}{n}} \geqslant 1 - \delta
\end{equation}
\end{proof}

The complexity of the algorithm is given by
\begin{theorem}[Complexity of Algorithm~\ref{alg: con_mer_estimator}]
\label{thm: con_mer_complexity}
Algorithm~\ref{alg: con_mer_estimator} uses $O\left(n \log \frac{d}{\delta}\right)$ access to the quantum experiment for multivariate random variable $\vec{\RV{X}}$. In terms of quantum memory it costs $O\left(\log n \log \log n\right)$.
\end{theorem}
\begin{proof}
In Algorithm~\ref{alg: con_mer_estimator}, by Remark~\ref{remark: quantum_experiment_algebra} and Theorem~\ref{thm: cost_V}, each call to $V$ consumes $O(N) = O\left(n\right)$, as we called Theorem~\ref{thm: uni_approx_phase} but with $\sigma_0, \xi$ replaced with constants. We ran $V$ for $O\left(\log \frac{d}{\delta}\right)$ times so the total cost is $O\left(n \log \frac{d}{\delta}\right)$.

Similarly, the memory cost is $O\left(\log n \log \log n\right)$ for each $V$. This memory can be reused for each multidimensional phase estimation so the final cost is also $O\left(\log n \log \log n\right)$.

\end{proof}

\subsection{Final Classical Reduction}
\label{sec: final_classical_reduction}

In Theorem~\ref{alg: con_sim_estimator} and Theorem~\ref{alg: con_mer_estimator} we have constructed two different multivariate mean value estimators, each with their advantages and disadvantages. In both cases we need to give a bound of the variance ($\sqrt{\tr \Sigma}$) for the random variable and ensures that it has a decently small mean (we can do this by give initial estimate and shift the random variable). In this section we use these primitives to handle an arbitary multivariate random variable with no previous assumptions known. 

For the remainder of this section, let's use $\mathcal{A}$ as a placeholder for an algorithm depending on random variable $\vec{\RV{X}}$ and parameters $\left(n, \sigma_0, \varepsilon_0, \delta\right)$ as described in Theorem~\ref{thm: con_sim_estimator} and \ref{thm: con_mer_estimator}, such that when $\vec{\RV{X}}$, with covariance matrix $\Sigma$, satisfy:
\begin{itemize}
    \item $\tr \Sigma \leqslant \sigma_0$;
    \item $\normtwo{\expect{\vec{\RV{X}}}} \leqslant \varepsilon_0 \leqslant \frac{2}{15}\sqrt{10D} \sigma_0$;
\end{itemize}
$\mathcal{A}$ returns a mean estimate $\vec{\tilde{\mu}}$ such that 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
It can be later substituted into either Algorithm~\ref{alg: con_sim_estimator} or \ref{alg: con_mer_estimator}.

First, similar to us elimiating the dependence on upper bound of $\expect{\RV{X}}$ on univariate case via Theorem~\ref{alg: not_so_uni_esimator}, we run a couple of classical trials first to complete an algorithm without dependence on $\expect{\vec{\RV{X}}}$:

\begin{algorithm}
    \caption{\label{alg: not_so_multi_esimator}(Not-so) Constrained Multivariate Mean Value Estimator}
    \KwData{Access to Quantum Experiment of Random Variable $\vec{\RV{X}}$, variance bound $\sigma_0 \geqslant 0$, number of trials parameter $n \in \mathbb{N}^+$, confidence parameter $0 < \delta < 1$}
    \KwResult{A mean value estimate $\vec{\tilde{\mu}}$}
    $n' \leftarrow \ceil{\frac{225}{4}10D\left(1 + \sqrt{\frac{1}{\ln \frac{2}{\delta}}}\right)^2} $ \footnote{The classical mean estimator primitive does need $n'$ to be integer so we have to take a ceil function}\;
    Run Classical Multivariate Mean Value Estimator in Theorem~\ref{thm: classical_multi_estimator} for $\vec{\RV{X}}$ with parameters $(n,\delta)$ replaced with $\left(n', \frac{\delta}{2}\right)$, store as $\vec{\mu}'$\;  
    Run $\mathcal{A}$ on $\vec{\RV{X}} - \vec{\mu}'$ with parameters $(n, \sigma_0, \varepsilon_0, \delta)$ replaced with $\left(n, \sigma_0, \frac{2}{15}\sqrt{10D} \sigma_0, \frac{\delta}{2}\right)$, let it be $\vec{\mu}''$\;
    Output $\vec{\tilde{\mu}} = \vec{\mu}' + \vec{\mu}''$\;
\end{algorithm}

\begin{theorem}[Analysis for Algorithm~\ref{alg: not_so_multi_esimator}]
\label{thm: notso_multi_estimator}
For multivariate random variable $\vec{\RV{X}}$ with covariance matrix $\Sigma$, such that $\tr \Sigma \leqslant \sigma_0^2$, the algorithm returns an estimate $\tilde{\mu}$ with 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty\leqslant \frac{\sigma_0}{n}} \geqslant 1 - \delta
\end{equation}
The algorithm uses $O\left(\log\frac{1}{\delta}\right)$ accesses to the quantum experiment along with a call to $\mathcal{A}$ with parameters $(n, \delta)$ replaced with $\left(O(n), \Omega(\delta)\right)$.
\end{theorem}
\begin{proof}

The proof is almost the same as Theorem~\ref{thm: notso_uni_estimator}. We have selected the value of $n'$ such that by Theorem~\ref{thm: classical_multi_estimator} and Corollary~\ref{cry: classical_multi_estimator_relaxed}, we know that with probability at least $1 - \frac{\delta}{2}$,
\begin{equation}
\normtwo{\expect{\vec{\RV{X}} - \vec{\mu}'}} = \normtwo{\vec{\mu}'-\vec{\RV{X}}} \leqslant \frac{2}{15}\sqrt{10D}  \sigma_0
\end{equation}
If this happens then with probability at least $1 - \frac{\delta}{2}$, by definition of $\mathcal{A}$ we find 
\begin{equation}
\label{eq: multi_notso_good}
\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty = \norm{\vec{\mu}'' - \expect{\vec{\RV{X}} - \vec{\mu}'}}_\infty \leqslant \frac{\sigma_0}{n}
\end{equation}

Combined, Eq.~(\ref{eq: multi_notso_good}) happens with probability at least $1 - \delta$ via union bound. It is also easy to see that the complexity bound is justified.
\end{proof}

In Sec.~\ref{sec: uni_estimator}, by proving Corollary~\ref{cry: connect_to_Ryan} we have unlocked solutions to important problems mentioned in the classical reduction in Ref.~\cite{Kothari_2022}. These steps in the paper are designed to handle an unknown standard deviation, here we will do exactly the same for our multivariate random variable, but this time to handle an unknown $\tr \Sigma$. To build a complete chain of logic, we will only need to make slight modifications starting from Problem 8 in Ref.~\cite{Kothari_2022}. Formally speaking, first, by using the exact proof (adding steps to boost probability arbitrarily high) up to Problem 7 in Ref.~\cite{Kothari_2022} we can do the following:
\begin{lemma}[Problem 7 in Ref.~\cite{Kothari_2022}]
\label{lemma: Ryan_useful_lemma}
Given $O\left(n \log \frac{1}{\delta}\right)$ accesses to quantum experiment for univariate random variable $\RV{X}$ where $\forall k \in \Omega\; 0 \leqslant \mathcal{X}_k \leqslant 1$, there is an algorithm that returns an estimate for the mean $\tilde{\mu}$ such that
\begin{equation}
    \prob{\left|\tilde{\mu} - \expect{\RV{X}}\right| \leqslant \frac{\sqrt{\expect{\RV{X}}}}{n}} \geqslant 1 - \delta 
\end{equation}
\end{lemma}

Now following almost exact steps starting from Problem 8 in Ref.~\cite{Kothari_2022}, we can give an algorithm that computes the mean with no prior assumption on the random variable itself:
\begin{algorithm}
    \caption{\label{alg: final_multi_esimator}Multivariate Mean Value Estimator}
    \KwData{Access to Quantum Experiment of Random Variable $\vec{\RV{X}}$, number of trials $n \in \mathbb{N}^+$, confidence parameter $0 < \delta < 1$}
    \KwResult{A mean value estimate $\vec{\tilde{\mu}}$}
    $p \leftarrow \frac{25}{52C n^2}$, where $C$ is the parameter discussed in Quantum Estimation in Theorem~\ref{thm: quantile}\;
    $n' \leftarrow  2 \sqrt{\frac{52}{25}} n$\;
    Run Classical Multivariate Mean Value Estimator in Theorem~\ref{thm: classical_multi_estimator} for $\vec{\RV{X}}$ with parameters $(n, \delta)$ replaced with $\left(\ceil{25\left(1 + \sqrt{\frac{1}{\ln\frac{4}{\delta}}}\right)^2},\sigma_0, \frac{\delta}{4}\right)$, store as $\vec{\mu}'$\;  
    Run quantile estimation (Theorem~\ref{thm: quantile}) on $\normtwo{\vec{\RV{X}} - \vec{\mu}'}$ with parameters $(p, \delta)$ replaced with $\left(p, \frac{\delta}{4}\right)$, let result be $K$\;
    Let $\vec{\RV{Y}} = \truncate{\vec{\RV{X}} - \vec{\mu}'}{K}$, run algorithm discussed in Lemma~\ref{lemma: Ryan_useful_lemma} on random variable $\left(\frac{\normtwo{\vec{\RV{Y}}}}{K}\right)^2$ with parameters $(n,\delta)$ replaced with $\left(\frac{3}{\sqrt{p}}, \frac{\delta}{4}\right)$, let the result be $s'^2$ with $s' \geqslant 0$\;
    Run Algorithm~\ref{alg: not_so_multi_esimator} we just discussed on quantum experiment for $\vec{\RV{Y}}$ with parameters $(n, \sigma_0, \delta)$ replaced with $(n', \sqrt{\frac{3}{2}}Ks', \frac{\delta}{4})$, say result is $\vec{\mu}''$\;
    Output $\vec{\tilde{\mu}} = \vec{\mu}' + \vec{\mu}''$\;
\end{algorithm}
\begin{theorem}[Generic Multivariate Estimator Main Result]
\label{thm: generic_multi_main}
Algorithm~\ref{alg: final_multi_esimator} uses $1$ calls to $\mathcal{A}$ with parameters $(n, \delta)$ replaced with $\left(O(n), \Omega(\delta)\right)$, along with other procedures that costs 
\begin{itemize}
    \item $O\left(n \log \frac{1}{\delta}\right)$ in terms of quantum experiments for $\vec{\RV{X}}$ (with covariance matrix $\Sigma$)
    \item $O(1)$ in terms of quantum registers needed
\end{itemize}  
to return a mean value estimate with
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
which implies 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_2 \leqslant \frac{\sqrt{d \tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
\end{theorem}
\begin{proof}
Assuming all calls succeed. Define $\RV{\vec{Z}} = \vec{\RV{X}}-\vec{\mu'}$. Then we set the parameters to the the initial call to classical mean value estimator such that:
\begin{equation}
    \label{eq: multi_estimator_proof_1}
    \normtwo{\expect{\vec{\RV{Z}}}} = \normtwo{\expect{\vec{\RV{X}}}-\vec{\mu'}} \leqslant \frac{\sqrt{\tr \Sigma}}{5}
\end{equation}
Then quantile estimation returns some $K$ with:
\begin{equation}
    p \leqslant \prob{\normtwo{\vec{\RV{Z}}} \geqslant K} \leqslant Cp
\end{equation}
where $C$ is the parameter discussed in Quantum Estimation in Theorem~\ref{thm: quantile}. Thus we know that:
\begin{equation}
    \expect{\normtwo{\vec{\RV{Y}}}^2} \geqslant K^2 \times \prob{\normtwo{\vec{\RV{Z}}} \geqslant K} \geqslant K^2p
\end{equation}
Thus $p \leqslant \frac{\expect{\normtwo{\vec{\RV{Y}}}^2}}{K^2}$. By choosing the parameter for algorithm in Lemma~\ref{lemma: Ryan_useful_lemma} to be $\frac{3}{\sqrt{p}}$, we have obtained:
\begin{equation}
\left|s'^2-\frac{\expect{\normtwo{\vec{\RV{Y}}}^2}}{K^2}\right| \leqslant \frac{1}{3K}\sqrt{p\expect{\normtwo{\vec{\RV{Y}}}^2}} \leqslant \frac{1}{3} \frac{\expect{\normtwo{\vec{\RV{Y}}}^2}}{K^2}
\end{equation}
In other words,
\begin{equation}
\label{eq: multi_estimator_proof_2}
    \left|K^2s'^2-\expect{\normtwo{\vec{\RV{Y}}}^2}\right| \leqslant \frac{1}{3} \expect{\normtwo{\vec{\RV{Y}}}^2}
\end{equation}
Thus we know that $\frac{3}{2} K^2 s'^2 \geqslant \expect{\normtwo{\vec{\RV{Y}}}^2}$ is guarenteed to be true. 

Let the covariance matrix of $\vec{\RV{Y}}$ to be $\Sigma'$ thus $\tr \Sigma' = \expect{\normtwo{\vec{\RV{Y}} - \expect{\vec{\RV{Y}}}}^2} \leqslant \expect{\normtwo{\vec{\RV{Y}}}^2} \leqslant  \frac{3}{2} K^2 s'^2$. So we know that Algorithm~\ref{alg: not_so_multi_esimator} is successful and Theorem~\ref{thm: notso_multi_estimator} applies, which means we find mean estimate $\mu''$ with 
\begin{equation}
    \norm{\vec{\mu}'' - \expect{\vec{\RV{Y}}}}_\infty \leqslant \frac{\sqrt{3 / 2} K s'}{ n'}
\end{equation}

Now we would like an upper bound in the form of $\frac{3}{2} K^2 s'^2 \leqslant O\left( \tr \Sigma\right)$. Eq.~(\ref{eq: multi_estimator_proof_2}) also implies that $K^2 s'^2 \leqslant \frac{4}{3} \expect{\normtwo{\vec{\RV{Y}}}^2}$ so $ \frac{3}{2} K^2 s'^2 \leqslant 2 \expect{\normtwo{\vec{\RV{Y}}}^2}$. At the start of proof we found Eq.~(\ref{eq: multi_estimator_proof_1}) which gives:
\begin{equation}
    \label{eq: multi_estimator_proof_3}
    \expect{\normtwo{\vec{\RV{Y}}}^2} \leqslant \expect{\normtwo{\vec{\RV{Z}}}^2} = \tr \Sigma + \normtwo{\expect{\vec{\RV{Z}}}}^2 \leqslant \frac{26}{25} \tr \Sigma 
\end{equation}
Because $\vec{\RV{Z}}$'s covariance matrix is also $\tr \Sigma$. So $\frac{3}{2} K^2 s'^2 \leqslant \frac{52}{25} \tr \Sigma$. Our pick of $n' \geqslant 2 \sqrt{\frac{52}{25}} n$ ensures that:
\begin{equation}
\norm{\vec{\mu}'' - \expect{\vec{\RV{Y}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{ 2 n}
\end{equation}
Equivalently:
\begin{equation}
\label{eq: multi_estimator_proof_4}
\norm{\left(\vec{\mu}' + \vec{\mu}''\right) - \left(\expect{\vec{\RV{Y}}} + \vec{\mu}'\right)}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{ 2 n}
\end{equation}

Now we would like to bound the deviation between $\expect{\vec{\RV{Y}}} + \vec{\mu}'$ and $\expect{\vec{\RV{X}}}$. Remember that $\vec{\RV{Y}} = \truncate{\vec{\RV{Z}}}{K}$.By Cauchy Schwarz inequality, for all $\alpha \in [d]$ 
\begin{equation}
    \expect{\left|\left(\RV{Y}^\alpha + \mu'^\alpha\right) - \RV{X}^\alpha \right|} = \expect{\left|\RV{Y}^\alpha - \RV{Z}^{\alpha}\right|} \leqslant \sqrt{\expect{\left(\RV{Z}^\alpha\right)^2} \prob{\normtwo{\vec{\RV{Z}}}\geqslant K}} \leqslant \sqrt{\expect{\left(\RV{Z}^\alpha\right)^2} Cp} 
\end{equation}
Relaxing this bound, we obtain:
\begin{equation}
    \norm{\expect{\left(\vec{\RV{Y}} + \vec{\mu}'\right) - \vec{\RV{X}}}_\infty} \leqslant \sqrt{\expect{\normtwo{\vec{\RV{Z}}}^2} C p} \leqslant \sqrt{\frac{26}{25} Cp \tr \Sigma}
\end{equation}
where we have evoked part of Eq.~(\ref{eq: multi_estimator_proof_3}). By our pick of $p = \frac{25}{52C n^2}$, we obtain:
\begin{equation}
    \norm{\expect{\left(\vec{\RV{Y}} + \vec{\mu}'\right) - \vec{\RV{X}}}_\infty} \leqslant \frac{\sqrt{\tr \Sigma}}{ 2 n}
\end{equation}
Combined with Eq.~(\ref{eq: multi_estimator_proof_4}) we find:
\begin{equation}
\label{eq: multi_estimator_proof_5}
\norm{\left(\vec{\mu}' + \vec{\mu}''\right) - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{ n}
\end{equation}
All the above calls to the algorithms succeed with probability at least $1- \delta$ by union bound, so Eq.~(\ref{eq: multi_estimator_proof_5}) happens with probability at least $1 - \delta$. Thus we have reached our conclusion.

Calling classical estimator costs $O\left(\log \frac{1}{\delta}\right)$, quantile estimation costs $O\left(\frac{\log{\frac{4}{\delta}}}{\sqrt{p}}\right) = O\left(n \log \frac{1}{\delta}\right)$. Run algorithm in Lemma~\ref{lemma: Ryan_useful_lemma} also costs $O\left(n \log\frac{1}{\delta} \right)$. Calling Algorithm~\ref{alg: not_so_multi_esimator} costs $O\left(\log \frac{1}{\delta}\right)$ along with a call to $\mathcal{A}$ with parameters $(n, \delta)$ replaced with $\left(O(n), \Omega(\delta)\right)$. In terms of memory, one quantum register suffices for the quantum experiment as we can always reuse it. Combined the total cost is $O\left(n \log \frac{1}{\delta}\right)$ in time and $O(1)$ in memory, along with whatever needed for a call to $\mathcal{A}$ with parameters $(n, \delta)$ replaced with $\left(O(n), \Omega(\delta)\right)$.
\end{proof}

Now let's simply substituite Algorithm~\ref{alg: con_sim_estimator} and \ref{alg: con_mer_estimator} for our placeholder algorithm $\mathcal{A}$ and we obtain the final theorems for the paper. 

\begin{theorem}[Main Result for Simple Estimator]
\label{thm: sim_main}
Given quantum experiments for a multivariate random variable $\vec{\RV{X}}$ with unknown covariance matrix $\Sigma$, there is an efficient algorithm that outputs a mean estimate $\vec{\tilde{\mu}}$ such that:
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
which implies 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_2 \leqslant \frac{\sqrt{d \tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
The algorithm takes
\begin{itemize}
    \item $O\left(n d^\frac{1}{4} \log \frac{d}{\delta}\right)$ in terms accesses to the quantum experiment
    \item $O\left(1\right)$ in terms of quantum registers needed to hold quantum experiments.
\end{itemize}
\end{theorem}
\begin{proof}
    Follows directly from Theorem~\ref{thm: con_sim_estimator}, \ref{thm: con_sim_complexity}, and \ref{thm: generic_multi_main}.
\end{proof}

\begin{theorem}[Main Result for Meticulous Estimator]
\label{thm: mer_main}
Given quantum experiments for a multivariate random variable $\vec{\RV{X}}$ with unknown covariance matrix $\Sigma$, there is an efficient algorithm that outputs a mean estimate $\vec{\tilde{\mu}}$ such that:
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_\infty \leqslant \frac{\sqrt{\tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
which implies 
\begin{equation}
    \prob{\norm{\vec{\tilde{\mu}} - \expect{\vec{\RV{X}}}}_2 \leqslant \frac{\sqrt{d \tr \Sigma}}{n}} \geqslant 1 - \delta
\end{equation}
The algorithm takes
\begin{itemize}
    \item $O\left(n \log \frac{d}{\delta}\right)$ in terms accesses to the quantum experiment
    \item $O\left(\log n \log \log n\right)$ in terms of quantum registers needed to hold quantum experiments.
\end{itemize}
\end{theorem}
\begin{proof}
    Follows directly from Theorem~\ref{thm: con_mer_estimator}, \ref{thm: con_mer_complexity}, and \ref{thm: generic_multi_main}.
\end{proof}


\section{Discussion and Application}
\label{sec: discussion}




We have just completed mathematical derivations and found two separate multivaraite estimators. The Meticulous Estimator theoretically outperforms previous algorithms in Ref.~\cite{Cornelissen_2022}, eliminating almost all log factors. Meanwhile, the simple estimator offers a straight-forward solution in the regime where $\log n \gg d^\frac{1}{4}$ and is memory-efficient.  In this section we make detailed discussions about their implications and future prospects.


\subsection{Utilizing Quantum Monte Carlo Directly}

One of the noticeable feature of the entire logic chain presented in this work is the fact that it deviates from the original derivations of Ref.~\cite{Kothari_2022}. We proved a different, and arguably stronger property of the Grover operator in Theorem~\ref{thm: alpha_close} and start from here. The only part where the logic collides with Ref.~\cite{Kothari_2022} is the classical reduction for the univariate mean value estimator. Is this justified?

For the simple estimator which trades a quartic slowdown but for memory-efficiency, the answer is yes. Our property in Theorem~\ref{thm: alpha_close} shows closeness for the original values, as opposed to its counterpart in Ref.~\cite{Kothari_2022}, which only demonstrates closeness for the absolute values. This property allows us to bound the distance between states which is vital to allow for multidimensional phase estimation. 

For the merticulous estimator, the answer is mixed. In Sec.~\ref{sec: mer_estimator}, we practically provided a pipeline that takes in any univaraite estimator and spits out a multivariate estimator. The only restriction is that the univariate estimator must be a hybird (reversible) circuit, where we are not allowed to skip any part of the execution. In other words, we want the number of times we called the Grover operator in the phase estimation to be a constant, such that it is independent of each thread in the quantum parallelization in the final algorithm. The original work in Ref.\cite{Kothari_2022} does not have this property. Nevertheless, we might find ways to convert it into so by admitting some constant overhead. In that sense, the merticulous estimator can probably be constructed from Ref.~\cite{Kothari_2022} directly, with some more work. 

\subsection{The final $\log \frac{d}{\delta}$ factor}
\label{sec: log_1/2}
Even the meticulous estimator we found is still not quite optimal, as there is a $O(\log \frac{d}{\delta})$ factor in our complexity. It is probably more pleasant if we have instead something that goes like $O(\log \frac{1}{\delta})$, because then for a constant $\delta$ we would not suffer from an additional $O(\log d)$ for large $d$. Note that this factor essentially comes from the properties of multidimensional phase estimation in Algorithm~\ref{alg: phase_estimation}, as it output results with a constant success probability for each dimension separately. Coalescing these dimensions into the $\norm{}_\infty$ bound causes this extra factor which finds a way into our final result. 

To remove this factor, one may find ways to generalize the multidimensional phase estimation and potentially obtain something different. The nicest way is to think of the hypercubic lattice $G$ as the name suggests---a lattice in the real space. Then, multivariate phase estimation essentially tries to pinpoint the corresponding location of the unknown vector on the reciprocal lattice in momentum space. This allows us to generalize multidimension phase estimation expect $G$ doesn't have to be an orthogonal lattice. However, this still won't give us any progress. 


To navigate the issue, one could define multivariate phase estimation except the coordinates in $G$ are somehow chosen from a sphere. However, this choice loses translational symmetry in the lattice, which leads to complications. At best, we might only be able to work with some form of spherical harmonics transform instead of Fourier transform, but the meaning of ``phase estimation'' remains unclear in this setting. Even if we can do such, there is no guarantee that we will work with something such as $\expval{\vec u, \vec{\RV{X}}}$ in the phase, which is a linear function of $\vec{\RV{X}}$. The linearity in the phase is important because we have $\expect{\expval{\vec u, \vec{\RV{X}}}} = \expval{\vec u, \expect{\vec{\RV{X}}}}$. If we relinquish such linearity it is unlikely that we get anything useful. For such reasons optimizing on this $\log \frac{d}{\delta}$ might be very difficult. In fact, we conjecture that our result is optimal for the $\norm{}_\infty$ norm. 

\subsection{Practical Considerations}

As discussed in Sec.~\ref{sec: primitives}, in practice, what we are presented is usually some program that generates a superposition of all possible situations representing all the possibilities of the value we are trying to measure, as we defined as ``complete quantum experiment'' in Definition~\ref{def: complete_quantum_exp}. In this paper we partitioned such a program into two parts, the synthesizer $\mathcal{P}$ which generates all the possibilities, and the quantum experiment which computes the value for each possibility. In practice, however, it may not be simple to create such partition. A program might create different possibilities along its execution and there is no clean distinction between these two stages. One easy solution is to note that we never truely define each instance $\ket{k}$ for $k \in \Omega$ means. So we can simply absorb each instance $\vec{\mathcal{X}}_k$ as a part of $\ket{k}$. In other words, given complete quantum experiment $V$ we set $U = I$ and $P = V$. That resolves the issue. 

By now it has been quite evident it really shouldn't matter how we partitioned the entire program, the complete quantum experiment whatsoever, as found in the following observation:
\begin{remark}
After connecting all the steps we discussed to build the entire mean value estimation algorithm, we can write it in a way that only involves $V = U \mathcal{P}$ instead of $U$ or $\mathcal{P}$ individually.
\label{remark: join}
\end{remark}
To be more exact, we can coalesce adjacent Grover operators in the phase estimation step,  such that our phase estimation algorithm always uses $U \mathcal{P}$ and its adjoint except in the beginning and the end. We then notice that we start with $\ket{\bm{1}} = \mathcal{P}\ket{0}$ so we insert $\mathcal{P}$ in the beginning and we can also insert $\mathcal{P^\dag}$ in the end since it doesn't affect our measurement outcome. Thus, the entire algorithm only utilizes $V = U \mathcal{P}$. 

Thus, we can see that the partition we introduced in the paper is arbitrary and does not matter whatsoever. We can, say, set $\mathcal{P} = I$ and $U = V$, then the phase estimation still returns the correct answer. 

\subsection{Generalizations}

In Sec.~\ref{sec: primitives} we briefly discussed some examples of the quantum experiment, such as QCD simulation or QML circuit, where a classical analogue is not necessary. The more interesting case, however, is when we are working with multiple observables and we are trying to estimate their expectation respect to some state $\ket{\psi}$ simultaneously. This has been explored in Ref.~\cite{Huggins_2022}, where the authors found a quadratic speedup up to polylog factors when the spectral norm of the observables $\norm{O}_j$ is bounded by some constant, or different constants. Is there an way that we can utilize the ideas developed in this paper to tackle this situation?

The answer is mixed. The key difference for general observables is that we have no knowledge of the eigenbasis for the observables and are therefore unable to efficiently perform the post-processing of the variables. For $\arctan$ function, we might be able do the transformations with block encoding and signal processing methods \cite{Dalzell_2023}. This would admit $\text{polylog}(n)$ factors in the algorithm. Furthermore, we are not aware of efficient methods to implement truncation in this situation. Without truncation, we can only do the bounded case, except the upper bound is no longer a constant but scales inversely with the true mean, similar to conditions in Theorem~\ref{thm: alpha_close}. If one could find a way to implement truncation and analyze the overhead to implement $\arctan$ transformation, then this slight potential advantage might be generalized to tackle the case of general observables. 


\section{Conclusion}

In this paper, utilizing the idea from quantum Monte Carlo \cite{Kothari_2022}, we developed an efficient quantum multivariate mean value estimation algorithm that almost saturates the optimal bound discussed in Ref.~\cite{Cornelissen_2022}. We also discussed another memory-efficient estimator, which foundamentally originates from a stronger property of the Grover operator primitive compared to Quantum Monte Carlo. Compared to previous work \cite{Cornelissen_2022}, we eliminated (almost) all polylog factors that is feasible. We then discussed its applications and potential generalizations to the case of estimating expectation for generic observables.  

