    \begin{equation}\label{eq:dimension_p}
    \sum_{p'=0}^{p}x_{i,p'}dp_i + \sum_{p'=p+1}^{M}x_{i,p'}dd_i \leq D \quad\forall i\in \{0,\dots,M\}.% i\neq p.
