\begin{center}
{\Large {\bf Quantum First-Order Logics That Capture Logarithmic-Time/Space Quantum Computability}}\footnote{An extended abstract  \cite{Yam24} appeared in the Proceedings of
the 20th Conference on Computability in Europe (CiE 2024), Amsterdam, the Netherlands, July 8-12, 2024, Lecture Notes in Computer Science, vol. 14773, pp.  311--323, Springer, 2024.} \bs\ms\\

{\sc Tomoyuki Yamakami}\footnote{Present Affiliation: Faculty of Engineering, University of Fukui, 3-9-1 Bunkyo, Fukui 910-8507, Japan}
\bs\\
