\begin{example}\label{example-formula}
To promote the reader's understanding of quantum formulas,  we intend to present several simple examples of quantum formulas. In the first example, we assume that $|y|=|z|\geq2$.
In the third example, $|y|=|z|\geq3$ is assumed. The notation $i=j=k$ is a shorthand for $i=j\wedge j=k\wedge j=k$.
The special symbol ``$\equiv$'' is used to mean ``defined by''.

\renewcommand{\labelitemi}{$\circ$}
\begin{enumerate}\vs{-1}
  \setlength{\topsep}{-2mm}%
  \setlength{\itemsep}{1mm}%
  \setlength{\parskip}{0cm}%

\item $\PP_{copy}(y:z) \equiv (|y|=|z|)\wedge (\forall i\leq|y|) [ \PP_I(y[i]:z[i]) ]$.

\item $\PP_{NOT}(y:z) \equiv (|y|=|z|=1)\wedge \PP_{ROT_{\pi}}(y:z)$. (negation)

\item $\PP_{CNOT}(y:z) \equiv (|y|=|z|) \wedge \PP_{I}(y[1]:z[1])\wedge (z[1])[\PP_{I}(y[2]:z[2]) \mmid \PP_{NOT}(y[2]:z[2])] \wedge (\forall i,3\leq i\leq |y|)(\PP_{I}(y[i]:z[i]))$. In this way, we can express $CNOT$ (controlled NOT) in our quantum logical system. This is the reason why we have not included $\PP_{CNOT}$ as our basic predicate symbol.

\item $\PP_{CSWAP}(y:z) \equiv (|y|=|z|)\wedge \PP_{I}(y[1]:z[1])\wedge (z[1])[ \PP_{I}(y[2]:z[2]) \wedge \PP_{I}(y[3]:z[3]) \mmid \PP_{I}(y[2]:z[3])\wedge \PP_{I}(y[3]:z[2])] \wedge (\forall i,4\leq i\leq |y|)(\PP_{I}(y[i]:z[i]))$. (Controlled-SWAP)

\item $\PP_{WH}(y:z) \equiv (|y|=|z|)\wedge (\forall i\leq |y|) \PP_{ROT_{\pi/4}}(y[i]:z[i])$. (Walsh-Hadamard transform)

\item  $\PP_{\oplus}(y,z:v,w) \equiv (|y|=|z|=|w|)\wedge (\forall i\leq|y|) [\PP_{CNOT}(y[i]\otimes z[i]: v[i]\otimes w[i]) ]$. This $w$  classically expresses the bitwise XOR of $y$ and $z$.

\item $NEQ(y,z) \equiv (\exists^Q v,|v|=|y|)(\exists^Q w,|w|=|z|) [ \PP_{\oplus}(y,z:v,w)\wedge (\exists j\leq |w|)[w[j]\simeq_{\varepsilon}1] ]$. Classically, this expression indicates $y\neq z$.

  \item $ONE(y:z) \equiv (\exists i\leq |y|)[(y[i])[ (\forall k\leq |z|)\PP_I(1:z[k]) \mmid (\forall j<i) [ (y[j])[\PP_I(0:z[j]) \mmid \PP_I(1:z[j])] \wedge (\forall k,i<k\leq \ilog(n))[ (y[k])[\PP_I(0:z[k]) \mmid \PP_I(1:z[k]) ]]]$.
      %This will be used in the proof of Lemma \ref{LOGTIME-to-QFO}.

\item $MAJ_1(X)\equiv  (\exists^Qy,|y|=\ilog(n)) [ (\forall i\leq |y|) [\PP_{ROT_{\pi/4}}(0:y[i])] \wedge X(y)\simeq_{\varepsilon}1 ]$. This expression7 checks whether $X$ contains a large number of $1$s. Since the Walsh-Hadamard transform $WH$ works as $WH(\qubit{0^{\ilog(n)}}) = \frac{1}{\sqrt{\hat{n}}} \sum_{s\in\{0,1\}^{\ilog(n)}} \qubit{s} = \frac{1}{\sqrt{\hat{n}}} \sum_{i=1}^{\hat{n}} \qubit{s^{(\ilog(n))}_i}$, it thus follows that $\sum_{i=1}^{\hat{n}} \prob[\text{ $s^{(\ilog(n))}_i$-th bit of $x$ is $1$ }] = \#_1(x)/\hat{n}$, where $\#_b(x)$ denotes the total number of $b$ in $x$.
\end{enumerate}
\end{example}

