\subsection{Basic Properties}

In classical logic, there are numerous rules that help us simplify complicated logical formulas. For instance, de Morgan's law helps transform  $x\wedge (y\vee z)$ to its logically equivalent formula $(x\wedge y) \vee (x\wedge z)$.

%%%

\begin{lemma}\label{logical-AND}
(1) If $(P\wedge Q) \wedge R$ and $P\wedge (Q\wedge R)$
are well-formed, then
they are  semantically equivalent to each other.
(2) If $P\wedge (x[1])[Q_1\mmid Q_2]$ and $(x[1])[P\wedge Q_1\mmid P\wedge Q_2]$, then
they are semantically equivalent to each other.
\end{lemma}

%%%%

\begin{proof}
(1) This immediately follows from the fact that $eval[(P\wedge Q)\wedge R](\MM)=1$ is decomposed into $eval[P](\MM)=1$, $eval[Q](\MM)=1$, and $eval[R](\MM)=1$.

(2) This comes from the following facts: (i) $eval[P\wedge (x[1])[Q_1\mmid Q_2]](\MM,\rho_x)=1$ iff $eval[P](\MM)=1$ and $eval[(x[1])[Q_1\mmid Q_2](\MM,\rho_x)=1$, (ii) $eval[(x[1])[Q_1\mmid Q_2](\MM,\rho_x)=1$ iff $eval[Q_1](\MM,\rho_0,\rho_x)=1$ and $eval[Q_2](\MM,\rho_1,\rho_x)=1$, and (iii) for any $i\in\{0,1\}$, $eval[P\wedge Q_i](\MM,\rho_i,\rho_x)=1$ iff $eval[P](\MM)=1$ and $eval[Q_i](\MM,\rho_i,\rho_x)=1$.
\end{proof}

Similar to the equivalence relation ($\leftrightarrow$) in classical logic, its quantum analogue ($\Leftrightarrow$) is defined as follows: the expression $\phi\Leftrightarrow \psi$ is an abbreviation of the quantum formula $(y,|y|=1)[\phi\wedge \psi \mmid \neg^Q\phi\wedge \neg^Q\psi]$, where $y$ appears in neither $\phi$ nor $\psi$.

\begin{lemma}
$eval[\phi\Leftrightarrow\psi](\rho_y,\MM) =1$ iff the values of $eval[\phi](,\rho_y,\rho_y(0),\MM)$, $eval[\psi](\rho_y,\rho_y(0),\MM)$, $eval[\neg^Q\phi](\rho_y,\rho_y(1),\MM)$, and $eval[\neg^Q\psi](\rho_y,\rho_y(1),\MM)$ are all $1$, where $\rho_y(b)$ denotes $\alpha_b\qubit{b}$ for any bit $b\in\{0,1\}$ when $\rho_y=\sum_{u\in\{0,1\}}\alpha_u\qubit{u}$.
\end{lemma}

\begin{proof}
Assume that $eval[\phi\Leftrightarrow\psi](\rho_y,\MM)=1$. Since ``$\phi\Leftrightarrow \psi$'' is given by the use of the quantum OR, we obtain both $eval[\phi\wedge\psi](\rho_{y},\rho_y(0),\MM)=1$ and $eval[\neg^Q\phi\wedge \neg^Q\psi](\rho_{y},\rho_y(1),\MM)=1$. It then follows that the values of $eval[\phi](\rho_y,\rho_y(0),\MM)$, $eval[\psi](\rho_y,\rho_y(0),\MM)$,  $eval[\neg^Q\phi](,\rho_y,\rho_y(1),\MM)$, and $eval[\neg^Q\psi](\rho_y,\rho_y(1),\MM)$ are all $1$.
From these values, we conclude that $eval[\phi](\rho_y,\rho_y(0),\MM) =eval[\psi](\rho_y,\rho_y(0),\MM)$ and $eval[\neg^Q\phi](\rho_y,\rho_y(1),\MM) =eval[\neg^Q\psi](\rho_y,\rho_y(1),\MM)$.

On the contrary, we assume that the values of $eval[\phi](,\rho_y,\rho_y(0),\MM)$, $eval[\psi](\rho_y,\rho_y(0),\MM)$,  $eval[\neg^Q\phi](\rho_y,\rho_y(1),\MM)$, and $eval[\neg^Q\psi](\rho_y,\rho_y(1),\MM)$ are all $1$.
By the definition of the quantum AND, we obtain $eval[\phi\wedge \psi](\rho_y,\rho_y(0),\MM) =1$ and $eval[\neg^Q\phi\wedge \neg^Q\psi](\rho_y,\rho_y(1),\MM) =1$. From these values, we conclude that   $eval[\phi\Leftrightarrow \psi](\rho_y,\MM)=1$.
\end{proof}

In classical logic, the negation ($\neg$) can be suppressed to the elementary formulas. In a similar fashion, we can remove all quantum negations from each quantum formula.

\begin{definition}
A quantum formula $\phi$ is said to be \emph{negation free} if the quantum NOT ($\neg^Q$) does not appear in $\phi$.
\end{definition}

Definition \ref{evaluation} immediately yields the following simple fact.

\begin{lemma}\label{negation-free}
Given a quantum formula $\phi$, there exists another quantum formula $\phi'$ such that $\phi'$ is semantically equivalent to $\phi$ and $\phi'$ is negation free.
\end{lemma}

We intend to expand the quantum OR so that it can handle multiple qubits in the conditional part.

\begin{lemma}\label{multi-quantumOR}
Let $m\in\nat^{+}$ and let $Y_m = (y_1[e_1],y_2[e_2],\ldots,y_m[e_m])$. The expression $(Y_m)[P_{0^m}\mmid P_{0^{m-1}1}\mmid \cdots \mmid P_{1^m}]$ means that if $Y_m$ evaluates to the $k$th string $s_{k}^{(m)}$ of $\{0,1\}^m$, then $P_{s_{k}^{(m)}}$ is true. This expression is expressible within  $\mathrm{classicQFO}$.
\end{lemma}

\begin{proof}
We inductively define the desired quantum formula. When $m=1$, since $Y_1$ coincides with $y_1[e_1]$, $(Y_1)[P_{0}\mmid P_{1}]$ is the same as the (standard) quantum OR. Consider the case of $m\geq2$.
We define $(Y_m)[P_{0^m}\mmid P_{0^{m-1}1}\mmid \cdots \mmid P_{1^m}]$ to be $(y_1[e_1])[R_0 \mmid R_1]$ with $R_0\equiv (y_2[e_2],\ldots,y_m[e_m])[P_{0^m}\mmid P_{0^{m-1}1}\mmid \cdots \mmid P_{01^{m-1}}]$ and $R_1\equiv (y_2[e_2],\ldots,y_m[e_m])[P_{10^{m-1}}\mmid P_{10^{m-2}1}\mmid \cdots \mmid P_{1^{m}}]$. It is not difficult to show that this is equivalent to  $(Y_m)[P_{0^m}\mmid P_{0^{m-1}1}\mmid \cdots \mmid P_{1^m}]$.
\end{proof}

For later convenience, we call the above form of quantum OR for multiple qubits by the \emph{multi quantum OR}.

\begin{proposition}\label{multi-quantum-OR-prop}
The expression $(y[e_1,e_2])[\{P_u\}_{u\in\{0,1\}^m}]$ with $e_2-e_1+1=2^m$ means that, if $y[e_1,e_2]$ evaluates to a string $u\in\{0,1\}^m$, then $P_u$ is true. This expression is expressible within $\mathrm{classicQFO}$.
\end{proposition}

\begin{proof}
Note that $|y[e_1,e_2]|=2^m$. Hence, we set $Y_{2^m}=(y[e_1],y[e_1+1],\ldots,y[e_2])$ and consider $(Y_{2^m})[\{P_u\}_{u\in\{0,1\}^m}]$. Lemma \ref{multi-quantumOR} implies the desired proposition.
\end{proof}

Even in the framework of quantum first-order logic, it is possible to simulate the classical connectives $\wedge$ (AND) and $\vee$ (OR) indirectly.

\begin{lemma}
Assuming that $x,y,z,u,v,w$ are variables representing qubits.

(1) If these variables represent classical bits, then there exists a formula $R_{AND}$ such that $R_{AND}(x,y,z: u,v,w)$ is true iff $x=u$, $y=v$, and $w= (x\wedge y)\oplus z$ are all true.

(2) If these variables represent classical bits, then there exists a formula $R_{OR}$ such that $R_{OR}(x,y,z: u,v,w)$ is true iff $x=u$, $y=v$, and $w= (x\vee y)\oplus z$ are all true.
\end{lemma}

\begin{proof}
By Proposition \ref{multi-quantum-OR-prop}, we can freely use the multi quantum OR.

(1) We define $R_{AND}(x,y,z: u,v,w)$ to be $\PP_{I}(x: u)\wedge \PP_{I}(y: v)\wedge (\exists^Qp,|p|=1) ((x,y)[Q_{00}\mmid Q_{01}\mmid Q_{10}\mmid Q_{11}])$, where $Q_{s}\equiv \PP_{\oplus}(0,z:p,w)$ for all $s\in\{00,01,10\}$ and $Q_{11}\equiv \PP_{\oplus}(1,z:p,w)$.

(2) We define $R_{OR}(x,y,z: u,v,w)$ to be $\PP_{I}(x:u)\wedge \PP_{I}(y:v)\wedge (\exists^Q p,|p|=1) ( (x,y)[Q'_{00}\mmid Q'_{01}\mmid Q'_{10}\mmid Q'_{11}])$, where $Q'_{00}\equiv \PP_{\oplus}(0,z:p,w)$ and $Q'_{s}\equiv \PP_{\oplus}(1,z:p,w)$ for any $s\in\{01,10,11\}$.
\end{proof}

