Due to the non-transitivity of $\varepsilon$-equivalence, we cannot simply group a factor $\phi$ with a group of $\varepsilon$-equivalent factors $\boldsymbol G = \{ \phi_1, \allowbreak \dots, \allowbreak \phi_k \}$ if $\phi$ is $\varepsilon$-equivalent to any $\phi_i \in \boldsymbol G$.
Doing so would give rise to the issue of cascading errors, that is, in the worst case, completely different factors could be grouped together (e.g., assuming $\varepsilon = 0.1$, the potential $1.0$ can be grouped with the potential $0.9$, which itself can be grouped with the potential $0.81$, and so on).
To avoid cascading errors, we thus ensure a factor $\phi$ is only added to a group of $\varepsilon$-equivalent factors $\boldsymbol G$ if $\phi$ is $\varepsilon$-equivalent to \emph{all} factors in $\boldsymbol G$.

Next, we need to solve the problem of changing the potentials for every group of pairwise $\varepsilon$-equivalent factors $\boldsymbol G = \{ \phi_1, \dots, \phi_k \}$.
To exploit exponentiation and thus avoid looking at every factor individually, the changes must ensure that all factors map to the same potentials.
At the same time, we aim to minimise the approximation error, that is, we want to apply the smallest possible change to the potentials.
Formally, the goal is to find $\phi^*$ such that
\begin{align}
	\phi^* = \argmin_{\phi_j} \sum_{\phi_i \in \boldsymbol G} Err(\phi_i, \phi_j), \label{eq:eacp_argmin_potential_change}
\end{align}
where $Err(\phi_i, \phi_j)$ is the sum of squared deviations between the potentials of $\phi_i$ and $\phi_j$:
\begin{align}
	Err(\phi_i, \phi_j) = \sum_{r_1, \ldots, r_n} \Big( \phi_i(r_1, \ldots, r_n) - \phi_j(r_1, \ldots, r_n) \Big)^2, \label{eq:eacp_error_between_factors}
\end{align}
with $r_1, \ldots, r_n$ denoting the possible assignments of the arguments of $\phi_i$ and $\phi_j$.\footnote{Recall that we assume $\pi$ from \cref{def:eacp_epsilon_equivalence} to be the identity function. In case $\pi$ is not the identity function, we end up with $Err(\phi_i, \phi_j) = \sum_{r_1, \ldots, r_n} ( \phi_i(r_1, \ldots, r_n) - \phi_j(r_{\pi(1)}, \ldots, r_{\pi(n)}) )^2$.}
To obtain identical potentials within a group $\boldsymbol G = \{ \phi_1, \dots, \phi_k \}$, our goal is to update the factors in $\boldsymbol G$ such that $\phi_1 = \phi^*, \dots, \phi_k = \phi^*$.

Thus, we now solve the problem of finding $\phi^*$.
In fact, it holds that for any set of numbers $\{ \varphi_1, \ldots, \varphi_k \}$, the arithmetic mean $\bar{\varphi} = \frac{1}{k} \sum_{i=1}^{k} \varphi_i$ minimises the sum of squared deviations $\sum_{i=1}^{k} (\varphi_i - \bar{\varphi})^2$, i.e., replacing $\bar{\varphi}$ by any other value would increase the sum of squared deviations.
\begin{restatable}{theorem}{eacpMeanMinimisesSumSquaredTheorem} \label{th:eacp_mean_minimal_sum_squared}
	Let $\varphi_1, \ldots, \varphi_k \in \mathbb{R}^+$.
	It holds that the arithmetic mean $\bar{\varphi} = \frac{1}{k} \sum_{i=1}^{k} \varphi_i$ is the optimal choice for $\varphi^* = \argmin_{\hat{\varphi}} \sum_{i=1}^{k} (\varphi_i - \hat{\varphi})^2$.
\end{restatable}
\Cref{th:eacp_mean_minimal_sum_squared} is a well-known property of the arithmetic mean (a proof is given in \cref{appendix:eacp_missing_proofs}).
As \cref{eq:eacp_argmin_potential_change} aims to minimise a sum over a sum of squared deviations $Err(\phi_i, \phi_j)$, the sum in \cref{eq:eacp_argmin_potential_change} becomes minimal if we minimise $Err(\phi_i, \phi_j)$, i.e., the right hand side of \cref{eq:eacp_error_between_factors}, according to \cref{th:eacp_mean_minimal_sum_squared}.
Therefore, for any group $\boldsymbol G = \{ \phi_1, \dots, \phi_k \}$ of pairwise $\varepsilon$-equivalent factors, we set $\phi_1 = \phi^*, \dots, \phi_k = \phi^*$ such that
\begin{align}
	\phi^*(\boldsymbol r) = \frac{1}{k} \sum_{i=1}^{k} \phi_i(\boldsymbol r) \label{eq:eacp_mean_potential}
\end{align}
for all possible assignments $\boldsymbol r = r_1, \ldots, r_n$ to ensure that all factors in $\boldsymbol G$ map to the same potentials while minimising the cumulative squared deviation of the group $\boldsymbol G$.

Next, we compile the insights on finding and grouping $\varepsilon$-equivalent factors into the \ac{eacp} algorithm, which paves the way to apply lifted model construction in practice.

\subsection{The \texorpdfstring{$\boldsymbol \varepsilon$}{e}-Advanced Colour Passing Algorithm} \label{sec:eacp_algorithm}

\begin{algorithm}[t]
	\caption{$\varepsilon$-Advanced Colour Passing}
	\label{alg:eacp_eacp}
	\alginput{An \ac{fg} $M = (\boldsymbol R \cup \boldsymbol \Phi, \boldsymbol E)$, a hyperparameter \\\hspace*{\algorithmicindent} $\varepsilon \in \mathbb{R}^+$, and a set of observed events (evidence) $\boldsymbol O = \\\hspace*{\algorithmicindent} \{ E_1 = e_1, \ldots, E_{\ell} = e_{\ell} \}$.} \\
	\algoutput{A lifted representation $M'$, encoded as a \ac{pfg}, \\\hspace*{\algorithmicindent} which is approximately equivalent to $M$.}
	\begin{algorithmic}[1]
		\LeftComment{Phase I: Find groups of pairwise $\varepsilon$-equivalent factors}\;
		\State $\boldsymbol G \gets \{ \{ \phi_1 \} \}$\;
		\ForEach{factor $\phi_i \in \boldsymbol \Phi \setminus \{ \phi_1 \}$}
			\State $\boldsymbol C \gets \emptyset$\; \label{line:eacp_initialise_candidates}
			\ForEach{group $\boldsymbol G_j \in \boldsymbol G$} \label{line:eacp_for_each_loop_candidates}
				\If{$\forall \phi_k \in \boldsymbol G_j \colon \phi_i =_{\varepsilon} \phi_k$} \label{line:eacp_check_eps_equiv}
					\State $\boldsymbol C \gets \boldsymbol C \cup \{ \boldsymbol G_j \}$\; \label{line:eacp_add_to_candidates}
				\EndIf
			\EndFor
			\If{$\boldsymbol C \neq \emptyset$}
				\State $\boldsymbol G_j \gets \argmin_{\boldsymbol C_i \in \boldsymbol C} \sum_{\phi_j \in \boldsymbol C_i} Err(\phi_i, \phi_j)$\; \label{line:eacp_argmin_group_candidates}
				\State $\boldsymbol G_j \gets \boldsymbol G_j \cup \{ \phi_i \}$\; \label{line:eacp_add_to_existing_group}
			\Else \label{line:eacp_if_create_new_group}
				\State $\boldsymbol G \gets \boldsymbol G \cup \{ \{ \phi_i \} \}$\; \label{line:eacp_add_to_new_group}
			\EndIf
		\EndFor
		\LeftComment{Phase II: Assign colours to factors and run \ac{acp}}\;
		%\State Assign each $\phi_i \in \boldsymbol \Phi$ a colour based on its group\;
		\ForEach{group $\boldsymbol G_j \in \boldsymbol G$}
			\ForEach{factor $\phi_i \in \boldsymbol G_j$}
				\State $\phi_i.colour \gets j$\;
			\EndFor
		\EndFor
		\State $\boldsymbol G' \gets$ Call \ac{acp} on $M$ and $\boldsymbol O$ using the assigned colours\;\label{line:eacp_call_acp}
		\LeftComment{Phase III: Update potentials}\;
		\ForEach{group $\boldsymbol G_j \in \boldsymbol G'$} \label{line:eacp_for_each_loop_update_potentials}
			\State $\phi^*(\boldsymbol r) \gets \frac{1}{\abs{\boldsymbol G_j}} \sum_{\phi_i \in \boldsymbol G_j} \phi_i(\boldsymbol r)$ for all assignments $\boldsymbol r$\; \label{line:eacp_mean_potential}
			\ForEach{factor $\phi_i \in \boldsymbol G_j$} \label{line:eacp_for_each_loop_update_potentials_factors}
				\State $\phi_i \gets \phi^*$\; \label{line:eacp_update_potentials}
			\EndFor
		\EndFor
		\State $M' \gets$ construct \ac{pfg} from groupings of \ac{acp}\; \label{line:eacp_eacp_pfg_construction}
	\end{algorithmic}
\end{algorithm}

The \ac{eacp} algorithm consists of three phases and is described in \cref{alg:eacp_eacp}.
In the first phase, \ac{eacp} computes groups of factors that are pairwise $\varepsilon$-equivalent.
For every factor $\phi_i$ in the input \ac{fg}, \ac{eacp} checks whether it can be added to an existing group or if a new group has to be created.
As it is possible for $\phi_i$ to be $\varepsilon$-equivalent to all factors of multiple existing groups (e.g., in \cref{tab:example_eps_equiv}, $\phi_2$ could be grouped both with $\{ \phi_1 \}$ and $\{ \phi_3 \}$), \ac{eacp} computes all candidate groups $\boldsymbol C$ (\cref{line:eacp_initialise_candidates,line:eacp_for_each_loop_candidates,line:eacp_check_eps_equiv,line:eacp_add_to_candidates}) and then adds $\phi_i$ to the group that minimises the sum of squared deviations between $\phi_i$ and all factors in the group (\cref{line:eacp_argmin_group_candidates,line:eacp_add_to_existing_group}).
If $\phi_i$ cannot be added to an existing group, \ac{eacp} creates a new group for $\phi_i$ (\cref{line:eacp_add_to_new_group}).
Then, in the second phase, \ac{eacp} assigns to every factor a colour based on the group it belongs to, that is, all factors within the same group receive the same colour (and factors in different groups receive different colours).
Factors within the same group could potentially be grouped together in a lifted representation if their arguments are indistinguishable.
To ensure the factors' arguments are indistinguishable, \ac{eacp} runs the \ac{acp} algorithm using the previously assigned colours (instead of \ac{acp}'s original colour assignment).
% It is also possible to incorporate evidence of observed events.
By running \ac{acp} with the assigned colours, \ac{eacp} ensures that in addition to the potential tables, the surrounding graph structure of the factors is taken into account, thereby enforcing that the arguments of factors within a group are indistinguishable (more details on this are given in \cref{appendix:eacp_acp_in_detail}).
Finally, in phase three, \ac{eacp} updates the potentials of every group of factors computed by \ac{acp} according to \cref{eq:eacp_mean_potential} to ensure that all factors in a group have identical potential tables (\cref{line:eacp_for_each_loop_update_potentials,line:eacp_mean_potential,line:eacp_for_each_loop_update_potentials_factors,line:eacp_update_potentials}).
As potentials within a group are now strictly equal, the corresponding \ac{pfg} is constructed from the groups as in the original \ac{acp} algorithm.\footnote{For a detailed description of the \ac{pfg} construction in \cref{line:eacp_eacp_pfg_construction} of \cref{alg:eacp_eacp}, we refer the reader to \citet{Luttermann2024a}.}
Commonly used lifted inference algorithms, such as \acl{lve}, operate on \acp{pfg} and thus can directly be run on the output of \ac{eacp}.\footnote{We remark that $\varepsilon$-equivalence can also be applied to exploit approximate symmetries \emph{within} factors that map assignments of their arguments to identical potentials independent of the order of the assigned values (for more details, see \cref{appendix:eacp_approximate_symmetries_within_factors}).}
\begin{example} \label{ex:eacp_example_eacp}
	Take a look at the \ac{fg} given in \cref{fig:eacp_example_fg} and assume the potential tables of $\phi_1$ and $\phi_2$ are as given in \cref{tab:example_eps_equiv_mappings} (i.e., $\varphi_1 = 0.75$, $\varphi'_1 = 0.8$, and so on).
	Further, let $\varepsilon = 0.1$ and assume we do not have any evidence, i.e., $\boldsymbol O = \emptyset$.
	As $\phi_1$ and $\phi_2$ are $\varepsilon$-equivalent, \ac{eacp} puts them into the same group and after the first phase, \ac{eacp} ends up with $\boldsymbol G = \{ \{ \phi_1, \phi_2 \} \}$.
	Then, \ac{acp} is called with $\phi_1$ and $\phi_2$ having the same colour, and after passing the colours around, $\phi_1$ and $\phi_2$ remain in the same group because their surrounding graph structure is symmetric (and thus, their arguments are indistinguishable).
	After the third phase, the potential tables are updated by computing a row-wise arithmetic mean, that is, $\varphi_1 = \varphi'_1 = (0.75 + 0.8) \mathbin{/} 2 = 0.775$, $\varphi_2 = \varphi'_2 = 0.315$, $\varphi_3 = \varphi'_3 = 0.49$, and $\varphi_4 = \varphi'_4 = 0.21$.
\end{example}
The \ac{eacp} algorithm takes a fundamental step towards the practical applicability of lifted inference algorithms by generalising the \ac{acp} algorithm to account for inaccurate estimates of potentials, which are abundant in practice.
In particular, it holds that \ac{eacp} is identical to \ac{acp} when setting $\varepsilon$ to zero because $\varepsilon$-equivalence reduces to strict equivalence if $\varepsilon = 0$.
\begin{restatable}{corollary}{eacpGeneralisationCorollary}
	If $\varepsilon = 0$, \ac{eacp} returns the same \ac{pfg} as \ac{acp}.
\end{restatable}
So far, we have shown how $\varepsilon$-equivalent factors can be grouped and updated to enable lifted inference with a minimal approximation error.
As we show later, the approximation error is often even negligible in practice.
To get an initial idea about the extent of the approximation error, consider \cref{ex:eacp_example_eacp} and the query $P(SalA \mid Rev = \high)$.
In the original \ac{fg}, we obtain $P(SalA \mid Rev = \high) \approx \langle 0.6098, 0.3902 \rangle$ and after running \ac{eacp}, we have $P(SalA \mid Rev = \high) \approx \langle 0.6126, 0.3874 \rangle$.
An essential question now is how much query results can change in general when using the approximate lifted representation instead of the initial exact \ac{fg} for query answering.
We answer this question next.

\section{Bounding the Change in Query Results} \label{sec:eacp_theoretical}
We now bound the change in query results when modifying a given \ac{fg} by grouping and updating the potentials of $\varepsilon$-equivalent factors according to \cref{alg:eacp_eacp}.
For the sake of our analysis, let $M$ denote the input for \cref{alg:eacp_eacp} and $M'$ the output of \cref{alg:eacp_eacp} such that $M$ encodes the distribution $P_M$ and $M'$ encodes the distribution $P_{M'}$.
In our analysis, we use the following distance measure between two distributions $P_M$ and $P_{M'}$ introduced by \citet{Chan2005a}:
\begingroup
\allowdisplaybreaks
\begin{align}
	D(P_M, P_{M'}) &= \ln \max_{\boldsymbol r} \frac{P_{M'}(\boldsymbol r)}{P_M(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{P_{M'}(\boldsymbol r)}{P_M(\boldsymbol r)} \label{eq:eacp_distance_measure} \\
	&= \ln \max_{\boldsymbol r} \frac{\frac{1}{Z'} \psi'(\boldsymbol r)}{\frac{1}{Z} \psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\frac{1}{Z'} \psi'(\boldsymbol r)}{\frac{1}{Z} \psi(\boldsymbol r)} \\
	&= \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)}, \label{eq:eacp_distance_measure_only_joint_potential}
\end{align}
\endgroup
where we define $0 \mathbin{/} 0 := 1$ and $\infty \mathbin{/} \infty := 1$.
$D$ satisfies important properties of a distance measure (positiveness, symmetry, and the triangle inequality) and a major advantage of $D$ is that it allows us to bound the change in query results, which is not possible with other common distance measures such as the \acl{kld}~\citep{Chan2005a}.
In particular, if it holds that $D(P_M, P_{M'}) = d$, the change in a query result is bounded by
\begin{align} \label{eq:eacp_distance_bound_odds}
	e^{-d} \leq \frac{O_{M'}(r \mid \boldsymbol e)}{O_M(r \mid \boldsymbol e)} \leq e^d,
\end{align}
where $O_M(r \mid \boldsymbol e) = P_M(r \mid \boldsymbol e) \mathbin{/} (1 - P_M(r \mid \boldsymbol e))$ defines the odds of $r$ given $\boldsymbol e$.
We can also write \cref{eq:eacp_distance_bound_odds} in terms of probabilities instead of odds and obtain
\begin{align}
	\frac{p e^{-d}}{p(e^{-d} -1) + 1} \leq P_{M'}(r \mid \boldsymbol e) \leq \frac{p e^{d}}{p(e^{d} -1) + 1}, \label{eq:eacp_error_bound_prob}
\end{align}
where $p = P_M(r \mid \boldsymbol e)$ is the initial probability of $r$ given $\boldsymbol e$ in model $M$ and $P_{M'}(r \mid \boldsymbol e)$ is the probability of $r$ given $\boldsymbol e$ in the modified model $M'$~\citep{Chan2005a}.
The bounds given in \cref{eq:eacp_distance_bound_odds,eq:eacp_error_bound_prob} are sharp. %, that is, for every $P_M$ and $P_{M'}$, there is a query such that equality holds.
To obtain a bound on the change in query results, we thus need to determine the value of $d = D(P_M, P_{M'})$ for a given choice of $\varepsilon$.
In general, the normalisation constant $Z$ changes when modifying the original model $M$.
Rewriting \cref{eq:eacp_distance_measure} as \cref{eq:eacp_distance_measure_only_joint_potential}, however, allows us to avoid dealing with the change from $Z$ to $Z'$ (a full derivation is given in \cref{appendix:eacp_missing_proofs}).

We next give a general bound on the distance $D(P_M, P_{M'})$ that applies to arbitrary \acp{fg} $M$ where updates of factors resulting in an \ac{fg} $M'$ ensure that all factors in $M'$ remain $\varepsilon$-equivalent to their original values after the update.
