\begin{restatable}{theorem}{eacpErrorBoundTheorem} \label{th:eacp_error_bound_given_eps}
	Let $M = (\boldsymbol R \cup \boldsymbol \Phi, \boldsymbol E)$ be an \ac{fg} and let $M'$ be an \ac{fg} obtained by updating arbitrary potentials of factors in $M$ such that every updated potential remains $\varepsilon$-equivalent to its original value.
	%for every group $\boldsymbol G$ of pairwise $\varepsilon$-equivalent factors in $M$, every factor in $\boldsymbol G$ remains pairwise $\varepsilon$-equivalent to all original factors of $\boldsymbol G$ in $M$ after the update.
	Then, it holds that $D(P_M, P_{M'}) \leq \ln\ (1 + \varepsilon)^m - \ln\ (1 - \varepsilon)^m$, where $P_M$ and $P_{M'}$ are the underlying full joint probability distributions encoded by $M$ and $M'$, respectively, and $m = \abs{\boldsymbol \Phi}$.
\end{restatable}
\begin{proof}[Proof Sketch]
	By definition, every potential in $M'$ differs from its original value in $M$ by factor at most $(1 \pm \varepsilon)$.
	Adding a deviation by factor $(1 \pm \varepsilon)$ to every potential in $M'$ and entering this into \cref{eq:eacp_distance_measure_only_joint_potential} yields the desired result.
\end{proof}
\begin{corollary} \label{co:eacp_pairwise_odds_bound}
	Given the bound from \cref{th:eacp_error_bound_given_eps}, \cref{eq:eacp_distance_bound_odds} leads to
	\begin{align} \label{eq:eacp_distance_specific_estimate}
		\left( \frac{1 - \varepsilon}{1 + \varepsilon} \right)^m \leq \frac{O_{M'}(r \mid \boldsymbol e)}{O_M(r \mid \boldsymbol e)} \leq \left( \frac{1 + \varepsilon}{1 - \varepsilon} \right)^m.
	\end{align}
\end{corollary}
% \Cref{th:eacp_error_bound_given_eps} provides a general bound for any update of potentials ensuring that groups of pairwise $\varepsilon$-equivalent remain pairwise $\varepsilon$-equivalent after the update.
% In particular, replacing a group of pairwise $\varepsilon$-equivalent by their arithmetic mean $\phi^*$ fulfils this property.\footnote{Choosing $\phi^*$ as the median factor or any other factor from the group also fulfils this property and hence, the bound from \cref{th:eacp_error_bound_given_eps} applies in these cases as well.}
% Since our grouping condition requires all factors in a group to be pairwise $\varepsilon$-equivalent, it holds that all potentials of any two factors from the same group differ by factor at most $(1 \pm \varepsilon)$.
% Consequently, after updating the potentials within a group according to \cref{eq:eacp_mean_potential}, every updated potential $\varphi^*$ lies within the interval $[\varphi_i \cdot (1 - \varepsilon), \varphi_i \cdot (1 + \varepsilon)]$ for any original potential $\varphi_i$ from the group.
The next lemma shows that updating the potentials within a group of pairwise $\varepsilon$-equivalent factors according to \cref{eq:eacp_mean_potential} satisfies the premise of \cref{th:eacp_error_bound_given_eps} and hence, the bound given in \cref{th:eacp_error_bound_given_eps} holds if $M'$ is the output of \cref{alg:eacp_eacp} run on $M$.
\begin{restatable}{lemma}{pairwiseEquivalenceGroupMeanLemma} \label{lemma:eacp_mean_in_group_equivalence}
	Let $\boldsymbol G = \{ \phi_1, \dots, \phi_k \}$ denote a group of pairwise $\varepsilon$-equivalent factors and let $\phi^*(\boldsymbol r) = \frac{1}{k} \sum_{i=1}^{k} \phi_i(\boldsymbol r)$ for all assignments $\boldsymbol r$.
	Then, $\boldsymbol G^* = \{ \phi_1, \dots, \phi_k, \phi^* \}$ is a group of pairwise $\varepsilon$-equivalent factors.
\end{restatable}
\begin{proof}[Proof Sketch]
	As for the arithmetic mean $\phi^*(\boldsymbol r)$ it holds that $\min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \leq \phi^*(\boldsymbol r) \leq \max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r)$ and all $\phi_i, \phi_j \in \boldsymbol G$ are pairwise $\varepsilon$-equivalent, it follows that $\phi^*(\boldsymbol r) \in [\phi_i(\boldsymbol r) \cdot (1 - \varepsilon), \phi_i(\boldsymbol r) \cdot (1 + \varepsilon)]$ and $\phi_i(\boldsymbol r) \in [\phi^*(\boldsymbol r) \cdot (1 - \varepsilon), \phi^*(\boldsymbol r) \cdot (1 + \varepsilon)]$ for any assignment $\boldsymbol r$ and $\phi_i \in \boldsymbol G$.
\end{proof}
\Cref{lemma:eacp_mean_in_group_equivalence} implies that all updated potentials for every factor differ by factor at most $(1 \pm \varepsilon)$ from their original potential after running \cref{alg:eacp_eacp}.
To obtain a bound on the change in query results depending on the choice of $\varepsilon$, we enter the bound from \cref{th:eacp_error_bound_given_eps} into \cref{eq:eacp_error_bound_prob}. %\footnote{Note that the bound is independent of the \ac{fg}'s graph structure.}
\Cref{fig:bound_plot} provides plots of the bound for different values of $\varepsilon$ and $m = \abs{\boldsymbol \Phi}$ to give a better idea on how the bound behaves.
Observe that $\varepsilon = 0.01$ yields a strong bound for $m = 10$, however, from $m = 100$ onward, the bound becomes weak (in particular, for $m = 1000$, the change in query results is essentially unbounded when choosing $\varepsilon = 0.01$).
When choosing $\varepsilon = 0.001$, the bound remains strong for $m = 100$, however, for $m = 1000$, the bound weakens as well.
% The lesson from \cref{fig:bound_plot} is that the more factors exist in an \ac{fg}, the smaller $\varepsilon$ has to be chosen to obtain a strong bound as with more factors, more potentials might differ from their original values in the worst case.
Fortunately, the bound from \cref{th:eacp_error_bound_given_eps} is overly pessimistic for the output of \cref{alg:eacp_eacp}, as we show in the following.
\begin{lemma} \label{le:smallimprovment}
	For two $\varepsilon$-equivalent factors $\phi_1$ and $\phi_2$, it holds that $\phi_1 \in [\phi_2 \cdot \frac{1}{1 + \varepsilon}, \phi_2 \cdot (1 + \varepsilon)]$ and $\phi_2 \in [\phi_1 \cdot \frac{1}{1 + \varepsilon}, \phi_1 \cdot (1 + \varepsilon)]$.
\end{lemma}
\begin{proof}
	Due to the symmetric definition of $\varepsilon$-equivalence, we get $\phi_{2-i} \leq \phi_{i+1} \cdot (1 + \varepsilon)$ for $i \in \{ 0, 1 \}$, resulting in $\phi_{2-i} \cdot \frac{1}{1 + \varepsilon} \leq \phi_{i+1}$.
	Since $1 - \varepsilon \leq \frac{1}{1 + \varepsilon}$ holds for any $\varepsilon > 0$, $\phi_{2-i}$ is contained in the strict subset $[\phi_{i+1} \cdot \frac{1}{1 + \varepsilon}, \phi_{i+1} \cdot (1 + \varepsilon)] \subsetneq [\phi_{i+1} \cdot (1 - \varepsilon), \phi_{i+1} \cdot (1 + \varepsilon)]$.
\end{proof}
Using \cref{le:smallimprovment} and the properties of the arithmetic mean, we obtain the following stronger bound on $D(P_M, P_{M'})$.
\begin{restatable}{theorem}{lowerboundeacpErrorBoundTheorem} \label{th:lowerboundeacp_error_bound_given_eps}
	Let $M = (\boldsymbol R \cup \boldsymbol \Phi, \boldsymbol E)$ be an \ac{fg} and let $M'$ be the output of \cref{alg:eacp_eacp} when run on $M$. With $P_M$ and $P_{M'}$ being the underlying full joint probability distributions encoded by $M$ and $M'$, respectively, and $m = \abs{\boldsymbol \Phi}$, it holds that
	\begin{align}
		D(P_M, P_{M'})   &\leq %\ln \prod_{j=1}^{m} \frac{\left(1+\frac{m-k_j}{m-k_j+1}\varepsilon\right)\cdot (1+\varepsilon)}{1+\frac{\varepsilon}{k_j+1}}\\
		%&\leq \ln\left(\left(\frac{\left(1+\frac{m-k^*}{m-k^*+1}\varepsilon\right)\cdot (1+\varepsilon)}{1+\frac{\varepsilon}{k^*+1}}\right)^m\right) \\
		%&\leq 
		\ln\left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^m\\
		&=\ln\left(\frac {\big( 1+\frac{m-1}{m}\varepsilon \big) \big( 1+\varepsilon \big)}{1+\frac{1}{m}\varepsilon}\right)^m\\
		&< \ln \big( 1 + \varepsilon \big)^{2m} \\
		&< \ln \left(\frac{1+\varepsilon}{1-\varepsilon}\right)^m.
	\end{align}
\end{restatable}
\begin{corollary} \label{co:smallinequalitywithimprovedbound}
	Given the bound from \cref{th:lowerboundeacp_error_bound_given_eps}, \cref{eq:eacp_distance_bound_odds} leads to
	\begin{align} \label{eq:eacp_distance_specific_estimate_moreprecise}
	\left(\frac{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon} }{1+\frac{m-1}{m}\varepsilon}\right)^m \leq \frac{O_{M'}(r \mid \boldsymbol e)}{O_M(r \mid \boldsymbol e)} \leq \left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^m.
	\end{align}
\end{corollary}
We give a proof of \cref{th:lowerboundeacp_error_bound_given_eps} in \cref{appendix:eacp_missing_proofs}.
The plot of the bound from \cref{th:lowerboundeacp_error_bound_given_eps} looks similar to the plot of \cref{th:eacp_error_bound_given_eps} (see \cref{fig:bound_plot}) and is optimal (i.e., it is the best bound we can find).
\begin{restatable}{theorem}{optimalBoundTheorem}
	The bound given in \cref{th:lowerboundeacp_error_bound_given_eps} is optimal.
\end{restatable}
\begin{proof}[Proof Sketch]
	We construct an \ac{fg} hitting the boundary from \cref{th:lowerboundeacp_error_bound_given_eps}.
	For the construction, see \cref{tab:example_worst_case} in \cref{appendix:eacp_missing_proofs}.
\end{proof}
