\section{Missing Proofs} \label{appendix:eacp_missing_proofs}
\eacpMeanMinimisesSumSquaredTheorem*
\begin{proof}
	Let $\hat{\varphi}$ denote an arbitrary estimate for $\varphi^*$ and let $\bar{\varphi} = \frac{1}{k} \sum_{i=1}^{k} \varphi_i$ denote the arithmetic mean of $\varphi_1, \ldots, \varphi_k$.
	We now show that choosing $\hat{\varphi} = \bar{\varphi}$ minimises the expression $\sum_{i=1}^{k} (\varphi_i - \hat{\varphi})^2$.
	Since $\bar{\varphi} - \bar{\varphi} = 0$, we can add it without changing the result and then rewrite the expression:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\sum_{i=1}^{k} \big( \varphi_i - \hat{\varphi} \big)^2 \\
		= &\sum_{i=1}^{k} \Big( \varphi_i - \hat{\varphi} + (\bar{\varphi} - \bar{\varphi}) \Big)^2 \\
		= &\sum_{i=1}^{k} \Big( (\varphi_i - \bar{\varphi}) + (\bar{\varphi} - \hat{\varphi}) \Big)^2 \\
		= &\sum_{i=1}^{k} \Big( \big( \varphi_i - \bar{\varphi} \big)^2 + 2 \big( \varphi_i - \bar{\varphi} \big) \big( \bar{\varphi} - \hat{\varphi} \big) + \big( \bar{\varphi} - \hat{\varphi} \big)^2 \Big) \\
		= &\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2 + \sum_{i=1}^{k} 2 \big( \varphi_i - \bar{\varphi} \big) \big( \bar{\varphi} - \hat{\varphi} \big) + \sum_{i=1}^{k} \big( \bar{\varphi} - \hat{\varphi} \big)^2 \\
		= &\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2 + 2 \big( \bar{\varphi} - \hat{\varphi} \big) \sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big) + k \big( \bar{\varphi} - \hat{\varphi} \big)^2. \label{eq:eacp_sum_squared_rewritten}
	\end{align}
	\endgroup
	Due to $\bar{\varphi} = \frac{1}{k} \sum_{i=1}^{k} \varphi_i$ being the arithmetic mean of $\varphi_1, \allowbreak \ldots, \allowbreak \varphi_k$, it holds that $\sum_{i=1}^{k} (\varphi_i - \bar{\varphi}) = 0$:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)
		&= \sum_{i=1}^{k} \varphi_i - k \cdot \bar{\varphi} \\
		&= \sum_{i=1}^{k} \varphi_i - k \cdot \frac{1}{k} \sum_{i=1}^{k} \varphi_i \\
		&= 0.
	\end{align}
	\endgroup
	By entering $\sum_{i=1}^{k} (\varphi_i - \bar{\varphi}) = 0$ into \cref{eq:eacp_sum_squared_rewritten}, we thus obtain
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2 + 2 \big( \bar{\varphi} - \hat{\varphi} \big) \sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big) + k \big( \bar{\varphi} - \hat{\varphi} \big)^2 \\
		= &\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2 + k \big( \bar{\varphi} - \hat{\varphi} \big)^2. \label{eq:eacp_before_mean_enter}
	\end{align}
	\endgroup
	Now, if we set $\hat{\varphi} = \bar{\varphi}$, it holds that $\bar{\varphi} - \hat{\varphi} = 0$ and hence, \cref{eq:eacp_before_mean_enter} simplifies to
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2 + k \big( \bar{\varphi} - \hat{\varphi} \big)^2 \\
		= &\sum_{i=1}^{k} \big( \varphi_i - \bar{\varphi} \big)^2.
	\end{align}
	\endgroup
	Choosing $\hat{\varphi}$ different from $\bar{\varphi}$ thus increases the value of the expression by $k (\bar{\varphi} - \hat{\varphi})^2$, which completes the proof.\footnote{\Cref{th:eacp_mean_minimal_sum_squared} is a well-known property of the arithmetic mean and there are different ways to prove this property. The proof given here is taken from \url{http://faculty.washington.edu/swithers/seestats/SeeingStatisticsFiles/seeing/center/meanproof/meanProof.html}.}
\end{proof}

\eacpGeneralisationCorollary*
\begin{proof}
	Let $\varepsilon = 0$.
	Recall that two potentials $\varphi \in \mathbb{R}^+$ and $\varphi' \in \mathbb{R}^+$ are $\varepsilon$-equivalent if $\varphi \in [\varphi' \cdot (1 - \varepsilon), \varphi' \cdot (1 + \varepsilon)]$ and $\varphi' \in [\varphi \cdot (1 - \varepsilon), \varphi \cdot (1 + \varepsilon)]$.
	Now, as $\varepsilon = 0$, $\varphi$ and $\varphi'$ are $\varepsilon$-equivalent if $\varphi = \varphi'$.
	In consequence, when running \ac{eacp} (\cref{alg:eacp_eacp}) on an arbitrary input \ac{fg} $M$, in the first phase all groups of $\varepsilon$-equivalent factors contain only factors whose potentials are strictly equivalent.
	Therefore, in phase two of \ac{eacp}, only factors with equivalent potentials receive the same colour and hence, the colour assignment is identical to the colour assignment of \ac{acp} (\cref{alg:eacp_acp}).
	Then, \ac{eacp} calls \ac{acp} and as the colour assignment of \ac{eacp} to factors is identical to the colour assignment of \ac{acp}, phase one of \ac{eacp} has no impact on the output of \ac{acp}.
	It remains to be shown that the update of potentials in phase three of \ac{eacp} does not alter the output of \ac{acp}.
	As all factors in any group have strictly equivalent potentials already and the arithmetic mean of a set of equal numbers $\varphi, \ldots, \varphi$ is $\varphi$ itself, the update in phase three does not alter the output of \ac{acp}.
	Hence, \ac{eacp} ends up with the same groups as \ac{acp} and therefore outputs the same \ac{pfg} as \ac{acp}, which completes the proof.
\end{proof}

\paragraph{Full derivation of writing \cref{eq:eacp_distance_measure} as \cref{eq:eacp_distance_measure_only_joint_potential}:}
\begingroup
\allowdisplaybreaks
\begin{align} \label{eq:eacp_distance_measure_without_z}
	&\phantom{=~} D(P_M, P_{M'}) \\
	&= \ln \max_{\boldsymbol r} \frac{P_{M'}(\boldsymbol r)}{P_M(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{P_{M'}(\boldsymbol r)}{P_M(\boldsymbol r)} \\
	&= \ln \max_{\boldsymbol r} \frac{\frac{1}{Z'} \psi'(\boldsymbol r)}{\frac{1}{Z} \psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\frac{1}{Z'} \psi'(\boldsymbol r)}{\frac{1}{Z} \psi(\boldsymbol r)} \\
	&= \ln \left( \frac{\frac{1}{Z'}}{\frac{1}{Z}} \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} \right) - \ln \left( \frac{\frac{1}{Z'}}{\frac{1}{Z}} \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} \right) \\
	&= \ln \frac{\frac{1}{Z'}}{\frac{1}{Z}} + \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \frac{\frac{1}{Z'}}{\frac{1}{Z}} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} \\
	&= \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)}
\end{align}
\endgroup

\paragraph{Full derivation of writing \cref{eq:eacp_distance_bound_odds} as \cref{eq:eacp_error_bound_prob}.}
Remember that $O_M(r \mid \boldsymbol e) = P_M(r \mid \boldsymbol e) \mathbin{/} (1 - P_M(r \mid \boldsymbol e))$ defines the odds of $r$ given $\boldsymbol e$.
Entering the definition of the odds into \cref{eq:eacp_distance_bound_odds} then results in
\begin{align}
	e^{-d} \leq \frac{P_{M'}(r \mid \boldsymbol e) \mathbin{/} (1 - P_{M'}(r \mid \boldsymbol e))}{P_M(r \mid \boldsymbol e) \mathbin{/} (1 - P_M(r \mid \boldsymbol e))} \leq e^d,
\end{align}
which can be rewritten as
\begin{align}
	e^{-d} \leq \frac{P_{M'}(r \mid \boldsymbol e)}{1 - P_{M'}(r \mid \boldsymbol e)} \cdot \frac{1 - P_M(r \mid \boldsymbol e)}{P_M(r \mid \boldsymbol e)} \leq e^d.
\end{align}
With $p = P_M(r \mid \boldsymbol e)$ and $p' = P_{M'}(r \mid \boldsymbol e)$, we obtain
\begin{align}
	e^{-d} \leq \frac{p' (1 - p)}{p (1 - p')} \leq e^d.
\end{align}
Multiplying by $p (1 - p')$ (which is always positive) yields
\begin{align}
	e^{-d} p (1 - p') \leq p' (1 - p) \leq e^d p (1 - p').
\end{align}
Expanding the terms gives us
\begin{align}
	e^{-d} p - e^{-d} p p' \leq p' - p' p \leq e^d p - e^d p p'.
\end{align}
By rearranging the terms, we end up with
\begin{align}
	e^{-d} p &\leq p' - p' p + e^{-d} p p' \\
	&= p' (1 - p + e^{-d} p),~\text{and} \\
	e^d p &\geq p' - p' p + e^d p p' \\
	&= p' (1 - p + e^d p).
\end{align}
Dividing by $1 - p + e^{-d} p$ and $1 - p + e^d p$ (both terms are always positive), respectively, results in
\begin{align}
	\frac{e^{-d} p}{1 - p + e^{-d} p} &\leq p',~\text{and} \\
	\frac{e^d p}{1 - p + e^d p} &\geq p'.
\end{align}
By rearranging the terms once more, we obtain
\begin{align}
	\frac{p e^{-d}}{p (e^{-d} - 1) + 1} &\leq p' \leq \frac{p e^d}{p (e^d - 1) + 1}.
\end{align}

\eacpErrorBoundTheorem*
\begin{proof}
	Let $\boldsymbol \Phi = \{ \phi_1, \ldots, \phi_m \}$ denote the set of factors in $M$.
	By definition, it holds that every updated potential $\varphi'$ in $M'$ differs by factor at most $(1 \pm \varepsilon)$ from its original potential $\varphi$ in $M$, independent of the distribution of the groups (that is, it is irrelevant whether all $m$ factors are in the same group or whether groups are distributed otherwise).
	Therefore, as $\psi(\boldsymbol r) = \prod_{j=1}^{m} \phi_j(\boldsymbol r_j)$ for any assignment $\boldsymbol r$, we obtain
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\psi'(\boldsymbol r) &\geq \prod_{j=1}^{m} \phi_j(\boldsymbol r_j) \cdot (1 - \varepsilon),~\text{and} \\
		\psi'(\boldsymbol r) &\leq \prod_{j=1}^{m} \phi_j(\boldsymbol r_j) \cdot (1 + \varepsilon).
	\end{align}
	\endgroup
	In consequence, we get the following bounds:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} &\geq \frac{\prod\limits_{j = 1}^m \big( \phi_j(\boldsymbol r_j) \cdot (1 - \varepsilon) \big)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)},~\text{and} \\
		\max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} &\leq \frac{\prod\limits_{j = 1}^m \big( \phi_j(\boldsymbol r_j) \cdot (1 + \varepsilon) \big)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)},
	\end{align}
	\endgroup
	where $\boldsymbol r_j$ is a projection of \emph{any} assignment $\boldsymbol r$ to the argument list of $\phi_j$.
	Entering these bounds into \cref{eq:eacp_distance_measure_only_joint_potential} then yields
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\phantom{=~} &D(P_M, P_{M'}) \\
		= &\ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} \\
		\leq &\ln \frac{\prod\limits_{j = 1}^m \big( \phi_j(\boldsymbol r_j) \cdot (1 + \varepsilon) \big)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)}
		- \ln \frac{\prod\limits_{j = 1}^m \big( \phi_j(\boldsymbol r_j) \cdot (1 - \varepsilon) \big)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)} \\
		= &\ln \frac{(1 + \varepsilon)^m \prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)}
		- \ln \frac{(1 - \varepsilon)^m \prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)} \\
		= &\ln\ (1 + \varepsilon)^m - \ln\ (1 - \varepsilon)^m.
	\end{align}
	\endgroup
\end{proof}

\pairwiseEquivalenceGroupMeanLemma*
\begin{proof}
	We show the claim in two directions by proving that $\phi^*(\boldsymbol r) \in [\phi_i(\boldsymbol r) \cdot (1 - \varepsilon), \phi_i(\boldsymbol r) \cdot (1 + \varepsilon)]$ and $\phi_i(\boldsymbol r) \in [\phi^*(\boldsymbol r) \cdot (1 - \varepsilon), \phi^*(\boldsymbol r) \cdot (1 + \varepsilon)]$ for any assignment $\boldsymbol r$ and $\phi_i \in \boldsymbol G$.

	For the first direction, let $\boldsymbol r$ be an arbitrary assignment and let $\phi_i \in \boldsymbol G$.
	As all factors in $\boldsymbol G$ are pairwise $\varepsilon$-equivalent, it holds that $\phi_i(\boldsymbol r) \cdot (1 - \varepsilon) \leq \min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r)$ and $\max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \leq \phi_i(\boldsymbol r) \cdot (1 + \varepsilon)$.
	Further, as $\phi^*(\boldsymbol r)$ is the arithmetic mean over all $\phi_j(\boldsymbol r) \in \boldsymbol G$, it holds that $\min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \leq \phi^*(\boldsymbol r) \leq \max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r)$ and thus $\phi^*(\boldsymbol r) \in [\phi_i(\boldsymbol r) \cdot (1 - \varepsilon), \phi_i(\boldsymbol r) \cdot (1 + \varepsilon)]$.

	For the second direction, it holds that for any assignment $\boldsymbol r$, every $\phi_i \in \boldsymbol G$ is contained in the interval $[\phi_j(\boldsymbol r) \cdot (1 - \varepsilon), \phi_j(\boldsymbol r) \cdot (1 + \varepsilon)]$ for any $j \in \{ 1, \ldots, k \}$, and thus also in the smallest possible composite interval $[\max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \cdot (1 - \varepsilon), \min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \cdot (1 + \varepsilon)]$. With the same argument as before, namely that for the arithmetic mean $\phi^*(\boldsymbol r)$ we have $\min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \leq \phi^*(\boldsymbol r) \leq \max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r)$, the composite interval $[\max_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \cdot (1 - \varepsilon), \min_{\phi_j \in \boldsymbol G} \phi_j(\boldsymbol r) \cdot (1 + \varepsilon)]$ is a subset of the interval $[\phi^*(\boldsymbol r) \cdot (1 - \varepsilon), \phi^*(\boldsymbol r)\cdot (1 + \varepsilon)]$ and hence, $\phi_i(\boldsymbol r) \in [\phi^*(\boldsymbol r) \cdot (1 - \varepsilon), \phi^*(\boldsymbol r) \cdot (1 + \varepsilon)]$.
\end{proof}

\lowerboundeacpErrorBoundTheorem*
\begin{proof}
	Let $\boldsymbol \Phi = \{ \phi_1, \ldots, \phi_m \}$ denote the set of factors in $M$, representing the distribution of $M$ via $P_M(\boldsymbol r) = \frac{1}{Z} \psi(\boldsymbol r) = \frac{1}{Z} \prod_{j=1}^{m} \phi_j(\boldsymbol r_j)$ for an assignment $\boldsymbol r = (r_1, \ldots, r_n) \in \times_{i=1}^n \range{R_i}$ to the \acp{rv} in $\boldsymbol R$.
	On the level of potentials, this means that for a specific assignment $\boldsymbol r$, there exist $j_i$, $i \in \{ 1, \ldots, m \}$, such that $\psi(\boldsymbol r) = \prod_{i=1}^{m} \varphi_{j_i,i}$, where $\varphi_{j,i}$ represents the potential in the $j^{th}$ row in the potential table of factor $\phi_i$.
	For $\phi^*(\boldsymbol r) = \frac{1}{m} \sum_{i=1}^{m} \phi_i(\boldsymbol r)$, its potentials $\varphi^*_{j} = \frac{1}{m} \sum_{i=1}^{m} \varphi_{j,i}$ are given by the row-wise arithmetic mean over all factors and thus are independent of $i$.

	According to \cref{lemma:eacp_mean_in_group_equivalence}, $\phi^*$ is pairwise $\varepsilon$-equivalent to all $\phi_i$ of a group of pairwise $\varepsilon$-equivalent factors.
	We first prove the claim for the case where all factors $\{ \phi_1, \ldots, \phi_m \}$ belong to the same group of pairwise $\varepsilon$-equivalence factors and afterwards generalise the proof to arbitrary distributions of groups.

	By ordering the potentials of every row $j$, we adopt, without loss of generality, the notation
	\begin{align}
		\varphi_{j,1} \leq \ldots \leq \varphi_{j,k_j} \leq \varphi_j^* \leq \varphi_{j,k_j + 1} \leq \ldots \leq \varphi_{j,m}
	\end{align}
	with $k_j \in \{ 1, \ldots, m-1 \}$.
	% Our goal is now to determine how much any $\varphi_{j,i}$ might differ from its original value in the worst case after updating it with the arithmetic mean $\varphi_j^*$.
	% Since $\varphi_{j,1}$ and $\varphi_{j,m}$ are the smallest and largest values of the group, respectively, we are interested how much they differ after the update in the worst case.
	% We begin to consider the smallest potential $\varphi_{j,1}$.
	Since $\varphi_{j,i}\geq \varphi_j^*$ holds already for $ i=k_j+1,\ldots,m$, we want to determine a minimal $\alpha_2(j) \in \mathbb{R}_{\geq 1}^+$ such that also $\varphi_{j,i} \cdot \alpha_2 \geq \varphi_j^*$ holds for all $ i=1,\ldots,m$. This means that $\varphi_j^* \leq \min_{i=1,\ldots,m} \varphi_{j,i}\cdot \alpha_2(j) =\varphi_{j,1}\cdot \alpha_2(j)$ has to hold. The minimal possible constant to fulfil this equation is $\alpha_2(j):= \frac{\varphi_j^*}{\varphi_{j,1}}$. In order to get the value of this constant, we have to assume the worst case scenario for the distribution of the $\varphi_{j,i}$'s. Therefore, we are looking for a small $\varphi_{j,1}$ and the largest $\varphi_j^*$, which is $\varphi_j^* = \frac{1}{m}\sum_{i=1}^{m} \varphi_{j,i}$ and $\varphi_{j,1}(1+\varepsilon) \geq \max_{i=1,\ldots,m}\varphi_{j,i}=\varphi_{j,m}$ according to the definition of $\varepsilon$-equivalence. Under these conditions, the maximal $\varphi_j^*$ is possible by the choice of $\varphi_{j,i}:= \varphi_j^*$ for $i=2,\ldots,k_j$ and $\varphi_{j,i}:= (1+\varepsilon)\varphi_{j,1}$ for $i=k_j+1,\ldots,m$. This results in the following mean
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\varphi_j^* &= \frac{1}{m}\left(\varphi_{j,1} + \sum_{i=2}^{k_j} \varphi_{j,i} + \sum_{i=k_j+1}^{m} \varphi_{j,1}(1+\varepsilon) \right)\\
		&=  \frac{1}{m}\Big(\varphi_{j,1} + (k_j-1)\varphi_j^* +(1+\varepsilon)(m-k_j)\varphi_{j,1}\Big),
	\end{align}
	\endgroup
	which is equivalent to
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\varphi_j^*& \left(1-\frac{k_j-1}{m} \right) = \frac{1}{m} \varphi_{j,1}\big(1+(m-k_j)(1+\varepsilon) \big)\\
		\Leftrightarrow \varphi_j^*& = \frac{1}{m-k_j+1} \varphi_{j,1}\big(1+(m-k_j)(1+\varepsilon) \big)\\
		%\Leftrightarrow&\varphi_j^* 
		&= \frac{m-k_j+1+(m-k_j)\varepsilon}{m-k_j+1} \varphi_{j,1}\\
		%\Leftrightarrow&\varphi_j^* 
		&= \left(1+\frac{m-k_j}{m-k_j+1}\varepsilon\right)\varphi_{j,1}.
	\end{align}
	\endgroup
	This results in $\alpha_2(j) = \left(1+\frac{m-k_j}{m-k_j+1}\varepsilon\right)>1$ for a $k_j\in \{1,\ldots,m-1\}$. Within this condition, $k_j=1$ leads to the largest $\varepsilon$-amount for $\alpha_2 = \left(1+\frac{m-1}{m}\varepsilon\right)$ in the worst case and therefore for any assignment independently of $j$.

	The estimation of a second constant $\alpha_1(j)$ as a lower constant works similar.
	Since $\varphi_{j,i}\leq \phi_j^*$ for $i=1,\ldots,k_j$ holds already, we determine a maximal $\alpha_1(j)\in \mathbb{R}^+_{\leq 1}$ such that $\varphi_{j,i}\leq \varphi_j^*$ holds for all $i=1,\ldots,m$. This means that $\varphi_j^*\geq \max_{i=1,\ldots,m} \varphi_{j,i}\cdot \alpha_1(j)=\varphi_{j,m}\cdot \alpha_1(j)$.
	The maximal possible constant is $\alpha_1(j):= \frac{\varphi_j^*}{\varphi_{j,m}}$.
	For the worst case scenario for the distribution of the $\varphi_{j,i}$'s, we get a large $\varphi_{j,m}$ and a low $\varphi_j^*$ and according to \cref{le:smallimprovment} this means $\varphi_{j,m} \cdot \frac{1}{1+\varepsilon}\leq \min_{i=1,\ldots,m}\varphi_{j,i}$. A minimal $\varphi_j^*$ can be reached by the choice of $\varphi_{j,i}:=\varphi_j^*$ for $i=k_j+1,\ldots,m$ and $\varphi_{j,i}:=\varphi_{j,m}\frac{1}{1+\varepsilon}$ for $i=1,\ldots,k_j$. This results in
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\varphi_j^* &= \frac{1}{m}\left(\sum_{i=1}^{k_j} \varphi_{j,m}\frac{1}{1+\varepsilon} + \sum_{i=k_j+1}^{m-1} \varphi_j^* +\varphi_{j,m} \right)\\
		&= \frac{1}{m} \left( \frac{k_j}{1 + \varepsilon} \varphi_{j,m} + (m - k_j - 1) \varphi_j^* + \varphi_{j,m} \right),
	\end{align}
	\endgroup
	which is equivalent to
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\varphi_j^*& \left(1-\frac{m-k_j-1}{m} \right) = \frac{1}{m}\left(\frac{k_j}{1+\varepsilon}+1\right)\varphi_{j,m}\\
		\Leftrightarrow \varphi_j^*& = \frac{1}{m} \frac{1}{1-\frac{m-k_j-1}{m}} \left(\frac{k_j}{1+\varepsilon}+1\right)\varphi_{j,m}\\
		&= \frac{1}{k_j+1}\frac{k_j+1+\varepsilon}{1+\varepsilon} \varphi_{j,m}\\
		&= \left(1+\frac{1}{k_j+1}\varepsilon\right)\frac{1}{1+\varepsilon} \varphi_{j,m}.
	\end{align}
	\endgroup
	This results in $1>\alpha_1(j)=\left(1+\frac{1}{k_j+1}\varepsilon\right)\frac{1}{1+\varepsilon}\geq \frac{1}{1+\varepsilon}$ for $k_j\in \{1,\ldots,m-1\}$, which is minimal for $k_j=m-1$, leading to $\alpha_1=\left(1+\frac{1}{m}\varepsilon\right)\frac{1}{1+\varepsilon}$ in the worst case for any assignment and independently of $j$.

	If we combine these calculations, we obtain
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\psi'(\boldsymbol r) &\geq \prod_{j=1}^{m} \phi_j(\boldsymbol r_j) \cdot \alpha_1,~\text{and} \\
		\psi'(\boldsymbol r) &\leq \prod_{j=1}^{m} \phi_j(\boldsymbol r_j) \cdot \alpha_2.
	\end{align}
	\endgroup
	In consequence, we get the following bounds:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} &\geq \frac{\prod\limits_{j = 1}^m  \phi_j(\boldsymbol r_j) \cdot \alpha_1}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)},~\text{and} \\
		\max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} &\leq \frac{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j) \cdot \alpha_2}{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)},
	\end{align}
	\endgroup
	where $\boldsymbol r_j$ is a projection of \emph{any} assignment $\boldsymbol r$ to the argument list of $\phi_j$.
	Entering these bounds into \cref{eq:eacp_distance_measure_only_joint_potential} then yields
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\phantom{=} D(P_M, P_{M'}) \\
		&= \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} \\
		&\leq \ln \frac{\prod\limits_{j = 1}^m  \phi_j(\boldsymbol r_j) \cdot \alpha_2 }{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)}
		- \ln \frac{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j) \cdot \alpha_1 }{\prod\limits_{j = 1}^m \phi_j(\boldsymbol r_j)} \\
		&= \ln \prod_{j=1}^{m} \alpha_2 - \ln \prod_{j=1}^{m} \alpha_1\\
		&= \ln \left(\frac{\alpha_2}{\alpha_1}\right)^m\\
		&= \ln\left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^m\\
		&= \ln \left(1+\frac{m-1}{m}\varepsilon\right)^m\left(\frac{1+\varepsilon}{1+\frac{\varepsilon}{m}}\right)^m \\
		&=\ln\left(\frac {\big( 1+\frac{m-1}{m}\varepsilon \big) \big( 1+\varepsilon \big)}{1+\frac{1}{m}\varepsilon}\right)^m\\
		&< \ln\ \big( 1 + \varepsilon \big)^{2m} \\
		&< \ln \left(\frac{1+\varepsilon}{1-\varepsilon}\right)^m.
	\end{align}
	\endgroup
	Next, we consider the general case of having an arbitrary distribution of groups of pairwise $\varepsilon$-equivalent factors.
	More specifically, let the factors now be distributed into $k \geq 2$ groups of pairwise $\varepsilon$-equivalent factors, meaning there is a set of summands $\{m_1,\ldots,m_k\}\in \mathbb{N}^k$ with $\sum_{i=1}^{k} m_i= m$ and $\phi_1,\ldots,\phi_{m_1}$ being pairwise $\varepsilon$-equivalent, $\phi_{m_1+1},\ldots,\phi_{m_1+m_2}$ being pairwise $\varepsilon$-equivalent, and so on. Since the previous case holds for a group of fully pairwise $\varepsilon$-equivalent factors we can apply this case $k$ times to get the maximal boundary as follows.
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\phantom{=} D(P_M,P_{M'}) \\
		&= \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)}\\
		&\leq \ln \prod_{j=1}^{m_1} \frac {1+\frac{m_1-1}{m_1}\varepsilon}{\frac{1+\frac{1}{m_1}\varepsilon}{1+\varepsilon}}\cdot\ldots\cdot \prod_{j=1}^{m_k} \frac {1+\frac{m_k-1}{m_k}\varepsilon}{\frac{1+\frac{1}{m_k}\varepsilon}{1+\varepsilon}}\\
		&= \ln \left(\frac {1+\frac{m_1-1}{m_1}\varepsilon}{\frac{1+\frac{1}{m_1}\varepsilon}{1+\varepsilon}}\right)^{m_1} \cdot\ldots\cdot
		\left(\frac {1+\frac{m_k-1}{m_k}\varepsilon}{\frac{1+\frac{1}{m_k}\varepsilon}{1+\varepsilon}}\right)^{m_k}
	\end{align}
	\endgroup
	Since $1+\frac{m_i-1}{m_i}\varepsilon < 1+\frac{m-1}{m}\varepsilon$ holds for the numerator and $\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}< \frac{1+\frac{1}{m_i}\varepsilon}{1+\varepsilon}$ holds for the denominator for every $i=1,\ldots,k$ due to $m_i<m$, we can bound each sub-product individually from above by
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\left(\frac {1+\frac{m_i-1}{m_i}\varepsilon}{\frac{1+\frac{1}{m_i}\varepsilon}{1+\varepsilon}}\right)^{m_i}< \left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^{m_i}.
	\end{align}
	\endgroup
	Putting everything back together yields the desired result:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		&\phantom{=} D(P_M,P_{M'}) \\
		&\leq \ln \left(\frac {1+\frac{m_1-1}{m_1}\varepsilon}{\frac{1+\frac{1}{m_1}\varepsilon}{1+\varepsilon}}\right)^{m_1} \cdot\ldots\cdot
		\left(\frac {1+\frac{m_k-1}{m_k}\varepsilon}{\frac{1+\frac{1}{m_k}\varepsilon}{1+\varepsilon}}\right)^{m_k}\\
		& < \ln \prod_{i=1}^{k} 
		\left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^{m_i}\\
		%&= \prod_{i=1}^{k} \left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^{m_i}\\
		&=\ln \left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^{\sum_{i=1}^{k} m_i}\\
		&=\ln \left(\frac {1+\frac{m-1}{m}\varepsilon}{\frac{1+\frac{1}{m}\varepsilon}{1+\varepsilon}}\right)^m,
	\end{align}
	\endgroup
	which implies due to the strict inequality, in particular, that the second case of multiple groups of pairwise $\varepsilon$-equivalent factors cannot reach the upper bound.
\end{proof}

\optimalBoundTheorem*
