	\centering
	\input{files/example_worst_case.tex}
	\caption{A construction of an exemplary \ac{fg} $M$ such that running \cref{alg:eacp_eacp} on $M$ to obtain $M'$ results in $D(P_M, P_{M'})$ becoming maximal and reaching the boundary given in \cref{th:lowerboundeacp_error_bound_given_eps}.}
	\label{tab:example_worst_case}
\end{table*}
\begin{proof}
	We show that the boundary of \cref{th:lowerboundeacp_error_bound_given_eps} can be reached by constructing an \ac{fg} $M$ such that running \cref{alg:eacp_eacp} on $M$ to obtain $M'$ results in $D(P_M, P_{M'})$ hitting the boundary.
	Consider the outcome of \cref{alg:eacp_eacp} for the \ac{fg} $M = (\boldsymbol R \cup \boldsymbol \Phi, \boldsymbol E)$ whose factors are depicted in \cref{tab:example_worst_case}.
	More specifically, the set of \acp{rv} is given by $\boldsymbol R = \{ R_1, \ldots, R_m \}$ with $\range{R_1} = \ldots = \range{R_m} = \{ r_1, \ldots, r_{2m} \}$, and the set of factors is defined as $\boldsymbol \Phi = \{ \phi_1(R_i), \ldots, \phi_m(R_m) \}$ (i.e., every factor has exactly one \ac{rv} as argument and the arguments of all factors are distinct).
	The set of edges is given by $\boldsymbol E = \{ \{R_1, \allowbreak \phi_1\}, \allowbreak \ldots, \allowbreak \{R_m, \allowbreak \phi_m\} \}$ but is not relevant for the proof.
	All factors in $\boldsymbol \Phi$ are pairwise $\varepsilon$-equivalent and hence end up in the same group after running \cref{alg:eacp_eacp}.

	Therefore, after updating the potentials, all factors in $\boldsymbol \Phi$ are replaced by the arithmetic mean $\phi^* = (\varphi^*_{1}, \ldots, \varphi^*_{2m})$ (shown in the rightmost column of \cref{tab:example_worst_case}) such that
	\begin{align}
		\varphi^*_{r} =
		\begin{cases}
			r \big( 1 + \frac{1}{m} \varepsilon \big) & \text{for } r = 1, \ldots, m \\
			r \big( 1 + \frac{m-1}{m} \varepsilon \big) & \text{for } r = m+1 ,\ldots, 2m.
		\end{cases}
	\end{align}
	We next compute $\min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)}$.
	By definition, it holds that $\psi'(\boldsymbol r) = \prod_{i=1}^{m} \phi^*(\boldsymbol r)$.
	To obtain the minimum quotient, the denominator thus must be maximal while at the same time keeping the arithmetic mean small, which is the case for the diagonal entries $\varphi_{i,i}$, $i = 1, \ldots, m$, where $\varphi_{j,i}$ refers to the potential in the $j^{th}$ row in the potential table of factor $\phi_i$.
	Choosing any other columns within the first $m$ rows would decrease the denominator (while leaving the nominator unchanged) and thus cannot lead to the minimum quotient.
	Furthermore, choosing any rows starting from row $m+1$ also increases the result of the quotient because
	\begin{align}
		\frac{i (1 + \frac{1}{m} \varepsilon)}{i (1 + \varepsilon)} \leq \frac{i (1 + \frac{m-1}{m} \varepsilon)}{i (1 + \varepsilon)},
	\end{align}
	with a minimal right hand side for row $m+1$ to $2m$. %In other words, the factor $i$ in front of the term $(1 + \varepsilon)$ can be increased by choosing the rows beginning at row $m+1$, however, the arithmetic mean increases more strongly and therefore, the resulting quotient increases compared to choosing rows $1$ to $m$.
	In other words, the factor of the denominator for the minimum would remain $(1+\varepsilon)$, while the mean $\varphi^*_i$ for the numerator increases independently of $i$, resulting in an overall increased quotient compared to choosing rows $1$ to $m$.
	Consequently, it holds that $\boldsymbol r_{\min} = (r_1, \allowbreak \ldots, \allowbreak r_m)$ fulfils the equation $\min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi(\boldsymbol r)} = \frac{\psi'(\boldsymbol r_{\min})}{\psi(\boldsymbol r_{\min})}$, resulting in
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)} &= \prod_{i=1}^{m} \frac{\varphi_i^*}{\varphi_{i,i}} \\
		&= \prod_{i=1}^{m} \frac{i\left( 1 + \frac{1}{m} \varepsilon \right)}{i \left( 1 + \varepsilon \right)}\\
		&= \left( \frac{1 + \frac{1}{m} \varepsilon}{1 + \varepsilon} \right)^m.
	\end{align}
	\endgroup
	Analogously, we compute the maximum quotient $\max_{\boldsymbol r}\frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)}$ by choosing $\boldsymbol r_{\max} = (r_{m+1}, \allowbreak \ldots, \allowbreak r_{2m})$ in the following way:
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		\max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)} &= \prod_{i=m+1}^{2m} \frac{\varphi_i^*}{\varphi_{i,i}} \\
		&= \prod_{i=m+1}^{2m} \frac{i \left( 1 + \frac{m-1}{m} \varepsilon \right)}{i} \\
		&= \prod_{i=1}^{m} \frac{i \left( 1 + \frac{m-1}{m} \varepsilon \right)}{i} \\
		&= \left( 1 + \frac{m-1}{m} \varepsilon \right)^m.
	\end{align}
	\endgroup
	Inserting the minimum and maximum quotients into the definition of the distance measure $D(P_M, P_{M'})$, we obtain
	\begingroup
	\allowdisplaybreaks
	\begin{align}
		D(P_M, P_{M'}) &= \ln \max_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)} - \ln \min_{\boldsymbol r} \frac{\psi'(\boldsymbol r)}{\psi (\boldsymbol r)} \\
		&= \ln \left( \frac{1+\frac{m-1}{m} \varepsilon}{\frac{1 + \frac{1}{m} \varepsilon}{1 + \varepsilon}} \right)^m \\
		&= \ln \left( \frac{(1+\frac{m-1}{m} \varepsilon)(1 + \varepsilon)}{1 + \frac{1}{m} \varepsilon} \right)^m,
	\end{align}
	\endgroup
	which is strictly smaller than $\ln\ (1 + \varepsilon)^m - \ln\ (1 - \varepsilon)^m$ but also strictly larger than $\ln\ (1 + \varepsilon)^m$ and effectively hits the bound given in \cref{th:lowerboundeacp_error_bound_given_eps}.

	In practice, however, our bounds improve significantly as soon as we deviate from this extreme scenario.
	This is because even minor dependencies between the maximum and minimum quotients suffice to obtain a tighter estimate.
	For instance, if there are more factors in a group than rows in their potential tables or if multiple groups of pairwise $\varepsilon$-equivalent factors exist, we can immediately conclude that the worst-case condition no longer holds, resulting in smaller overall values of $D$.
	This effect occurs since even minimal deviations from the worst-case scenario result in dependencies between the maximum and minimum for any assignment $\boldsymbol r$.
\end{proof}

\section{The Advanced Colour Passing Algorithm} \label{appendix:eacp_acp_in_detail}
The \ac{acp} algorithm introduced by \citet{Luttermann2024a} builds on the \acl{cp} algorithm (originally named CompressFactorGraph)~\citep{Kersting2009a,Ahmadi2013a} and solves the problem of constructing a lifted representation, encoded as a \ac{pfg}, from a given propositional \ac{fg}.
The idea of \ac{acp} is to first find indistinguishabilities in a propositional \ac{fg} and then group together symmetric subgraphs.
In particular, \ac{acp} looks for indistinguishabilities based on potentials of factors, on ranges and evidence of \acp{rv}, as well as on the graph structure by passing around colours.
\Cref{alg:eacp_acp} provides a formal description of the \ac{acp} algorithm, which proceeds as follows.

\begin{algorithm}[t]
	\caption{Advanced Colour Passing}
	\label{alg:eacp_acp}
	\alginput{An \ac{fg} $M = (\boldsymbol R \cup \boldsymbol \Phi, \boldsymbol E)$ and a set of observed \\\hspace*{\algorithmicindent} events (evidence) $\boldsymbol O = \{ E_1 = e_1, \ldots, E_{\ell} = e_{\ell} \}$.} \\
	\algoutput{A lifted representation $M'$, encoded as a \ac{pfg}, \\\hspace*{\algorithmicindent} which entails equivalent semantics as $M$.}
	\begin{algorithmic}[1]
		\State Assign each $R_i$ a colour according to $\range{R_i}$ and $\boldsymbol O$\;
		\State Assign each $\phi_i$ a colour according to order-independent potentials and rearrange arguments accordingly\; \label{line:eacp_acp_init_factor_colours}
		\Repeat
			\For{each factor $\phi \in \boldsymbol \Phi$}
				\State $signature_{\phi} \gets [\,]$\;
				\For{each \ac{rv} $R \in neighbours(M, \phi)$}
					\State\Comment{In order of appearance in $\phi$}\;
					\State $append(signature_{\phi}, R.colour)$\;
				\EndFor
				\State $append(signature_{\phi}, \phi.colour)$\;
			\EndFor
			\State Group together all $\phi$s with the same signature\;
			\State Assign each such cluster a unique colour\;
			\State Set $\phi.colour$ correspondingly for all $\phi$s\;
			\For{each \ac{rv} $R \in \boldsymbol R$}
				\State $signature_{R} \gets [\,]$\;
				\For{each factor $\phi \in neighbours(M, R)$}
					\If{$\phi$ is commutative w.r.t.\ $\boldsymbol S$ and $R \in \boldsymbol S$}
						\State $append(signature_{R}, (\phi.colour, 0))$\;
					\Else
						\State $append(signature_{R}, (\phi.colour, p(R, \phi)))$\;
					\EndIf
				\EndFor
				\State Sort $signature_{R}$ according to colour\;
				\State $append(signature_{R}, R.colour)$\;
			\EndFor
			\State Group together all $R$s with the same signature\;
			\State Assign each such cluster a unique colour\;
			\State Set $R.colour$ correspondingly for all $R$s\;
		\Until{grouping does not change}
		\State $M' \gets$ construct \acs{pfg} from groupings\; \label{line:eacp_acp_construct_pfg}
	\end{algorithmic}
\end{algorithm}

\Ac{acp} begins with the colour assignment to variable nodes, meaning that all \acp{rv} that have the same range and observed event are assigned the same colour.
Thereafter, \ac{acp} assigns a colour to every factor node such that factors representing equivalent potentials are assigned the same colour.
After the initial colour assignments, \ac{acp} begins to pass the colours around.
\Ac{acp} first passes the colours from every variable node to its neighbouring factor nodes and afterwards, every factor node $\phi$ sends both its colour and the position $p(R, \phi)$ of $R$ in $\phi$'s argument list to all of its neighbouring variable nodes $R$.
Factors that have symmetries within themselves, formally denoted as being commutative with respect to a subset $\boldsymbol S$ of their arguments, omit the position when sending their colour to a neighbouring variable node $R \in \boldsymbol S$.
We provide more details on commutative factors in \cref{appendix:eacp_approximate_symmetries_within_factors}.
\begin{figure*}[t]
	\centering
	\input{files/acp_example.tex}
	\caption{A visualisation of the steps undertaken by the \ac{acp} algorithm (\cref{alg:eacp_acp}) on the input \ac{fg} from \cref{fig:eacp_example_fg} (left). All \acp{rv} have the same range ($\{ \low, \high \}$) and there are no observed events (evidence) available. Colours are first passed from variable nodes to factor nodes, followed by a recolouring, and then passed back from factor nodes to variable nodes, again followed by a recolouring. The colour passing procedure is then iterated until convergence (here, the colour assignments remain the same in the next iteration) and the resulting \ac{pfg} is depicted on the right. In the resulting \ac{pfg}, $Sal(E)$ is a so-called \acl{prv} that represents a group of \acp{rv} ($SalA$ and $SalB$) by using a \acl{lv} $E$ with domain $\domain{E} = \{ SalA, SalB \}$. Analogously, $\phi'_1$ now represents both $\phi_1$ and $\phi_2$ simultaneously.}
	\label{fig:acp_example}
\end{figure*}
\begin{example}
	\Cref{fig:acp_example} illustrates the course of the \ac{acp} algorithm on the \ac{fg} from \cref{fig:eacp_example_fg} with the modification that $\varphi_i = \varphi'_i$ for all $i \in \{ 1, \ldots, 4 \}$.
	Recall that $SalA$, $SalB$, and $Rev$ all have the range $\{ \low, \high \}$.
	We further assume that there are no observed events (evidence) and thus, $SalA$, $SalB$, and $Rev$ receive the same colour (e.g., $\mathrm{yellow}$).
	As the potentials of $\phi_1$ and $\phi_2$ are identical, $\phi_1$ and $\phi_2$ are assigned the same colour as well (e.g., $\mathrm{blue}$).
	The colour passing then starts from variable nodes to factor nodes, that is, $SalA$ and $Rev$ send their colour ($\mathrm{yellow}$) to $\phi_1$, and $Rev$ and $SalB$ send their colour ($\mathrm{yellow}$) to $\phi_2$.
	$\phi_1$ and $\phi_2$ are then recoloured according to the colours they received from their neighbours to reduce the communication overhead.
	Since $\phi_1$ and $\phi_2$ received identical colours (two times the colour $\mathrm{yellow}$), they are assigned the same colour during recolouring.
	Afterwards, the colours are passed from factor nodes to variable nodes and this time not only the colours but also the position of the \acp{rv} in the argument list of the corresponding factor are shared (because none of the factors is commutative with respect to a subset of its arguments having size at least two---see \cref{appendix:eacp_approximate_symmetries_within_factors} for more details).
	Consequently, $\phi_1$ sends a tuple $(\mathrm{blue}, 1)$ to $SalA$ and a tuple $(\mathrm{blue}, 2)$ to $Rev$, and $\phi_2$ sends a tuple $(\mathrm{blue}, 2)$ to $Rev$ and a tuple $(\mathrm{blue}, 1)$ to $SalB$ (positions are not shown in \cref{fig:acp_example}).
	As $SalA$ and $SalB$ are both at position one in the argument list of their respective neighbouring factor, they receive identical messages and are recoloured with the same colour.
	$Rev$ is assigned a different colour during recolouring than $SalA$ and $SalB$ because $Rev$ received different messages than $SalA$ and $SalB$.
	The groupings do not change in further iterations and hence the algorithm terminates.
	The output is the \ac{pfg} shown on the right in \cref{fig:acp_example}, where both $SalA$ and $SalB$ as well as $\phi_1$ and $\phi_2$ are grouped.
\end{example}
For more details on the colour passing procedure and the construction of the \ac{pfg} in the final step (\cref{line:eacp_acp_construct_pfg}), we refer the reader to \citet{Luttermann2024a}.
Note that when \ac{eacp} (\cref{alg:eacp_eacp}) calls \ac{acp} in \cref{line:eacp_call_acp}, the colour assignment of \ac{acp} to factors (\cref{line:eacp_acp_init_factor_colours} in \cref{alg:eacp_acp}) is replaced by the colour assignment of \ac{eacp} prior to calling \ac{acp}.
We also remark that \ac{eacp} does not use the \ac{pfg} output by \ac{acp} but instead takes the groups computed by \ac{acp}, updates them in phase three, and then applies the final step to construct the \ac{pfg}.

\section{Permutations of Factors' Arguments} \label{appendix:eacp_permuted_arguments}
In general, we cannot assume that the tables of equivalent factors (i.e., factors that encode equivalent underlying functions) read identical values from top to bottom.
More specifically, it is not always the case that indistinguishable \acp{rv} are located at the same position in their respective factors' argument lists.
The following example illustrates this point.
\begin{figure}
	\centering
	\input{files/example_fg_permuted.tex}
	\caption{Another \ac{fg} modeling the interplay between the revenue of a company ($Rev$) and the salaries of its employees ($SalA$ and $SalB$). In comparison to \cref{fig:eacp_example_fg}, the order of $\phi_2$'s arguments has now changed. Nevertheless, the semantics (i.e., the underlying full joint probability distribution) of the \ac{fg} remains the same as in \cref{fig:eacp_example_fg}.}
	\label{fig:eacp_example_fg_permuted}
\end{figure}
\begin{example}
	Consider the \ac{fg} $M_1$ shown in \cref{fig:eacp_example_fg_permuted}.
	In fact, $M_1$ entails equivalent semantics as the \ac{fg} $M_2$ depicted in \cref{fig:eacp_example_fg}.
	Observe that the function definition of $\phi_1$ is identical in $M_1$ and $M_2$ (i.e., its potential table is exactly the same).
	If we now take a look at $\phi_2$, we see that in $M_1$, the order of its arguments differs from the order of its arguments in $M_2$.
	In particular, $Rev$ is now located at position one and $SalB$ at position two in $M_1$ (opposed to $SalB$ at position one and $Rev$ at position two in $M_2$).
	The semantics of $\phi_2$, however, remains unchanged as all assignments are mapped to the same potential: $Rev = \high$, $SalB = \high$ is mapped to $\varphi'_1$, $Rev = \high, SalB = \low$ is mapped to $\varphi'_3$, $Rev = \low$, $SalB = \high$ is mapped to $\varphi'_2$, and $Rev = \low$, $SalB = \low$ is mapped to $\varphi'_4$.
	In consequence, $\phi_2$ entails the same semantics in $M_1$ as in $M_2$.
\end{example}
To construct a lifted representation such as a \ac{pfg}, indistinguishable \acp{rv} like $SalA$ and $SalB$ are required to be located at the same position in the argument list of their respective factors (otherwise, they cannot be grouped).
Therefore, to account for permutations of factors' arguments when looking for ($\varepsilon$-)equivalent factors, we first have to check whether there exists a rearrangement of the arguments such that the potential tables read identical ($\varepsilon$-equivalent, respectively) values from top to bottom.
If such a rearrangement exists, arguments are rearranged accordingly to ensure that indistinguishable \acp{rv} are actually located at the same position in their respective factors' argument lists.
After the rearrangement, it is guaranteed that the potential tables of ($\varepsilon$-)equivalent factors can be compared row-wise and the \ac{acp} algorithm (\cref{alg:eacp_acp}) assigns identical colours to them.
More details on how such rearrangements of arguments can be computed efficiently are given in \citep{Luttermann2024d}.

\section{Approximate Symmetries Within Factors} \label{appendix:eacp_approximate_symmetries_within_factors}
Symmetries within factors arise when arguments of the same factor are indistinguishable.
A factor that contains symmetries within itself is referred to as a \emph{commutative factor} in the literature.
The next definition formally introduces the notion of a commutative factor.
\begin{definition}[Commutative Factor, \citealp{Luttermann2024a}] \label{def:eacp_commutative_factor}
	Let $\phi(R_1, \ldots, R_n)$ denote a factor.
	We say that $\phi$ is \emph{commutative with respect to} $\boldsymbol S \subseteq \{R_1, \ldots, R_n\}$ if for all events $r_1, \ldots, r_n \in \times_{i=1}^n \range{R_i}$ it holds that $\phi(r_1, \ldots, r_n) = \phi(r_{\pi(1)}, \ldots, r_{\pi(n)})$ for all permutations $\pi$ of $\{1, \ldots, n\}$ with $\pi(i) = i$ for all $R_i \notin \boldsymbol S$.
	If $\phi$ is commutative with respect to $\boldsymbol S$, all arguments in $\boldsymbol S$ are called \emph{commutative arguments}.
\end{definition}
