	\caption{Boxplots illustrating the distributions of the number $\alpha$ of queries after which the additional offline effort of \ac{eacp} amortises for input \acp{fg} containing a proportion of $x = 0.1$ (left) and $x = 0.3$ (right) of factors that are modified by factor at most $(1 \pm \varepsilon)$.}
	\label{fig:eacp_plot-offline-p=0.1-3}
\end{figure*}
