\section{Necessary and sufficient conditions}\label{Section2}


Let $G$ be a graph obtained by a clique $K_g$ and the graph $H$ by adding two vertices $u,w$ such that $H$ is a graph with maximum degree $\Delta(G)<g-2$, $g\geq 3$ and $|V(H)|=r$; see Fig. \ref{Figure3}.
\begin{remark}\label{rem1-1}
One can see that $t^{g}(G) \ (g\geq 3)$ may not exist. Suppose that $F$ is a $g$-good-neighbor conditional faulty set. Then one of the following holds.
\begin{itemize}
\item $V(H)\subseteq F$ and $K_g\cap F=\emptyset$;
\item $u\in F$ and $w\in F$ do not hold.
\end{itemize}
Then $F=V(H)$ or $F=V(H)\cup \{u\}$ or $F=V(H)\cup \{w\}$, and there is no other  $g$-good-neighbor conditional faulty sets in $G$.
\begin{figure}[!hbpt]
\begin{center}
\includegraphics[scale=0.7]{G1.eps}
\end{center}
\begin{center}
\caption{Graphs for Remark \ref{rem1-1}}\label{Figure3}
\end{center}
\end{figure}

For any two different $g$-good-neighbor conditional faulty sets $F_1,F_2\subseteq V(G)$, $F_1=V(H)\cup \{u\}$ or $F_1=V(H)\cup \{w\}$ or $F_2=V(H)\cup \{u\}$ or $F_2=V(H)\cup \{w\}$. Then $(F_1,F_2)$ is a $g$-good-neighbor distinguishable pair in $G$ under the PMC model. For any integer $s\geq r+1$, we have $|F_i|\leq s$ for $i=1,2$, and $(F_1,F_2)$ is a $g$-good-neighbor distinguishable pair in $G$ under the PMC model.
From the arbitrariness of $s$, we have there is no maximum value of $t^{g}(G)$ and so $t^{g}(G)$ can not exist.
\end{remark}

In this subsection, we give two necessary and sufficient conditions that $t^{g}(G)$ exists.











\begin{theorem}\label{th-condition}
Let $G$ be a graph, and let $s$ be a non-negative integer. Then
$t^{g}(G)=s$ if and only if
\begin{center}
$(\mathcal{C})$: there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $|F_1|=s+1$ and $|F_2|\leq s+1$. ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
\end{center}
\end{theorem}
\begin{proof}
Suppose that $t^g(G)=s$. If there does not exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $|F_1|=s+1$ and $|F_2|\leq s+1$, then $t^{g}(G)=s+1$, which contradicts the fact that $t^{g}(G)=s$.

Suppose that there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $|F_1|=s+1$ and $|F_2|\leq s+1$. We choose $F_1,F_2$ such that $s$ is minimum. Then $t^g(G)\leq |F_1|-1=s$. Let $t^{g}(G)=t$. Then there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1',F_2'$ such that $|F_1'|=t+1$ and $|F_2'|\leq t+1$.
If $t<s$, then $|F_1'|=t+1<s+1$, which contradicts the fact that $s$ is minimum. Then
$t^{g}(G)=t=s$.
\end{proof}

\begin{corollary}
Let $g$ be a non-negative integer. If $G$ has $g$-good-neighbor conditional diagnosability, then
$$
0 \leq g \leq \Delta(G).
$$
\end{corollary}

\begin{theorem}\label{th-condition-D}
Let $G$ be a graph, and let $s$ be a non-negative integer. Then
$t^{g}(G)$ exists if and only if
\begin{center}
$(\mathcal{D})$: $\kappa^g(G)$ exists or there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $F_1\cup F_2=V(G)$. ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
\end{center}
\end{theorem}
\begin{proof}
Suppose that the condition $(\mathcal{D})$ holds. Suppose that $\kappa^g(G)$ exists. Then there exists a cutset $X\subseteq V(G)$ such that the minimum degree of each component of $G-X$ is at least $g$. Let $C_1,C_2,...,C_r$ be the connected components of $G-X$. Without loss of generality, let $|C_1|\leq |C_2|\leq \cdots \leq |C_r|$. Let $F_1=C_1\cup X$ and $F_2=X$. Then $(F_1,F_2)$ is a  indistinguishable $g$-good-neighbor conditional pair. From Theorem \ref{th-condition}, $t_g(G)$ exists.
Suppose that there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $F_1\cup F_2=V(G)$. Then $(F_1,F_2)$ is a  indistinguishable $g$-good-neighbor conditional pair. From Theorem \ref{th-condition}, $t^g(G)$ exists.

Suppose that $t^g(G)$ exists. From Theorem \ref{th-condition}, there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $|F_1|=s+1$ and $|F_2|\leq s+1$.

If $F_1\cup F_2=V(G)$, then the result follows.


Suppose that $F_1\cup F_2\neq V(G)$. Then $\overline{F_1\cup F_2}\neq \emptyset$.
\begin{claim}\label{claim-D}
$F_1\cap F_2\neq \emptyset$.
\end{claim}
\begin{proof}
Otherwise, we assume that $F_1\cap F_2= \emptyset$. Since $F_1\cup F_2\neq V(G)$, it follows that
there exists a vertex $u\in \overline{F_1\cup F_2}$ adjacent to a vertex $u'\in F_1\cup F_2$, since $G$ is connected. From Theorem \ref{th-DM84}, $(F_1,F_2)$ is a distinguishable $g$-good-neighbor conditional pair, a contradiction.
\end{proof}

From Claim \ref{claim-D}, we have
$F_1\cap F_2\neq \emptyset$. Since $(F_1,F_2)$ is an indistinguishable $g$-good-neighbor conditional pair, it follows that there does not exist an edge from $\overline{F_1\cup F_2}$ to $F_1\triangle F_2$. Then $F_1\cap F_2$ is a $g$-good-neighbor cutset of $G$. Then $\kappa^g(G)$ exists.
\end{proof}

\section{$g$-good neighbour cut-component numbers}\label{Section3}


Let $C_1,C_2,...,C_r$ be the connected components of $G-X$, where $X$ is a $g$-good-neighbor cutset of $G$ with $|X|\geq \kappa^g(G)$. Let $\mathcal{X}=\{X\,|\,|X|\geq \kappa^g(G)\}$.

We assume that there exists an integer $s$ such that
\begin{itemize}
    \item For each $C_i \ (1\leq i\leq s)$, there exists a partition of $C_i$: two vertex subsets $A_i,B_i$ such that $A_i\cup B_i=C_i$ with $\delta(G[A_i])\geq g$ and $\delta(G[B_i])\geq g$ for $j=1,2$. In this partition, we find such two subsets $A_i,B_i$ such that $|A_i|-|B_i|$ is minimum, where $0\leq |A_i|-|B_i|\leq |C_i|-2g-2$ we assume that $|A_i|\geq |B_i|$.

    \item For each $C_i \ (s+1\leq i\leq r)$, there does not exist such a partition of $C_i$.
\end{itemize}

Without loss of generality, let $|A_1|\leq |A_2|\leq \cdots \leq |A_s|$ and $|C_{r}|\leq |C_{r-1}|\leq \cdots \leq |C_{s+1}|$.
Let $\mathcal{A}(X)=\{A_1,A_2,...,A_s\}$ and $\mathcal{C}(X)=\{C_{s+1},C_{s+2},...,C_{r}\}$.


\begin{definition}\label{def3-1}
The \textit{$g$-good neighbour cut-component number} (\textit{gc number} for short) is defined as $c^g(G)=\min\{\min\{|A_1|,|C_r|\}+|X|\,:\,X\in \mathcal{X},$~$A_1\in \mathcal{A}(X)$,~$C_r\in \mathcal{C}(X)$~and $\delta(G-X) \geq g\}$.
\end{definition}

Let $\mathcal{G}_1$ be a graph class such that $G\in \mathcal{G}_1$ if and if only if there exists a $g$-good neighbor cut $X$ of $G$ such that
$c^g(G)=|C_r|+|X|$.
Let $\mathcal{G}_2$ be a graph class such that $G\in \mathcal{G}_2$ if and if only if there exists a $g$-good neighbor cut $X$ of $G$ such that
$c^g(G)=|A_1|+|X|$. If $G\in \mathcal{G}_1$ and $G\in \mathcal{G}_2$, then we let $G\in \mathcal{G}_1$.





\begin{algorithm}[H]
\footnotesize
\caption{The algorithm   determining $c^g(G)$}%算法名字
\label{algorithm:Caculate Stain tree}
\LinesNumbered %要求显示行号
\KwIn{A graph $G$
and $X\subseteq V(G)$ with $|X|\geq \kappa^g(G)$;}% 输入参数
\KwOut{$c^g(G)$ ;}%输出
$C \gets |V(G)|$\;%\;用于换行
$a \gets |V(G)|$\;
$d \gets |V(G)|$\;
$t \gets 0$\;
$A_1 \gets \emptyset$\;
\For{each vertex set $X\subseteq V(G)$
 with $|X|\geq \kappa^g(G)$}{

$\mathcal{C}$ $ \gets$ the  connected components set of $G\setminus X$\;
$\mathcal{T} \gets$ $\mathcal{C}$ \;
\For{each vertex set $C\subseteq \mathcal{C}$
}{
\For{each vertex set $A\subseteq C$
}{
\If{$A$ such with $\delta(G[A])\geq g$ ,$\delta(G[C\setminus A])\geq g$ and $|A|\geq |C\setminus A|$
}{
$d_1\gets$$|A|-|C\setminus A|$ \;

\If{$d_1 < d$}{
$d$ $ \gets$ $d_1$ \;
$A_1$ $ \gets$ $A$ \;
 }
