We can give a lower bound of $c^g(G)$ in terms of $\kappa^g(G)$.


\begin{theorem}\label{th-gc-Lower}
Let $G$ be a connected graph, and let $g$ be an integer with $g\geq 0$. If $\kappa^g(G)$ exists, then
$$
c^g(G)\geq \kappa^g(G)+g+1.
$$
Moreover, the equality holds if and only if there exists a cutset $X=\kappa^g(G)$ such that the minimum degree of each connected component of $G-X$ is at least $g$ and one of the following condition holds.
\begin{itemize}
    \item one of connected components is a clique $K_{g+1}$.

    \item one of connected components is obtained from two cliques $K_{g+1}$ by adding at least one edge between them.
\end{itemize}
\end{theorem}
\begin{proof}
From the definition of $c^g(G)$, there exists a cutset $X\subseteq V(G)$ with $|X|\geq \kappa^g(G)$ and a vertex subset $C_r$ or $A_1$ such that
\begin{equation}\label{eq-1}
c^g(G)=|X|+\min\{|C_1|,|A_1|\}\geq \kappa^g(G)+g+1
\end{equation}
and  $|N_G(v) \cap(V(G)-X)| \geq g$ for every vertex $v$ in $V(G)-X$.

Suppose that there exists a cutset $X=\kappa^g(G)$ such that the minimum degree of each connected component of $G-X$ is at least $g$ and one of connected components is a clique $K_{g+1}$. Then $
c^g(G)\leq |X|+|K_{g+1}|=\kappa^g(G)+g+1
$, and hence $
c^g(G)= \kappa^g(G)+g+1
$ by this theorem.

Suppose that there exists a cutset $X=\kappa^g(G)$ such that the minimum degree of each connected component of $G-X$ is at least $g$ and one of connected components, say $C_j$, is obtained from two cliques $K_{g+1}$ by adding at least one edge between them. Clearly, we have $A_j=V(K_{g+1})$ and $B_j=V(K_{g+1})$
Then $
c^g(G)\leq |X|+|V(K_{g+1})|=\kappa^g(G)+g+1
$, and hence $
c^g(G)= \kappa^g(G)+g+1
$ by this theorem.

Conversely, we suppose that $
c^g(G)= \kappa^g(G)+g+1
$.
From the definition of $c^g(G)$, there exists a cutset $X\subseteq V(G)$ with $|X|\geq \kappa^g(G)$ and a vertex subset $A_1$ or $C_r$ such that $|C_r|+|X|=\kappa^g(G)+g+1$ or $|A_1|+|X|=\kappa^g(G)+g+1$ and the minimum degree of each connected component of $G-X$ is at least $g$. Then $|X|\geq  \kappa^g(G)$, and $|C_r|\geq g+1$ or $|A_1|\geq g+1$, and hence $|X|=\kappa^g(G)$, and $|C_r|=g+1$ or $|A_1|=g+1$. Since the minimum degree of $C_r$ is at least $g$, it follows that $C_r=K_{g+1}$. Since $\delta(G[A_1])\geq g$ and $\delta(G[B_1])\geq g$, it follows that the connected component containing $A_1$ is obtained from two cliques $K_{g+1}$ by adding at least one edge between them.
\end{proof}


\begin{corollary}\label{pro1}
Let $T$ be a tree.
If $g=0$, then
$c^g(T)=2$.
\end{corollary}

We can give an upper bound of $c^g(G)$ in terms of $\kappa^g(G)$.

\begin{theorem}\label{th-gc-Upper}
Let $G$ be a connected graph, and let $g$ be an integer with $g\geq 0$. If $\kappa^g(G)$ exists, then
$$
c^g(G)\leq  \kappa^g(G)+\min\{|C_r|,|A_1|\},
$$
where $X$ is a $g$-good neighbor cutset of $G$ with $|X|=\kappa^g(G)$ and $C_r$ is a minimal connected component of $G-X$ in $\mathcal{C}$ and $A_1$ is a minimal vertex subset of $G-X$ in $\mathcal{A}$.

Moreover, the bound is sharp.
\end{theorem}
\begin{proof}
From the definition of $\kappa^g(G)$, there exists a subset $X\subseteq V(G)$ with $|X|=\kappa^g(G)$ such that $G\setminus X$ is not connected  and the minimum degree of each connected component of $G-X$ is at least $g$.
From the definition of $c^g(G)$, we have $c^g(G)\leq |X|+\min\{|C_r|,|A_1|\}=\kappa^g(G)+\min\{|C_r|,|A_1|\}$.
\end{proof}

To show the sharpness of Theorem \ref{th-gc-Upper}, we consider the following example.
\begin{example}
Let $H_n$ be a graph of order $n$ obtained from two $g$-regular connected graphs $D_{\lfloor (n-r)/2\rfloor}$ and $D_{\lceil (n-r)/2\rceil}$ by adding new vertices $u_1,u_2,...,u_{r}$ and new edges in $\{u_iu\,|\,1\leq i\leq r\}\cup \{u_iv\,|\,1\leq i\leq r\}$, where $r=\kappa^g(H_n)$, $u\in V(D_{\lfloor (n-r)/2\rfloor})$, $v\in V(D_{\lceil (n-r)/2\rceil})$, and $3\leq g\leq \lceil (n-r)/2\rceil-1$. For any $g$-good neighbor cut $X\subseteq V(H_n)$, we have $\{u_i\,|\,1\leq i\leq r\}\subseteq X$, since $g\geq 3$ and $deg_{H_n}(u_i)=2$. Since $D_{\lfloor (n-r)/2\rfloor}$ and $D_{\lceil (n-r)/2\rceil}$ are two $g$-regular connected graphs, it follows that $X\cap V(D_{\lfloor (n-r)/2\rfloor})=\emptyset$ and $X\cap V(D_{\lceil (n-r)/2\rceil})=\emptyset$. Then $X=\{u_i\,|\,1\leq i\leq r\}$, and hence
$c^g(H_n)=r+\lfloor (n-r)/2\rfloor=\kappa^g(H_n)+|D_{\lfloor (n-r)/2\rfloor}|$, and hence the bound is sharp.
\end{example}


The following corollary is immediate by Theorems \ref{th-gc-Upper} and \ref{th-gc-Lower}.
\begin{corollary}\label{cor-formula-c}
Let $G$ be a connected graph, and let $g$ be an integer with $g\geq 0$. If $\kappa^g(G)$ exists and there exists a minimum
$g$-good-neighbor
cut $X$ and a vertex subset $C_r$ or $A_1$ with $|C_r|=|A_1|=g+1$, then
$$
c^g(G)=\kappa^g(G)+g+1.
$$
\end{corollary}





\section{Results for $g$-good-neighbor diagnosability}\label{Section4}









We now give an upper bound of $t^{g}(G)$ in terms of gc numbers and order.
\begin{theorem}\label{th-Upper-gc}
Let $G$ be a connected graph with $n$ vertices. If $\kappa^g(G)$ exists, then
$$
t^{g}(G)\leq \min\{c^g(G)-1,n-g-2\}.
$$
Moreover, the bound is sharp.
\end{theorem}
\begin{proof}
From the definition of $c^g(G)$, there exists a subset $X\subseteq V(G)$ with $|X|\geq \kappa^g(G)$, and a connected component $C_r\in \mathcal{C}$ or a vertex subset $A_1\in \mathcal{A}$ of $G\setminus X$ such that $|C_r\cup X|=c^g(G)$ or $|A_1\cup X|=c^g(G)$, and the minimum degree of each connected component of $G-X$ is at least $g$. Let $F_1=X\cup C_r$ and $F_2=X$ if $|C_r\cup X|=c^g(G)$, and let $F_1=X\cup A_1$ and $F_2=X\cup B_1$ if $|A_1\cup X|=c^g(G)$.
Clearly,
$|F_1|=|X|+|C_r|$ and $|F_2|=|X|$ if $|C_r\cup X|=c^g(G)$, and let $|F_1|=|X|+|A_1|$ and $|F_2|=|X|+|B_1|$ if $|A_1\cup X|=c^g(G)$.
Since there is no edges between each $C_i \ (1\leq i\leq r-1)$
and $F_1 \triangle F_2=C_r$ or there is no edges between each $C_i \ (2\leq i\leq r)$
and $F_1 \triangle F_2=C_1$, it follows that there do not exist two vertices $u,u'$ in $G$ with $u\in C_1=F_1 \triangle F_2$ and $u' \in \overline{F_1 \cup F_2}$ such that $uu'\in E(G)$. From Theorem \ref{th-DM84},
$(F_1,F_2)$ is an indistinguishable pair in $G$ under the PMC model. This means that $t^{g}(G)\leq |F_1|-1=c^g(G)-1.$

Suppose that $
t^{g}(G)\geq n-g-1.$ From Theorem \ref{th-condition}, there exist two indistinguishable $g$-good-neighbor conditional faulty sets $F_1,F_2$ such that $|F_1|=t^{g}(G)+1$ and $|F_2|\leq t^{g}(G)+1$. Then $|F_1|=t^{g}(G)+1\geq n-g$, and hence $|V(G)|-|F_1|\leq g$, a contradiction. So, we have $
t^{g}(G)\leq n-g-2.$
\end{proof}

\begin{example}
Let $F_n$ be a graph of order $n$ obtained from two cliques $K_{g+1}$ and $K_{n-g-1}$ by adding a new edge between them, where $n\geq 2g+3$.
Then $c^g(F_n)=g+2$ and $t^{g}(F_n)=g+1$, and hence the bound is sharp.
\end{example}




\begin{theorem}\label{th-Upper-gc-condition}
Let $G$ be a connected graph with $n$ vertices such that $\kappa^g(G)$ exists. If $c^g(G)\leq \lceil n/2\rceil$, then
\begin{equation}\label{eq-t-c}
t^{g}(G)=c^g(G)-1.
\end{equation}
\end{theorem}
\begin{proof}
Since $\kappa^g(G)$ exists, it follows from Theorem \ref{th-condition-D} that $t^{g}(G)$ exists. Since $\kappa^g(G)$ exists, it follows from Proposition \ref{pro-g} that $g\leq \lfloor
(n-3)/2\rfloor$. From Theorem \ref{th-Upper-gc}, we have $t^{g}(G)\leq \min\{c^g(G)-1,n-g-2\}=c^g(G)-1$.

To show $t^{g}(G)\geq c^g(G)-1$, for any $F_i\subseteq V(G)$ with $|F_i|\leq c^g(G)-1\leq \lceil n/2\rceil-1$, and $F_i$ is a $g$-good-neighbor conditional faulty set, where $i=1,2$, we suppose that $F_1\cap F_2=\emptyset$. Since $|F_1|+|F_2|\leq n-1$, it follows that there exists a vertex $u\in \overline{F_1\cup F_2}$ and there exists a vertex $u'\in F_1\cup F_2$ such that $uu'\in E(G)$. From Theorem \ref{th-DM84}, $(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model.

Suppose that $F_1\cap F_2\neq \emptyset$. Then we have the following claim.
\begin{claim}\label{claim}
$(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model.
\end{claim}
\begin{proof}
Suppose, to the contrary, that $(F_1,F_2)$ is an indistinguishable $g$-good-neighbor pair in $G$ under the PMC model. Without loss of generality, let $|F_1|\geq |F_2|$. Since $\overline{F_1 \cup F_2}\neq \emptyset$, it follows from Theorem \ref{th-DM84} that there is no edge from $\overline{F_1 \cup F_2}$ to $F_1 \triangle F_2$. Then $F_1\cap F_2$ is a $g$-good-neighbor cutset of $G$. Note that the minimum degree of the subgraph induced by the vertices in $F_1-F_2$ (resp. $F_2-F_1$) is at least $g$.
Therefore, $F_1\triangle F_2$ is a union of connected components of $G-(F_1\cap F_2)$, and hence $|F_1|\geq c^g(G)$, a contradiction.
\end{proof}

From Claim \ref{claim}, $(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model, and so $t^{g}(G)\geq c^g(G)-1.$ The result follows.
\end{proof}


\section{Results for $g$-good-neighbor diagnosability of product networks}\label{Section5}



The following result is immediate by Theorem \ref{th-Upper-gc-condition}.
\begin{corollary}\label{th-cor}
Let $G,H$ be two connected graphs
with $n,m$ vertices, respectively.
 such that $\kappa^g(G\Box H)$ exists. If $c^g(G\Box H)\leq \lceil nm/2\rceil$, then
$$
t^{g}(G\square H)=c^g(G\square H)-1.
$$
\end{corollary}
\begin{proof}
From Theorem \ref{th-Upper-gc-condition}, we have
$t^{g}(G\square H)= c^g(G\square H)-1$.
\end{proof}


Under the PMC model, we can derive an upper bound of diagnosability.
\begin{theorem}\label{th-Upper-D}
Let $p,q,g$ be three integers with $p+q=g$.
Let $G,H$ be two connected graphs
with at least $n\geq p+1,m\geq q+1$ vertices, respectively, such that $0\leq p\leq g\leq  \delta(G)+q$ and $0\leq q\leq g\leq \delta(H)+p$.
Suppose that $G,H$ are not complete graphs such that $\kappa^p(G)$ and $\kappa^q(H)$ exist, and $c^p(G)\leq \lceil n/2\rceil$ and $c^q(H)\leq \lceil m/2\rceil$.

$(i)$ If $G\in \mathcal{G}_1$ and $H\in \mathcal{G}_1$, then
$$
t^{g}(G\square H)\leq (t^{p}(G)+1)(t^{q}(H)+1)-1.
$$
Moreover, the bound is sharp.

$(ii)$ If $G\in \mathcal{G}_2$ and $H\in \mathcal{G}_1$, then
$$
\begin{aligned}
t^{g}(G\square H)
&\leq 2(t^{p}(G)+1)(t^{q}(H)+1)-(t^q(H)+1)\kappa^p(G)-(p+1)(q+1)-1.
\end{aligned}
$$
Moreover, the bound is sharp.

$(iii)$ If $G\in \mathcal{G}_1$ and $H\in \mathcal{G}_2$, then
$$
\begin{aligned}
t^{g}(G\square H)
&\leq 2(t^{p}(G)+1)(t^{q}(H)+1)-(t^p(G)+1)\kappa^q(H)-(p+1)(q+1)-1.
\end{aligned}
$$
Moreover, the bound is sharp.

$(iv)$ If $G\in \mathcal{G}_2$ and $H\in \mathcal{G}_2$, then
$$
\begin{aligned}
t^{g}(G\square H)
&\leq (2t^{p}(G)-\kappa^p(G)+2)(2t^{p}(H)-\kappa^q(H)+2)-2(p+1)(q+1)-1.
\end{aligned}
$$
\end{theorem}
\begin{proof}
Let $c^p(G)=c^p$ and $c^q(H)=c^q$. From Theorem \ref{th-Upper-gc-condition}, we have $t^p(G)= c^p-1$ and $t^q(H)= c^q-1$.
Since $\kappa^p(G)$ exists, it follows from the definition of $c^p(G)$ that there exists a cutset $X^p\subseteq V(G)$ with $|X^p|\geq \kappa^p(G)$ and a vertex subset $C_r^p$ or $A_1^p$ such that $|C_r^p|+|X^p|=c^p(G)$ or $|A_1^p|+|X^p|=c^p(G)$ and the minimum degree of the subgraph induced by the vertices of $C_r^p$ or $A_1^p$ in $G-X^p$ is at least $p$.
Since $\kappa^q(H)$ exists, it follows from the definition of $c^q(H)$ that there exists a cutset $X^q\subseteq V(H)$ with $|X^q|\geq \kappa^q(H)$ and a vertex subset $C_r^q$ or $A_1^q$ such that $|C_r^q|+|X^q|=c^q(H)$ or $|A_1^q|+|X^q|=c^q(H)$ and the minimum degree of the subgraph induced by the vertices of $C_r^q$ or $A_1^q$ in $H-X^q$ is at least $q$.
\begin{case}
$G\in \mathcal{G}_1$ and $H\in \mathcal{G}_1$.
\end{case}

In this case, we have $|C_r^p|+|X^p|=c^p(G)$ and  $|C_r^q|+|X^q|=c^q(H)$.
Let
$$
X_1= (C_r^p\Box C_r^q)\cup (C_r^p\Box X^q)\cup (X^p\Box C_r^q)\cup (X^p\Box X^q)
$$
and
$$
X_2=(C_r^p\Box X^q)\cup (C_r^q\Box X^p)\cup (X^q\Box X^p);
$$
see Fig. \ref{Figure4}. From Observation \ref{obs-1}, we have $X_1=((C_r^p\cup X^p) \Box C_r^q)\cup ((C_r^p\cup X^p)\Box X^q)=(C_r^p\cup X^p) \Box (C_r^q\cup X^q)$, and hence
\begin{equation}\label{case1}
|X_1|=|C_r^p\cup X^p||C_r^q\cup X^q|=(|C_r^p|+|X^p|)(|C_r^q|+|X^q|)=c^p(G)c^q(H).
\end{equation}

