$|X\cap (V(G)-Y)|=8$ or $9$. If $|X\cap (V(G)-Y)|=8$, then $G-X$ is connected, a contradiction.
Suppose that $|X\cap (V(G)-Y)|=9$.
To guarantee $\delta(G-X)\geq 3$, $G-X$ is connected, a contradiction.
From the above arguments, we have $c^3(G)\geq 14$, and hence $c^3(D_8\Box P_n)\geq c^3(D_8\Box P_{10})\geq 14$.
\end{proof}

The following corollary shows that the bound in Theorem \ref{th-Upper-D} $(iii)$ is sharp. By symmetry of Cartesian product, the bound in Theorem \ref{th-Upper-D} $(ii)$ is sharp.
\begin{corollary}\label{cor-14}
$t^3(D_8\Box P_n)=13$ for $n\geq 11$.
\end{corollary}
\begin{proof}
From Proposition \ref{pro-DP-2} and Corollary \ref{th-cor}, we have $t^3(D_8\Box P_n)= c^3(D_8\Box P_n)-1= 14-1=13$.
\end{proof}

\begin{remark}
From Corollary \ref{cor-14}, we have $
t^{3}(D_8\Box P_n)=13=14-1=4\times 5-2\times 1-4-1=2(t^{0}(P_n)+1)(t^{3}(D_8)+1)-(t^0(P_n)+1)\kappa^3(D_8)-(0+1)(3+1)-1$. Note that $p=0$, $q=3$ and $g=3$. This shows that the bound in Theorem \ref{th-Upper-D} $(i)$ is sharp.
\end{remark}

\section{Applications}\label{Section6}

In this section, we demonstrate the usefulness of the proposed constructions by applying them to some instances of Cartesian product networks.

\subsection{2-dimensional grid networks}

A two-dimensional grid graph is the Cartesian product $P_n \square P_m$ of path graphs on $n$ and $m$ vertices. For more details on the grid graph, we refer to \cite{CW98,IR88}.

\begin{proposition}\label{pro-6-1}
For network $P_n \square P_m(n \geq m \geq 5)$,
$$
c^{g}(P_n \square P_m)=
\begin{cases}
3 & \text { if } g=0, \\
5, & \text { if } g=1,\\
8, & \text { if } g=2.
\end{cases}
$$
\end{proposition}
\begin{proof}
Let $H=P_n \square P_m$. If $g=0$, then it follows from Theorem \ref{th-gc-Lower} that
$c^0(H)\geq \kappa^0(H)+g+1=3.$
Let $X=\{(u_1,v_2),(u_2,v_1)\}$; see Fig. \ref{Grid}. Then $H-X$ is not connected, and there is a isolated vertex in it. So $c^0(H)\leq |X|+1=3.$

Suppose that $g=1$. Let $Y=\{(u_{n-1},v_1),(u_{n-1},v_2),(u_n,v_3)\}$; see Fig. \ref{Grid}. Then $H-Y$ is not connected, and the minimum degree of each component is at least $1$. So $c^1(H)\leq |Y|+2=5.$ For any cutset $Y\subseteq V(H)$ with $|Y|\geq 3$, if the minimum degree of each component of $H-Y$ is at least $1$, then $|Y|+|C_1|\geq 3+2=5$, where $C_1$ is the minimum component of $H-Y$. From the arbitrariness of $Y$, we have $c^1(H)\geq 5$.


Suppose that $g=2$. We choose $Z=\{(u_1,v_3),(u_2,v_3),(u_3,v_1),(u_3,v_2)\};$
see Fig. \ref{Grid}.
Then $H-Z$ is not connected, and each component has at least $4$ vertices of degree at least $2$. So $c^2(H)\leq |Z|+4=8.$ For any cutset $Z\subseteq V(H)$, if the minimum degree of each component of $H-Z$ is at least $2$, then $|Z|\geq 4$, and hence $|Z|+|C_1|\geq 4+4=8$, where $C_1$ is the minimum component of $H-Z$. From the arbitrariness of $Z$, we have $c^2(H)\geq 8$.
\end{proof}

The following corollary is immediate by Theorem \ref{th-Upper-gc-condition} and Proposition \ref{pro-6-1}.
\begin{corollary}\label{cor-6-1}
For network $P_n \square P_m(n \geq m \geq 5)$,
$$
t^{g}(P_n \square P_m)=
\begin{cases}
2 & \text { if } g=0, \\
4, & \text { if } g=1,\\
7, & \text { if } g=2.
\end{cases}
$$
\end{corollary}


\subsection{2-dimensional torus networks}


A \textit{torus} is the Cartesian product of two cycles of size at least three, that is, $C_n\Box C_m$; see Fig. \ref{Torus}. Ku et al. \cite{KWH03} showed that there are $n$ edge-disjoint spanning trees in an $n$-dimensional torus.



\begin{proposition}\label{pro-6-2}
For network $C_n \square C_m \ (n \geq m \geq 8)$, we have

$(i)$
$$
c^{g}(C_n \square C_m)=
\begin{cases}
5, & \text { if } g=0 \\
8, & \text { if } g=1\\
12, & \text { if } g=2.
\end{cases}
$$

$(ii)$ $c^{3}(C_n \square C_m)\leq 4m$.
\end{proposition}
\begin{proof}
Let $G=C_n \square C_m$.
If $g=0$, then it follows from Theorem \ref{th-gc-Lower} that
$c^0(G)\geq \kappa^0(G)+g+1=5.$
Let $X=\{(u_1,v_2),(u_2,v_1),(u_1,v_m),(u_n,v_1)\}$. Then $G-X$ is not connected, and there is a isolated vertex in it. So $c^0(G)\leq |X|+1=4+1=5.$


Suppose that $g=1$. We choose an edge $(u_1,v_1)(u_1,v_2)$.  Let
$$
\begin{aligned}
Y
&=N_{G}((u_1,v_1))\cup N_{G}((u_1,v_2))-\{(u_1,v_1),(u_1,v_2)\}\\
&=\{(u_{2},v_1),(u_{2},v_2),(u_n,v_1),(u_n,v_2),(u_1,v_3),(u_1,v_n)\}.
\end{aligned}
$$
Then $G-Y$ is not connected, and the minimum degree of each component is at least $1$. So $c^1(G)\leq |Y|+2=8.$ For any cutset $Y\subseteq V(G)$, suppose that the minimum degree of each component of $G-Y$ is at least $1$.
Recall that $C_1$ is the minimum component of $G-Y$. If there is a component having two vertices, then they are adjacent and their neighbors belong to $Y$, and hence
$|Y|+|C_1|\geq 6+2=8$. If each component has at least three vertices, then their neighbors belong to $Y$, and hence
$|Y|+|C_1|\geq 7+3=10$.
From the arbitrariness of $Y$, we have $c^1(G)\geq 8$.


Suppose that $g=2$. We choose
$$
\begin{aligned}
Z
&=N_{G}((u_1,v_1))\cup N_{G}((u_1,v_2))\cup N_{G}((u_2,v_1))\cup N_{G}((u_2,v_2))-\\
&\{(u_{1},v_1),(u_{2},v_1),(u_1,v_2),(u_2,v_2)\}.
\end{aligned}
$$
Then $G-Z$ is not connected, and the minimum degree of each component is at least $2$ and each component has at least $4$ vertices. So $c^2(G)\leq |Z|+4=8+4=12.$ For any cutset $Z\subseteq V(G)$, suppose that the minimum degree of each component of $G-Z$ is at least $2$.
Then $|Z|\geq 8$, and hence $|Z|+|C_1|\geq 8+4=12$, where $C_1$ is the minimum component of $G-Z$. From the arbitrariness of $Z$, we have $c^2(G)\geq 12$.
