Suppose that $g=3$. We choose
$$
\begin{aligned}
W
&=\{(u_3,v_i)\,|\,1\leq i\leq m\}\cup \{(u_n,v_i)\,|\,1\leq i\leq m\}.
\end{aligned}
$$
Then $G-W$ is not connected, and the minimum degree of each component is at least $3$ and each component has at least $2m$ vertices. So $c^2(G)\leq |W|+2m=2m+2m=4m.$
\end{proof}

\begin{corollary}\label{cor-6-2}
For network $C_n \square C_m \ (n \geq m \geq 8)$, we have

$(i)$
$$
t^{g}(C_n \square C_m)=
\begin{cases}
4, & \text { if } g=0 \\
7, & \text { if } g=1\\
11, & \text { if } g=2.
\end{cases}
$$

$(ii)$ $t^{3}(C_n \square C_m)\leq 4m-1$.
\end{corollary}

\subsection{2-dimensional generalized hypercube}

Let $K_m$ be a clique of $m$ vertices, where $m \geq 2$. An \textit{$n$-dimensional generalized hypercube} \cite{DA97,FA96} is the product of $n$ cliques.

\begin{proposition}\label{pro-6-3}
For network $K_n \square K_m \ (n \geq m \geq 2)$ and $0 \leq g \leq \lfloor (m+n-4)/2\rfloor-1$, we have
$$
\begin{aligned}
n+m-1+g
\leq c^{g}(K_n \square K_m)\leq (g+1)(m-1)+n.
\end{aligned}
$$
Moreover, the bounds are sharp.
\end{proposition}
\begin{proof}
From Theorem \ref{th-gc-Lower}, we have
$c^g(K_n \square K_m)\geq \kappa^g(K_n \square K_m)+g+1
\geq \kappa(K_n \square K_m)+g+1=n+m-1+g.$
Let $G=K_n$ and $H=K_m$. Choose a clique $K_{g+1}$ in $K_{n}$ with $U=\{u_1,u_2,...,u_{g+1}\}$. Let $v_1\in V(H)$ and $N_{H}(v_1)=\{v_2,v_3,...,v_{m}\}$. Let
$$
X=(G(v_1)-K_{g+1}(v_1))\cup \{(u_i,v_j)\,|\,1\leq i\leq g+1,~2\leq j\leq m\}.
$$
Then $X$ is a $g$-good neighbor cutset of $G\Box H$, and $K_{g+1}$ is a component of $G\Box H-X$, and hence $c^g(G\Box H)\leq |X|+|K_{g+1}|=(g+1)(m-1)+n$.

For $g=0$, we have $\kappa^g(K_n \square K_m)=n+m-2$, and hence the bounds are sharp.
\end{proof}

The following corollary is immediate by Theorems \ref{th-Upper-gc}, \ref{th-gc-Lower} and Proposition \ref{pro-6-3}.
\begin{corollary}\label{cor-6-3}
For network $K_n \square K_m(n \geq m \geq 4)$ and $0 \leq g \leq \lfloor n/2\rfloor-1$, we have
$$
\begin{aligned}
n+m-2+g
\leq t^{g}(K_n \square K_m)\leq (g+1)(m-1)+n-1.
\end{aligned}
$$
Moreover, the bounds are sharp.
\end{corollary}




\section{Concluding Remark}

In this paper, we focus our attention on the $g$-good-neighbor conditional diagnosability of Cartesian product networks. It is interesting to study the three other main products, including lexicographic, strong and direct products.

