Sabidussi \cite{Sa57} derived the following theorem on the connectivity of Cartesian product graphs.
\begin{theorem}{\upshape \cite{Sa57}}
Let $G$ and $H$ be two connected graphs. Then
$$
\kappa(G \square H) \geq \kappa(G)+\kappa(H) .
$$
\end{theorem}




But we mention that it is incorrectly claimed that $\kappa(G \square H)=\kappa(G)+\kappa(H)$ holds for any connected $G$ and $H$, see \cite{HIK11} ($p$-308). Let $G$ be a graph obtained from two triangles by identifying one vertex in each of them. Then $\kappa(G)=1$ and $\kappa(G \square G)=4>2=\kappa(G)+\kappa(G)$, see \cite{HIK11} (p-309). In \cite{Sp08}, Špacapan obtained the following result.
\begin{theorem}{\upshape \cite{Sp08}}\label{th-Sp08}
Let $G$ and $H$ be two nontrivial graphs. Then
$$
\kappa(G \square H)=\min \{\kappa(G)|V(H)|, \kappa(H)|V(G)|, \delta(G)+\delta(H)\}
$$
\end{theorem}


\begin{theorem}\label{th-Upper-gc-condition}
Let $G$ be a connected graph with $n$ vertices such that $\kappa^g(G)$ exists. If $c^g(G)\leq \lceil n/2\rceil$, then
$$
t^{g}(G)=c^g(G)-1.
$$
\end{theorem}
\begin{proof}
Since $\kappa^g(G)$ exists, it follows from Theorem \ref{th-condition-D} that $t^{g}(G)$ exists. Since $\kappa^g(G)$ exists, it follows from Proposition \ref{pro-g} that $g\leq \lfloor
(n-3)/2\rfloor$. From Theorem \ref{th-Upper-gc}, we have $t^{g}(G)\leq \min\{c^g(G)-1,n-g-2\}=c^g(G)-1$.

To show $t^{g}(G)\geq c^g(G)-1$, for any $F_i\subseteq V(G)$ with $|F_i|\leq c^g(G)-1\leq \lceil n/2\rceil-1$, and $F_i$ is a $g$-good-neighbor conditional faulty set, where $i=1,2$, we suppose that $F_1\cap F_2=\emptyset$. Since $|F_1|+|F_2|\leq n-1$, it follows that there exists a vertex $u\in \overline{F_1\cup F_2}$ and there exists a vertex $u'\in F_1\cup F_2$ such that $uu'\in V(G)$, and hence $(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model.

Suppose that $F_1\cap F_2\neq \emptyset$. Then we have the following claim.
\begin{claim}\label{claim}
$(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model.
\end{claim}
\begin{proof}
Suppose, to the contrary, that $(F_1,F_2)$ is an indistinguishable $g$-good-neighbor pair in $G$ under the PMC model. Since $\overline{F_1 \cup F_2}\neq \emptyset$, it follows that there is no edge from $\overline{F_1 \cup F_2}$ to $F_1 \triangle F_2$. Then $F_1\cap F_2$ is a $g$-good-neighbor cutset of $G$, and $F_1-F_2$ is a union of connected components of $G-(F_1\cap F_2)$, and hence $|F_1|\geq c^g(G)$, a contradiction.
\end{proof}

From Claim \ref{claim}, $(F_1,F_2)$ is a distinguishable $g$-good-neighbor pair in $G$ under the PMC model, and so $t^{g}(G)\geq \mathrm{gc}(G)-1.$ The result follows.
\end{proof}

