\section{Circuit for Robustness Calculation}
\label{sec:circuit}
This section will describe the process of developing the Register Transfer Logic (RTL) circuit that performs robustness calculations. Verilog, a popular hardware description language, is used to blueprint the circuit's logic before it is synthesized into a gate-level circuit.
That circuit is then used as input to TinyGarble~\cite{songhori2015tinygarble}, an implementation of GC. 
TinyGarble allows sequential gates (like flops), which allows us to design a circuit with a smaller footprint than possible with purely combinational circuits.

\begin{algorithm}
    \KwIn{$\phi$ as a bus $[\phi_1, \dots, \phi_m]$, the signal $s$ as a bus $[(x_1, t_1), \dots, (x_n, t_n)]$}
    \KwOut{Return the value stored in $R[1, 1]$}
    \BlankLine

    \Proc{DP-TALIRO($\phi, s$)}{
        $b_l, b_u := [\infty, \dots, \infty], [-\infty, \dots, -\infty]$ ($m$ times each)\;
        \For{$i := n \KwTo 1$, $j := m \KwTo 1$}{
            \Switch{$\phi_j$}{
                \lCase{$\top$}{$R[i, j] := \infty$}
                \lCase{$\text{``$x > c$''} \in AP$}{$R[i, j] := x_i - c$}
                \lCase{$\text{``$x \leq c$''} \in AP$}{$R[i, j] := c - x_i$}
                \lCase{$\neg \phi_k$}{$R[i, j] := -R[i, k]$}
                \lCase{$\phi_{k_1} \land \phi_{k_2}$}{$R[i, j] := \min(R[i, k_1], R[i, k_2])$}
                \lCase{$\phi_{k_1} \lor \phi_{k_2}$}{$R[i, j] := \max(R[i, k_1], R[i, k_2])$}
                \lCase{$\phi_{k_1} \implies \phi_{k_2}$}{$R[i, j] := \max(-R[i, k_1], R[i, k_2])$}
                \lCase{$\phi_{k_1} \iff \phi_{k_2}$}{$R[i, j] := \min(\max(-R[i, k_1], R[i, k_2]), \max(R[i, k_1], -R[i, k_2]))$}
                \uCase{$\phi_{k_1} U_{I}\:\,\phi_{k_2}$}{
                    \lIf{$i = n \text{ and } 0 \in I$}{$R[i, j] := R[i, k_2]$}
                    \lElseIf{$i = n \text{ and } 0 \notin I$}{$R[i, j] := -\infty$}
                    \lElseIf{$I = [0, \infty)$}{$R[i, j] := \max(R[i, k_2], \min(R[i, k_1], R[i+1, j]))$}
                    \Else{
                        $b_l[j], b_u[j] := \mathbf{BOUNDS}(I, i, [t_1, \dots, t_n], n, b_l[j], b_u[j])$\;
                        $tmp_{min} := \min_{i \leq i' < b_l[j]} R[i', k_1]$\;
                        $R[i, j] := -\infty$\;
                        \For{$i' := b_l[j] \KwTo b_u[j]$}{
                            $R[i, j] := \max(R[i, j], \min(R[i', k_2], tmp_{min}))$\;
                            $tmp_{min} := \min(tmp_{min}, R[i', k_1])$\;
                        }
                        \lIf{$\sup I = \infty$}{$R[i, j] := \max(R[i, j], \min(R[i, k_1], R[i+1, j]))$}
                    }
                }
            }
        }
        \Return{$R[1, 1]$}
    }
    \caption{Temporal Logic Robustness Computation}
    \label{algo:dp-taliro}
\end{algorithm}

