        \hline
        & $\until_{[4,9)}$ & $\neg$ & $x \geq 0$ & $x \geq 10$ \\
        \hhline{|=#=|=|=|=|}
        0 ($t_1$)  & $3$ & $7$ & $3$ & $-7$ \\
        \hline
        5 ($t_2$)  & $-2$ & $-1$ & $11$ & $1$ \\
        \hline
        7 ($t_3$)  & $-\infty$ & $12$ & $-2$ & $-12$ \\
        \hline
