the closed hyper-interval (or hyper-rectangle) $\Hintcc{a,b}$ denotes the set $\Set{x\in \mathbb{R}^{n}}{a\leq x\leq b}$. Let $\norm{\cdot}$ and $\norm{\cdot}_{\infty}$ denote the Euclidean and maximal norms on $\mathbb{R}^{n}$, respectively, and $\mathbb{B}_{n}$ be the $n$-dimensional closed unit ball induced by $\norm{\cdot}$. The $n$-dimensional zero vector is denoted by $0_{n}$.  Let $\id_{n}$ denote the $n\times n$ identity matrix. For $A\in \mathbb{R}^{n\times m}$, $\norm{A}$ and  $\norm{A}_{\infty}$ denote the matrix norms of $A$ induced by the Euclidean and maximal norms, respectively. Given $x\in \mathbb{R}^{n}$  and $A\in \mathbb{R}^{n\times m}$, $\abs{x}\in \mathbb{R}^{n}_{+}$ and $\abs{A}\in \mathbb{R}_{+}^{n\times m}$ are defined as $|x|_{i}\defas |x_{i}|,~i\in \intcc{1;n}$, and $\abs{A}_{i,j}\defas \abs{A_{i,j}},~(i,j)\in \intcc{1;n}\times \intcc{1;m}$, respectively. Let $\mathcal{S}^{n}$ denote the set of $n\times n$ real symmetric matrices. Given $A\in \mathcal{S}^{n}$, $\underline{\lambda}(A)$ and $\overline{\lambda}(A)$ denote the minimum and maximum eigenvalues of $A$, respectively.  Let $\mathcal{S}_{++}^{n}$ denote the set of $n\times n$ real symmetric positive definite matrices $\Set{A\in \mathcal{S}^{n}}{\underline{\lambda}(A)>0}$. Given $A\in \mathcal{S}_{++}^{n}$, $A^{\frac{1}{2}}$ denotes the unique real symmetric positive definite matrix $K$ satisfying $A=K^2$ \cite[p.~220]{Abadir2005matrix}.  The interior and the boundary  of $X\subseteq \mathbb{R}^{n}$ are denoted by $\mathrm{int}(X)$ and $\partial X$, respectively. Given $f\colon X\rightarrow Y$ and  $P\subseteq X$, the image  of $f$ on $P$ is defined as  $f(P)\defas\Set{f(x)}{x\in P}$.     Given $f\colon X \rightarrow X$ and  $x\in X$,  $f^{0}(x)\defas x$, and for  $M\in \mathbb{N}$, we define $f^{M}(x)$ recursively as follows:   $f^{k}(x)=f(f^{k-1}(x)),~k\in \intcc{1;M}$.   A subset $S\subseteq X$ is said to be  invariant under a mapping $f\colon X\rightarrow X$ if $f(X)\subseteq X$.


\section{Problem Setup}
\label{sec:ProblemSetup}
Consider the discrete-time system
\begin{equation}\label{eq:System}
x_{k+1}=f(x_{k}),~k\in \mathbb{Z}_{+},
\end{equation}
where $x_{k}\in \mathbb{R}^{n}$ is the state and $f\colon \mathbb{R}^{n}\rightarrow \mathbb{R}^{n}$ is the system's transition function. The trajectory of system \eqref{eq:System} starting from $x_{0}\in \mathbb{R}^{n}$ is the function $\varphi_{x}\colon\mathbb{Z}_{+}\rightarrow \mathbb{R}^{n}$, satisfying:
\begin{align*}
    \varphi_{x}(0)&=x,\\
    \varphi_{x}(k+1)&=f(\varphi_{x}(k))=f^{k+1}(x),~k\in \mathbb{Z}_{+}.
\end{align*}

\begin{assumption}\label{Assumptions}
$f$ is continuous over $\mathbb{R}^{n}$,  $0_{n}$ is an equilibrium point of system \eqref{eq:System} (i.e., $f(0_{n})=0_{n}$), and
    $0_{n}$ is locally exponentially stable. That is, there exist fixed parameters $r\in \intoo{0,\infty}$,  $M\in \intco{1,\infty}$, and $\lambda \in \intoo{0,1}$ such that for all $x\in r\mathbb{B}_{n}$,
$
\norm{\varphi_{x}(k)}\leq M \lambda^{k}\norm{x},~k\in \mathbb{Z}_{+}. 
$   
\end{assumption}
Let $\mathcal{X}\subseteq \mathbb{R}^{n}$ be a safe set.  We make the following assumption. 
\begin{assumption}
$\mathcal{X}$ is open and $0_{n}\in \mathcal{X}$.
\end{assumption}



Define the safe DOA inside $\mathcal{X}$ as 
\begin{equation*}
\mathcal{D}_{0}^{\mathcal{X}}\defas\Set{x\in \mathcal{X}}{\varphi_{x}(k)\in \mathcal{X},\, \forall k\in \mathbb{Z}_{+}, \,\lim_{k\rightarrow \infty} \varphi_{x}(k)=0_{n}}.
\end{equation*}

Any invariant subset of $\mathcal{D}_{0}^{\mathcal{X}}$ under $f$, containing $0_{n}$ in its interior  is called a safe region of attraction (ROA) in $\mathcal{X}$. Our goal is to compute a large safe ROA that  closely approximates  $\mathcal{D}_{0}^{\mathcal{X}}$.

\section{Properties of the DOA}
\label{sec:DOAProperties}
In this section, we introduce some important properties of the safe DOA $\mathcal{D}_{0}^{\mathcal{X}}$, which will be utilized in the proofs of the main results of this work.

\begin{theorem}
    The set $\mathcal{D}_{0}^{\mathcal{X}}\subseteq \mathcal{X}$ is nonempty, invariant under $f$, and open.
\end{theorem}
\begin{proof}
   The non-emptiness follows from the fact that $0_{n}\in\mathcal{D}_{0}^{\mathcal{X}}$. The invariance property can be deduced as follows: for  $x\in \mathcal{D}_{0}^{\mathcal{X}}$, $\varphi_{x}(k)\in \mathcal{X}~\forall k\in \mathbb{Z}_{+}$ and $\lim_{k\rightarrow \infty}\varphi_{x}(k)=0_{n}$. This implies that  $\varphi_{x}(k+1)=\phi_{f(x)}(k)\in \mathcal{X}~\forall k\in \mathbb{Z}_{+}$ and $\lim_{k\rightarrow \infty}\varphi_{x}(k+1)=\lim_{k\rightarrow \infty}\varphi_{f(x)}(k)=0_{n}$. Hence, $f(x)\in \mathcal{D}_{0}^{\mathcal{X}}$.

Now, we prove that $\mathcal{D}_{0}^{\mathcal{X}}$ is open.  Recall the definitions of $M,~r,~\lambda$ in Assumption \ref{Assumptions}. Let $\theta\in \intoo{0,\infty}$ be such that 
    $
\theta \mathbb{B}_{n}\subseteq \mathcal{X},
    $
    which exists due to the openness of $\mathcal{X}$ and the fact that $0_{n}\in \mathcal{X}$. Fix $x_{0}\in \mathcal{D}_{0}^{\mathcal{X}}$, then due to the convergence of $\varphi_{x_{0}}$ to $0_{n}$ within $\mathcal{X}$, there exists $N\in \mathbb{Z}_{+}$ such that  
    $
\varphi_{x_{0}}(j)\in \mathcal{X}~\forall j\in \intcc{0;N-1}
    $
and 
    $
\varphi_{x_{0}}(N)\in \frac{\tilde{r}}{2}\mathbb{B},
    $
where  $\tilde{r}$ satisfies
$
0<\tilde{r}\leq \min \{\frac{\theta}{M}, r\}.
$
Let $\rho_{j},~j\in \intcc{0;N-1}$, be positive numbers satisfying:
$
\varphi_{x_{0}}(j)+\rho_{j}\mathbb{B}_{n}\subset \mathcal{X},~j\in \intcc{0;N-1}.
$
Such numbers exist due to the openness of $\mathcal{X}$.
Note that 
$\varphi_{y}(j)=f^{j}(y)$
for all $y\in \mathbb{R}^{n}$ and $j\in \mathbb{Z}_{+}$.  As $f$ is continuous at $x_{0}$, $f^{2}$, ...  ,$f^{N}$ are also continuous at $x_{0}$. Therefore, there exists $\delta\in \intoo{0,\infty}$ such that, for all $x\in x_{0}+\delta \mathbb{B}_{n}$, 
$
\norm{f^{j}(x)-f^{j}(x_{0})} < \rho_{j},~j\in \intcc{0;N-1}$, and 
$\norm{f^{N}(x)-f^{N}(x_{0})}<\frac{\tilde{r}}{2}$. Consequently, we have for all $x\in x_{0}+\delta \mathbb{B}_{n}$,
$
\varphi_{x}(j)=f^{j}(x)\in \varphi_{x_{0}}(j)+\rho_{j}\mathbb{B}_{n}\subset \mathcal{X},~j\in \intcc{0;N-1},
$
and
$\norm{\varphi_{x}(N)}=\norm{f^{N}(x)}
\leq \norm{f^{N}(x)-f^{N}(x_{0})}+\norm{f^{N}(x_{0})} \leq \tilde{r}\leq r$.  The local exponential stability indicates that, for all $x\in x_{0}+\delta \mathbb{B}_{n}$, 
    $
\norm{f^{N+k}(x)}\leq M  \norm{f^{N}(x)} \lambda^{k}\leq M\tilde{r}\lambda^{k} ,~k\in \mathbb{Z}_{+}.
    $
Hence, {\color{red}$\varphi_{x}(j)=f^{j}(x)\rightarrow 0_{n}$} as $j\rightarrow \infty$ for all $x\in x_{0}+\delta \mathbb{B}_{n}$.
    Also, the local exponential stability and the definition of $\tilde{r}$ imply that, for all $x\in x_{0}+\delta \mathbb{B}_{n}$,
$\norm{f^{N+k}(x)}\leq  M \tilde{r} \leq \theta,~k\in \mathbb{Z}_{+}
\Rightarrow \varphi_{x}(N+k)=f^{N+k}(x)\in \theta \mathbb{B}_{n}\subseteq \mathcal{X}~\forall k\in \mathbb{Z}_{+}$.
    Therefore, $x\in\mathcal{D}_{0}^{\mathcal{X}}$ for all $x\in x_{0}+\delta \mathbb{B}_{n}$. As $x_{0}\in \mathcal{D}_{0}^{\mathcal{X}}$ is arbitrary, the proof is complete.
\end{proof}
\section{Value Functions}
In this section, we introduce the value functions that can be used to characterize $\mathcal{D}_{0}^{\mathcal{X}}$ and to derive Lyapunov and Zubov type equations.
\label{sec:ValueFunctions}
To this end, we
    let $\alpha\colon \mathbb{R}^{n}\rightarrow \mathbb{R}_{+}$ be a positive definite continuous function such that 
$$
\alpha_{m}\norm{x}^{2}\leq \alpha(x)\leq \alpha_{M}\norm{x}^{2},~x\in \mathbb{R}^{n},
$$
for some $\alpha_{m}, \alpha_{M}\in \intoo{0,\infty}$.  The definition of $\alpha$ and the parameters $\alpha_{m}$ and $\alpha_{M}$ are fixed throughout the following discussion. 
\begin{assumption}\label{assump:gamma}
    There exists a function $\gamma \colon \mathbb{R}^{n} \rightarrow \mathbb{R}_{+}\cup\{\infty\}$ satisfying:
    \begin{enumerate}
        \item $\gamma$ is finite and  continuous over $\mathcal{X}$, and there exists $\underline{\gamma}\in \mathbb{R}_{+}\setminus \{0\}$ such that 
        $$
\gamma(x)\geq \underline{\gamma}~\forall x\in \mathcal{X},
        $$
        \item $\gamma(x)=\infty$ whenever $x\notin \mathcal{X}$,
        \item for any sequence $\{x_{n}\}$, with $x_{n}\rightarrow x\in \partial \mathcal{X}$,  $\gamma(x_{n})\rightarrow \infty$.
    \end{enumerate}
\end{assumption}


\begin{remark} \label{rem:transformation}
    If $\mathcal{X}$ is a strict 1-sublevel set of a continuous function $g_{\mathcal{X}}\colon \mathbb{R}^{n}\rightarrow \mathbb{R}$, i.e., $\mathcal{X}=\{x\in \mathbb{R}^{n}|g_{\mathcal{X}}(x)<1\}$, then we can define 
    $$
\gamma(x)=1+\frac{1}{\mathrm{ReLu}(1-g_{\mathcal{X}}(x))},
    $$
    where $1/0\defas \infty$ and $\mathrm{ReLu}\colon \mathbb{R}\rightarrow \mathbb{R}$ is the rectifier linear unit function defined as $\mathrm{ReLu}(x)=(x+|x|)/2,~x\in \mathbb{R}$. With this definition of $\gamma$, the conditions of Assumption \ref{assump:gamma} hold with $\underline{\gamma}=1$. 
\end{remark}


We define the  value functions $\mathcal{V}\colon \mathbb{R}^{n}\rightarrow \mathbb{R}_{+}\cup \{\infty\}$ 
and $\mathcal{W}\colon \mathbb{R}^{n}\rightarrow \intcc{0,1}$ 
as follows: 

\begin{equation}\label{eq:Lyapunov1}
\mathcal{V}(x)\defas \sum_{k=0}^{\infty} \gamma(\varphi_{x}(k))\alpha(\varphi_{x}(k)),
\end{equation}
and
\begin{equation}\label{eq:Lyapunov2}
  \mathcal{W}(x)\defas 1-\exp(-\mathcal{V}(x)),
\end{equation}
where $\exp(-\infty)\defas 0$.

\section{Characterizing the DOA Using the Value Functions}
In this section, we charcterize the safe DOA in terms of the sublevel sets corresponding tho the value functions $\mathcal{V}$ and $\mathcal{W}$.
\label{sec:DOACharcterization}

\begin{theorem}
\begin{align*}
\mathcal{D}_{0}^{\mathcal{X}}&=
\mathbb{V}_{\infty}\defas \Set{x\in \mathbb{R}^{n}}{\mathcal{V}(x)<\infty}\\
&=\mathbb{W}_{1}\defas \Set{x\in \mathbb{R}^{n}}{\mathcal{W}(x)<1}.
\end{align*}
\end{theorem}

\begin{proof}
   Due to the one-to-one correspondence between the codomains of $\mathcal{V}$ 
 and $\mathcal{W}$ using equation \eqref{eq:Lyapunov2}, it is sufficient to only show that $\mathbb{V}_{\infty}=\mathcal{D}_{0}^{\mathcal{X}}$. Let $x\in \mathbb{V}_{\infty}$. We will show that ${\varphi}_{x}(k)\in \mathcal{X}$ for all $k\in \mathbb{Z}_{+}$.  By contradiction, assume that ${\varphi}_{x}(N)\notin \mathcal{X}$ for some $N\in \mathbb{Z}_{+}$. Then by the definition of $\gamma$, 
    $
\gamma({\varphi}_{x}(N))=\infty
    $
    implying that $\mathcal{V}(x)=\infty$, and that contradicts the fact that $x\in \mathbb{V}_{\infty}$. Hence, we have $\varphi_{x}(k)\in \mathcal{X}$ for all $k\in \mathbb{Z}_{+}$. Using the lower bound on $\gamma$, we have 
$
\alpha({\varphi}_{x}(k))\leq \gamma({\varphi}_{x}(k)) \alpha({\varphi}_{x}(k))/\underline{\gamma},~k\in \mathbb{Z}_{+}.
$
As $\sum_{k=0}^{\infty}\gamma({\varphi}_{x}(k)) \alpha({\varphi}_{x}(k))$ is convergent,
then by the  comparison test, {\color{red}$\sum_{k=0}^{\infty} \alpha({\varphi}_{x}(k))$} is also convergent, implying  $\lim_{k\rightarrow \infty} \alpha({\varphi}_{x}(k))=0$. Using the lower bound on $\alpha$, we have
    $
\lim_{k\rightarrow \infty} \norm{\varphi_{x}(k)}^{2}\leq \lim_{k\rightarrow \infty} \frac{1}{\alpha_{m}}\alpha(\varphi_{x}(k))=0.
    $
    Therefore, $x\in\mathcal{D}_{0}^{\mathcal{X}}$.

Now, let $x\in\mathcal{D}_{0}^{\mathcal{X}}$ and  recall the definitions of $M,~r,~\lambda$ in Assumption \ref{Assumptions}. Note that $0<\underline{\gamma}\leq \gamma(\varphi_{x}(j))<\infty$ for all $j\in \mathbb{Z}_{+}$ as $\varphi_{x}(j)\in \mathcal{X},~j\in \mathbb{Z}_{+}$.   Let $\theta\in \intoo{0,\infty}$ be such that 
    $
\theta \mathbb{B}_{n}\subseteq \mathcal{X},
    $
    which exists due to the openness of $\mathcal{X}$ and the fact that $0_{n}\in \mathcal{X}$. Due to the convergence of $\varphi_{x} $ to $0_{n}$, there exists $N\in \mathbb{Z}_{+}$ such that 
$
\varphi_{x}(N)=y\in \tilde{r}\mathbb{B}_{n},
$
where 
$
0<\tilde{r}\leq \min \{\theta/M,r\}.
$
As $\varphi_{x}(N)\in {r}\mathbb{B}_{n}$, the local exponential stability and the definition of $\tilde{r}$ imply that 
$\norm{\varphi_{x}(N+k)}=\norm{\varphi_{y}(k)}\leq M \lambda^{k}\norm{y}
\leq M \lambda^{k}\tilde{r}\leq  \lambda^{k}\theta\leq \theta  ,~k\in \mathbb{Z}_{+}$.
Hence, 
$
\alpha(\varphi_{x}(N+k))\leq \alpha_{M}\norm{\varphi_{x}(N+k)}^{2}\leq \alpha_{M}\lambda^{2k}\theta^{2},~k\in \mathbb{Z}_{+}.
$ Let $\Gamma_{\theta }\in \intoo{0,\infty}$ be such that 
$
\gamma(x)\leq \Gamma_{\theta }~\forall x\in \theta \mathbb{B}_{n},
$
which exists due to the compactness of $\theta \mathbb{B}_{n}$ and the continuity of $\gamma$ over $\theta \mathbb{B}_{n}$. Consequently, we have  
$
\mathcal{V}(x)=\sum_{k=0}^{\infty}\gamma({\varphi}_{x}(k))\alpha({\varphi}_{x}(k))=\sum_{k=0}^{N-1}\gamma({\varphi}_{x}(k))\alpha({\varphi}_{x}(k))+\sum_{k=N}^{\infty}\gamma({\varphi}_{x}(k))\alpha({\varphi}_{x}(k)) \leq \sum_{k=0}^{N-1}\gamma({\varphi}_{x}(k))\alpha({\varphi}_{x}(k))+\alpha_{M}\Gamma_{\theta}\theta^{2}\sum_{k=0}^{\infty}\lambda^{2k} \leq \sum_{k=0}^{N-1}\gamma({\varphi}_{x}(k))\alpha({\varphi}_{x}(k))+\alpha_{M}\Gamma_{\theta}\theta^{2}\frac{1}{1-\lambda^{2}}<\infty.
$   
Hence, $x\in \mathbb{V}_{\infty}$, and that completes the proof.
\end{proof}
\section{Properties of the Value Functions}
\label{sec:VFProperties}
In this section, we state some important properties for the functions $\mathcal{V}$ and $\mathcal{W}$.

\begin{lemma}
    The functions $\mathcal{V}$ and $\mathcal{W}$ are positive definite.
\end{lemma}
This is an immediate consequence of the definitions.
% \begin{proof}
% This follows from the fact that $\mathcal{V}(x)\geq \underline{\gamma}\alpha(x),~x\in \mathbb{R}^{n}$, the positive defniteness of $\alpha$, the fact that $V(0_{n})=0$, and the definition of $\mathcal{W}$ in \eqref{eq:Lyapunov2}.  
% \end{proof}

\begin{theorem} 
    $\mathcal{V}$ is continuous over $\mathcal{D}_{0}^{\mathcal{X}}$.
\end{theorem}

\begin{proof}
     Recall the definitions of $M,~r,~\lambda$ in Assumption \ref{Assumptions}. Let $\theta\in \intoo{0,\infty}$ be such that 
    $
\theta \mathbb{B}_{n}\subseteq \mathcal{X},
    $
    which exists due to the openness of $\mathcal{X}$ and the fact that $0_{n}\in \mathcal{X}$. Let $x_{0}\in\mathcal{D}_{0}^{\mathcal{X}}$ and $\varepsilon>0$ be arbitrary, where we assume without loss of generality that $\varepsilon\leq \min\{\theta/M,r\}$. Then there exists $N\in \mathbb{Z}_{+}$ such that $\varphi_{x_{0}}(N)\in \frac{\varepsilon}{2}\mathbb{B}_{n}$, where the exponential stability indicates that 
     $
\norm{\varphi_{x_{0}}(N+k)}\leq M \varepsilon \lambda^{k}\leq \theta ,~k\in \mathbb{Z}_{+}.
     $
   Let $\Gamma_{\theta }\in \intoo{0,\infty}$ be such that 
$
\gamma(x)\leq \Gamma_{\theta }~\forall x\in \theta \mathbb{B}_{n},
$
which exists due to the compactness of $\theta \mathbb{B}_{n}$ and the continuity of $\gamma$ over $\theta \mathbb{B}_{n}$. Consequently, we have
  $
\sum_{k=N}^{\infty}\gamma (\varphi_{x_{0}}(k)) \alpha (\varphi_{x_{0}}(k))\leq \sum_{k=0}^{\infty} \Gamma_{\theta}\alpha_{M} \norm{\varphi_{x_{0}}(N+k)}^{2}
\leq \Gamma_{\theta}\alpha_{M}\frac{M^{2}\varepsilon^{2}}{1-\lambda^{2}}.
   $
Let $\delta>0$ be such that $x_{0}+\delta \mathbb{B}_{n}\subset\mathcal{D}_{0}^{\mathcal{X}}$ and, for all $x\in x_{0}+\delta \mathbb{B}_{n}$, 
$
    \abs{\sum_{k=0}^{N-1}\gamma(\varphi_{x_{0}}(k))\alpha(\varphi_{x_{0}}(k))- \gamma(\varphi_{x}(k))\alpha(\varphi_{x}(k))}< \varepsilon$, and $
    \norm{\varphi_{x_{0}}(N)-\varphi_{x}(N)}\leq  \frac{\varepsilon}{2}$.
   Such $\delta$ exists due to the openness of $\mathcal{D}_{0}^{\mathcal{X}}$, the continuity of $f$ (and consequently the continuity of $f^{i},~i\in\intcc{1;N}$),  the continuity of $\alpha$ and the continuity of $\gamma$ over $\mathcal{X}$.
Consequently, for all $x\in x_{0}+\delta \mathbb{B}_{n}$, 
$
\norm{\varphi_{x}(N)}\leq \norm{\varphi_{x_{0}}(N)-\varphi_{x}(N)}+\norm{\varphi_{x_{0}}(N)}\leq \varepsilon.
$
The exponential stability indicates that, for all $x\in x_{0}+\delta \mathbb{B}_{n}$, 
   $
\norm{\varphi_{x}(N+k)}\leq M \varepsilon \lambda^{k}\leq \theta ,~k\in \mathbb{Z}_{+}.
   $
   Therefore, 
   $
\sum_{k=N}^{\infty} \gamma (\varphi_{x}(k)) \alpha (\varphi_{x}(k))\leq \sum_{k=0}^{\infty} \Gamma_{\theta}\alpha_{M} \norm{\varphi_{x_{0}}(N+k)}^{2}\leq \Gamma_{\theta}\alpha_{M}\frac{M^{2}\varepsilon^{2}}{1-\lambda^{2}}~\forall x\in x_{0}+\delta \mathbb{B}_{n}$.    Finally we have, for all $x\in x_{0}+\delta \mathbb{B}_{n}$ ($\mathcal{V}(x)$ is well-defined for $x\in x_{0}+\delta \mathbb{B}_{n}$),
 $
       \abs{\mathcal{V}(x_{0})-\mathcal{V}(x)} \leq
 \abs{\sum_{k=0}^{N-1}\gamma(\varphi_{x_{0}}(k))\alpha(\varphi_{x_{0}}(k))-\gamma(\varphi_{x}(k)) \alpha(\varphi_{x}(k))}
       +\sum_{k=N}^{\infty}\gamma (\varphi_{x_{0}}(k)) \alpha (\varphi_{x_{0}}(k))
       +\sum_{k=N}^{\infty} \gamma (\varphi_{x}(k)) \alpha (\varphi_{x}(k))
        \leq \varepsilon+ \Gamma_{\theta}\alpha_{M}\frac{M^{2}\varepsilon^{2}}{1-\lambda^{2}}+\Gamma_{\theta}\alpha_{M}\frac{M^{2}\varepsilon^{2}}{1-\lambda^{2}}$. As $\varepsilon$ is arbitrary, the proof is complete.
\end{proof}
\begin{theorem}  $\mathcal{V}(x_{k})\rightarrow \infty$ whenever $x_{k}\rightarrow x\in \partial\mathcal{D}_{0}^{\mathcal{X}}$,
\end{theorem}
\begin{proof}
    Without loss of generality, consider a sequence $\{x_{k}\}\subseteq \mathcal{D}_{0}^{\mathcal{X}}$, where $x_{k}\rightarrow x\in \partial \mathcal{D}_{0}^{\mathcal{X}}$. Let $\theta \in \intoo{0,\infty}$ be such that
$
\theta<r$ and 
$\theta\mathbb{B}_{n}\subseteq \mathcal{X}.
    $
    Let $\tilde{r}\in \intoo{0, \theta/M^{2}}   $.
    For each $k\in \mathbb{Z}_{+}$, let $T_{k}\in \mathbb{Z}_{+}$ be the first time instance such that 
    $
\varphi_{x_{k}}(T_{k})\in \tilde{r}\mathbb{B}_{n}.
    $
    If the sequence $\{T_{k}\}$ diverges to $\infty$, then we have
    $
\mathcal{V}(x_{k})\geq \sum_{j=0}^{T_{k}-1}\gamma(\varphi_{x_{k}}(j))\alpha(\varphi_{x_{k}}(j))\geq \underline{\gamma}\alpha_{m}\tilde{r}^{2}(T_{k}-1)\rightarrow \infty
    $ as $k\rightarrow \infty$,
    Assume that $\{T_{k}\}$ does not diverge to $\infty$, then there exists a bounded subsequence, again denoted $\{T_{k}\}$, with an upper bound $T\in \mathbb{Z}_{+}$ such that  
    $
T_{k}\leq T,~k\in \mathbb{Z}_{+}.
    $
It follows, as $\tilde{r}\leq \theta/M^{2}\leq \theta<r$, that  
$
\varphi_{x_{k}}(T_{k})\in \tilde{r} \mathbb{B}_{n}\subseteq r \mathbb{B}_{n},~k\in \mathbb{Z}_{+}.
$
Therefore, 
$
\norm{\varphi_{x_{k}}(T_{k}+j)}\leq  M\lambda^{j}\tilde{r}\leq \theta/M,~j,k\in \mathbb{Z}_{+}. 
$
Hence, 
$
\varphi_{x_{k}}(T)\in (\theta/M) \mathbb{B}_{n}\subseteq r\mathbb{B}_{n},~k\in \mathbb{Z}_{+},
$
implying, using the continuity of $f^{T}(\cdot)$, 
$
\varphi_{x}(T)\in (\theta/M) \mathbb{B}_{n}\subseteq r \mathbb{B}_{n}.
$
Therefore, 
$
\norm{\varphi_{x}(T+j)}\leq  M(\theta/M)\lambda^{j}=\theta \lambda^{j}\leq \theta,~j\in \mathbb{Z}_{+}.
$
This implies that 
$
\varphi_{x}(T+j)\in \mathcal{X},~j\in \mathbb{Z}_{+},
$
and 
$
\varphi_{x}\rightarrow 0_{n}
$
exponentially. If $\varphi_{x}(j)\in \mathcal{X}~\forall j\in \intcc{0;T-1}$, it follows that $\mathcal{V}(x)<\infty$, implying $x$ in an interior point of $\mathcal{D}_{0}^{\mathcal{X}}$, which yields a contradiction. Now, assume $\varphi_{x}(j)=y\in \mathbb{R}^{n}\setminus\mathcal{X}$ for some $j\in \intcc{0;T-1}$. Then, using the continuity of $f^{j}$, it follows that $\varphi_{x_{k}}(j)\rightarrow y$ as $k\rightarrow \infty$. This yields $\lim_{k\rightarrow \infty}\gamma(\varphi_{x_{k}}(j))= \infty$ and consequently $\mathcal{V}(x_{k})\rightarrow\infty$ as $k\rightarrow \infty$.
\end{proof}
\begin{corollary}
   $\mathcal{W}$ is continuous over $\mathbb{R}^{n}$. 
\end{corollary}

\section{Characterizing the Value Functions: Lyapunov and Zubov Equations}
\label{sec:Zubov}
In this section, we derive the Lyapunov and Zubov equations corresponding to the functions $\mathcal{V}$ and $\mathcal{W}$, respectively.

\begin{theorem}\label{Thm:LyapunovEquation}
For all $x\in \mathbb{R}^{n}$, $\mathcal{V}$ satisfies the maximal Lyapunov equation (w.r.t. to the function $v$)
\begin{align}\label{eq:LyapunovEqn}
v(x)%&= \sum_{k=0}^{\infty}\gamma({\varphi}_{x}(k))\alpha ({\varphi}_{x}(k))\\
%& =\gamma(x)\alpha(x)+\sum_{k=1}^{\infty}\gamma ({\varphi}_{x}(k))\alpha ({\varphi}_{x}(k))\\
= \gamma(x)\alpha(x)+v({f}(x)).
\end{align}
\end{theorem}
\begin{proof}
    Given $x\in \mathbb{R}^{n}$ and the definition of $\mathcal{V}$ in \eqref{eq:Lyapunov1}, we have 
       $ \mathcal{V}(x)= \sum_{k=0}^{\infty}\gamma({\varphi}_{x}(k))\alpha ({\varphi}_{x}(k))=\gamma(x)\alpha(x)+\sum_{k=1}^{\infty}\gamma ({\varphi}_{x}(k))\alpha ({\varphi}_{x}(k))=\gamma(x)\alpha(x)+\sum_{k=0}^{\infty}\gamma ({\varphi}_{f(x)}(k))\alpha ({\varphi}_{f(x)}(k))=\gamma(x)\alpha(x)+\mathcal{V}(f(x))$.
   Note that the above decomposition is valid even if $\mathcal{V}(x)$ is infinite.
\end{proof}

\begin{theorem}\label{thm:ZubovEqn1}
For all $x\in \mathbb{R}^{n}$, $\mathcal{W}$ satisfies the Zubov equation (w.r.t. to the function $w$)
\begin{equation}\label{eq:ZubovEqn1}
w(x)-w({f}(x))=\xi(x)(1-w(f(x))),
\end{equation}
where 
\begin{equation}\label{eq:xi}
\xi(x)\defas 1-\exp(-\gamma(x)\alpha(x)).
\end{equation}
\end{theorem}


\begin{proof}
Using Theorem \ref{Thm:LyapunovEquation}, we have, for any $x\in \mathbb{R}^{n}$, $\mathcal{W}(x)= 1-\exp(-\mathcal{V}(x))= 1-\exp(-\mathcal{V}({f}(x))-\gamma(x)\alpha(x))
        =1-\exp(-\gamma(x)\alpha(x))(1-\mathcal{W}({f}(x)))$,
implying 
$
     \mathcal{W}(x)-\mathcal{W}(f(x))=1-\mathcal{W}({f}(x))
     -\exp(-\gamma(x)\alpha(x))(1-\mathcal{W}({f}(x)))
     =\xi(x)(1-\mathcal{W}({f}(x)))$.
\end{proof}

\begin{theorem}\label{thm:ZubovEqn2}
If $w\colon D\subseteq\mathcal{X}\rightarrow \mathbb{R}$ satisfies equation \eqref{eq:ZubovEqn1} over $D$, then for  all $x\in D$, 
$w$ satisfies  the Zubov equation
\begin{equation}\label{eq:ZubovEqn2}
w(x)-w({f}(x))=\beta(x)(1-w(x)),
\end{equation}
where 
\begin{equation}\label{eq:beta}
\beta(x)\defas \exp(\gamma(x)\alpha(x))-1.
\end{equation}
\end{theorem}
\begin{proof}
    When $x\in D \subseteq \mathcal{X}$,  $\gamma(x)<\infty$, therefore, using equation \eqref{eq:ZubovEqn1}, 
    $
1-{w}({f}(x))=\exp(\gamma(x)\alpha(x))(1-w(x)).
    $
    Hence,
    $
       w(x)- w({f}(x))=\exp(\gamma(x)\alpha(x))(1-w(x))-1+w(x)= \exp(\gamma(x)\alpha(x))(1-w(x))-(1-w(x))= \beta(x)(1-w(x))$.  
\end{proof}
\subsection{Lyapunov and Zubov equations: Uniqueness results}
We have shown that the value functions $\mathcal{V}$ and $\mathcal{W}$ are solutions to the equations \eqref{eq:LyapunovEqn} and \eqref{eq:ZubovEqn1}, respectively. In the next section, we show that the solutions to these equations are unique with respect to functions the are continuous at the origin. We start with the following technical result:
\begin{lemma}\label{lem:boundedness}
    Assume that $w\colon \mathcal{D}_{0}^{\mathcal{X}}\rightarrow \mathbb{R}$ is continuous at the origin, with $w(0_{n})=0$ and satisfying equation \eqref{eq:ZubovEqn1} over $\mathcal{D}_{0}^{\mathcal{X}}$. Then $w(x)<1$ for all $x\in \mathcal{D}_{0}^{\mathcal{X}}$.
\end{lemma}
\begin{proof}
  Using Theorem \ref{thm:ZubovEqn2}, $w$ satisfies equation \eqref{eq:ZubovEqn2} over $\mathcal{D}_{0}^{\mathcal{X}}$. Assume that for some  $x\in \mathcal{D}_{0}^{\mathcal{X}}$, $w(x)\geq 1$. We have $\varphi_{x}(k)\in \mathcal{D}_{0}^{\mathcal{X}}~\forall k\in \mathbb{Z}_{+}$ and $\lim_{k\rightarrow \infty}\varphi_{x}(k)=0_{n}$. Using equation \eqref{eq:ZubovEqn2}, we have 
  $
w(x)-w(\varphi_{x}(1))=\beta(x)(1-w(x))\leq 0
  $
Hence, $w(\varphi_{x}(1))\geq w(x)\geq 1$, and by induction, we have $w(\varphi_{x}(k+1))\geq w(\varphi_{x}(k))\geq 1$ for all $k\in \mathbb{Z}_{+}$. Hence, $\lim_{k\rightarrow \infty}w(\varphi_{x}(k))\neq 0$, which yields a contradiction as $\lim_{k\rightarrow \infty}w(\varphi_{x}(k))$ must be zero due to the {\color{red}continuity} of $w$ at the origin, with ${\color{red}w(0_{n})=0}$ and $\lim_{k\rightarrow \infty}\varphi_{x}(k)=0_{n}$, and that completes the proof.
\end{proof}

\begin{theorem}\label{thm:LyapunovEqnUniqueness}
    Let $\mathbf{v}\colon \mathcal{D}_{0}^{\mathcal{X}}\rightarrow \mathbb{R}$ be a  function continuous at the origin and satisfying $\mathbf{v}(0_{n})=0$. Assume that $\mathbf{v}$ satisfies equation \eqref{eq:LyapunovEqn} over   
    $\mathcal{D}_{0}^{\mathcal{X}}$. Then
    $
\mathbf{v}(x)=\mathcal{V}(x)~\forall x\in \mathcal{D}_{0}^{\mathcal{X}}.
    $
\end{theorem}

\begin{proof}
    Let $x\in \mathcal{D}_{0}^{\mathcal{X}}$. As $\mathcal{D}_{0}^{\mathcal{X}}$ is invariant, we have 
    $\varphi_{x}(k)\in \mathcal{D}_{0}^{\mathcal{X}}~\forall k\in \mathbb{Z}_{+}.
    $
 Let $k\in \mathbb{N}$. We consequently have 
$ \mathbf{v}(x)-\mathbf{v}(\varphi_{x}(k))=\sum_{j=0}^{k-1}(\mathbf{v}(\varphi_{x}(j))-\mathbf{v}(\varphi_{x}(j+1)))
 =\sum_{j=0}^{k-1}\gamma(\varphi_{x}(j))\alpha(\varphi_{x}(j))$. As $\mathbf{v}$ is continuous at the origin with $\mathbf{v}(0_{n})=0$, $\varphi_{x}(k)\rightarrow 0_{n}$ as $k\rightarrow \infty$, and $\mathcal{V}(x)<\infty$ ($\sum_{j=0}^{k-1}\gamma(\varphi_{x}(j))\alpha(\varphi_{x}(j))$ converges), then taking the limit as $k\rightarrow \infty$ in the both sides of the above equation results in
    $
     \mathbf{v}(x)=\sum_{j=0}^{\infty}\gamma(\varphi_{x}(j))\alpha(\varphi_{x}(j))=\mathcal{V}(x).
    $
\end{proof}
\begin{theorem}
    Let $\mathbf{w}\colon \mathbb{R}^{n}\rightarrow \mathbb{R}$ be a bounded function, continuous at the origin, with $\mathbf{w}(0_{n})=0$, and  satisfying 
    equation \eqref{eq:ZubovEqn1} over $\mathbb{R}^{n}$.  
Then $\mathbf{w}=\mathcal{W}$.
\end{theorem}
\begin{proof}
   First note that the difference of two solutions, $\mathbf{w}_{1}$ and $\mathbf{w}_{2}$, to equation \eqref{eq:ZubovEqn1} satisfies, for $x\in \mathbb{R}^{n}$,
\begin{equation}\label{eq:difference1}
    \mathbf{w}_{1}(x)-\mathbf{w}_{2}(x)=(1-\xi(x))(\mathbf{w}_{1}(f(x))-\mathbf{w}_{2}(f(x))).
\end{equation}
When $x\in \mathbb{R}^{n}\setminus \mathcal{X}$, we have $\xi(x)=1$, implying $\mathbf{w}(x)=1=\mathcal{W}(x)$. Over  $ \mathcal{D}_{0}^{\mathcal{X}}$, $\mathbf{v}(\cdot)=-\ln(1-\mathbf{w}(\cdot))$ is well-defined due to Lemma \ref{lem:boundedness}, satisfying equation \eqref{eq:LyapunovEqn}. Then, using Theorem \ref{thm:LyapunovEqnUniqueness},  it follows that $\mathbf{v}(x)=\mathcal{V}(x)$, hence $\mathbf{w}(x)=\mathcal{W}(x)$ for all   $x\in \mathcal{D}_{0}^{\mathcal{X}}$.


Let $x\in \mathcal{X}$ be such that $\varphi_{x}(j)\in \mathbb{R}^{n}\setminus \mathcal{X}$ or $\varphi_{x}(j)\in \mathcal{D}_{0}^{\mathcal{X}}$  for some $j\in \mathbb{N}$ and $\varphi_{x}(k)\in \mathcal{X}~\forall k\in \intcc{0;j-1}$.  Then, we have, using equation \eqref{eq:difference1},  
$
\mathbf{w}(\varphi_{x}(j-1))-\mathcal{W}(\varphi_{x}(j-1))=(1-\xi(\varphi_{x}(j-1)))(\mathbf{w}(\varphi_{x}(j))-\mathcal{W}(\varphi_{x}(j)))=0$,
and by an inductive argument, we have 
$\mathbf{w}(\varphi_{x}(k))-\mathcal{W}(\varphi_{x}(k))=0~\forall k\in \intcc{0;j}$, implying $\mathbf{w}(x)=\mathcal{W}(x)$. 

 Now, let $x\in \mathcal{X}$ be such that $\varphi_{x}(k)\in \mathcal{X}$ for all $k\in \mathbb{Z}_{+}$ and $\lim_{k\rightarrow \infty}\varphi_{x}(k)\neq 0_{n}$. Obviously, $\varphi_{x}(k)\not\in \mathcal{D}_{0}^{\mathcal{X}}$ for all $k\in \mathbb{Z}_{+}$ 
then it follows, using the openness of $\mathcal{D}_{0}^{\mathcal{X}}$ that there exist $\theta>0$ such that $\norm{\varphi_{x}(k)}\geq \theta~\forall k\in \mathbb{Z}_{+}$. Assume $\mathbf{w}(x)\neq \mathcal{W}(x)$. 

Note the difference of two solutions, $\mathbf{w}_{1}$ and $\mathbf{w}_{2}$, to equation \eqref{eq:ZubovEqn1} over $\mathcal{X}$ (which are also solutions to \eqref{eq:ZubovEqn2} over $\mathcal{X}$ using Theorem \ref{thm:ZubovEqn2}) satisfies, for $x\in \mathcal{X}$,
\begin{equation}\label{eq:difference2}
    \mathbf{w}_{1}(f(x))-\mathbf{w}_{2}(f(x))=(1+\beta(x))(\mathbf{w}_{1}(x)-\mathbf{w}_{2}(x)).
\end{equation} 
It then follows that, for all $j\in \mathbb{N}$,   
$
\mathbf{w}(\varphi_{x}(j))-\mathcal{W}(\varphi_{x}(j))=\prod_{k=0}^{j-1}(1+\beta(\varphi_{x}(k)))(\mathbf{w}(x)-\mathcal{W}(x)).
$
For all $k \in \intcc{0;j-1}$, we have 
$
1+\beta(\varphi_{x}(k))=\exp(\gamma(\varphi_{x}(k))\alpha(\varphi_{x}(k))) \geq \exp(\underline{\gamma}\alpha_{m}\norm{\varphi_{x}(k)})\geq  \exp(\underline{\gamma}\alpha_{m}\theta^{2})$. Hence,
  $
\abs{\mathbf{w}(\varphi_{x}(j))-\mathcal{W}(\varphi_{x}(j))}\geq \exp(j\underline{\gamma}\alpha_{m}\theta^{2})\abs{\mathbf{w}(x)-\mathcal{W}(x)}.
  $
  As $\lim_{ j\rightarrow\infty}\exp(j\underline{\gamma}\alpha_{m}\theta^{2})=\infty$. It then follows that for each $M>0$, there exists $y\in \mathcal{X}$ (which corresponds to a point in the trajectory $\varphi_{x}$) such that  $\mathbf{w}(y)>M+\mathcal{W}(y)\geq M-1$ or $\mathbf{w}(y)<-M+\mathcal{W}(y)\leq -M+1=-(M-1)$, which is equivalent to $\abs{w(y)}> M-1$. Hence, $\mathbf{w}$ is unbounded over $\mathcal{X}$, a contradiction.
\end{proof}
\section{Physics-Informed neural solution}
\label{sec:PINN}

 Let $W_N(\cdot ; \theta)\colon \mathbb{R}^{n}\rightarrow \mathbb{R}$ be a fully-connected feedforward neural network with parameters denoted by $\theta$. We now train $W_N$ to solve Zubov's equation \eqref{eq:ZubovEqn1} on a compact set $\mathbb{X} \subset \mathbb{R}^n$, with $\mathcal{X} \cap \mathbb{X}\neq \emptyset$, by minimizing the following loss function:
\begin{equation}
\begin{split}
 \label{eq:lossV}
     \text{Loss}(\theta)=& 
     \frac{1}{N_c}\sum_{i=1}^{N_c} (W_N(x_{i};\theta)-W_N({f}(x_{i});\theta)-\\
    &\xi(x_{i})(1-W_N(f(x_{i});\theta)))^2  \\
    % \\& + \lambda_b \frac{1}{N_b} \sum_{i=1}^{N_b}(W_N(y_i;\theta)-B(y_i))^2\\
    & + \lambda_d \frac{1}{N_d} \sum_{i=1}^{N_d}(W_N(z_i;\theta)-\hat W(z_i))^2, 
    \end{split}
\end{equation}
 where $\lambda_b > 0$ and $\lambda_d > 0$ are user-defined weighting parameters. Here, the points $\{x_i\}_{i=1}^{N_c} \subset \mathbb{X}$ are the (interior) collocation points to compute the residual error of \eqref{eq:ZubovEqn1}. 
 % $B(y_i)$ denotes the boundary conditions of the Zubov equation, with the set $\{y_i\}_{i=1}^{N_b} \subset \partial \mathbb{X}$ consists of boundary points. Specifically, we only have  here. Moreover, if 
 To ensure an accurate neural network solution, we add the second term (refer to the data term) to guide the training, using the (approximate) ground truth values for $w$ at a set of points $\{z_i\}_{i=1}^{N_d} \subset \mathbb{X}$.

For each $z_i$, given a fixed (sufficiently large)  $M\in \mathbb{N}$, we compute $\mathcal{V}(z_i) \approx \sum_{k=0}^{M}\gamma({\varphi}_{x}(k))\alpha ({\varphi}_{x}(k))$. Note that as along as $\mathcal{V}(z_i)$ is finite, it is within the safe region. Next, we choose a large enough constant $C_{max}$ such that $C_{max} > \mathcal{V}(z_i)$, for all sampled $z_i$ whose trajectory does not leave the safe region and converges towards to the origin. Considering the fact that $1 - \exp(-40) \approx 1$, we introduce a scaling factor $\mu = \frac{40}{C_{max}}$ and define $\hat{\mathcal{V}}=\mu \mathcal{V}$, which corresponds to the value function given by (\ref{eq:Lyapunov1}) with $\alpha$ replaced by $\mu\alpha$. We then let $\hat W(z_i) = 1- \exp ( - \hat{\mathcal{V}}(z_i))$. Consequently, the approximate ground truth $\hat W$ takes values from 0 to 1, and $\hat W(z_i) < 1$ when it is in the safe region. Additionally, we set $\hat W(z_i) = 1$ in the following two scenarios: 1) if the trajectory $\varphi_{z_i}(k)$ that enters the unsafe region which results in $\mathcal{V}(z_i) > C_{max}$; 2) $\varphi_{z_i}(k)$ diverges, which can be numerically checked by examining the values of the states, that is, $\norm{\varphi_{z_i}(k)} > C_X$, where $C_X$ is a user-defined threshold.
% i.e., the pairs $(z_i, \hat{W}(z_i))\}_{i=1}^{N_d}$.
We also include the condition $\hat W(0) = 0$ in the data loss.

