\subsection{Enlarge the ROAs with the neural Lyapunov functions} 
\label{sec:enlarge_neural}
% Assume $\mathbf{V}_{c_2} \subseteq X$.
The safe ROA estimate can be further enlarged if we can find a neural network Lyapunov function $W_N(x)$ by minimizing \eqref{eq:lossV} and verifying the following inequalities:
\begin{align}
(W_N(x)\le w_1) \wedge (x\in \mathbb{X})  & \Longrightarrow V_P(x)\le c_2, \label{eq:c2_inclusion} \\
(V_P(x)\le c_2) \wedge (x\in \mathbb{X})  &  \Longrightarrow W_N(x)\le w_2, \label{eq:w2_inclusion} \\
(w_1\le W_N(x) \le w_2) \wedge (x\in \mathbb{X}) & \Longrightarrow \notag \\ 
(W_N^+(x)  \le -\varepsilon) \wedge (g(x) & < 1) \wedge (f(x) \in \mathbb{X})\label{eq:dW}.
\end{align}
where $\varepsilon>0$, $w_2>w_1>0$, and $W_N^+(x) := W_N (f(x)) - W_N(x)$. 
% If (\ref{eq:dW}) and (\ref{eq:WP}) hold and the set $\mathcal{W}_{c_{V2}}=\{x\in X:\, W_N(x)\le c_{V2}\}$ does not intersect with the boundary of $X$, then $\mathcal{W}_{c_{V2}}$ is a safe ROA for (\ref{eq:System}).


\begin{prop}
    % \textcolor{blue}{Assume $\mathbf{V}_{c_2} \subseteq X$.} 
    Suppose that \eqref{eq:c2_inclusion}-\eqref{eq:dW} and the conditions in Proposition \ref{prop:enlarge_quad} hold. Then the set $\textbf{W}_{w_2} := \{x\in \mathbb{X}:\,W_N(x)\le w_2\}$ is a safe  ROA of \eqref{eq:System}. 
\end{prop}

\begin{proof}
    Define $\textbf{W}_{w_1} := \{x\in \mathbb{X}:\,W_N(x)\le w_1\}$ and  $\textbf{W}_{w_2/w_1} := \{x\in \mathbb{X}:\, w_1 < W_N(x)\le w_2\}$, where  $\textbf{W}_{w_2}=\textbf{W}_{w_1}\cup \textbf{W}_{w_2/w_1}$. 

    By conditions \eqref{eq:c2_inclusion} and \eqref{eq:w2_inclusion}, and proposition \eqref{prop:enlarge_quad},
    $\textbf{W}_{w_1}\subseteq \mathbf{V}_{c_{2}}\subseteq \textbf{W}_{w_2}\subseteq \mathcal{X}$.  Moreover, proposition \eqref{prop:enlarge_quad} implies that 
    \begin{equation}
    \label{eq:StartingFromWw1}
    x\in \mathbf{W}_{w_{1}}\Rightarrow \varphi_{x}(k)\in \mathbf{V}_{c_{2}}\subseteq \textbf{W}_{w_2},~ k\in \mathbb{Z}_{+},
    \end{equation}
    and $\lim_{k\rightarrow \infty}\varphi_{x}(k)=0_{n}$. 

    Let $x \in \mathbf{W}_{w_2/w_1}$.  Using condition \eqref{eq:dW}, we have $f(x) \in \mathbb{X}$ and $W_{N}(f(x))\leq w_{2}-\varepsilon\leq w_{2}$, i.e.,  $f(x)\in \textbf{W}_{w_2}$. This and  equation \eqref{eq:StartingFromWw1} imply the invariance of  $\mathbf{W}_{w_{2}}$.  

    It remains to show that, for $x \in \textbf{W}_{w_2/w_1}$,  there exists $N\in \mathbb{Z}_{+}$ such that $\varphi_{x}(N)\in \mathbf{W}_{w_{1}}$.    By contradiction, assume that $\varphi_{x}(k) \in \textbf{W}_{w_2/w_1}$ for all $k\in \mathbb{Z}_{+}$, then $w_1 < W_N(\varphi_{x}(k)) \le w_2$ for all $k\in \mathbb{Z}_{+}$. However, by inductively using   condition \eqref{eq:dW},  $W_N(\varphi_{x_0}(k))\leq w_{2} - k \epsilon,~k\in \mathbb{Z}_{+}$, which implies that for an integer $k>(w_{2}-w_{1})/\varepsilon$, $W_N(\varphi_{x_0}(k))< w_{1}$, a contradiction.  
\end{proof}


