\begin{algorithm}
\caption{Parallel Factorization on CPU}
\label{a:cpu}
\begin{algorithmic}[1]
\Require Laplacian matrix $L \in \mathbb{R}^{N \times N}$ associated with $\mathcal{G} = (V, E)$, elimination index $k$, and \texttt{count}
\Ensure output array $O$ containing the factor entries, diagonal matrix $D$.

\State{\texttt{num\_threads} = total number of threads}
\State{initialize dependency array: $\forall i, \texttt{dp}[i] = |\{j \mid j < i, e_{ij} \neq 0\}|$}
\State{initialize job queue: $q \leftarrow \{i \mid i \in V, e_{ij} = 0, \forall j < i\}$}
\State{$O \leftarrow$ output array}
\State{$P \leftarrow $ linked-list head-pointer}

\For {$\texttt{id} = \texttt{thread\_id}$, $\texttt{id} = \texttt{id} + \texttt{num\_threads}$, $\texttt{id} \leq N-1$}
\State{$k \leftarrow q[\texttt{id}]$, spin wait on $q[\texttt{id}]$ if necessary}
\State{allocate space in $O$}
\State{$\mathcal{N}_k \leftarrow$ traverse linked-list start from $P(k)$ }
\If{$|\mathcal{N}_k| = 0$}
\State{$D(k,k) = 0$, continue}
\Else
\State{$D(k,k) = \sum_i^{|\mathcal{N}_k|} |\mathcal{N}_k(i)$.\texttt{sum}|}
\EndIf
\State {$\mathcal{N}_k \leftarrow$ Sort $\mathcal{N}_k$ in ascending order based on row/vertex id, then merge same ids}
\State {$\mathcal{N}_k \leftarrow$ Sort $\mathcal{N}_k$ in ascending order based on $|\ell_{ik}|$ for $i \in \mathcal{N}_k$}
\State $S \leftarrow $ suffix sum on $|\ell_{ik}|$ for $i \in \mathcal{N}_k$.
\hfill \Comment{\cyan{// $S[i] = - \sum_{g = i}^{\left| \mathcal{N}_k \right|} \ell_{gk}$}}
\For{$i = 1 : \left| \mathcal{N}_k \right| - 1$}
\State{Sample  $j$ from $\mathcal{N}_k[i + 1: \left| \mathcal{N}_k \right|]$ w.p. $|\ell_{kj}|/S[i + 1]$} 
\State {\texttt{dp}$[\max(i, j)]\texttt{+=1}$}
%\hfill \Comment{\cyan{// blue node in \cref{f:sample}}}
\State $P(\min(i,j)) \underbrace{\leftarrow}_{\text{insert to linked-list}} \frac{S[i + 1]\, \ell_{ki}}{\ell_{kk}} \, \bb_{ij} \bb_{ij}^\top$
\EndFor
\State {do $\forall i = 1 : |\mathcal{N}|$, \texttt{dp}[$i$]\texttt{ -= }$\mathcal{N}(i).\texttt{multiplicity}~~$} \hfill \Comment{\cyan{// multiplicity is used since same edge might be added multiple times}}
\State{insert into queue: $q \leftarrow \{i \mid \texttt{dp}[i] = 0\}$}

\EndFor
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htpb]
\caption{Parallel Factorization on GPU}
\label{a:gpu}
\begin{algorithmic}[1]
\Require Laplacian matrix $L \in \mathbb{R}^{N \times N}$ associated with $\mathcal{G} = (V, E)$, elimination index $k$, and \texttt{count}
\Ensure output array $O$ containing the factor entries, diagonal matrix $D$.
\State{\texttt{block\_id} $\leftarrow$ block number}
\State{\texttt{num\_blocks} = total number of blocks}
\State{initialize dependency array: $\forall i, \texttt{dp}[i] = |\{j \mid j < i, e_{ij} \neq 0\}|$}
\State{initialize job queue: $q \leftarrow \{i \mid i \in V, e_{ij} = 0, \forall j < i\}$}
\State{$O \leftarrow$ output array, $W \leftarrow $ workspace containing the Schur-complement updates of active vertices (ones that are not eliminated)}


\For {$\texttt{id} = \texttt{block\_id}$, $\texttt{id} = \texttt{id} + \texttt{num\_blocks}$, $\texttt{id} \leq N-1$}
\State{$k \leftarrow q[\texttt{id}]$, spin wait on $q[\texttt{id}]$ if necessary}
\State{allocate space in $O$}
\State{$h \leftarrow$} hash($k$)
\State{$\mathcal{N}_k \leftarrow$ search $W$ in parallel starting from $h$}
\If{$|\mathcal{N}_k| = 0$}
\State{$D(k,k) = 0$, continue}
\Else
\State{$D(k,k) = \sum_i^{|\mathcal{N}_k|} |\mathcal{N}_k(i)$.\texttt{sum}|}
\EndIf
\State {$\mathcal{N}_k \leftarrow$ Parallel Sort $\mathcal{N}_k$ in ascending order based on row id, then use prefix sum to merge entries with same row id in parallel}
\State {$\mathcal{N}_k \leftarrow$ Parallel Sort $\mathcal{N}_k$ in ascending order based on $|\ell_{ik}|$ for $i \in \mathcal{N}_k$}
\State $S \leftarrow $ parallel suffix sum on $|\ell_{ik}|$ for $i \in \mathcal{N}_k$.
\hfill \Comment{\cyan{// $S[i] = - \sum_{g = i}^{\left| \mathcal{N}_k \right|} \ell_{gk}$}}
\For{$i = 1 : \left| \mathcal{N}_k \right| - 1$} in parallel
\State{Sample  $j$ from $\mathcal{N}_k[i + 1: \left| \mathcal{N}_k \right|]$ w.p. $|\ell_{kj}|/S[i + 1]$} 
\State {\texttt{dp}$[\max(i, j)]\texttt{+=1}$}
%\hfill \Comment{\cyan{// blue node in \cref{f:sample}}}
\State $W(\texttt{hash}(\min(i, j))) \leftarrow \frac{S[i + 1]\, \ell_{ki}}{\ell_{kk}} \, \bb_{ij} \bb_{ij}^\top$
\hfill \Comment{\cyan{// pick edge $(i,j)$; assign weight ${S\, |\ell_{ki}|}/{\ell_{kk}}$, right-looking update}}
\EndFor
\State {do parallel $\forall i = 1 : |\mathcal{N}|$, \texttt{dp}[$i$]\texttt{ -= }$\mathcal{N}(i).\texttt{multiplicity}~~$} \hfill \Comment{\cyan{// multiplicity is used since same edge might be added multiple times}}
\State{insert into queue: $q \leftarrow \{i \mid \texttt{dp}[i] = 0\}$}

\EndFor
\end{algorithmic}
\end{algorithm}

