\subsection{Entropy-Optimal DDG Trees}

\Citet{knuth1976} settle the problem of constructing a DDG tree sampler for
any distribution $\bp$ whose expected entropy cost is minimal among the
class of all DDG trees with output distribution $\bp$.

\begin{theorem}[{\Citet[Theorem 2.1]{knuth1976}}]
\label{theorem:knuth-yao}
Let $\bp \defeq (p_1, \dots, p_n)$ denote a discrete probability
distribution over $n$ outcomes.
%
Let
$\mathcal{T}(\bp) = \set{T : \set{0,1}^{*} \rightharpoonup \nat \mid \bp_T = \bp}$
denote the set of all DDG trees whose output distribution is $\bp$.
%
The following statements regarding a DDG tree $T \in \mathcal{T}(\bp)$ are equivalent:
\begin{enumerate}[label={\labelcref{theorem:knuth-yao}.\arabic*)}]
\item For all $d \geq 0$, $T$ minimizes the probability of consuming more than
$d$ coin flips, in the sense that
\begin{align}
\forall\ T' \in \mathcal{T}(\bp).\
\forall d \in \mathbb{N}.\
\Pr(\cost{T} > d) \leq \Pr(\cost{T'} > d).
\end{align}

\item For each label $i=1,\dots,n$ and depth $d \geq 0$,
the number of leaf nodes with label $i$ at depth $d$ of $T$ satisfies
$\leaves{T}{d}{i} = \epsilon_d(p_i) \in \set{0,1}$, where
$\epsilon_d(x) \defeq \floor{2^d x} \bmod 2$ is the $d$th bit to the
right of the binary point in the binary expansion of $x \in [0,1]$.

\item The expected entropy cost of $T$ is minimal, in the sense that
\begin{align}
\expect{\cost{T}} = \min\set{ \expect{\cost{T'}} \mid T' \in \mathcal{T}(\bp)}
= \nu(p_1) + \dots + \nu(p_n),
\end{align}
where $\nu(x) = \sum_{d=0}^{\infty} d \epsilon_d(x)2^{-d}$ is the ``new''
entropy function.
\qedhere
\end{enumerate}
\end{theorem}

Following this theorem, an entropy-optimal DDG tree
can be constructed from the binary expansions of the probabilities $p_i$.
%
\Citeauthor{knuth1976} also characterize the expected entropy cost of
entropy-optimal DDG trees.

\begin{theorem}[{\Citet[Theorem 2.2 and Corollary]{knuth1976}}]
\label{theorem:ky-toll}
The expected entropy cost $\expect{\cost{T}}$ of any entropy-optimal DDG
tree $T$ for $\bp$ satisfies
$H(\bp) \leq \expect{\cost{T}} < H(\bp) + 2$,
and these bounds are the best possible.
\end{theorem}

\begin{proof}[Proof (Sketch)]
\Cref{eq:ddg-tree-toll} and \cref{theorem:knuth-yao} give a simple
expression for the entropy toll of an entropy-optimal DDG tree $T$
with output distribution $\bp_T = \bp$:
\begin{align}
\toll{T}
  \defeq \expect{\cost{T}} - H(\bp)
  = \sum_{i=1}^{n}p_i \left[{\frac{\nu(p_i) - H_1(p_i)}{p_i}}\right],
\label{eq:toll-expectation}
\end{align}
where $H_1(x) \defeq x \log(1/x)$, and by continuity $H_1(0) \defeq 0$.
%
(Here, the ${}_1$ subscript indicates that the function is applied to a
single value, rather than a distribution.)
%
\Citet[Theorem 2.2]{knuth1976} prove that
$0 \leq ({\nu(x) - H_1(x)})/{x} < 2$
for any $x>0$ (cf.~\cref{corollary:relative-toll-bound-constant}),
which implies by \cref{eq:toll-expectation} that
the entropy toll satisfies
$0 \leq \toll{T} < 2$.
\end{proof}

\begin{remark}
\label{remark:toll-of-dist}
The notation $\ky[\bp]$
denotes any entropy-optimal DDG tree with output distribution $\bp$.
% %
Every DDG tree $T$ satisfies $\toll{\ky[\bp_T]} \leq \toll{T}$, with
equality if and only if $T$ is entropy optimal.
%
The gap $\toll{T} - \toll{\ky[\bp_T]} \geq 0$ characterizes the
entropy inefficiency of $T$ relative to an entropy-optimal sampler.
\end{remark}

\paragraph*{Exponential Space Complexity}
%=
\Citet[Theorem 3.5]{saad2020popl} show that, in a standard model of
computation for \cref{problem:sampling},
any entropy-optimal DDG tree $T$ for $\bp$
has a finite representation with at most $m$ levels, and that this
bound is tight \citep[Theorem 3.6]{saad2020popl} for infinitely many
target distributions $\bp$ \citep[Remark 3.7]{saad2020fldr} (assuming Artin's
conjecture on primitive roots).
%
Because the $m$-type distribution $\bp$ can be encoded using $n\log(m)$ bits, a DDG
tree with $m$ levels is exponentially large in the input size.
%
For example, any finite representation of an entropy-optimal DDG tree for
the $\mathrm{Binomial}(50, 61/500)$ distribution has roughly
$5.6\times{10^{104}}$ levels.
%
More generally, a 64-bit machine can natively represent $m$-type
distributions where $m \approx 2^{64}$, highlighting the enormous resources
in practice required by any algorithm whose space complexity is
$\Omega(m)$.

\subsection{Rejection Sampling}
\label{sec:rejection-sampling}

The rejection sampling method of \citet{neumann1951}
generates exact random variates from
$\bp \defeq (p_0, p_1, \dots, p_n)$
by means of a proposal distribution $\bq \defeq (q_0, q_1, \dots, q_n)$, for
which there exists a finite bound $B \geq 1$ that satisfies
$p_i \leq B q_i$ and each $q_i$ is assumed to be positive.
%
A sample $I \sim \bq$ is first generated from $\bq$ and then accepted with
probability $\alpha(I) \defeq p_I/(Bq_I)$;
otherwise it is rejected and the process repeats.
%
As the probability of accepting in any given trial is $1/B$,
the number of trials until acceptance follows a geometric
distribution with parameter $1/B$.

\paragraph*{Expected Entropy Cost}

Let $T_\bq$ be any DDG tree with output distribution $\bq$ and let $T_i$ be
entropy-optimal DDG
trees for the accept-reject decision, i.e., $\bp_{T_i} = (1-\alpha(i),
\alpha(i))$ for $i=0,\dots,n$.
%
The overall DDG tree $R$ of the rejection sampler has the same structure as
$T$, where each leaf labeled $i$ in $T$ is replaced with a new subtree
$T'_i$ in $T$.
%
Each tree $T'_i$ is derived from $T_i$, where leaves with label $0$
in $T_i$ are replaced in $T'_i$ with a back edge to the root of $R$ (reject);
and leaves with label $1$ in $T_i$ are relabeled to $i$ in $T'_i$ (accept).
%
By memorylessness of the rejection sampler,
the expected entropy cost of $R$ is the expected number of trials times
the per trial expected cost:
\begin{align}
\expect{\cost{R}} &= B \cdot
  \left(
    \expect{\cost{T_\bq}}
    + \sum_{i=0}^{n}\expect{\cost{T_i}}q_i
  \right),
  \label{eq:expected-cost-rejection}
\end{align}
where $\expect{\cost{T_i}} \leq 2$, as analyzed in \cref{remark:bernoulli-nu}.

\paragraph*{Choice of Proposal}
If $T_\bq \equiv \ky[\bq]$ is an entropy-optimal sampler for the proposal $\bq$,
then it may in general be much larger than the target distribution $\bp$.
%
However, if $\bq$ is additionally
constrained to contain only dyadic probabilities with
denominator $2^K = \textrm{poly}(m)$, then its DDG tree
$\ky[\bq]$ scales polynomially with the input size.
%
If there exists $i$ such that $1-\alpha(i)$ is not a power of two, then the overall
rejection sampler $R$
fails to be entropy optimal, because it has at least two distinct back edges to
the root; cf.~\cref{corollary:fldr-power-of-two}.
%
If $\bq$ is dyadic and every $\alpha(i)$ is dyadic, then $R$ can be thought of as a
(possibly entropy-suboptimal) rejection sampler using another proposal $\bq'$
that is dyadic and satisfies $\alpha(i) \in \set{0,1}$ for all $i$.
%
In other words, in the random bit model, it suffices to consider dyadic
proposals $\bq$ which have all rejection concentrated in a single label $0$
where $p_0 \defeq 0$, and all other labels $1 \leq i \leq n$ have acceptance
probability $\alpha(i) = 1$.
%
The next sections study this family of entropy-efficient rejection samplers.

\section{Fast Loaded Dice Roller}
\label{sec:fldr}

\input{fig-aldr}

The Fast Loaded Dice Roller ($\fldr$) \citep{saad2020fldr} is an efficient
rejection sampling algorithm for simulating a discrete probability
distribution with rational weights, whose memory scales linearithmically
with the input size.
%
Recalling \cref{problem:sampling}, we will momentarily consider an arbitrary input list
$(A_1,\dots,A_n)$ of $n$ positive integers that need not be coprime,
with sum $M$.
%
The first step is to set $K \defeq \ceil{\log(M)}$, i.e., $2^{K-1} < M \leq 2^K$.
%
Then form a dyadic proposal distribution
$\bq \defeq (q_0, q_1, \dots, q_{n})$ with denominator $2^K$
over $n+1$ outcomes, whose probabilities are
\begin{align}
A_{0} \defeq 2^K-M
&&
q_{i} \defeq A_i / 2^K
\qquad (i = 0,1,\dots,n).
\label{eq:proposal-distribution}
\end{align}
%
The DDG tree of the FLDR sampler---denoted $\fldr[A_1,\dots,A_n]$---is
identical to an entropy-optimal DDG tree $\ky[\bq]$,
except that every leaf with the reject label $0$
becomes a back edge to the root.
%
Because $\bq$ is dyadic, the tree $\ky[\bq]$ has $K$ levels, avoiding
exponential growth of the depth with the size of $\bp$.

In terms of rejection sampling, the tightest rejection bound
is $B \defeq 2^K/M$; i.e., it is the smallest number that satisfies
$p_i \leq B q_i$ for $i=0,1,\dots,n$, because
$p_i = A_i/M = 2^K/M \cdot A_i/2^K = Bq_i$
($i=1,\dots,n$) and $p_{0} = 0 \leq Bq_{0}$.
%
It follows that $i \sim \bq$ is accepted with probability $p_i/(Bq_i) = 1$
if $i \in \set{1,\dots,n}$, and $i=0$ is rejected.
%
This property means that the Bernoulli subtree cost is $\expect{\cost{T_i}} = 0$
in \cref{eq:expected-cost-rejection}, with all entropy used only to sample the
proposal, and in particular,
\begin{equation}
\expect{\cost{\fldr[A_1,\dots,A_n]}} = (2^K/M) \expect{\cost{\ky[\bq]}}.
\label{eq:fldr-cost}
\end{equation}
%
\Cref{alg:fldr} gives a high-level overview of the $\fldr$ algorithm and
\cref{fig:ddg-ky-fldr} shows examples of the underlying DDG trees for the
target distribution, the proposal distribution, and overall rejection
sampler $\fldr[\bp]$.

\begin{remark}
\label{remark:fldr-scaling}
The explicit notation $\fldr[A_1,\dots,A_n]$ is necessary because the space
and entropy costs of \cref{alg:fldr} are sensitive to the scaling of
the inputs $(a_1,\dots,a_n)$ that define the $m$-type distribution
$\bp$ (i.e., these integers need not be coprime).
%
The notation $\fldr[\bp]$ is defined as $\fldr[a_1,\dots,a_n]$, where
$(a_1,\dots,a_n)$ is the unique list of coprime positive integers that define
$\bp = (a_1/m, \dots, a_n/m)$ and
$m \defeq a_1 + \dots + a_n$ is the smallest integer
for which $\bp$ is $m$-type.
%
Henceforth, the ``entropy cost (or depth or toll) of $\fldr$'' will therefore
refer to $\fldr[\bp]$ unless otherwise specified.
\end{remark}

\input{fig-ddg-ky-fldr}

\paragraph*{FLDR Space and Entropy Bound}

\Citet[Theorem 5.1]{saad2020fldr} prove that the tree $\fldr[A_1,\dots,A_n]$ has
at most $2(n+1)\ceil{\log(M)} = \Theta(n\log(M))$ nodes, matching the input.
%
Because each label $i \in \set{0,1,\dots,n}$ at a leaf requires
$\ceil{\log(n+1)}$ bits, the overall space complexity is $n\log(M)\log(n)$,
which is linearithmic in the input size.
%
In addition, \citeauthor{saad2020fldr} prove the following bound on the expected
entropy cost of the FLDR sampler.

\begin{theorem}[{\Citet[Theorem 5.1]{saad2020fldr}}]
\label{theorem:fldr-bound}
The toll of the FLDR sampler for any distribution $\bp$ is less than $6$.
%
That is, the expected entropy cost of FLDR satisfies
$H(\bp) \leq \expect{\cost{\fldr[A_1,\dots,A_n]}} < H(\bp) + 6$.
\end{theorem}

\begin{proof}
\Citet{saad2020fldr} prove that the full expression of the toll is given by
\begin{align}
\toll{\fldr[A_1,\dots,A_n]}
  &= \log(2^K / M) + (2^K - M) / M \log(2^K / (2^K - M)) + 2^K \toll{\ky[\bq]} / M
  \label{eq:fldr-toll-original}
\end{align}
and note that the three summands in \cref{eq:fldr-toll-original} are bounded by
1, 1, and 4, respectively, which establishes \cref{theorem:fldr-bound}.
%
We present an alternative proof of \cref{eq:fldr-toll-original}
directly in terms of entropy, which will be useful in future sections.
%
Let $E$ be the event that an ``accept'' outcome
in $\set{1,\dots,n}$ is obtained from a single draw from
the proposal $\bq$, so that
$\Pr(E) = q_{1} + \cdots + q_{n} = M/2^K$.
%
The conditional entropy of $\bq$ given $E$
is $H(\bq|E) = H(\bp)$, and $H(\bq|E') = 0$.
%
Using the chain rule for conditional entropy to write $H(\bq)$ in terms of
$H(\bp)$ and the acceptance probability $M/2^K$ gives
\begin{align}
H(\bq)
&= H(\bq|E) \Pr(E) + H(\bq|E')\Pr(E') + H(E) \\
&= H(\bp)M/2^K + H_{\rm b}(M/2^K).
\label{eq:q-entropy-decomposition}
\end{align}
%
Combining the toll expressions \cref{eq:fldr-cost,eq:ddg-tree-toll} with the
proposal entropy decomposition \cref{eq:q-entropy-decomposition} gives
\begin{align}
\toll{\aldr[\bp, K]}
&= \left(2^K/M\right) \left( H(\bq)+\toll{\ky[\bq]} \right) - H(\bp) \\
&= \left(2^K/M\right) \left( H(\bp)M/2^K + H_{\rm b}\left(M/2^K\right)+\toll{\ky[\bq]} \right) - H(\bp) \\
&= \left(2^K/M\right) \left( \toll{\ky[\bq]} + H_{\rm b}\left(M / 2^K\right) \right),
\label{eq:fldr-toll-binary-entropy}
\end{align}
and expanding the binary entropy yields \cref{eq:fldr-toll-original}.
\end{proof}

More particular details of the toll depend on the exact input $(A_1,\dots,A_n)$.
%
If $M \in \set{2^K, 2^K-1}$, then FLDR is entropy optimal in the sense of
\cref{theorem:knuth-yao}.
%
If $M = 2^{K-1}+1$, then FLDR
obtains its worst-case rejection probability
$1-1/B = (2^K-M)/2^K = 1/2 - 2^{-K} \approx 1/2$.

\paragraph*{FLDR Entropy Bound is Tight}

\Cref{theorem:fldr-is-tight} extends the result of
\citet{saad2020fldr} by demonstrating a sequence of probability
distributions for which the expected entropy cost of FLDR approaches
$H(\bp) + 6$ exponentially quickly in the depth $k$,
which proves that the upper bound in \cref{theorem:fldr-bound} is in fact tight.

The following bound on the binary entropy function is useful.

\begin{proposition}[{\Citet[Theorem 1.1]{topsoe2001}}]
\label{theorem:topsoe}
The binary entropy $H_{\rm b}(p) \defeq p \log(1/p) + (1-p) \log(1/(1-p))$
satisfies
\begin{align}
\ln(2) \log(p) \log(1-p) &\leq H_{\rm b}(p) \leq \log(p) \log(1-p)
\end{align}
for all $p \in [0,1]$.
\end{proposition}

\begin{theorem}[Tightness of FLDR toll bound]
\label{theorem:fldr-is-tight}
There exists a sequence of rational discrete probability distributions
$\bp_2, \bp_3, \dots$ whose entropy tolls satisfy
$6 - \toll{\fldr[\bp_k]} = O(k2^{-k})$, for each FLDR tree depth $k \geq 2$.
\end{theorem}

\begin{proof}
\input{fig-fldr-tight}

Let $k \geq 2$, and consider the distribution
$\bp_k \defeq ((2^{k-1} - 1)/m, 2/m)$ with $m \defeq (2^{k-1} + 1)$.
%
Then \cref{theorem:topsoe} and $\log(1+x) \leq x/\ln(2)$ together yield an upper
bound on the entropy:
\begin{align}
H(\bp_k)
= H_{\rm b}\left(\frac{2}{2^{k-1} + 1}\right)
\leq \log\left(\frac{2^{k-1} + 1}{2}\right) \log\left(\frac{2^{k-1} + 1}{2^{k-1} - 1}\right)
< (k-1) \frac{2}{2^{k-1} - 1} \big/ \ln(2)
< \frac{k-1}{2^{k-4}}.
\end{align}
%
\Cref{theorem:knuth-yao} shows that the expected entropy cost of the
entropy-optimal sampler for the proposal distribution
$\bq_k \defeq ((2^{k-1}-1)/2^k, (2^{k-1}-1)/2^k, 2/2^k)$ is
\begin{equation}
\expect{\cost{\ky[\bq_k]}}
= \nu\left(\frac{2}{2^k}\right) + 2\nu\left(\frac{2^{k-1} - 1}{2^k}\right)
= \frac{k-1}{2^{k-1}} + 2 \sum_{i=2}^{k} \frac{i}{2^i}
= \frac{k-1}{2^{k-1}} + 3 - \frac{k+2}{2^{k-1}}
= 3 \left(\frac{2^{k-1} - 1}{2^{k-1}}\right),
\end{equation}
so \cref{eq:fldr-cost} shows that the expected entropy cost of $\fldr[\bp_k]$ is
\begin{align}
  \expect{\cost{\fldr[\bp_k]}}
  = \frac{2^k}{m} \expect{\cost{\ky[\bq_k]}}
  = 6\left(\frac{2^{k-1} - 1}{2^{k-1} + 1}\right).
\end{align}
%
Therefore, the toll is bounded as
\begin{align}
\toll{\fldr[\bp_k]}
= 6\left(\frac{2^{k-1} - 1}{2^{k-1} + 1} \right) - \frac{k-1}{2^{k-4}}
> 6 - \frac{12}{2^{k-1}} - \frac{2k-2}{2^{k-3}}
= 6 - \frac{2k + 1}{2^{k-3}},
\end{align}
%
which approaches $6$ exponentially quickly as $k$ grows, so the bound in
\cref{theorem:fldr-bound} is tight, as illustrated in \cref{fig:fldr-tight}.
\end{proof}

\section{Amplified Loaded Dice Roller}
\label{sec:aldr}

The main contribution of this article is a parameterized
family of rejection samplers called the
\textit{Amplified Loaded Dice Roller} ($\aldr$), which exploits the
sensitivity of $\fldr[A_1,\dots,A_n]$ to the specific
scaling of the integer weights that define $\bp$.
%
These weights can be scaled in such a way that the entropy cost becomes
strictly less than $H(\bp)+2$, while maintaining the linearithmic space
complexity of FLDR.

\subsection{Main Idea}
\label{sec:aldr-main-idea}

Returning to \cref{problem:sampling}, where $(a_1, \dots, a_n)$
are coprime with sum $m$,
the proposal distribution $\bq \defeq (q_0, \dots, q_n)$
in \cref{eq:proposal-distribution}
used by $\fldr[a_1,\dots,a_n]$ has denominator $2^k$,
where $k \defeq \ceil{\log(m)}$.
%
This proposal can be generalized to a dyadic proposal
$\bq_K \defeq (q_{K,0}, q_{K,1}, \dots, q_{K,n})$
whose denominator is $2^K$ for some integer $K \geq k$.
%
To retain the desirable property from $\fldr$
that the new acceptance probabilities are
$p_i/(Bq_{K,i}) \in \set{0,1}$, it is necessary and sufficient
to scale the target weights
$(a_1, \dots, a_n)$ by an integer $c \geq 1$:
\begin{align}
A_0 \defeq 2^K-cm
&&
A_i \defeq ca_i
\; (i = 1,\dots,n),
&&
q_{K,i} \defeq A_i / 2^K
\; (i = 0,1,\dots,n).
\label{eq:amplified-proposal-distribution}
\end{align}
%
\Cref{eq:amplified-proposal-distribution} defines a valid distribution
if and only if $M \defeq cm \leq 2^K$ (i.e., $c \leq 2^K/m$), which gives
the following family of proposals whose entropy-optimal samplers
have depth at most $K$:
\begin{align}
\bq_{K,c} \defeq \left((2^K - cm)/2^K, ca_1/2^K, \dots, ca_n/2^K\right)
&&
(c = 1, 2, \dots, \floor{2^K/m}).
\label{eq:amplified-proposal-distribution-family}
\end{align}
%
Within this family, setting $c_K \defeq \floor{2^K/m}$ is the
optimal choice for maximizing the acceptance probability $cm/2^k$; and
so we define $\bq_K \defeq \bq_{K,c_K}$ or simply $\bq \defeq \bq_K$ when $K$
is a constant or clear from context.
%
Invoking \cref{alg:fldr} with the amplified weights $(A_1, \dots, A_n)$
in \cref{eq:amplified-proposal-distribution}
gives the $\aldr$ method.
%
\Cref{alg:aldr} shows the resulting family of rejection samplers, which
take as input the coprime positive integers $(a_1,\dots,a_n)$ and an
amplification rule $r: \mathbb{N} \to \mathbb{N}$ that maps the original
($\fldr$) depth $k$ to an amplified depth $K \geq k$.
%
The DDG tree of \cref{alg:aldr} is denoted $\aldr[\bp, K]$, where $K$
is an expression that involves $k$, e.g., $K = 2k$, or a constant
$K \geq k$ when there is a fixed $k$ under consideration.
%
Following \citet[Theorem 5.1]{saad2020fldr},
$\aldr[\bp,K]$ is a depth-$K$ DDG tree
and its total number of nodes is at most $2(n+1)\ceil{\log(M)} = 2(n+1)K$,
which is linear in the input size whenever $K = \Theta(k)$.

\begin{remark}
In contrast to the possible ambiguity of $\fldr[\bp]$ in
\cref{remark:fldr-scaling}, $\aldr[\bp, K]$ is uniquely defined because the
inputs $(a_1,\dots,a_n)$ to \cref{alg:fldr} that define $\bp$ are coprime.
%
Moreover, $\fldr[\bp] \equiv \aldr[\bp, k]$.
\end{remark}

\begin{remark}[Choice of Depth]
\label{remark:aldr-choice-of-K}
Because $2^{k-1} < m \leq 2^k$, the amplification constant $c_K = \floor{2^K/m}$
satisfies $2^{K-k} \leq c_K < 2^{K-k+1}$.
%
If $c_K = 2^{K-k}$ obtains its lowest possible value,
then
\begin{align}
q_{K,i} = A_i/2^K = 2^{K-k}a_i/2^K = a_i/2^k = q_{k,i}
&&
(i=1,\dots,n)
\end{align}
i.e., the amplified proposal
$\bq_K$ is equivalent to the original proposal $\bq_k$.
%
Therefore, to ensure that $\bq_K \neq \bq_k$, the new depth $K$
must be large enough to satisfy $2^{K-k} < c_K$, which means
\begin{align}
2^K/2^k < \floor{2^K/m}
\iff
2^K/2^k + 1 \leq 2^K/m
\iff
K \geq k + \log_2(m/(2^k-m)).
\label{eq:aldr-min-K}
\end{align}
If the target distribution $\bp$ satisfies
$2^{k-1} < m < 2/3 \cdot 2^k$, then \cref{eq:aldr-min-K}
holds for any choice of depth $K \geq k+1$.
%
For general $m \neq 2^k$, \cref{eq:aldr-min-K} holds for all $K \geq 2k$
because $\log_2(m/(2^k-m)) \leq \log_2(2^k-1) < k$.

More generally, because
$c_K = \floor{2^K/m} = 2 c_{K-1} + \epsilon_K(1/m)$, the proposal
distributions satisfy
\begin{alignat}{3}
\mbox{$c_K$ is even} & \iff \mbox{$c_K = 2 c_{K-1}$}
& ~                  & \iff \bq_{K} = \bq_{K-1}
\label{eq:c-case-even}
\\
\mbox{$c_K$ is odd}  & \iff \mbox{$c_K = 2 c_{K-1} + 1$}
& ~                  & \iff \bq_{K} \neq \bq_{K'}
                          & \, (K'=k,\dots,K-1).
\label{eq:c-case-odd}
\end{alignat}
%
For an intuitive understanding of this result, observe that
for fixed $(a_1,\dots,a_n)$, the ALDR proposal distributions
$\bq_K \defeq (1 - c_K m/2^K, c_K a_1/2^K, \dots, c_K a_n/2^K)$
are parameterized by the single real variable
$c_K/2^K = \floor{2^K/m}/2^K$, which is just $1/m$ rounded down
to the nearest multiple of $1/2^K$.
%
Therefore, the proposal distributions change at precisely the
depths $K$ for which bit $K$ is set in $1/m$.
\end{remark}

\begin{example}
Consider the target distribution $\bp = (4/19, 7/19, 8/19)$,
whose FLDR tree has depth $k = 5$.
%
\Cref{fig:fldr478-tolls} shows the tolls for $\aldr[\bp,K]$ trees with new
depth $K \in \set{5, \dots, 18}$, where
$\aldr[\bp,18]$ coincides with the entropy-optimal sampler from
\cref{theorem:knuth-yao}.
%
\Crefrange{fig:fldr478-trees-d5}{fig:fldr478-trees-d18}
illustrate the general trend that using greater depth
$K$ can reduce the expected entropy cost, at the expense of increased
memory.
\input{fig-ddg-exponential}
\end{example}

\subsection{Analysis of Expected Entropy Cost}

\begin{proposition}
\label{prop:rejection-probability-decreasing}
The rejection probabilities of the amplified
proposals~\labelcref{eq:amplified-proposal-distribution} are monotonically
decreasing, in the sense that
if $\bq_{K+1} \neq \bq_{K}$ then $q_{K+1, 0} < q_{K,0}$.
\end{proposition}

\begin{proof}
If $\bq_{K+1} \neq \bq_K$, then \cref{eq:c-case-odd} implies that
$c_{K+1} = 2 c_{K} + 1$, so
\begin{align}
q_{K+1,0}
\defeq 1 - \frac{m c_{K+1}}{2^{K+1}}
= 1- \frac{m (2c_K + 1)}{2^{K+1}}
< 1- \frac{m 2c_K}{2^{K+1}}
= 1- \frac{m c_K}{2^{K}}
\eqdef
q_{K,0}.
\rlap{\qquad \qedhere}
\end{align}
\end{proof}

\begin{proposition}
\label{proposition:amplified-reject-prob}
In the amplified proposal $\bq_K$ from \cref{eq:amplified-proposal-distribution},
the reject outcome has probability
$q_{K,0} < 1/(2^{K-k} + 1)$.
\end{proposition}

\begin{proof}
There are two cases on $m/2^k$ to consider:
%
\begin{enumerate}[label={Case \arabic*.}]
\item
If $m / 2^k > 1 - 1/(2^{K-k} + 1)$, then $\bq_K = \bq_k$ and the
reject outcome has probability
\begin{align}
q_{K,0} = 1 - \frac{m}{2^k} < \frac{1}{2^{K-k} + 1}.
\end{align}
%
\item
If $m / 2^k < 1 - 1/(2^{K-k} + 1) = 2^{K-k}/(2^{K-k} + 1)$,
then the reject outcome has probability
\begin{align}
q_{K,0}
= \frac{2^K - \floor{2^K / m} m}{2^K}
= \frac{2^K \bmod m}{2^K} < \frac{m}{2^K} = 2^{k-K} \frac{m}{2^k} < \frac{1}{2^{K-k} + 1}.
\end{align}
\end{enumerate}

In either case, $q_{K,0} < 1/(2^{K-k} + 1)$, and
this bound is tight along
$m = \floor{2^K/(2^{K-k} + 1)}$ as $k \to \infty$.
\end{proof}

\begin{theorem}[Generic bound on toll of ALDR]
\label{theorem:aldr-generic-bound}
The expected entropy cost of the $\aldr[\bp, K]$ sampler satisfies
$H(\bp) \leq \expect{\cost{\aldr[\bp, K]}} < H(\bp) + 2 + (4 + K-k)2^{k-K}$.
\end{theorem}

\begin{proof}
\input{fig-aldr-generic-toll-bound}
%
If $K=k$, then \cref{theorem:fldr-bound} applies directly.
%
Otherwise, applying \cref{theorem:ky-toll} and
\cref{proposition:amplified-reject-prob} to bound the toll $\toll{\ky[\bq]}$ and
the rejection bound $2^K/M$ in \cref{eq:fldr-toll-binary-entropy} yields
\begin{align}
\toll{\aldr[\bp, K]}
&< (2^K/M) ( 2 + H_{\rm b}(M / 2^K) ) \\
&< \frac{2^{K-k}+1}{2^{K-k}} \left[ 2 + H_{\rm b}\left(\frac{1}{2^{K-k}+1}\right) \right]
  \label{eq:aldr-generic-actual} \\
&= (1+2^{k-K}) ( 2 + \log(1+2^{k-K}) ) + 2^{k-K}\log(2^{K-k}) \\
&= 2 + 2^{k-K} ( 2 + K-k ) + (1+2^{k-K})\log(1+2^{k-K}).
\end{align}
%
Therefore, it suffices to show that whenever $x$ is positive,
$(1+2^x) \log(1+2^{-x}) \leq 2$.
%
When $x$ is zero, the value of this function is $(1+2^x) \log(1+2^{-x}) = 2$.
%
For $x > 0$, the derivative of $(1+2^x) \log(1+2^{-x})$ is
\begin{align}
\frac{\diff}{\diff{x}} (1+2^x) \log(1+2^{-x}) = 2^x \ln(1+2^{-x}) - 1 < 0,
\end{align}
which completes the proof.
%
\Cref{fig:aldr-generic-toll-bound} shows this result visually.
\end{proof}

Recall that $\toll{\ky[\bq]} \in [0, 2)$ is the entropy toll from a single
iteration of the FLDR rejection loop, which uses an entropy-optimal sampler for
$\bq$.
%
The excess $O((K-k)/2^{K-k})$ beyond this toll decays very
quickly in $\delta \defeq K-k$.
%
\Cref{fig:aldr-generic-toll-bound} shows how these values grow as $\delta$
increases.
%
This bound is (asymptotically) the best possible when using the
generic result $\toll{\ky[\bq]} \in [0,2)$.
%
However, this excess decreases so rapidly that it is possible to bound the
entire toll of the ALDR sampler to $2$ bits with linear amplification
$\delta = O(k)$, as demonstrated in \cref{theorem:aldr-2k-toll-two}.

\subsection{Tighter Bound on Entropy Cost for \texorpdfstring{$K = 2k$}{K=2k}}

The main theorem of this section states that $\aldr[\bp,2k]$ achieves a
toll strictly less than $2$ bits with only a doubling of memory relative to
$\fldr[\bp] \equiv \aldr[\bp,k]$.

\begin{theorem}[Bounding the toll of ALDR]
\label{theorem:aldr-2k-toll-two}
For any $K \geq 2k$, the entropy toll of $\aldr[\bp,K]$ is bounded by two.
%
That is, the expected entropy cost of the ALDR sampler satisfies
$H(\bp) \leq \expect{\cost{\aldr[\bp,K]}} < H(\bp) + 2$.
\end{theorem}

\Citet[Theorem 2.2]{knuth1976} prove that every entropy-optimal sampler satisfies
this bound using the fact that
$({\nu(x) - H_1(x)})/{x} < 2$,
but this alone will not suffice to prove that the toll of ALDR is
strictly less than $2$ (cf.~\cref{theorem:aldr-generic-bound}).
%
Instead, we need a tighter upper bound parametric in $x$.
%
The proof of \cref{theorem:aldr-2k-toll-two} requires several intermediate
results.
%
We first define relative tolls to split up the toll contributions by weight,
then bound these relative tolls, and finally combine these bounds based on the
weights of the input distribution, paying special attention to the case when
$p_i$ is a power of two, which turns out to give the worst-case relative toll
for ALDR.

\begin{definition}
\label{definition:relative-toll}
The \textit{relative toll} of $x \in [0,1]$ is
\begin{align}
\label{eq:relative-toll}
\trel{x} \defeq \frac{\nu(x) - H_1(x)}{x},
\end{align}
where $H_1(x) \defeq x \log(1/x)$, so that $H(\bp) = \sum_{i=1}^{n} H_1(p_i)$
and $\toll{\ky[\bp]} = \sum_{i=1}^{n} p_i \trel{p_i} = \expect{\trel{p_i}}$.
\end{definition}

\begin{lemma}
\label{lemma:bit-shift-relative-toll}
The relative toll is invariant under bit shifts of its argument.
%
That is, $\trel{2^a x} = \trel{x}$ for any $a \in \integers$.
\end{lemma}

\begin{proof}
Apply the equation
\begin{equation}
\trel{2x}
\defeq \frac{\nu(2x)-H_1(2x)}{2x}
= \frac{(2\nu(x)-2x)-(2H_1(x)-2x)}{2x}
= \frac{\nu(x)-H_1(x)}{x}
\eqdef \trel{x}
\end{equation}
(repeatedly as necessary for larger powers of two).
\end{proof}

\begin{remark}[$\nu$ entropy of Bernoulli distributions]
\label{remark:bernoulli-nu}
Because $\nu(1-2^{-a}) = 2 - (a+2)2^{-a}$ for any integer $a$,
the expected entropy cost of an entropy-optimal sampler for a
Bernoulli distribution with dyadic parameter $x = b/2^a$ in lowest terms (i.e., either
$b$ is odd or $x = 0 / 2^0$) is $\nu(x) + \nu(1-x) = \nu(2^{-a}) +
\nu(1-2^{-a}) = 2 - 2^{1-a}$.
%
Similarly, $\nu(x) \leq 2 - \nu(1-x)$ for any $x \in [0,1]$,
with strict inequality if and only if $x$ is dyadic.
\end{remark}

\begin{lemma}[Piecewise linear relative toll bound]
\label{lemma:relative-toll-bound-linear}
For any $a \geq 2$ and $b \in \nat$, the relative toll of
any real $x \in (2^{-b} - 2^{-b-a+1}, 2^{-b} - 2^{-b-a}]$
can be bounded strictly less than two as
$\trel{x}
< 2 - (1 - 2^b x) (a - 2 + 1/\ln(2))$.
\end{lemma}

\begin{proof}
The relative toll function and corresponding bounds are plotted in
\cref{fig:relative-tolls}.
%
\input{fig-relative-tolls}
%
First, apply \cref{lemma:bit-shift-relative-toll} to reduce to the case
$x \in (1 - 2^{1-a}, 1 - 2^{-a}]$.
%
Then $1-x \in (2^{-a}, 2^{1-a}]$ so that
$\nu(1-x) \geq a 2^{-a} + (1 - 2^{-a} - x)(a+1)$,
and \cref{remark:bernoulli-nu} implies that
\begin{align}
\trel{x}
&\leq \frac{
  2 - \nu(1-x)
}{x} + \log(x) \\
&\leq \frac{
  2 - a 2^{-a}
  - (1 - 2^{-a} - x)(a+1)
}{x} + \log(x) \\
&< \frac{2-a}{x} + a + \frac{x-1}{\ln(2)} \\
&\leq (2-a)(2-x) + a + \frac{x-1}{\ln(2)} \\
&= 2 - (1-x)(a-2+1/\ln(2)),
\end{align}
which completes the proof.
\end{proof}

\begin{corollary}[Piecewise constant relative toll bound]
\label{corollary:relative-toll-bound-constant}
For any $a \geq 2$ and $b \in \nat$, the relative toll of
any real $x \in [2^{-b-1}, 2^{-b} - 2^{-b-a}]$
can be bounded strictly less than two as
$\trel{x}
< 2 - 2^{-a}(a-2+1/\ln(2))$.
\end{corollary}

\begin{proof}
Apply \cref{lemma:relative-toll-bound-linear}, using $1-2^b x \geq 2^{-a}$
and the fact that
$2 - 2^{-a}(a-2+1/\ln(2))$ is an increasing function of $a \geq 2$,
as well as $\trel{2^{-b-1}} = 0$.
\end{proof}

\begin{definition}
\label{definition:fldr-toll}
The \textit{relative FLDR toll} of a weight $A$ given weight sum $M$ is
\begin{align}
\label{eq:rel-fldr-toll}
\trelfldr{A, M} &\defeq \trel{A / 2^K} +
\frac{2^K}{M}
\left( H_{\rm b}(M/2^K)
  + \nu(1 - M/2^K) - H_1(1 - M/2^K) \right) \\
&= \trel{A / 2^K} +
  \frac{2^K}{M}
  \left( H_1(M/2^K)
    + \nu(1 - M/2^K) \right),
\end{align}
where $K \defeq \ceil{\log(M)}$.
\end{definition}

\begin{remark}
Rewriting \cref{eq:fldr-toll-binary-entropy} as
\begin{align}
\toll{\fldr[A_1, \ldots, A_n]}
&= \frac{2^K}{M}
  \left( H_{\rm b}(M/2^K)
        + \mathbb{E}_{i \sim \bq} \trel{A_i / 2^K} \right)
\\
&= \mathbb{E}_{i \sim \bp}\left[
  \trel{A_i / 2^K} +
  \frac{2^K}{M}
  \left( H_{\rm b}(M/2^K)
    + \nu(A_0 / 2^K) - H_1(A_0 / 2^K) \right)
\right]
\\
&= \mathbb{E}_{i \sim \bp}\left[ \trelfldr{A_i, M} \right]
\label{eq:entropy-difference-convex-combination}
\end{align}
confirms that \cref{definition:fldr-toll}
is consistent with our usage of the relative toll.
\end{remark}

\begin{lemma}
\label{lemma:aldr-pow-two-toll}
When $K \geq 2k$ and $m$ is not a power of two but $a_i / m$ is a power of two,
the relative FLDR toll of $A_i$ given weight sum $M$ is bounded as
$2 \leq \trelfldr{A_i, M} < 2 ( 1 + A_0/2^K )$.
\end{lemma}

\begin{proof}
When $A_i/M$ is a power of two, \cref{lemma:bit-shift-relative-toll} shows that
$\trel{A_i/2^K} = \trel{M/2^K}$.
%
Then, applying \cref{remark:bernoulli-nu} to \cref{definition:fldr-toll} gives
\begin{align}
\trelfldr{A_i, M}
&= \trel{M / 2^K} +
\frac{2^K}{M}
\left( H_1(M/2^K)
  + \nu(1 - M/2^K) \right)
\\
&= \frac{2^K}{M} \left(
  \nu(M/2^K) + \nu(1 - M/2^K)
\right)
\\
&= \frac{2^K}{M} \left(
  2 - 2\gcd(M,2^K)/2^K
\right).
\end{align}
%
Therefore, $\trelfldr{A_i, M}$ equals $0$ if $m$ is a power of two
and equals $2$ if $2^K - M$ is a power of two.
%
Otherwise,
\begin{align}
\frac{2^K}{M} \left( 2 - 2\gcd(M,2^K)/2^K \right)
= 2 \left( 1 + \frac{A_0}{M} - \frac{\gcd(A_0, 2^K)}{M} \right)
< 2 \left( 1 + \frac{A_0}{2^K} \right),
\end{align}
whenever $K \geq 2k$.
\end{proof}

\begin{lemma}[Tightness of $q_i \lessapprox p_i$]
\label{lemma:q-p-tightness}
Assume that $m$ is not a power of two and $p_i \defeq a_i / m$ is not a power of two.
%
If $K \geq 2k$, then $p_i$ and $q_i \defeq A_i / 2^K$ share the same most
significant bit.
\end{lemma}

\begin{proof}
The following are equivalent:
\begin{inlinelist}[label=(\roman*)]
\item $p_i$ and $q_i$ share the same most significant bit;
\item $\floor{\log(p_i)} = \floor{\log(q_i)}$;
\item $2^{-1-\floor{\log(p_i)}} q_i \in [1/2, 1)$.
\label{item:share-msb}
\end{inlinelist}
%
We will prove \cref{item:share-msb}.
%
Consider the function $s(x) \defeq 2^{-1-\floor{\log(x)}} x$, which
bit-shifts any positive real $x$ into the interval $[1/2, 1)$.
%
Because $a_i / m$ is not a power of two,
\begin{equation}
s(p_i) = 2^{-1-\floor{\log(a_i/m)}}\frac{a_i}{m} \in (1/2, 1) \cap \frac{1}{m} \integers,
\end{equation}
so $s(p_i) \geq 1/2 + 1/2m$ (or $s(p_i) \geq 1/2 + 1/m$ if $m$ is even).
%
Then the bounds $m \leq 2^k-1$ and $M < 2^K - 2^k$ give
\begin{align}
2^{-1-\floor{\log(a_i/m)}}\frac{A_i}{2^K}
\geq \frac{m+1}{2m}\frac{M}{2^K}
> \frac{2^k}{2(2^k-1)}\frac{2^K-2^k}{2^K}
\geq 1/2,
\end{align}
which proves \cref{item:share-msb}.
\end{proof}

\begin{lemma}[Rejection toll bound]
\label{lemma:aldr-rejection-toll}
The rejection contribution to the relative FLDR toll is bounded in terms of the
rejection weight $A_0 \defeq 2^K-M$ as
$(2^K/M) \left( H_1(M/2^K) + \nu(1 - M/2^K) \right)
< (A_0/M)(K+3-\floor{\log(A_0)})$.
\end{lemma}

\begin{proof}
The leading bit of $A_0 / 2^K$ is at position $K - \floor{\log(A_0)}$, so
$\nu(A_0 / 2^K) < (K + 1 - \floor{\log(A_0)}) (A_0 / 2^K)$.
%
Then
\begin{align}
\frac{2^K}{M} \left( H_1(M/2^K) + \nu(1 - M/2^K) \right)
&< \log(2^K/M)
+ \frac{2^K}{M} \frac{A_0}{2^K} (1-\floor{\log(A_0/2^K)}) \\
&< \frac{A_0}{M \ln(2)} + \frac{A_0}{M}(K+1-\floor{\log(A_0)}) \\
&< \frac{A_0}{M}(K+3-\floor{\log(A_0)}),
\end{align}
which is the desired bound.
\end{proof}

We now have the tools required to prove that $\toll{\aldr[\bp, K]} < 2$ for all
$\bp$ and all $K \geq 2k$.

\begin{proof}[Proof of \cref{theorem:aldr-2k-toll-two}]
If $m$ is a power of two then $\aldr[\bp, K]$ is entropy optimal for any $K \geq
k$, and the result follows from \cref{theorem:knuth-yao}, so we assume for the
rest of the proof that $m$ is not a power of two.

\Cref{lemma:aldr-pow-two-toll} shows that the relative FLDR toll for powers
of two is not less than two, so we must bound the total probability
contribution from power-of-two probabilities.
%
Write $m = 2^u x$ where $x > 1$ is odd.
%
Then at most $1-2^{-u}$ of the
probability distribution $\bp$ can come from powers of two.
%
(The fact that not every $p_i$ is a power of two makes use of coprimality
$\gcd(a_1, \dots, a_n) = 1$, unlike \cref{theorem:aldr-generic-bound}, which
applies to arbitrary integer lists but cannot strictly meet the bound of $2$
bits.)
%
Let $b$ be the smallest integer such that at most $1 - 2^{-b}$ of the
probability comes from powers of two, so $0 \leq b \leq u \leq k-2$ and
the total probability not from powers of two is in
$\set{2^{-b}, 2^{-b}+2^{-u}, \dots, 2^{1-b}-2^{-u}}$.
%
Then, for every $i$ such that $a_i / m$ is not a power of two,
$a_i \in \set{1,2,3,\dots,m(2^{1-b}-2^{-u})}$.
%
Dividing by $m$ and multiplying by an appropriate power of two shows that
$1/2 < 2^{-1-\floor{\log(a_i/m)}} a_i/m \leq 1-2^b/m$.
%
Finally, \cref{lemma:q-p-tightness} shows that
$1/2 < 2^{-1-\floor{\log(a_i/m)}} A_i/2^K \leq (1-2^b/m)M/2^K$,
which matches the conditions to apply the relative toll bounds,
\cref{lemma:relative-toll-bound-linear,corollary:relative-toll-bound-constant}.

If $b=k-2$, then $x=3$ and the relative FLDR toll of power-of-two probabilities
is exactly $2$, and for $a_i < 3$ we have $\trelfldr{A_i, M} = \trel{1/3} < 2$,
so the overall toll is less than $2$ by
\cref{eq:entropy-difference-convex-combination}.
%
Henceforth, $0 \leq b \leq k-3$.

We now bound the relative FLDR toll of the non-power-of-two probabilities by
proving in three cases that
\begin{align}
  \textrm{for each $i$, if $p_i$ is not a power of two then } \trel{A_i/2^K} < 2 - (A_0/M) (2^{b+1}+K+1-\floor{\log(A_0)}).
\label{eq:relative-toll-not-pow-two}
\end{align}

\begin{enumerate}[label={Case \arabic*.}]
\item
If $k \geq 8$ and $2^{-1-\floor{\log(a_i/m)}} A_i/M < 1 - 2^{1+b-k}$, then
\cref{corollary:relative-toll-bound-constant} gives
\begin{align}
\trel{A_i/2^K}
&< 2 - \frac{k-b-3+1/\ln(2)}{2^{k-b-1}} \\
&= 2 - \frac{1}{2^k}\left(2^{b+1}+2^{b+1}(k-b-4+1/\ln(2))\right) \\
&< 2 - \frac{1}{2^k}\left(2^{b+1}+k+2\right) \\
&< 2 - \frac{A_0}{M}\left(2^{b+1}+K+1-\floor{\log(A_0)}\right)
\end{align}
by casework on $0 \leq b \leq k-3$.

\item
If $k \geq 8$ and
$2^{-1-\floor{\log(a_i/m)}} A_i/M \in [1 - 2^{1+b-k}, 1 - 2^{b-k})$,
then \cref{lemma:relative-toll-bound-linear} gives
\begin{align}
&\quad \trel{A_i / 2^K} \\
&< 2 - \left[ 1 - \left(1 - \frac{2^b}{m}\right) \left(1 - \frac{A_0}{2^K}\right) \right](k-b-2+1/\ln(2)) \\
&< 2 - \left(\frac{2^b}{m}+\frac{A_0}{2^K}-\frac{2^b A_0}{2^K m}\right)(k-b-2+1/\ln(2)) \\
&= 2 - \frac{A_0}{M}\left(\frac{c_K 2^b}{A_0} + \frac{c_K(m-2^b)}{2^K}\right) (k-b-2+1/\ln(2)) \\
&< 2 - \frac{A_0}{M}\left(2^{b+1}+2^b 2^{K-2k}\left( \frac{c_K}{A_0} - \frac{c_K}{2^K} \right) (k-b-4+1/\ln(2)) + \frac{M}{2^K} (k-b-2+1/\ln(2))\right) \\
&< 2 - \frac{A_0}{M}\left(2^{b+1}+2^b 2^{K-2k} \frac{2^k}{A_0} (k-b-4+1/\ln(2)) + k-b-1\right).
\end{align}
%
Casework on $K$, $A_0$, $b$, and $k$ then gives
\begin{align}
\trel{A_i / 2^K} < 2 - \frac{A_0}{M}\left(2^{b+1}+K+1-\floor{\log(A_0)}\right).
\end{align}

\item
If $k < 8$, then direct computation shows that
\cref{eq:relative-toll-not-pow-two} holds for all
$0 \leq b \leq k-3$ and $2k \leq K < 16$:
\begin{equation}
\min_{\substack{
  2k \leq K < 16; \\
  a_i / m \textrm{ not a power of two}
}}
\left[ 2 - (A_0/M) (2^{b+1}+K+1-\floor{\log(A_0)}) - \trel{A_i/2^K} \right]
\gtrapprox 0.0394,
\end{equation}
and this tightest case occurs at $a_i = 117$, $m = 118$, and $K = 14$.
%
For $K \geq 16$, we reduce to the case $k = 8$, by repeating the array of
weights $2^{8-k}$ times and amplifying these repeated weights using the depth
$K+8-k \geq 16$, which gives the amplified weight sum $2^{8-k}M$ and amplified
rejection weight $2^{8-k}A_0$.
%
From the result of the previous cases, together with
\cref{lemma:bit-shift-relative-toll},
it follows that
\begin{align}
\trel{A_i/2^K}
= \trel{A_i/2^{K+8-k}}
&< 2 - \frac{2^{8-k}A_0}{2^{8-k}M}\left(2^{b+1}+K+8-k+1-\floor{\log(2^{8-k}A_0)}\right) \\
&= 2 - \frac{A_0}{M}\left(2^{b+1}+K+1-\floor{\log(A_0)}\right),
\end{align}
which completes the proof of \cref{eq:relative-toll-not-pow-two}.
\end{enumerate}

Applying \cref{lemma:aldr-rejection-toll} together with
\cref{eq:relative-toll-not-pow-two},
if $a_i/m$ is not a power of two, then
\begin{align}
\trelfldr{A_i, M}
&= \trel{A_i / 2^K} +
\frac{2^K}{M} \left( H_1(M/2^K) + \nu(1 - M/2^K) \right) \\
&< 2 - \frac{A_0}{M}\left(2^{b+1}+K+1-\floor{\log(A_0)}\right)
+ \frac{A_0}{M} (K+3-\floor{\log(A_0)}) \\
&< 2 - (2^{b+1} - 2) A_0 / 2^K.
\label{eq:relative-aldr-toll-not-pow-two}
\end{align}

Now, we use \cref{lemma:aldr-pow-two-toll} and
\cref{eq:relative-aldr-toll-not-pow-two} in
\cref{eq:entropy-difference-convex-combination} to bound the overall toll.
%
In the worst case, $1-2^{-b}$ of the probability comes
from powers of two, which gives the bound
\begin{align}
\toll{\aldr[\bp, K]}
= \mathbb{E}_{i \sim \bp}\left[ \trelfldr{A_i, M} \right]
< (1-2^{-b}) 2 (1 + A_0 / 2^K)
  + 2^{-b} \left( 2 - (2^{b+1} - 2) A_0 / 2^K \right)
= 2.
\end{align}
%
The claim that $\toll{\aldr[\bp, K]} < 2$ for all $\bp$ and all
$K \geq 2k$ is thus established.
\end{proof}

By \cref{theorem:aldr-2k-toll-two}, $K = 2k$ is a sufficiently large depth
function to ensure that the toll of ALDR is strictly less than $2$ bits.
%
\Cref{theorem:aldr-doubling-minimal} shows that this is the smallest possible
depth function satisfying this bound.

\begin{theorem}[$K = 2k$ is minimal]
\label{theorem:aldr-doubling-minimal}
For any $k \geq 4$, there exists a probability distribution $\bp$
such that $\fldr[\bp]$ has depth $k$ and the $\aldr$
entropy tolls satisfy
$\toll{\aldr[\bp, K]} > 2$
for $K = k, \dots, 2k-1$.
\end{theorem}

\begin{proof}
\input{fig-ddg-isomorphism}

Let $k \geq 4$ and consider the distribution
$\bp \defeq ((2^{k-1}-1)/m, (2^{k-1}-2)/m)$ with $m \defeq (2^{k}-3)$.
%
By \cref{eq:ddg-tree-toll,eq:fldr-cost}, the toll of the FLDR tree for $\bp$ is
\begin{align}
\toll{\fldr[\bp]}
&\defeq \frac{2^k}{m} \left( \nu\left( \frac{3}{2^k} \right) + \nu\left( \frac{2^{k-1}-1}{2^k} \right) + \nu\left( \frac{2^{k-1}-2}{2^k} \right) \right) - H(\bp)
\\
&=
\frac{2^k}{2^k-3} \left[
  \left(\frac{k-1}{2^{k-1}} + \frac{k}{2^k}\right) +
  \left(\frac{3}{2} - \frac{k+2}{2^k}\right) +
  \left(\frac{3}{2} - \frac{k+1}{2^{k-1}}\right)
\right]
- H_{\rm b}\left(\frac{2^{k-1}-1}{2^k-3}\right)
\\
&=
\frac{2^k}{2^k-3} \left[ 3 \frac{2^k-2}{2^k} \right]
- H_{\rm b}\left(\frac{2^{k-1}-1}{2^k-3}\right)
\\
% % tops{\o}e's polynomial bound just gives a higher-order term:
% &> 3 + \frac{3}{2^k-3} - \left(\frac{(2^k-2)(2^k-4)}{(2^k-3)^2}\right)^{1/\ln(4)} \\
% &= 3 + \frac{3}{2^k-3} - \left(1 - \frac{1}{(2^k-3)^2}\right)^{1/\ln(4)} \\
% &> 3 + \frac{3}{2^k-3} - 1 + \frac{1}{(2^k-3)^2 \ln(4)} \\
% &= 2 + \frac{3}{2^k-3} + \frac{1}{(2^k-3)^2 \ln(4)} \\
% &> 2.
&> 3 - 1 \\
&= 2.
\end{align}
%
Because $k \geq 4$, we have $2^{2k-2} = 2^{k-2}m + 3\cdot2^{k-2}$ and
$3\cdot2^{k-2} < 2^k-3 \eqdef m$, so $c_{2k-2}=2^{k-2}$ and $c_K = 2^{K-k}$ for
$K = k,\dots,2k-2$, which implies that $\bq_k = \cdots = \bq_{2k-2}$
(cf.~\cref{eq:c-case-even}), and so all $\aldr[\bp, K]$ tolls are equal.
%
For $K = 2k-1$, we have $c_{2k-1} = 2^{k-1}+1$, and every $a_i$ has a bit-length
of at most $k-1$, so there are no carries in any product $a_i \times c_{2k-1}$.
%
The toll of $\aldr[\bp, 2k-1]$ is therefore also equal to the FLDR toll, by
the no-carry case of \cref{theorem:aldr-leq-fldr}.
%
\Cref{fig:ddg-isomorphism} shows this argument graphically,
where $\aldr[\bp, 2k-1]$ is isomorphic to $\fldr[\bp]$,
unrolling the back edge at depth $k-1$ once.
%
Although the toll of $\fldr[\bp]$ exceeds $2$ for each of these distributions,
for larger $k$, the toll necessarily approaches $2$:
\begin{equation}
\toll{\fldr[\bp]} = \toll{\aldr[\bp, 2k-1]} < 2 + (k+3)2^{1-k}
\end{equation}
in accordance with \cref{theorem:aldr-generic-bound}.
\end{proof}

\section{Further Entropy Properties}
\label{sec:properties}

\Cref{fig:fldr478} suggests that $\aldr[\bp,K]$ can
``interpolate'' between $\fldr[\bp]$ (when $K = k$) and the
entropy-optimal $\ky[\bp]$ (for sufficiently large $K$).
%
This section studies the properties of $\aldr[\bp,K]$ as $K$ varies
more formally.
%
\Cref{sec:properties-ky} characterizes distributions
$\bp$ for which $\aldr[\bp,K]$ is entropy optimal for
some choice of $K$.
%
\Cref{sec:properties-fldr} establishes that the expected entropy cost
of $\aldr[\bp,K]$ is upper bounded by that of $\fldr[\bp] \equiv \aldr[\bp,k]$,
providing a necessary and sufficient condition for strict inequality.

\subsection{Comparison of ALDR and Entropy-Optimal Sampling}
\label{sec:properties-ky}

The first result shows that \cref{theorem:aldr-2k-toll-two} is tight and
that $\aldr$ may never be entropy optimal for any $K$.

\begin{proposition}
\label{proposition:aldr-large-gap}
For every $\epsilon > 0$, there exists a discrete probability distribution $\bp$
such that $\toll{\ky[\bp]} < \epsilon$
and $\toll{\aldr[\bp,K]} > 2 - \epsilon$ for all $K$.
\end{proposition}

\begin{proof}
It is sufficient to consider the case that $\epsilon$ is a positive power of $1/2$,
by setting $\epsilon \gets \min(1/2, 2^{\floor{\log(\epsilon)}})$ if needed.
%
Consider the distribution $\bp \defeq (a_1/m, a_2/m, \dots, a_n/m)$
defined as follows:
\begin{align}
n \defeq 2 + 2/\epsilon, &&
m \defeq 6 / \epsilon, &&
a_1 \defeq a_2 \defeq a_3 \defeq 1, &&
a_4 \defeq \dots \defeq a_n \defeq 3.
\label{eq:dist-powers-of-two}
\end{align}
%
The outcomes $a_4 = \dots = a_n$, whose probabilities are
$p_4 = \dots = p_n = \epsilon/2$, have total probability $1 - \epsilon/2$.
%
Then $\toll{\ky[\bp]} = 3(\epsilon/6)\trel{\epsilon / 6} < \epsilon$, whereas
$\toll{\aldr[\bp,K]}
\geq (1-\epsilon/2) \trelfldr{A_n, M}
\geq 2 - \epsilon$
by \cref{lemma:aldr-pow-two-toll}.
\end{proof}

\begin{example}[ALDR-KY gap]
\input{fig-fldr-toll-1669}
%
\Cref{fig:fldr-toll-1669} shows the tolls of
$\fldr$, $\aldr$, and entropy-optimal DDG tree samplers for the
distribution $\bp = (1/m, (b-1)/m, b/m, 2b/m, 4b/m, \dots, 2^{10}b/m)$,
where $b=1669$ and $m = 2^{11}b$.
%
Following the example in \cref{proposition:aldr-large-gap}---for which many
probabilities that are powers of two comprise most of the probability---this
choice ensures that $1-2^{-11}$ of the probability consists of
powers of two, which drives $\toll{\ky[\bp]}$ to near zero, whereas
the toll of $\aldr[\bp,K]$ remains near $2$ for all $K$.
%
Additionally, $b=1669$ is a prime number such that the order of 2 modulo $b$ is
$b-1$, which ensures that any entropy-optimal sampler has a large
depth of at least $b-1 + \ceil{\log(b)} = 1679$.
\end{example}

To address the question of when $\aldr[\bp,K]$ can be entropy optimal, we recall
that \cref{theorem:knuth-yao} fully characterizes entropy optimality in terms of
the distribution of leaf nodes across levels in a DDG tree.
%
To apply \cref{theorem:knuth-yao} to $\aldr[\bp,K]$, it is necessary to
characterize the distribution of leaf nodes in $\aldr[\bp,K]$, which are
obtained by infinitely unrolling the back edges that corresponds to the
rejection label in $\ky[\bq_K]$.
%
The following theorem provides a method for directly counting the leaf nodes in
$\aldr[\bp,K]$ in terms of the leaf nodes in $\ky[\bq_K]$.

\begin{theorem}[Counting leaves]
\label{theorem:generating-fn}
The number of leaf nodes with label $i$ at depth $d$ in the unrolled tree
$\fldr[A_1,\dots,A_n]$ can be computed in terms of the leaves in the unexpanded
tree $\ky[\bq]$ as the coefficients of a generating function (i.e., formal power
series):
\begin{align}
\sum_{d=0}^{\infty} \leaves{\fldr[A_1,\dots,A_n]}{d}{i} z^d
&= \frac{\sum_{d=0}^{\infty} \leaves{\ky[\bq]}{d}{i} z^d}
{1 - \sum_{d=0}^{\infty} \leaves{\ky[\bq]}{d}{0} z^d} \\
&= \frac{\sum_{d=0}^K \epsilon_d(A_i/2^K)z^d}{1 - \sum_{d=0}^K \epsilon_d(A_0/2^K)z^d} \\
&= \sum_{j=0}^{\infty}
  \left\lbrace
    \left(\sum_{d=0}^K\epsilon_d(A_i/2^K)z^d\right)
    \left(\sum_{d=0}^K \epsilon_d(A_0/2^K)z^d\right)^j
  \right\rbrace,
\label{eq:generating-fn}
\end{align}
where $(1-f(z))^{-1} \defeq \sum_{j=0}^{\infty} f(z)^j$ for
generating functions $f(z)$.
\end{theorem}

\begin{proof}
Because $\ky[\bq]$ is entropy optimal,
$\leaves{\ky[\bq]}{d}{i} = \epsilon_d(A_i/2^K)$ for all $d$ and
$0 \leq i \leq n$.
%
Upon unrolling one back edge at depth $r$, the label counts at depth $d$ become
$\epsilon_d(A_i/2^K) + \epsilon_{d-r}(A_i/2^K)$, because one new leaf node with
label $i$ appears at depth $d+r$ for every leaf with label $i$ at depth $d$ in
the original tree.
%
Therefore, if there is just a single back edge at depth $r$, then by repeatedly
unrolling it to get an infinite tree, we have
\begin{equation}
\leaves{\fldr[A_1,\dots,A_n]}{d}{i}
= \epsilon_d(A_i/2^K) + \epsilon_{d-r}(A_i/2^K) + \epsilon_{d-2r}(A_i/2^K) + \cdots,
\end{equation}
which agrees with \cref{eq:generating-fn}.
%
This case is revisited in the proof of \cref{theorem:aldr-ky-match-bounded}.

To analyze the more general case where there may be multiple back edges in the
FLDR tree, it will be convenient to introduce some notation to describe the
convolutions that arise from unrolling multiple back edges at once.
%
For this purpose, we will use generating functions.
%
We wish to construct the formal power series
$\sum_{d=0}^{\infty} \leaves{\fldr[A_1,\dots,A_n]}{d}{i} z^d$,
whose $z^d$--coefficient is the number of leaves with label $i$ at depth $d$
in the unrolled tree $\fldr[A_1,\dots,A_n]$.
%
The generating function for the leaves with label $i$ in the unexpanded FLDR tree is
\begin{equation}
\sum_{d=0}^{\infty} \leaves{\ky[\bq]}{d}{i} z^d
= \sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d
\end{equation}

Upon unrolling back edges targeting the root of the tree, the new leaves at
depth $d$ are in bijective correspondence with pairs of back edge sources at
depth $r$ and leaves at depth $d-r$, which corresponds exactly to the
operation of convolution or polynomial multiplication.
The generating function describing the newly-added leaves is therefore
\begin{equation}
\sum_{d=0}^\infty \sum_{r=0}^\infty \epsilon_r(A_0/2^K) \epsilon_{d-r}(A_i/2^K) z^d
= \sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d \sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d.
\end{equation}
%
Therefore, upon unrolling all back edges present in the original tree once
(cf.~\cref{fig:fldr-tree-unrolling-1}), the generating function for the leaves
with label $i$ becomes
\begin{equation}
\sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d
+ \sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d \sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d
= \left(1 + \sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d\right) \sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d,
\end{equation}
and the generating function for the rejection labels in the new tree is
$(\sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d)^2$.
%
Upon unrolling these new back edges once (cf.~\cref{fig:fldr-tree-unrolling-2}),
the generating function for the leaves with label $i$ becomes
\begin{equation}
\left(
  1
  + \sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d
  + \left(\sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d\right)^2
  \right)
  \sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d,
\end{equation}
and the new rejection labels have generating function $(\sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d)^3$.
%
By inductively continuing this pattern, the generating function for
the leaves with label $i$ in the fully-unrolled infinite tree is
\begin{align}
\sum_{d=0}^{\infty} \leaves{\fldr[A_1,\dots,A_n]}{d}{i} z^d
&=
\left(
  1
  + \sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d
  + \left(\sum_{d=0}^{K} \epsilon_d(A_0/2^K) z^d\right)^2
  + \cdots
  \right)
\sum_{d=0}^{K} \epsilon_d(A_i/2^K) z^d,
\end{align}
which completes the proof.
\end{proof}

\begin{corollary}[Optimal FLDR rejection]
\label{corollary:fldr-power-of-two}
If the rejection probability $q_0 \defeq A_0/2^K$ in $\fldr$
is neither zero not a power
of two, then the FLDR tree is not entropy optimal, i.e.,
$\toll{\fldr[A_1,\dots,A_n]} > \toll{\ky[\bp]}$.
\end{corollary}

\begin{proof}
If $A_0/2^K$ is neither zero nor a power of two, then $A_0$ must have
at least two set bits, say
$\epsilon_{d_1}(A_0/2^K) = \epsilon_{d_2}(A_0/2^K) = 1$.
%
Also, let $d_3$ be any set bit in $A_1 / 2^K$, i.e.,
$\epsilon_{d_3}(A_1/2^K) = 1$.
%
Then, using $[z^D]\sum_d g_d z^d \defeq g_D$ to denote the $z^D$--coefficient of
a given generating function, the number of leaf nodes with label $1$ at depth
$d_1 + d_2 + d_3$ (cf.~\cref{fig:fldr-tree-unrolling-2}, depth $8$) in the fully
unrolled tree is
\begin{align}
\left[z^{d_1+d_2+d_3}\right]
    \frac{\sum_{d=0}^K z^d \epsilon_d(A_1/2^K)}{1 - \sum_{d=0}^K z^d \epsilon_d(A_1/2^K)}
&\geq \left[z^{d_1+d_2+d_3}\right] \frac{z^{d_3}}{1 - z^{d_1} - z^{d_2}} \\
&\geq \left[z^{d_1+d_2+d_3}\right] z^{d_3}(z^{d_1} + z^{d_2})^2 \\
&\geq \left[z^{d_1+d_2+d_3}\right] 2z^{d_1+d_2+d_3} \\
&= 2.
\end{align}
%
By \cref{theorem:knuth-yao}, the tree $\fldr[A_1,\dots,A_n]$ cannot be
entropy optimal.
\end{proof}

\input{fig-fldr-tree-unrolling}

\begin{example}[Suboptimal FLDR rejection]
\Cref{fig:fldr-tree-unrolling} shows DDG trees obtained by unrolling
the back edges of $\fldr[\bp]$ zero, one, and two times,
where $\bp \defeq (1/5, 4/5)$.
%
Nodes labeled $1$ and $4$
represent the outcomes with $1/5$ and $4/5$ probability, respectively,
as in \cref{fig:ddg-ky-fldr}.
%
Nodes labeled R represent ``reject nodes'', which are back edges to
the root of the tree.
%
The twice-unrolled tree in \cref{fig:fldr-tree-unrolling-2} has two leaves
with label $4$ at depth $6$, and two leaves with label $1$ at depth $8$,
corresponding to two possible orders of traversing the $1/4$-- and
$1/8$--probability reject nodes in \cref{fig:fldr-tree-unrolling-0}.
%
This type of duplication occurs for any FLDR (or ALDR) tree whose rejection
probability is not a power of two.
%
The proof of \cref{corollary:fldr-power-of-two} uses this same idea of
traversing the same two rejection nodes in a different order to identify a
