We now characterize which probability distributions can have
entropy-optimal ALDR trees.

\begin{theorem}[Characterization of entropy-optimal ALDR trees]
\label{theorem:aldr-ky-match-bounded}
Consider coprime integer weights $(a_1,\dots,a_n)$
whose sum $m$ is not a power of two.
%
Write $m = 2^u x$ for odd $x>1$ and $u \geq 0$, and
write $\ell$ for the order of $2 \bmod x$,
so that a standard construction of the entropy-optimal \citeauthor{knuth1976}
tree has depth $u + \ell$ (cf.~\cref{fig:fldr-ky-match-even-optimal}).
%
The following statements are equivalent.
%
\begin{enumerate}[label=(\labelcref{theorem:aldr-ky-match-bounded}.\arabic*)]
\item \label{item:aldr-ky-match-bounded-k}
for some $K \leq u+\ell$, the tree $\aldr[\bp,K]$ is entropy optimal.

\item \label{item:aldr-ky-match-bounded-k-ul}
$\aldr[\bp,u+\ell]$ is entropy optimal.

\item \label{item:aldr-ky-match-bounded-gen-eq}
for all $1 \leq i \leq n$,
the binary expansions of $p_i$ and $q_i$ satisfy
$(1 - z^\ell) \sum_d \epsilon_d(p_i) z^d = \sum_d \epsilon_d(q_i) z^d$.

\item \label{item:aldr-ky-match-bounded-gen}
for all $1 \leq i \leq n$, the generating function
$(1 - z^\ell) \sum_d \epsilon_d(p_i) z^d$ has only nonnegative coefficients.

\item \label{item:aldr-ky-match-bounded-p}
for all $d \geq 1$ and $1 \leq i \leq n$,
the bits in the binary expansion of $p_i$ satisfy
$\epsilon_d(p_i) \leq \epsilon_{d+\ell}(p_i)$.
\qedhere
\end{enumerate}
\end{theorem}

\begin{proof}
By \cref{corollary:fldr-power-of-two}, the rejection probability of
the ALDR tree must be a power of two in order to achieve
entropy optimality.
%
The smallest depth at which the rejection probability $1-cm/2^K$ becomes a power
of two is $K = u + \ell$, where $M = 2^{u+\ell} - 2^u$, so
\labelcref{item:aldr-ky-match-bounded-k,item:aldr-ky-match-bounded-k-ul} are
equivalent.

\Cref{theorem:generating-fn,theorem:knuth-yao} show that
\labelcref{item:aldr-ky-match-bounded-k-ul,item:aldr-ky-match-bounded-gen-eq} are
equivalent, because the distribution of labeled leaves at different depths in
the tree uniquely determines the set of entropy-optimal trees.

For the equivalence of
\labelcref{item:aldr-ky-match-bounded-gen-eq,item:aldr-ky-match-bounded-gen}, the
forward implication follows from the nonnegativity of $\epsilon_d(q_i)$.
%
For the reverse implication, consider the following properties of
$(1 - z^\ell) \sum_d \epsilon_d(p_i) z^d$:
its only nonzero coefficients appear at $0 < d \leq u+\ell$,
every coefficient is at most $1$,
and when evaluated at $z \mapsto 1/2$, it becomes $q_i \defeq A_i / 2^K$.
%
Given the additional assumption of nonnegative coefficients, uniqueness of the
finite binary representation of dyadic numbers then implies that
$(1 - z^\ell) \sum_d \epsilon_d(p_i) z^d = \sum_d \epsilon_d(A_i / 2^K) z^d$,
which establishes the reverse implication.

Lastly, the equivalence of
\labelcref{item:aldr-ky-match-bounded-gen,item:aldr-ky-match-bounded-p}
follows from
$(1 - z^\ell) \sum_d \epsilon_d(p_i) z^d
= \sum_d (\epsilon_d(p_i) - \epsilon_{d-\ell}(p_i))$.
\end{proof}

\begin{remark}[Full characterization of entropy-optimal ALDR trees]
\label{remark:aldr-ky-match-general}
In the notation of \cref{theorem:aldr-ky-match-bounded},
$\aldr[\bp,K]$ can match the entropy-optimal tree
$\ky[\bp]$ within
depth $K \leq u+\Lambda\ell$ if and only if
there is some $\lambda \in \{1, \dots, \Lambda\}$ such that
for all $d \geq 1$ and $1 \leq i \leq n$,
the bits in the binary expansion of $p_i$ satisfy
$\epsilon_d(p_i) \leq \epsilon_{d+\lambda\ell}(p_i)$.
%
This result follows directly from the proof of
\cref{theorem:aldr-ky-match-bounded},
but allowing any rejection probability $2^{-\lambda\ell}$
and replacing $1/(1-z^\ell)$ with $1/(1-z^{\lambda\ell})$.
%
If the inequality holds for some $\Lambda$,
then it also holds for $\lambda = \ceil{u / \ell}$.
%
This property is similar to the requirement that no probability be dyadic,
but stronger.
%
For example, it is impossible to obtain an entropy-optimal representation
of $5/6 = (0.1\overline{10})_2$ using any finite DDG tree with a
back edge to the root.
\end{remark}

\begin{corollary}[Entropy-optimal ALDR trees for odd denominators]
\label{proposition:fldr-ky-match-odd}
In the notation of \cref{theorem:aldr-ky-match-bounded},
if the distribution $\bp$ has odd denominator $m$,
then $\aldr[\bp,\ell]$ is an entropy-optimal tree.
\end{corollary}

\begin{proof}
Apply \cref{theorem:aldr-ky-match-bounded}, noting that $u=0$ and
the binary expansion of each $p_i$ repeats with period $\ell$.
\end{proof}

\begin{example}[ALDR matching \citeauthor{knuth1976}]
\input{fig-ddg-compare}

Consider the distribution $\bp = (1, 2, 3, 4)/10$.
%
In the notation of \cref{theorem:aldr-ky-match-bounded}, $m=10$,
$u=1$, $x=5$, and the order of $2 \bmod 5$ is $\ell=4$.
%
The binary expansion of each probability repeats with period $\ell$ and with no
preperiod.
%
The tree $\aldr[\bp, 5]$, depicted in \cref{fig:fldr-ky-match-even},
matches the entropy-optimal sampler.
%
The rejection node for the ALDR tree points to the root
(\cref{fig:fldr-ky-match-even-amplified}), whereas a typical representation of
the \citeauthor{knuth1976} tree would use two back edges that target the
two children of the root (\cref{fig:fldr-ky-match-even-optimal}).
\end{example}

\subsection{Comparison of ALDR and FLDR}
\label{sec:properties-fldr}

This section establishes conditions under which $\aldr[\bp,K]$ has a lower
expected entropy cost than $\fldr[\bp] \equiv \aldr[\bp,]$
for a given $K > k$.
%
The first result shows that the toll does not necessarily decrease with $K$.

\begin{proposition}[ALDR toll not monotonic in depth]
\label{proposition:aldr-not-monotonic-decrease}
There exists a discrete probability distribution $\bp$ and depth $K$ such that
$\toll{\aldr[\bp, K]} < \toll{\aldr[\bp, K+1]}$.
\end{proposition}

\begin{proof}
Set $\bp = (4/19, 7/19, 8/19)$.
%
Then
\begin{align}
\expect{\cost{\aldr[\bp, 10]}}
= \frac{3038}{1007}
< \frac{6150}{2033}
= \expect{\cost{\aldr[\bp, 11]}}.
\end{align}
%
The tolls just subtract $H(\bp)$ from the expected entropy cost,
so they have the same relationship, as shown in \cref{fig:fldr478-tolls}.
%
This non-monotonicity is dictated by the irregularity of
$\trel{A_0/2^K}$ as $K$ varies.
%
The rejection outcome in $\ky[\bq_{10}]$ has
probability $17/1024$, which has a small relative toll
$\trel{17/1024} \approx 0.32$, whereas the rejection outcome in
$\ky[\bq_{11}]$ has probability $15/2048$,
which has a much larger relative toll $\trel{15/2048} \approx 1.64$.
\end{proof}

In order to compare the expected entropy costs of $\fldr[\bp]$ and
$\aldr[\bp,K]$ in general, we must relate
the terms $\nu(a_i/2^k)$ and $\nu(c_K a_i / 2^K)$, which, respectively,
make up the costs of the two trees.
%
This comparison requires an analysis of the behavior of
$\nu$ under multiplication.
%
To better describe the properties of $\nu$, we generalize
its domain from the set of positive real numbers to a more natural domain.

\begin{definition}
\label{definition:nu-entropy}
The \textit{``new'' entropy function}
$\nu(x) \defeq \sum_{d=0}^{\infty} d \epsilon_d(x)2^{-d}$
from \citet{knuth1976}
can be extended any $\nat$-ordered and $\real$-valued sequence,
which in the general case is represented by the
coefficients of a formal Laurent series
$g = \sum_{d = D}^{\infty} g_d z^d \in \real((z))$
for some $D \in \integers$.
%
On this domain, we define $\nu(g) \defeq \sum_d d g_d z^d$.
%
These formal Laurent series can be converted to real numbers by evaluating with
$z \mapsto 1/2$, which is consistent with the definition of $\nu$ on real
numbers, because the diagram
\begin{equation}
\begin{tikzcd}
  {\real_{\geq 0}} &&& {\real((z))} \\
  \real &&& {\real((z))}
  \arrow["{x \mapsto \sum_d \epsilon_d(x) z^d}", tail, from=1-1, to=1-4]
  \arrow["\nu"', from=1-1, to=2-1]
  \arrow["\nu", from=1-4, to=2-4]
  \arrow["{z \mapsto 1/2}", rightharpoonup, from=2-4, to=2-1]
\end{tikzcd}
\end{equation}
commutes.
%
Convergence of the series evaluation $z \mapsto 1/2$ is guaranteed whenever the
coefficients are bounded by an exponential function with base strictly less than
$2$, which holds for every sequence considered in this paper.
\end{definition}

\begin{remark}
\label{remark:toll-per-weight}
The generalized $\nu$ entropy can be used to directly compute the toll of a tree
given the generating function for its leaf counts.
%
For example, applying $\nu$ to a generating function from
\cref{theorem:generating-fn} yields
\begin{align}
\frac{A_i}{M}\trelfldr{A_i, M}
= \left[
  \nu \left(
      \frac{\sum_{d=0}^K \epsilon_d(A_i/2^K)z^d}{1 - \sum_{d=0}^K \epsilon_d(A_0/2^K)z^d}
      \right)
    \right]_{z \mapsto 1/2}
  - H_1(A_i / M)
\end{align}
as an alternative expression for the toll contributions in a FLDR tree
(cf.~\cref{definition:fldr-toll}).
\end{remark}

\begin{definition}[Carries]
\label{definition:carries}
For nonnegative $x,y \in \real_{\geq 0}$ and $\star \in \set{+, \times}$, the operation
$x \star y$ is said to \textit{carry} if and only if
$\sum_d \epsilon_d(x \star y) z^d \neq
\left( \sum_d \epsilon_d(x) z^d \right) \star \left( \sum_d \epsilon_d(y) z^d \right)$.
\end{definition}

\begin{remark}
\label{remark:carries}
Given $x \defeq (0.x_1x_2x_3\ldots)_2$ and $y \defeq (0.y_1y_2y_3\ldots)_2 \in [0,1)$,
the addition $z = x + y = (0.z_1z_2z_3\ldots)_2$ does not carry if
and only if $z_i = x_i + y_i$ for $i \geq 1$ (cf.~\cite[Eqs.~(2.23--2.24)]{knuth1976}).
%
In other words, the addition carries if and only if one of the
two conditions holds: \begin{inlinelist}[label=(\alph*)]
\item $z$ is dyadic when $x$ is not; or
\item there exists $i \geq 1$ such that $x_i = y_i = 1$.
\end{inlinelist}
%
The multiplication $z = xy = (0.z_1z_2z_3\ldots)_2$ does not carry
if and only if $z_1 = 0$ and $z_j = \sum_{i=1}^{j-1}x_i y_{j-i}$.
%
(All binary expansions in these definitions are concise.)
\end{remark}

\begin{lemma}[{$\nu$} is a subadditive subderivation]
\label{lemma:nu-derivation}
For real $x, y \geq 0$,
the $\nu$ entropy satisfies the following inequalities:
\begin{align}
\nu(x + y) &\leq \nu(x) + \nu(y)
&&\mbox{(with equality iff $x + y$ does not carry),}
% Knuth and Yao call this $\nu(x+y) = \nu(x)+\nu(y) + (x \capplus y)$,
% where $\capplus$ (analogous to \LaTeX's $\uplus$)
% sets bits exactly where carries would occur
% when adding its two operands.
\label{eq:nu-subadditive}\\
\nu(x y) &\leq x \nu(y) + y \nu(x)
&&\mbox{(with equality iff $x \times y$ does not carry).}
\label{eq:nu-derivation}
\end{align}
%
These inequalities have the same form as additivity and Leibniz's law (i.e., the
product rule), except that `$=$' is replaced by `$<$' whenever the corresponding
operation carries.
\end{lemma}

\begin{proof}
Consider the extension of the $\nu$ entropy to formal Laurent series
$\nu\left( \sum_d g_d z^d \right) = \sum_d d g_d z^d$
from \cref{definition:nu-entropy}.
%
This $\nu$ is a derivation on formal Laurent series, i.e.,
\begin{align}
  \nu(f(z) + g(z)) &= \nu(f(z)) + \nu(g(z)), \\
  \nu(f(z)g(z)) &= f(z) \nu(g(z)) + g(z) \nu(f(z)),
\end{align}
because $\nu = z \frac{d}{dz}$.
% or for more detail,
% \begin{align*}
% \nu(f(z)g(z))
% &=\nu\left( \sum_d f_d z^d \sum_e g_e z^e \right) \\
% &= \nu\left( \sum_d \sum_e f_d g_e z^{d+e} \right) \\
% &= \sum_d \sum_e f_d g_e (d+e) z^{d+e} \\
% &= \sum_d \sum_e f_d e g_e z^{d+e} + \sum_d \sum_e f_d g_e d z^{d+e} \\
% &= \sum_d f_d z^d \sum_e e g_e z^e + \sum_e g_e z^e \sum_d d f_d z^d \\
% &= f(z) \nu(g(z)) + g(z) \nu(f(z)).
% \end{align*}
%
In using bitstring conversions from real numbers, the only difference is
carries, which gives
\begin{align}
\nu(x + y)
&= \left[ \nu\left( \sum_d \epsilon_d(x + y) z^d \right) \right]_{z \mapsto 1/2} \\
&\leq \left[ \nu\left( \sum_d \epsilon_d(x) z^d + \sum_d \epsilon_d(y) z^d \right) \right]_{z \mapsto 1/2} \\
&= \left[ \nu\left( \sum_d \epsilon_d(x) z^d \right) \right]_{z \mapsto 1/2} + \left[ \nu\left( \sum_d \epsilon_d(y) z^d \right) \right]_{z \mapsto 1/2}
= \nu(x) + \nu(y),
\shortintertext{and}
\nu(x y)
&= \left[ \nu\left( \sum_d \epsilon_d(x y) z^d \right) \right]_{z \mapsto 1/2} \\
&\leq \left[ \nu\left( \sum_d \epsilon_d(x) z^d \sum_e \epsilon_e(y) z^e \right) \right]_{z \mapsto 1/2} \\
&= \left[ \sum_d \epsilon_d(x) z^d \nu\left( \sum_e \epsilon_e(y) z^e \right) + \sum_e \epsilon_e(y) z^e \nu\left( \sum_d \epsilon_d(x) z^d \right) \right]_{z \mapsto 1/2} \\
&= \left[ \sum_d \epsilon_d(x) \nu(y) z^d + \sum_e \epsilon_e(y) \nu(x) z^e \right]_{z \mapsto 1/2}
= x \nu(y) + y \nu(x).
\end{align}
These inequalities are strict if and only if $x + y$ (resp.~$x \times y$)
carries.
\end{proof}

The main theorem of this section shows that the non-monotonicity
identified in \cref{proposition:aldr-not-monotonic-decrease} never occurs when
comparing the entropy cost of $\fldr[\bp]$ with that of
$\aldr[\bp, K]$ for $K > k$.
%
In particular, since $\fldr[\bp] \equiv \aldr[\bp, k]$ is the first sampler
in the $\aldr[\bp,K]$ family ($K=k,k+1,\dots$) of rejection samplers for
the target $\bp$, the entropy costs of all members are upper bounded by
that of the first member.

\begin{theorem}[Comparison of $\aldr$ and $\fldr$ entropy cost]
\label{theorem:aldr-leq-fldr}
For every probability distribution $\bp$, the expected entropy cost
of $\aldr$ is upper bounded by that of $\fldr$:
\begin{align}
\expect{\cost{\aldr[\bp,K]}} \leq \expect{\cost{\fldr[\bp]}}
&&(K \geq k),
\end{align}
with equality if and only if no
multiplication $c_K \times a_i$ carries $(i=0,\dots,n)$.
\end{theorem}

\begin{proof}
Recall that $c_K = \floor{2^K/m}$.
%
We now apply \cref{lemma:nu-derivation} to bound parts of the entropy cost
of the ALDR tree in terms of corresponding parts of the FLDR tree.
%
For $1 \leq i \leq n$, \cref{eq:nu-derivation} directly yields
\begin{equation}
\nu\left( \frac{A_i}{2^K} \right)
= \nu\left( \frac{c_K}{2^{K-k}} \frac{a_i}{2^k} \right)
\leq \frac{c_K}{2^{K-k}} \nu\left( \frac{a_i}{2^k} \right) + \frac{a_i}{2^k} \nu\left( \frac{c_K}{2^{K-k}} \right).
\label{eq:weight-nu-entropy}
\end{equation}
%
For $i = 0$, note that the sum $A_0 + (2^k c_K - 2^K)$ does not carry because
$A_0 < 2^k$.
%
Then the no-carry case of \cref{eq:nu-subadditive} together with either case of
\cref{eq:nu-derivation} gives
\begin{equation}
\nu\left(\frac{A_0}{2^K}\right)+\nu\left(\frac{2^k c_K - 2^K}{2^K}\right)
= \nu\left(\frac{A_0 + 2^k c_K - 2^K}{2^K}\right)
= \nu\left(\frac{c_K a_0}{2^K}\right)
= \nu\left(\frac{c_K}{2^{K-k}} \frac{a_0}{2^k}\right)
\leq \frac{c_K}{2^{K-k}} \nu\left(\frac{a_0}{2^k}\right) + \frac{a_0}{2^k} \nu\left(\frac{c_K}{2^{K-k}}\right).
\end{equation}
%
Applying additivity with $\nu(1) = 0$ shows that
$\nu((2^k c_K - 2^K)/2^K) = \nu((2^k c_K)/2^K)$, so
\begin{equation}
\nu\left(\frac{A_0}{2^K}\right)
\leq \frac{c_K}{2^{K-k}} \nu\left(\frac{a_0}{2^k}\right)
  + \frac{a_0}{2^k} \nu\left(\frac{c_K}{2^{K-k}}\right)
  - \nu\left(\frac{c_K}{2^{K-k}}\right).
\label{eq:rejection-nu-entropy}
\end{equation}
%
Combining \cref{eq:weight-nu-entropy,eq:rejection-nu-entropy}
gives the desired bound on the total cost of ALDR:
\begin{align}
\expect{\cost{\aldr[\bp,K]}}
&= \frac{2^K}{M} \sum_{i=0}^{n} \nu\left( \frac{A_i}{2^K} \right) \\
&\leq \frac{2^K}{M} \sum_{i=0}^{n}
  \left[ \frac{c_K}{2^{K-k}} \nu\left( \frac{a_i}{2^k} \right)
  + \frac{a_i}{2^k} \nu\left( \frac{c_K}{2^{K-k}} \right) \right]
  - \frac{2^K}{M}\nu\left( \frac{c_K}{2^{K-k}} \right) \\
&= \frac{2^K}{M} \sum_{i=0}^{n} \frac{c_K}{2^{K-k}} \nu\left( \frac{a_i}{2^k} \right) \\
&= \frac{2^k}{m} \sum_{i=0}^{n} \nu\left( \frac{a_i}{2^k} \right) \\
&= \expect{\cost{\fldr[\bp]}}.
\end{align}

To establish the necessary and sufficient conditions for equality, it suffices
to note that every inequality in
\cref{eq:weight-nu-entropy,eq:rejection-nu-entropy} is an equality if and only
if the corresponding multiplication $c_K \times a_i$ does not carry, by
\cref{lemma:nu-derivation}.
%
Therefore, the final result is an equality if and only if
none of the multiplications $c_K \times a_i$ carry $(i=0,1,\dots,n)$.
\end{proof}

