\section{Proof of Proposition \ref{proposition2}}\label{appendixB}
For the given transmit power $p^\star$, the user's energy efficiency can be written as
\begin{align}
	EE & = \frac{{\left( {T - \frac{{\left| {x - {x^0}} \right|}}{v}} \right){{\log }_2}\left( {1 + \frac{{p^\star\left\| {\mathbf{h}\left( x \right)} \right\|_2^2}}{{{\sigma ^2}}}} \right)}}{{\bar E\left| {x - {x^0}} \right| + \frac{p^\star}{\eta_\mathrm{c}}\left( {T - \frac{{\left| {x - {x^0}} \right|}}{v}} \right)}}  \nonumber\\
	&=\frac{{{{\log }_2}\left( {1 + \frac{{p^\star\left\| {\mathbf{h}\left( x \right)} \right\|_2^2}}{{{\sigma ^2}}}} \right)}}{{\frac{{\bar E\left| {x - {x^0}} \right|}}{{T - \frac{{\left| {x - {x^0}} \right|}}{v}}} + \frac{p^\star}{\eta_\mathrm{c}}}} \nonumber\\
	&\mathop \le \limits^{\left( {{b_1}} \right)} \frac{\eta_\mathrm{c}}{{p^\star}} {{{\log }_2}\left( {1 + \frac{{p^\star\left\| {\mathbf{h}\left( x \right)} \right\|_2^2}}{{{\sigma ^2}}}} \right)} \nonumber\\
	&\mathop \le \limits^{\left( {{b_2}} \right)} \frac{\eta_\mathrm{c}}{{p^\star}}{{{\log }_2}\left( {1 + \frac{{p^\star\left\| {\mathbf{h}\left( {\bar x} \right)} \right\|_2^2}}{{{\sigma ^2}}}} \right)} \triangleq E{E^\mathrm{ub}},
\end{align}
where the inequality marked by $\left( {{b_1}} \right)$ holds because ${{{\bar E\left| {x - {x^0}} \right|}}/\left( {{T - {{\left| {x - {x^0}} \right|}}/{v}}}\right) } \ge 0$, and the equality can be achieved when $x=x^0$. The inequality marked by $\left( {{b_2}} \right)$ holds because ${\left\| {\mathbf{h}\left( \bar x \right)} \right\|_2^2}$ is the maximum channel gain, and the equality can be achieved when $x=\bar x$. Hence, when $x^0=\bar x$, the upper bound on the user's energy efficiency, $EE_\mathrm{ub}$, can be achieved. This thus completes the proof.
\section{Construction of $\varepsilon_{jk}$}\label{appendixC}
Based on the expression of ${{\mathrm{d}{h_{jk}}\left( {x_j^i} \right)}}/{{\mathrm{d}{x_j}}}$ in \eqref{1order}, we have
\begin{small}
\begin{align}
	&\frac{{{\mathrm{d}^2}{h_{jk}}\left( {x_j^i} \right)}}{{\mathrm{d}x_j^2}} \nonumber\\
	&= \sum\limits_{a = 1}^{{L_k}-1} \sum\limits_{b = a+1}^{{L_k}}  - \frac{{8{\pi ^2}\left| {{m_{jk,ab}}} \right|\vartheta _{k,ab}^2}}{{{\lambda ^2}}}\cos \left( {\frac{{2\pi}}{\lambda }x_j^i{\vartheta _{k,ab}} + \angle {m_{jk,ab}}} \right)  ,
\end{align}
\end{small}
and can select $\varepsilon_{jk}$ as
\begin{equation}\label{varkj}
	\varepsilon_{jk}=\sum\limits_{a = 1}^{{L_k}-1} {\sum\limits_{b = a+1}^{{L_k}} { \frac{{8{\pi ^2}\left| {{m_{jk,ab}}} \right|\vartheta _{k,ab}^2}}{{{\lambda ^2}}}} }.
\end{equation}
