Next, we identify the optimal combination of code rate and batch size, denoted as $(R^*, b^*)$, which minimizes the expected job completion time across various straggling scenarios. We consider three cases depending on the ratio $\frac{W}{\Updelta}$, which characterizes the randomness in the system. The next three separate theorems give the results.
%\ul{Case 1: $W \gg \Updelta$}
% \begin{figure}[t]
%     \centering
%     \includegraphics[width=0.6\linewidth]{Fig/W_1_delta_0.pdf}
%     \caption{$X \sim S-Exp(\Updelta,W)$. Code rate $R=0.1$(Replication) with minimum batch size is optimal.}
%     \label{fig:case1}
% \end{figure}
\begin{theorem}\label{thm:case1}
      For $X \sim S-Exp(\Updelta,W)$ and $\frac{W}{\Updelta} \gg 1$, the expected job completion time is minimized by replication with batch size $b=1$ for a large value of $n$.  
\end{theorem}
\begin{proof}
For batch size $b=1$ and for $\frac{W}{\Updelta} \gg 1$ expected job completion time , Equ.\ref{equ:expo_shifted_ejct} can be written as follows
%
\[\lim_{\frac{\Updelta}{W} \to 0} \expect{\leftindex^GY_{k:n}^{b=1}} = \frac{lWP^{-1}(R,1)}{R} =-\frac{lWlog(1-R)}{R} \]
%
which is a strictly increasing function with code rate $R$. So, for the batch size $b=1$, the optimal code rate will be the lowest possible code rate, i.e., $R=\frac{1}{n}$(replication). For batch size $b=1$ with replication $k=1$, the expected job completion time can be derived as follows
\begin{equation}\label{equ:case_1_r_min}
        \lim_{\frac{\Updelta}{W} \to 0} \expect{\leftindex^GY_{1:n}^{b=1}} =G\frac{W}{n}=lW\\
\end{equation}
We next calculate the expected job completion time for the maximum batch size, where $b_{max}=s=\frac{l}{R}$.

% \begin{equation}
%     \begin{aligned}
%         \expect{\leftindex^GY_{k:n}^{b=\frac{l}{R}}} &= l \Big( \frac{\Updelta}{R} + \frac{WP^{-1}(R,\frac{l}{R})}{\cancel{R}\times\frac{l}{\cancel{R}}} \Big)]]\\
%         &=lW \Big(\frac{\Updelta}{W}\times \frac{1}{R}+\frac{P^{-1}(R,\frac{l}{R})}{l} \Big)
%     \end{aligned}
% \end{equation}

\[\lim_{\frac{\Updelta}{W} \to 0} \expect{\leftindex^GY_{k:n}^{b=\frac{l}{R}}} = WP^{-1}(R,\frac{l}{R}) =mW \].

For a high job scale factor, $l \gg 1$, $P^{-1}(R,\frac{l}{R})=m$ can be considered a moderately high value to use the Normal approximation to the Poisson distribution. 
\begin{equation}
    l \approx R (Z\sqrt{m} + m)
\end{equation}
where $\upphi(Z)=1-R$ and $\upphi(\cdot)$ is the area of the left tail of the standard normal CDF.
$Z$ is close to $0$ for code rate $R \approx \frac{1}{2}$ and is negative for $R=1$(splitting). So, for both cases, $l < m$. which implies that replication ($R=\frac{1}{n}$) with unit batch size $b=1$ is optimal.
It can be shown that numerically, $l < m$ also holds for a low job scale factor, $l \approx 1$.
\end{proof}

