|\textcolor{pairedTwoDarkBlue}{\%c\_a = eqsat.eclass }\textcolor{pairedOneLightBlue}{\%a}|
|\textcolor{pairedFiveLightRed}{\%res = arith.muli }\textcolor{pairedTwoDarkBlue}{\%c\_a}\gray{, }\textcolor{pairedFourDarkGreen}{\%c\_two}|
|\textcolor{black}{\%res1 = arith.shli }\textcolor{pairedTwoDarkBlue}{\%c\_a}\gray{, }\textcolor{black}{\%c\_one}|
|\textcolor{pairedSixDarkRed}{\%c\_res = eqsat.eclass }\textcolor{pairedFiveLightRed}{\%res}\gray{, }\textcolor{black}{\%res1}|
|\gray{eqsat.yield }\textcolor{pairedSixDarkRed}{\%c\_res}|
\end{xdsl}
