%calculate the respective smallest and largest indices $\mu<\nu$ for which $v_{\p}(a_n)+nr= \underset{j \geq 0}\min\, v_{\p}(a_j)+jr$ 
%by computing each derivative $f_\ell^{(j)}(z) \bmod \p^{k}$ for increasing powers $k$.
%By Theorem~\ref{newton_polygon} there are $\nu-\mu$ extended $\p$-adic zeros in the same residue class as $z$ modulo $\pi^r$.
%If $\nu=\mu$ then the residue class contains no zeros of $f_\ell$ and we make the class a leaf of the search tree.  Otherwise we continue and repeat the process on each residue class mod $\p^{r+1}$ inside the residue class $z \bmod \p^{r}$.

%Whenever we detect a residue class with only one extended $\p$-adic zero of $f_\ell$, represented by $z\in \mathcal O_{\p}$, we can check the condition $|f(z)|_\p < |f'(z)|_\p^2$ in Hensel's Lemma.  If the condition holds, then this gives a specification of a $\p$-adic zero and we are done with this residue class. Otherwise, we look at deeper residue classes.

%The algorithm stops when it has checked all residue classes. However the problem with this procedure is that Hensel's Lemma can only detect zeros of multiplicity one. If $f_\ell$ has a zero of multiplicity two then the algorithm will keep on checking residue classes mod $\p^k$ for increasing powers $k$ and thereby fail to terminate.

It so happens that for irreducible factors of $f_\ell$, assuming $p$-adic Schanuel's Conjecture, the only possible zeros of multiplicity two or more are rational. This is the content of the main technical results in this section and it allows us to amend the above algorithm so that it always terminates.  Specifically, in parallel with the above-described process, we search by enumeration for rational zeros of $f_\ell$.
We thus find all $\p$-adic zeros either by specifying them with Hensel's Lemma or by enumerating and checking directly.  We use Thm.~\ref{newton_polygon} to certify that all zeros have thereby been found.
\subsection{Simultaneous Zeros of Coprime Exponential Polynomials}
We now state our main technical lemma.
\begin{lemma}\label{mainLemma}
Let $\K$ be a number field, $P,Q \in \K[x_0, x_1 , \dots , x_{2s}]$ be coprime multivariate polynomials, that are also coprime to any irreducible polynomial of the form $\sum_{i=1}^s (a_i+b_ix_0)x_i$, $a_i,b_i \in \Z$, $a_i$ and $b_i$ not all $0$. Let $\p \subseteq \O$ be a prime ideal lying above prime $p\in\mathbb Z$. Let $\lambda_1, \dots , \lambda_s \in \K$ be such that $v_\p(\lambda_i-1)>\frac{e}{p-1}$ where $e = e_{\p/p}$ is the ramification index, and such that the $\p$-adic logarithms $\log \lambda_1, \dots , \log \lambda_s$ are linearly independent over $\Q$. Let $f_P(x) = P(x,\log \lambda_1, \dots , \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s))$, with $f_Q$ defined analogously. 

Assuming the $p$-adic Schanuel Conjecture, if $f_P(x) = f_Q(x) = 0$, then $x \in \Q$.
\end{lemma}
\begin{proof}
Suppose $x \in \O_{\p}$ satisfies $f_P(x) = f_Q(x)$. Suppose that $x \not \in \Q$. First, assume that the set $S = \{\log \lambda_1, \dots , \log \lambda_s, x \log \lambda_1, \dots , x \log \lambda_s\}$ is linearly independent over $\Q$. By the $p$-adic Schanuel Conjecture,
\begin{align}\notag
&\mathrm{trdeg}_\Q \Q(S \cup \{ \exp(x\log\lambda_1) , \dots , \exp(x\log\lambda_s) , \lambda_1, \dots , \lambda_s\})\\ \label{trdeg1}
    =\; &\mathrm{trdeg}_\Q \Q(x,\log \lambda_1 , \dots , \log \lambda_s, \exp(x\log\lambda_1) , \dots , \exp(x\log\lambda_s)) \geq 2s \, .
\end{align}
Now $f_P(x) = f_Q(x) = 0$ implies that $T = \{x, \log \lambda_1, \dots , \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s)\}$ is comprised of at most $2s-1$ algebraically independent elements. Indeed, pick some element $\sigma$ of $\{x_i : 0 \leq i \leq 2s\}$ with positive degree in $P$. Then $f_P(x)=0$ implies that the component of $T$ corresponding to $\sigma$ is algebraic over the remaining components of $T$. Now $f_Q(x) = 0$ implies that the remaining components of $S$ are algebraically dependent. Indeed, if $\sigma$ does not appear in $Q$ then this is obviously true, otherwise since $P$ and $Q$ are coprime, the multivariate resultant $\text{Res}_\sigma(P,Q)$ is a non-zero polynomial in the remaining components of $\{x_i: 0 \leq i \leq 2s\}\setminus\{\sigma\}$ with a zero at $(x,\log \lambda_1, \dots, \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s))$ (see, e.g., \cite[pp.~163--164]{cox_ideals_2015}). Thus
\begin{align} \label{trdeg2}
    \mathrm{trdeg}_\Q \Q(x,\log \lambda_1 , \dots , \log \lambda_s, \exp(x\log\lambda_1) , \dots , \exp(x\log\lambda_s)) \leq 2s-1
\end{align}
which contradicts \eqref{trdeg1}.

We deduce that the set $S$ must be linearly dependent over $\Q$. Consequently, we have
\begin{align*}
    \sum_{i=1}^s (a_i + b_i x)\log \lambda_i = 0
\end{align*}
for some $a_i$, $b_i \in \Z$, with the $b_i$ not all zero. Without loss of generality, assume that $b_1 \neq 0$. Suppose now that $S\setminus\{x \log \lambda_1\}$ is a $\Q$-linearly independent set. Then the $p$-adic Schanuel Conjecture gives
\begin{align} \notag
    &\text{trdeg}_{\Q} \Q(S \cup \{\exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s), \lambda_1 , \dots , \lambda_s\}) \\ \label{trdeg3}
    =\; &\text{trdeg}_{\Q} \Q(x,\log \lambda_1 , \dots , \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s)) \geq 2s-1 \, .
\end{align}
Note that the multivariate polynomial $R(x_0, \dots x_s) = \sum_{i=1}^s (a_i + b_i x_0)x_i$ is irreducible. Indeed, if $R$ were reducible then $R = R_1R_2$ with $R_1=R_1(x_0)$ and $R_2=R_2(x_1, \dots , x_s)$ linear polynomials with rational coefficients. Since $x \not \in \Q$, $R_1(x) \neq 0$ so $R_2(\log \lambda_1, \dots , \log \lambda_s) = 0$, which contradicts $\Q$-linear independence of $\log \lambda_1, \dots , \log \lambda_s$. 

Now we have $f_P(x) = f_Q(x) = \sum_{i=1}^s (a_i + b_i x)\log \lambda_i =0$, and the multivariate polynomials $P, Q$ and $R(x_0, \dots x_s) = \sum_{i=1}^s (a_i + b_i x_0)x_i$ are all coprime. Hence, by repeating the earlier argument with resultants several times on $P,Q,R$, the set $T$ is comprised of at most $2s-2$ algebraically independent elements. Therefore,
\begin{align} \label{trdeg4}
    \text{trdeg}_{\Q} \Q(x,\log \lambda_1 , \dots , \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s)) \leq 2s-2
\end{align}
which contradicts \eqref{trdeg3}. We conclude that the elements $\log \lambda_1 , \dots , \log \lambda_s, x \log \lambda_2 , \dots , x \log \lambda_s$ are linearly dependent over $\Q$. So
\begin{align*}
\sum_{i=1}^s (a_i + b_i x)\log \lambda_i = \sum_{i=1}^s (c_i + d_i x)\log \lambda_i = 0 
\end{align*}
for $a_i,b_i,c_i,d_i \in \Z$, and $b_1 \neq 0$, $d_1 = 0$. Therefore,
\begin{align*}
x = -\frac{\sum_{i=1}^s a_i \log \lambda_i}{\sum_{j=1}^s b_j \log \lambda_j} = -\frac{\sum_{i=1}^s c_i \log \lambda_i}{\sum_{j=1}^s d_j \log \lambda_j}
\end{align*}
and hence
\begin{align} \label{trdeg5}
\left(\sum_{i=1}^s a_i \log \lambda_i\right)\left(\sum_{j=1}^s d_j \log \lambda_j\right) - \left(\sum_{i=1}^s c_i \log \lambda_i \right)\left(\sum_{j=1}^s b_j \log \lambda_j \right) = 0 \, .
\end{align}
This is a non-trivial algebraic relationship between $\log \lambda_1 , \dots , \log \lambda_s$. Indeed, suppose the coefficients of any monomial in $\log \lambda_1 , \dots , \log\lambda_s$ in the equation \eqref{trdeg5} are all zero. This gives the system of equations
\begin{align*}
    \{a_id_j + a_jd_i = c_i b_j + c_j b_i : 1 \leq i,j \leq s\} \, .
\end{align*}
By taking the equation corresponding to $i=j=1$, $d_1 = 0$ and $b_1 \neq 0$ imply that $c_1 = 0$. Therefore, we have
\begin{align*}
    a_1d_j = c_jb_1 , \, \forall 1 \leq j \leq s
\end{align*}
so $c_j = \frac{a_1}{b_1}d_j$ for all $1 \leq j \leq s$. Therefore $x = \frac{a_1}{b_1}$, contradicting our assumption that $x \not \in \Q$. 

But since $\log \lambda_1 , \dots , \log \lambda_s$ are $\Q$-linearly independent, the $p$-adic Schanuel Conjecture implies they are algebraically independent. This contradicts \eqref{trdeg5}. We conclude finally that our initial assumption that $x \not \in \Q$ must have been false, and so $x \in \Q$.
\end{proof}
Some remarks are in order.
\begin{remark} \label{complex_remark}
  The result also holds if we work instead with Schanuel's Conjecture on elements of $\C$, and logarithms and exponentials over $\C$.
\end{remark}
\begin{remark} \label{algebraicZeros}
By taking $Q$ to be an integer polynomial in $x_0$ in the lemma statement, one sees that irrational algebraic numbers cannot be zeros of exponential polynomials that are not polynomials in the usual sense.
\end{remark}
\begin{remark}
In the language of the theorem, call $f_P$ an exponential polynomial with algebraic coefficients if $x_i$ does not appear in $P$ with positive degree for $1 \leq i \leq s$. Then the theorem shows that any irrational zero $z$ of an exponential polynomial with algebraic coefficients has a unique irreducible exponential polynomial with algebraic coefficients that it is a root of (if $z$ is algebraic this is just its normal minimal polynomial). Therefore, just as in the case of algebraic numbers, we may associate to any \emph{exponential-algebraic number}  (i.e., a root of an exponential polynomial with algebraic coefficients) a unique \emph{minimal} exponential polynomial with algebraic coefficients that it is a root of.
\end{remark}
The application of this result to LRS is the following corollary.
\begin{corollary} \label{multCor}
Let $\K$, $\lambda_1, \dots , \lambda_s$ be as in Lem.~\ref{mainLemma}. Let $P \in \K[x_0, x_1 , \dots , x_{2s}]$ be non-zero and irreducible and such that $x_1, \dots x_s$ do not appear with positive degree in $P$. Let $f_P(x) = P(x, \log\lambda_1 , \dots , \log \lambda_s, \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s))$. 
Assuming the $p$-adic Schanuel Conjecture, 
if $x \in \O_{\p}$ is a zero of $f_P$ with multiplicity $\geq 2$ then $x \in \Q$. 
\end{corollary}
\begin{proof}
Let $Q \in \K[x_0, \dots , x_{2s}]$ be the polynomial such that
\begin{align*}
    f_P'(x) = Q(x, \log \lambda_1, \dots , \log \lambda_s , \exp(x \log \lambda_1), \dots , \exp(x \log \lambda_s)) \, .
\end{align*}
Suppose $f_P,f_P'$ have an irrational common zero. We are done if we show $P,Q$ are coprime to each other and to any irreducible polynomial $R = \sum_{i=1}^s (a_i + b_ix_0)x_i$ for any $a_i, b_i \in \Z$ not all zero, as then we can immediately conclude this cannot hold by Lem.~\ref{mainLemma}.

Since $P$ is irreducible, $P,Q$ only fail to be coprime if $P \mid Q$. Note that
\begin{align*}
    Q = \partial_0P + \sum_{i=1}^s x_i x_{s+i} \partial_{s+i}P
\end{align*}
Since $P$ has no $x_i$ component for each $1 \leq i \leq s$, we have $P|_{x_i = 0, \, i \in I}=P$ is a non-zero polynomial dividing $Q|_{x_i = 0, \, i \in I}$ for any subset $I \subseteq \{1, \dots , s\}$. In particular this implies that $P \mid \partial_0P$, hence $\partial_0P = 0$ since it has strictly lower total degree than $P$. Now using $I = \{1, \dots , s\} \setminus i$ for each $i$, we also have $P \mid x_i x_{s+i}\partial_{s+i}P$. Since we assume $f_P$ has a zero, we must have $P \mid \partial_{s+i}P$, implying $\partial_{s+i}P = 0$ since it has strictly smaller total degree than $P$. We conclude that $P$ must be constant as all of its partial derivatives vanish. This is impossible as we assume $f_P$ has a zero, so $P$ and $Q$ are coprime.

Now, since $P$ has no $x_i$ component for $1 \leq i \leq s$, $P,R$ are obviously coprime.

Finally, $R,Q$ are only not coprime if $R \mid Q$. Suppose that $Q = RT$ for some $T \in \K[x_0 , \dots , x_{2s}]$. Then setting all $x_i=0$ for $1 \leq i \leq s$ makes both sides of the equation vanish, so in particular $\partial_0 P = 0$. But then $P$ has no $x_0$ component, so clearly $R$ cannot divide $Q$, so this is a contradiction. Thus, $P,Q,R$ are all coprime for any choice of $R$ as described, so Lem.~\ref{mainLemma} applies. This completes the proof.
\end{proof}
We may now ask, do there exist rational zeros of exponential polynomials $f$ with irreducible underlying multivariate polynomials, with multiplicity greater than 1? Unfortunately, the answer is yes.  
\begin{example}
Let $Q(x,y) = x^2(x-1) + y^2$. Then $(x-1)$ is a prime ideal in $\overline \Q[x]$ which divides $x^2(x-1)$ exactly once and does not divide the coefficient of $y^2$, so by Eisenstein's criterion $Q(x,y)$ is irreducible in $\overline \Q[x][y] = \overline \Q[x,y]$. Now let $f(x) = Q(\exp(x \log 2)-1,\exp(x \log 3)-1)$. It is easy to see that $0$ is a multiplicity 2 root of $f$.
\end{example}
It would be interesting to determine the lowest possible order of an LRS with irreducible associated multivariate polynomial and a zero with multiplicity greater than 1, however we do not investigate this further here.
\subsection{The Algorithm and the Proof of Termination and Correctness}
With Corollary \ref{multCor} in hand, we may amend the algorithm outlined earlier for finding the $\p$-adic zeros of an LRS. First we define a recursive subroutine given by Algorithm \ref{zeroSearch}, which finds the $\p$-adic zeros of a suitable $\p$-adic analytic function $f$.
\begin{algorithm} 
\SetKwFunction{zeroSearch}{zeroSearch}
\SetKwData{zerosFound}{zerosFound}
\SetKwData{multCount}{multCount}
\SetKwFor{Parallel}{in parallel until}{do}{}
\SetKwFor{Until}{until}{do}{}
\caption{The \protect\zeroSearch subroutine} \label{zeroSearch}
\KwIn{A non-zero $\p$-adic analytic function $f: \O_{\p} \to \O_{\p}$, integer $r$ representing the depth of the residue class considered, and residue class representative $z_r$ of class $z_r \bmod \p^r$. We let $\pi$ be a computed uniformiser for $\p$, and $A$ a set of representatives of the residue field ${\O_{\p}}/{\p}$ (both may be easily computed given $\K$ and $\p$).}
\KwOut{A complete list of elements of $\O_{\p}$ that are either rational zeros of $f$ or give a specification of a $\p$-adic zero of $f$.} 
\BlankLine
\Def{\zeroSearch$(f,r,z_r,\zerosFound)$}{}
\ForEach{$a \in A$}{
$z_{r+1} \leftarrow z_r+a\pi^r$\;
\multCount $\leftarrow$ sum of the multiplicities of zeros $x$ in \zerosFound with $x \equiv z_{r+1} \bmod \pi^{r+1}$\;
$n \leftarrow$ the number (counting multiplicity) of extended $\p$-adic zeros $\equiv z_{r+1} \bmod \pi^{r+1}$ (computed using Thm.~\ref{newton_polygon})\;
\lIf{$n = \multCount$}{\Next $a$}
\ElseIf{$n = \multCount + 1$}{
\lIf{$v_\p(f'(z_{r+1})) < 2 v_\p(f(z_{r+1}))$}{append $z_{r+1}$ to \zerosFound}
\lElse{append \zeroSearch$(f,r+1,z_{r+1},\zerosFound)$ to \zerosFound}
\Next $a$
}
\Else{
\Parallel{\textup{(1) or (2) terminate}}{
\text{(1)} \ForEach{\textup{$q \in \Q$ with $q \equiv z_{r+1} \bmod \pi^{r+1}$}}{
\If{$f(q) = 0$}{
Append $q$ to \zerosFound\;
Append \zeroSearch$(f,r+1,z_{r+1},\zerosFound)$ to \zerosFound\;
}
}
\text{(2)} Append \zeroSearch$(f,r+1,z_{r+1},\zerosFound)$ to \zerosFound\;
}
\multCount $\leftarrow$ sum of the multiplicities of zeros $x$ in \zerosFound with $x \equiv z_{r+1} \bmod \pi^{r+1}$\;
\Next $a$
}
}
\Return{\zerosFound}
\end{algorithm}
\begin{algorithm} 
\SetKwFunction{zeroSearch}{zeroSearch}
\SetKw{Output}{output:}
\caption{An algorithm to compute the $\p$-adic zeros of an LRS $\LRS{u}$}
\KwIn{An LRS $\LRS{u}$, number field $\K$ containing $\LRS{u}$ and its characteristic roots, and prime ideal $\p \subseteq \O$ lying above prime $p$ with $v_\p(\lambda) = 0$ for all characteristic roots $\lambda$.} \label{fullAlg}
\KwOut{A list of elements of $\O_\p$ giving specifications of all the $\p$-adic zeros of $\LRS{u}$.}
Compute a multiplicatively independent subset $\{\lambda_1, \dots , \lambda_s\}$ of the characteristic roots\;
Compute least integer $M > 0$ such that for each $0 \leq t \leq M-1$ we may write $u_{Mn+t} = P_t(n,\lambda_1^n,\dots,\lambda_s^n)$ for multivariate polynomial $P_t$ with algebraic coefficients\;
Compute least integer $N > 0$ such that $v_\p(\lambda_i^{MN}-1) > \frac{e}{p-1}$ for all $1\leq i \leq s$, where $e = e_{\p/p}$ is the ramification index\;
\ForEach{$0 \leq t \leq M-1, \, 0 \leq \ell \leq N-1$}{
\ForEach{\textup{$P$ irreducible factor of of $P_t$}}{
$f(x) \leftarrow P(Nx+\ell,\exp(x \log \lambda_1^{MN}),\dots,\exp(x \log \lambda_s^{MN}))$\;
\Output \zeroSearch$(f,0,0,\emptyset)$
}
}
\end{algorithm}

Using the subroutine in Algorithm \ref{zeroSearch}, we present an algorithm to find all the $\p$-adic zeros of an LRS as Algorithm \ref{fullAlg}. Computing the multiplicatively independent subset in Line 1 can be done by Masser's Theorem (Thm.~\ref{Masser}).  In Line 2 we use multiplicative relations to express the $M$-th power of each root that is not in the multiplicatively independent set as a monomial (with positive and negative integer powers) in those roots in the set.  This allows us 
to express the subsequence $\langle u_{Mn+t}\rangle_{n=0}^\infty$ as a polynomial in $n$ and the $n$-th powers of the multiplicatively independent roots.  
%Note that Line 2 is required as when expressing dependent characteristic roots in terms of the multiplicatively independent characteristic roots there may be roots of unity introduced. For example, we may have a relation $\lambda_1^2=\lambda_2^2$ arising from $\lambda_1 = - \lambda_2$. Taking subsequences to raise each characteristic root to a sufficiently large power eliminates these roots of unity. 

Theorem~\ref{pDecidable} follows from the next result.
\begin{proposition}
Assuming the $p$-adic Schanuel  Conjecture, Algorithm \ref{fullAlg} always terminates.  Upon termination it outputs all $\p$-adic zeros of the  given LRS $\LRS{u}$.
\end{proposition}
\begin{proof}
Since each  factor $P$ defined on line 5 is irreducible, by Corollary \ref{multCor}, the $p$-adic Schanuel Conjecture implies that every zero in $\O_{\p}$ of $f$ either has multiplicity 1 or is rational. Therefore, in the \zeroSearch subroutine (Algorithm \ref{zeroSearch}), all $\p$-adic zeros of $f$ with multiplicity greater than 1 will eventually be found by the search for rational zeros on line 14, and all $\p$-adic zeros of $f$ with multiplicity equal to 1 will eventually be found by the Hensel condition on line 8. Note that the multiplicity of every rational zero $q$ can be determined by finding the first $j$ such that $f^{(j)}(q) \neq 0$. This can be done as $f^{(j)}(q)$ is a polynomial in $\log \lambda_1^{MN} , \dots , \log \lambda_s^{MN}$. By the $p$-adic Schanuel Conjecture, these logarithms are algebraically independent, hence $f^{(j)}(q) = 0$ iff the coefficients of $\log \lambda_i^{MN}$ are 0 for all $i$.

Now, if $f$ has any extended $\p$-adic zero $x \in \C_p \setminus \O_{\p}$, there is some $R$ such that for every $z \in \O_{\p}$, $v_\p(x-z) < R$. Therefore, for large enough $r$, the number $n$ computed in \zeroSearch$(f,r,z_r,\zerosFound)$ does not count any extended $\p$-adic zeros. This ensures that \zeroSearch$(f,r,z_r,\zerosFound)$ always terminates for large enough $r$ (since eventually \multCount will equal $n$), which implies that \zeroSearch$(f,0,0,\emptyset)$ terminates due to the recursive structure of the subroutine.

Since all $\p$-adic zeros of $f$ are eventually found, and termination can only occur once all $\p$-adic zeros are found, the output is correct.
\end{proof}
\begin{remark}
We stress that the  $p$-adic Schanuel Conjecture is required only for termination, not for correctness. When the algorithm terminates, its output is unconditionally correct.
\end{remark}
We end by noting a consequence for the Simultaneous Skolem Problem. Given two LRS $\LRS{u}$, $\LRS{v}$, suppose their exponential-polynomial expansions may be written in terms of multiplicatively independent characteristic roots $\{\lambda_1, \dots, \lambda_s\}$ (possibly after going to subsequences to deal with roots of unity brought on from the multiplicative relations). Suppose the multivariate polynomials defined by the respective exponential-polynomial expansions are coprime.\footnote{Note that two LRS that are coprime in the sense of~\cite{Everest2002} are coprime in our sense.} In this case we say that $\LRS{u}$ and $\LRS{v}$ are \emph{coprime}. We define the Simultaneous Skolem Problem to be the problem of deciding whether two LRS $\LRS{u}$ and $\LRS{v}$ share an integer zero.

\SIMP*
%\begin{theorem}
%Assuming the $p$-adic Schanuel Conjecture, the Simultaneous Skolem Problem on two coprime LRS $\LRS{u}, \LRS{v}$ is decidable.
%\end{theorem}
\begin{proof}
Pick $p$ such that the characteristic polynomials of both $\LRS{u},\LRS{v}$ split in $\Z_p$, and consider the LRS $\LRS{w}$ defined by $w_n = v_n^2 + p u_n^2$. For some $N \geq 1$, and all $0 \leq \ell \leq N-1$, their interpolants with respect to $p$ are related by $f_{w,\ell} = f_{v,\ell}^2 + p f_{u,\ell}^2$. For all $x \in \Z_p$, $f_{w,\ell}(x) = 0$ iff $f_{v,\ell}(x) = f_{u,\ell}(x) = 0$. Indeed, if $f_{v,\ell}(x),f_{u,\ell}(x)$ are non-zero then $v_p(f_{v,\ell}(x)^2)$ is even, and $v_p(pf_{u,\ell}(x)^2)$ is odd, so $f_{w,\ell} \neq 0$.

% Then $w_n = 0$ iff $v_n = 0$ and $u_n = 0$. Indeed if either $v_n$ and $u_n$ are non-zero, then $v_p(v_n^2)$ is even and $v_p(pu_n^2)$ is odd, so $w_n \neq 0$. 

By Thm.~\ref{pDecidable}, we may find all $p$-adic zeros of $\LRS{w}$. By coprimality of $\LRS{u}, \LRS{v}$, all the $p$-adic zeros found must be rational according to Lem.~\ref{mainLemma}. Therefore they may be found by a brute-force guess-and-check search, which in particular identifies all common integer zeros.
\end{proof}
\begin{remark}
The condition that $\LRS{u}$ and $\LRS{v}$ are coprime is fairly generic. A sufficient condition for $\LRS{u}$ and $\LRS{v}$ to be coprime is that $\LRS{v}$ has a characteristic root that is multiplicatively independent from the characteristic roots of $\LRS{u}$ (or vice-versa).
\end{remark}

\subsection{The Skolem Conjecture and the Skolem Problem} \label{SkolemConjecture}
As noted earlier, it is open whether there is a Turing reduction between $\mathtt{FSP}(\N)$ and $\mathtt{FSP}(\O_\p)$. 
For a given sequence $\LRS{u}$, if
we happen to choose a prime ideal $\p$ such that all $\p$-adic zeros of $\LRS{u}$ are rational, then they can all be identified, and the output of Algorithm \ref{fullAlg} gives a certificate that we have found all the integer zeros. This solves $\mathtt{FSP}(\N)$ for $\LRS{u}$. One may ask whether such a prime ideal always exists. It turns out that a generalisation of this idea is equivalent to the Skolem Conjecture, also known as the Exponential Local-Global Principle (see Conjecture~\ref{conj:skolem}).

\begin{theorem}\label{Skolem_conjecture_equivalent}
The Skolem Conjecture is equivalent to the following statement: if $\LRS{u}$ is a simple rational LRBS taking values in the ring $\Z[\frac{1}{b}]$ for some integer $b$, then $\LRS{u}$ has no integer zero iff there exists $N \in \Z_{\geq 1}$ and prime ideals $\p_1, \dots , \p_t$ lying above primes $p_1, \dots , p_t$ coprime to $b$ such that for all $0 \leq \ell \leq N-1$, there exists $i$ such that $u_{Nn+\ell}$ has no $\p_i$-adic zeros in $\Z_{p_i}$.
\end{theorem}
\begin{proof}
Suppose $\LRS{u}$ is a simple rational LRBS of order $d$ taking values in the ring $\Z[\frac{1}{b}]$ for some integer $b$ and that $\LRS{u}$ has no integer zeros (the reverse implication is trivial for both statements). 

Suppose the Skolem Conjecture holds, then there's an integer $m$ with $\text{gcd}(m,b) = 1$ and $u_n \not\equiv 0 \bmod m$ for all $n \in \Z$. Write
\begin{align*}
m = \prod_{i=1}^t p_i^{k_i}.
\end{align*}
Since ${\Z}/{p_i^{k_i}\Z}$ has finitely many elements, the vector $(u_n, u_{n+1}, \dots , u_{n+d-1})$ takes only finitely many values mod $p_i^{k_i}$ and thus eventually repeats. Since $\LRS{u}$ has order $d$, this means that $u_n \bmod p^{k_i}$ is periodic, with some period $N_i$. Let $N = \prod_i N_i$. Then each subsequence $u_{Nn+\ell}$ for $0 \leq \ell \leq N-1$ is constant mod $m$. In particular, for each $0 \leq \ell \leq N-1$ there's $i$ such that $u_{Nn+\ell} \not\equiv 0 \bmod p_i^{k_i}$. Therefore there are no $\p_i$-adic zeros of $u_{Nn+\ell}$ in $\Z_{p_i}$.

Now suppose there exist $N$, $\p_1, \dots , \p_t$, $p_1, \dots , p_t$ as in the theorem statement. Then for each $0 \leq \ell \leq N-1$, the subsequence $u_{Nn+\ell}$ has no $\p_i$-adic zeros in $\Z_{p_i}$ for some $i$, which means that $v_{p_i}(u_{Nn+\ell}) < k_\ell$ for some integer $k_\ell$. Let $k = \underset{\ell} \max \ k_\ell$. Then the Skolem Conjecture holds for $\LRS{u}$ with $m = \prod_i p_i^k$.
\end{proof}


