\title{Empirical Validation of the Independent Chip Model}

% \author{\textit{Redacted for Double-Blind Review}}
\author{\IEEEauthorblockN{Juho Kim}
\IEEEauthorblockA{Carnegie Mellon University, Pittsburgh, USA \\
juhok@andrew.cmu.edu}
\thanks{Paper category: short.}
