			\hline
			Medium stacks & $-5.75 \times 10^{-4}$ ($1 \times 10^{-3}$) & $0.642$ \\
			\hline
			Small stacks & $-4.44 \times 10^{-3}$ ($1 \times 10^{-3}$) & $<0.001$ \\
