\begin{proof}[Proof of Theorem \ref{thm:inducedchar} Statement 2.]

Recall $k:=v(H)$. For the other cases where we show there exists $k$-closed graphs $G$ on $n$ vertices such that there exists at least $2^{-3k^2-2k+\frac n2}$ maximal induced $(H,U_+,U_-)$-blow-ups, the key strategy in all the constructions is to somehow stick a matching such that if we choose exactly one vertex from each matching, we get a blow-up, and in any blow-up, there are a bounded number of pairs (for example $\le 3k^2$) in the matching. Furthermore, if $H$ is $c$-closed, our construction guarantees that $G$ is $(c+2)$-closed.

\

\begin{proposition}\label{prop:unifying}
    Suppose the graph $G$ satisfies the following condition: there exists vertices $a_1,a_2,\cdots,a_K,b_1,\cdots,b_K \in V(G)$ and a set of vertices $U\subseteq V(G), U \cap \{a_1,\cdots,a_K,b_1,\cdots,b_K\} = \emptyset$ such that 

    \begin{itemize}
        \item If $V$ is a subset of $ \{a_1,a_2,\cdots,a_K,b_1,\cdots,b_K \}$ such that $V \ne \{a_1,\cdots,a_K\}, V\ne \{b_1,\cdots,b_K\}$ and for each $i\in \{1,\cdots,K\}$, exactly one of $a_i,b_i$ is in $V$. Then $V\sqcup U$ is a (not necessarily maximal) induced $(H,U_+,U_-)$-blow-up.
        \item Any induced $(H,U_+,U_-)$-blow-up containing $U$ and at least one of $a_i,b_i$ for every $i$ must contain at most $K + 3k^2$ elements in $\{a_1,\cdots,a_K,b_1,\cdots,b_K\}$. 
    \end{itemize}
    Then there are at least $2^{-3k^2}(2^K-2)$ vertex sets that form maximal $(H,U_-,U_+)$-blow-ups in $G$.
\end{proposition}

\begin{proof}
    for every nonempty $S\subsetneq \{1,\cdots,k\}$, we can find $f(S)\subseteq V(G)$ such that $A_S \subseteq f(S)$, $f(S)$ is a maximal $H$-blow-up, and by the claim, $|f(S) \setminus A_S| \le 2k$. Consider the mapping $$\mathcal{P}(\{1,\cdots,k\}) \setminus \{ \emptyset, \{1,\cdots,k\}\} \to \{ \text{maximal }H\text{-blow-ups}\}, S \mapsto f(S)$$ 

   Note that the fibers of $f$ have size at most $2^{2k}$. This is because a maximal $H$-blow-up $X$ in the image of $f$ must contain $V(H) \setminus \{v_1,v_2\}$ and at least one of $a_i,b_i$ for every $1\le i\le K$, and there must exist at most $2k$ indices $i$ such that both $a_i,b_i$ are contained in $X$. Now suppose $X=f(S)$, then $A_S$ must be obtained by removing exactly one of $a_i,b_i$ for every $i$ such that $a_i,b_i\in X$. Thus, $|f^{-1}(\{X\})| \le 2^{2k}$ for all $X$. Since the source of $f$ has $2^K-2$ elements,  $$|Im(f)| \ge \left\lceil\frac{2^K-2}{2^{2k}}\right\rceil = 2^{K-2k} > 2^{\frac n2 - 2k - 3k^2}.$$
\end{proof}
We first handle the case where $H$ has $b \geq 2$ bad twin groups.

 \begin{claim}\label{claim:disjoint}
     If $v,w$ belong to two different bad twin groups, then $v\not\sim w$. 
 \end{claim}
 \begin{proof}
     We prove by contradiction. If $v\sim w$, then $v \in N(w)$. Since $w$ is bad, $H[N(w)]$ is a clique, so $N(v) \cup \{v\} \supseteq N(w) \cup\{w\}$. Analogously, $N(w) \cup\{w\}\supseteq N(v) \cup \{v\}$, so $v,w$ belong to the same bad plus twin group, which leads to a contradiction.
 \end{proof}


We now divide this into three subcases.

\begin{enumerate}
    \item There are at least two different bad twin groups $B_1\not\subseteq U_-$ and $B_2\not\subseteq U_-$. 
    \item There exists exactly one bad twin group $B$ such that $B\not\subseteq U_-$. 
    \item All bad vertices are in $U_-$. 
\end{enumerate}

