Let $B_1,B_2$ be two distinct bad twin groups not contained in $U_-$. We choose $v_1 \in B_1 \setminus U_-$ and $v_2\in B_2\setminus U_-$ arbitrarily. Define $K := \lceil \frac{n-(k-2)}{2}\rceil$.

\textbf{Construction:} For each $n$, we now construct a $(k+1)$-closed graph on $n$ or $n+1$ vertices as follows. 
    Starting from the original graph $H$ (Figure \ref{fig:inducedH}), replace $v_1$ by a clique $\{a_1,\cdots,a_K\}$, and replace $v_2$ by a clique $\{b_1,\cdots,b_K\}$ of size $K$. In between there two cliques, there is a perfect matching $\{(a_1, b_1), \dots, (a_K, b_K)\}$, and add edges from each vertex in $N(v_1)$ to each vertex in $\{a_1,\cdots,a_K\}$ and add edges from each vertex in $N(v_2)$ to each vertex in $\{b_1,\cdots,b_K\}$. 
    See Figure \ref{fig:inducedG} for an illustration. In this construction, we treat $H \setminus \{v_1, v_2\}$ as an induced subgraph of $G$ on $V(G) \setminus \{a_1,\cdots,a_K,b_1,\cdots,b_K\}$, where by a slight abuse of notation, each vertex $v \in V(H) \setminus \{v_1, v_2\}$ is also vertex $v$ in $G$. 

    Observe that if $H$ is $c$-closed, then we claim $G$ is $(c+1)$-closed. Recall $G$ is $\alpha$-closed if $\max\limits_{u \not\sim v, u\ne v} |N(u) \cap N(v)| < \alpha$. 

    \begin{itemize}
        \item $u,v \notin \{a_1,\cdots,a_K,b_1,\cdots,b_K\}$: in this case, if $a_i \in N(u)\cap N(v)$, then in $H$, $u\sim v_1$ and $v\sim v_1$. Since $v_1$ is bad, this implies $u\sim v$. Thus, if $u \not\sim v$, then none of the $a_i$'s or the $b_j$'s are in $N(u)\cap N(v)$, so $|N_G(u) \cap N_G(v)| = |N_H(u)\cap N_H(v)| < c$.
        \item $u \in \{a_1,\cdots,a_K,b_1,\cdots,b_K\}, v\notin \{a_1,\cdots,a_K,b_1,\cdots,b_K\}$. WLOG $u \in \{a_1,\cdots,a_K\}$, for the case where $u \in \{b_1,\cdots,b_K\}$ is handled in a symmetric way. If $u\not\sim v$, then in $H$, $v_1 \not \sim v$. Thus, $v$ is not adjacent to any of $a_1,\cdots,a_K$ in $G$. Thus, if $u=a_i$, then $N_G(u)\cap N_G(v) \subseteq (N_H(v_1) \cap N_H(v)) \cup \{b_i\}$, which has cardinality less than $c+1$. 
        \item $u,v \in \{a_1,\cdots,a_K,b_1,\cdots,b_K\}$. In this case, if $u\not \sim v$, then there exists $i\ne j$ in $[K]$ such that $u = a_i, v=b_j$. Then $N_G(a_i)\cap N_G(b_j) \subseteq \{a_j,b_i\} \cup (N_H(v_1)\cap N_H(v_2)) $, which has at most $c+2$ elements. 
    \end{itemize}

   We now point out $2^K-2$ specific (not necessarily maximal) induced blow-ups of $H$ in $G$. 
    For each nonempty subset $S \subsetneq \{1,\cdots,K\}$  we define $$ A_S := \{a_i\colon i\in S\} \bigsqcup \{ b_i \colon i\notin S\} \bigsqcup (V(H)\setminus \{v_1,v_2\})$$ 

    Note $G[A_S]$ is a prescribed induced blow-up of $H$. Indeed, it is the case by setting $A_{v_1} = \{a_i\colon i\in S\}, A_{v_2} = \{ b_i \colon i\notin S\}$ and $A_x = \{x\}$ for all $x\in V(H)\setminus \{v_1,v_2\}$.

    Clearly $|A_S| = |V(G)| - K$ and $A_S \ne A_{S'}$ if $S\ne S'$.

    It is possible that each $G[A_S]$ is already a maximal induced blow-up of $H$. But we do not have a direct proof of it. Instead, we will prove the following. 
   \begin{claim}\label{claim:inducedmain}
       If $A\subseteq G$ is a  $H$-blow-up, then there exists at most $2k$ indices $i \in [K]$ can satisfy that both the vertices $a_i, b_i$ are in $A$. 
   \end{claim}

   Assuming Claim \ref{claim:inducedmain}, we can deduce the theorem by applying proposition \ref{prop:unifying} with $U = V(H)\setminus \{v_1,v_2\}$.


   The rest of the proof is dedicated to prove Claim \ref{claim:inducedmain}. We prove by contradiction. 
Suppose there are at least $2k$ indices $j$ such that the vertices $a_j$ and $b_j$ are both in $A$. By the pigeonhole principle, there exists $z\in V(H)$ and at least $2k / |V(H)| = 2$ indices $j$ such that $a_j\in A_z$. Call the indices $j\ne j'$.  Note that $b_j \sim a_j$ but $b_j \not\sim a_{j'}$. Thus, $b_j\in A_z$. Analogously, $b_{j'} \in A_z$. Now, for any $i\notin \{j,j'\}$ such that $a_i \in A$, note that $a_i \sim a_j$ but $a_i\not\sim b_j$. Since $a_j,b_j\in A_z$, it follows that $a_i\in A_z$. Analogously, if $b_i\in A$, then $b_i\in A_z$.

Now note $\{a_1, \dots, a_K, b_1, \dots, b_K\} \cap A \subseteq A_z$, we still need to assign at least one vertex to every $A_y$ for $y\in V(H) \setminus \{z\}$. However, there are only at most $v(H)-2$ vertices in $A \setminus \{a_1, \dots, a_K, b_1, \dots, b_K\} = V(H) \setminus \{v_1,v_2\}$. We can only use $v(H)-2$ vertices, and need to place at least one vertex in $v(H)-1$ parts of the blow-up. This is a contradiction. 

\

    \noindent\textbf{Case $2$: $H$ has at least two bad twin groups, and there is exactly one bad twin group that is not completely contained in $U_-$.}

Let $W$ be a bad twin group contained in $U_-$, and $B$ be the bad twin group not contained in $U_-$. We choose $v \in B\setminus U_-$, and choose $w\in W$ arbitrarily. Note $v\not\sim_H w$. 

\textbf{Construction:} Recall $k:=v(H)$. Let $K  := \lceil \frac{n-(k-2)}{2} \rceil > 20k^5$. We construct a graph $G$ on $k-2+2K $ vertices as follows: we start with $H$, replace $v$ with a clique $\{a_1,\cdots,a_K\}$, connect every $a_i$ with only the neighbors of $v$. We replace $w$ with an independent set $\{b_1,\cdots,b_K\}$. We connect $b_1,\cdots,b_K$ with the neighbors of $w$, and we connect $a_i$ with $b_i$ for all $1\le i\le K$. Call the resulting graph $G$. Note that $G$ is $(k+1)$-closed, and if $H$ is $c$-closed then $G$ is $(c+2)$-closed. 

Note that for any nonempty subset $S \subsetneq \{1,\cdots,K\}$, setting $A_v = \{ a_i \colon i\in S\}, A_w  = \{ b_i \colon i\notin S\}$ and $A_x = \{x\}$ for all $x\in V(H) \setminus \{v,w\}$ does make $\bigsqcup_{u\in V(H)} A_u$ an induced $H$-blow-up. 

\begin{claim}
    If $A$ is a
    $H$-blow-up, then there exists at most $2k$ indices $i$ such that $a_i,b_i\in A$.
\end{claim} 
\begin{proof}

By the pigeonhole principle, there exists $l\in V(H)$ and at least $2k / |V(H)| = 2$ indices $j$ such that $a_j\in A_l$. Call the indices $j,j'$.  Note that $b_j \sim a_j$ but $b_j \not\sim a_{j'}$. Thus, $b_j\in A_l$. Analogously, $b_{j'} \in A_l$. Now, for any $i\notin \{j,j'\}$ such that $a_i \in A$, note that $a_i \sim a_j$ but $a_i\not\sim b_j$. Since $a_j,b_j\in A_l$, it follows that $a_i\in A_l$. Thus $\{a_1,\ldots,a_K\}\cap A\subset A_l.$  Hence $|A_l|\geq |\{a_1,\ldots,a_K\}\cap A| \ge 2k$ so $l$ is bad. Since $a_j,a_{j'},b_j \in A_l$ and $a_j\sim b_j$ but $b_j\not\sim a_{j'}$, $A_l$ is neither a clique nor independent set, so $l$ is not prescribed. By assumption of Case 2, $l\in B$ thus $l$ is a twin of $v$, and $|N_H(l)| = |N_H(v)|$. 

 Note that the common neighborhood of $a_i,b_i$ in $G$ corresponds precisely to $N_H(v) \cap N_H(w)$, so at most $|N_H(v) \cap N_H(w)|$ vertices can be assigned to $\bigsqcup_{x\in N_H(l)} A_x $. Since each such $A_x$ has to be assigned at least one vertex, it follows that $|\{ A_x \colon x\in N_H(l)\}|=|N_H(l)|\leq |N_H(v) \cap N_H(w)|$. Since $|N_H(l)| = |N_H(v)|$, we have $|N_H(v)|\leq |N_H(v) \cap N_H(w)|$. This implies $ N_H(v)\subseteq N_H(w)$. 

However, since $v,w$ belong to different bad twin groups and $v\not\sim w$, we have $N_H(v) \subsetneq N_H(w)$. Choose $z \in N_H(w) \setminus N_H(v)$. Note that $z\sim b_i$ but $z\not\sim a_i$ for some pair $a_i,b_i\in A$, and we have shown before that $a_i,b_i\in A_l$. It follows that $z\in A_l$.

Now note for any $j$ such that $b_j \in A$, note $b_j$ is adjacent to $z\in A_l$, but also not adjacent to some other $b_i\in A_l$. Thus, $\{b_1,\cdots,b_K\} \cap A \subseteq A_l$. 

From $\{a_1,\cdots,a_K, b_1,\cdots,b_K\} \cap A \subseteq A_l$, we now have $\le v(H)-2$ other vertices in $A$ to be placed in $v(H)-1$ parts, contradiction.
\end{proof}

By applying proposition \ref{prop:unifying} on $U = V(H) \setminus \{v,w\}$, $G$ has at least $2^{-3k^2} (2^K-2)$ maximal $H$-blow-ups. 

\

    \noindent\textbf{Case $3$: $H$ has at least two bad twin groups, both contained in $U_-$.}

Let $B,W$ be arbitrarily chosen bad twin groups, and choose $v\in B, w\in W$ arbitrarily. Note $v \not\sim w$. 

\textbf{Construction:} Recall $k:=v(H)$. Let $K  := \lceil \frac{n-(k-2)}{2} \rceil > 20k^5$. We will construct a graph $G$ with $k-2+2K$ vertices as follows. We start with $H$, replace $v$ with a an independent set $\{a_1,\cdots,a_K\}$, connect every $a_i$ with only the neighbors of $v$. We replace $w$ with an independent set $\{b_1,\cdots,b_K\}$. We connect $b_1,\cdots,b_K$ with the neighbors of $w$, and we connect $a_i$ with $b_i$ for all $1\le i\le K$. Call the resulting graph $G$. Note that $G$ is $(k+1)$-closed. 

Note that for any nonempty subset $S \subsetneq \{1,\cdots,K\}$, setting $A_v = \{ a_i \colon i\in S\}, A_w  = \{ b_i \colon i\notin S\}$ and $A_x = \{x\}$ for all $x\in V(H) \setminus \{v,w\}$ does make $\bigsqcup_{u\in V(H)} A_u$ an induced $H$-blow-up. 

\begin{claim}
    If $A$ is a $H$-blow-up, then there exists at most $k^2$ indices $i$ such that $a_i,b_i\in A$.
\end{claim} 
\begin{proof}


Suppose more than $k^2$ indices $i$ such that $a_i,b_i\in A$. By the pigeonhole principle, there exists $l\in V(H)$ and at least $\lceil (k^2+1) / |V(H)| \rceil = k+1$ indices $j$ such that $a_j\in A_l$. Call the indices $j_1,j_2,\ldots,j_{k+1}$.  Note that $b_{j_2} \sim a_{j_2}$ but $b_{j_2} \not\sim a_{j_1}$. Thus, $b_{j_2}\in A_l$, and analogously $b_{j_t} \in A_l$ for all $t\in [k+1]$. Hence $|A_l|\geq 2k$ and $l$ is bad by the construction. But $A_l$ is not an independent set, contradicting the assumption that each bad vertex belongs to $U_-$.
\end{proof}
By applying proposition \ref{prop:unifying} on $U = V(H) \setminus \{v,w\}$, $G$ has at least $2^{-3k^2} (2^K-2)$ maximal $H$-blow-ups. 

\

    \noindent\textbf{Case 4: $H$ has exactly one bad twin group $B$, and $H[B]$ is an independent set with at least two vertices not in $U_-$.} This corresponds to scenario c) of Statement 2 of Theorem \ref{thm:inducedchar}.



Let $V(H)=\{x_1,x_2,\ldots,x_k\}.$ Without loss of generality, assume $x_1,x_2\in B$ and $x_1,x_2\not\in U_-$.

\textbf{Construction:} define $K := \lceil \frac{n-(k-2)}{2}\rceil$. 


\begin{itemize}
    \item Start with $H$
    \item Replace $x_1$ with a large clique on $K$ vertices, call the vertices $\{a_1,\cdots,a_K\}$. These vertices are adjacent to the neighbors of $x_1$.
    \item Replace $x_2$ with a large clique on $K$ vertices, call the vertices $\{b_1,\cdots,b_K\}$. These vertices are adjacent to the neighbors of $x_2$.
    \item Add edges $(a_i,b_i)$ for $1\le i\le K$; in particular, if $i\ne j$, $a_i$ is \emph{not} adjacent to $b_j$. 
\end{itemize}

Note that this graph has $k-2+2K$ vertices.

An illustration of this construction is in Figure \ref{fig6}.

It's straightforward to check that the resulting construction is $(k+1)$-closed, where $k = v(H)$.


