\title{MobileGUI-RL: Advancing Mobile GUI Agent through Reinforcement Learning in Online Environment}



\renewcommand\Authfont{\bfseries}


\author[ ]{Yucheng Shi$^{1,2 *}$, Wenhao Yu$^{1 *}$, Zaitang Li$^{1,3}$, Yonglin  Wang$^{1}$, Hongming Zhang$^{1}$, Ninghao Liu$^{2}$, Haitao Mi$^{1}$, Dong Yu$^{1}$}

