\section{Analytic background}
\label{sec:background}

\subsection{Generalities}
\label{sec:generalities}






We recall the three standard quantities conserved by the flow
of 
\eqref{eq:nls}: mass, energy, and linear momentum, given respectively
by
\begin{align*}
  M&=\|u(t)\|_{L^2(\R^d)}^2,\\
E& = \frac{1}{2}\|\nabla u(t)\|_{L^2(\R^d)}^2
   +\frac{1}{\si+1}\|u(t)\|_{L^{2\si+2}(\R^d)}^{2\si+2} ,\\
P &= \IM \int_{\R^d} \bar u(t,x)\nabla u(t,x)dx.
\end{align*}




The following lemma is standard (see
\cite{TsutsumiSigma} or  \cite{Rauch91}):
\begin{lemma}\label{lem:tsutsumi}
  Let $f\in L^2(\R^d)$, and recall that
  $U_0(t)=e^{i\frac{t}{2}\Delta}$. 
  \begin{equation*}
    \left\lVert U_0(t) f - A(t)f\right\rVert_{L^2(\R^d)} \Tend t
    {\pm\infty} 0, \quad \text{where }A(t)f(x) = \frac{1}{(it)^{d/2}}\widehat
  f\(\frac{x}{t}\)e^{i\frac{\lvert x\rvert^2}{2t}},
  \end{equation*}
and the Fourier transform is normalised in \eqref{eq:fourier}. 
\end{lemma}
The lemma is an easy consequence of the factorisation
\begin{equation*}
  U_0(t) = M_t D_t {\mathcal F} M_t,
\end{equation*}
where $M_t$ stands for the multiplication by the function
$e^{i\frac{\lvert  x\rvert^2}{2t}}$, ${\mathcal F}$ is the Fourier
transform defined in  \eqref{eq:fourier}, and $D_t$ is the dilation
operator 
\begin{equation*}
      \(D_t f\)(x) = \frac{1}{(it)^{d/2}}f\(\frac{x}{t}\).
\end{equation*}
These three operators are unitary on $L^2$, and the lemma follows from
the Dominated Convergence Theorem, noticing that $A(t) = M_t D_t {\mathcal F}$.

