 % \begin{equation*}
 %  \left\lVert \nabla U_0(t) f - i M_t D_t \(x\mathcal F
 %     f\)\right\rVert_{L^2(\R^d)} \Tend t 
 %   {\pm\infty} 0.
 % \end{equation*} 
%\end{lemma}
%\begin{proof}
