 % \end{equation*}
 % hence the lemma. 
%\end{proof}
The sharp decay in time of linear solutions is classical and recalled in
the following lemma:
\begin{lemma}\label{lem:disp-lin}
  There exists $C$ such that for all $f\in \Sigma$, and all $2\le
  p<\frac{2d}{(d-2)_+}$, 
  \begin{equation*}
    \|U_0(t) f\|_{L^p(\R^d)}\le
    \frac{C}{\<t\>^{d\(\frac{1}{2}-\frac{1}{p}\)}}\|f\|_{\Sigma},\quad
      \forall t\in \R.
  \end{equation*}
\end{lemma}
\begin{proof}
  The tools and properties evoked in this proof can be found in
  e.g. \cite{CazCourant} or \cite{GinibreDEA}. 
  Gagliardo-Nirenberg inequality yields
  \begin{equation*}
      \|U_0(t) f\|_{L^p(\R^d)}\lesssim
      \|U_0(t)f\|_{L^2(\R^d)}^{1-\delta(p)}
\|\nabla U_0(t)f\|_{L^2(\R^d)}^{\delta(p)},\quad
\delta(p):=d\(\frac{1}{2}-\frac{1}{p}\),
  \end{equation*}
and since $U_0(t)$ is unitary on $L^2$ and commutes with $\nabla$,
 \begin{equation*}
      \|U_0(t) f\|_{L^p(\R^d)}\lesssim
      \|f\|_{L^2(\R^d)}^{1-\delta(p)}
\|\nabla f\|_{L^2(\R^d)}^{\delta(p)},\quad
\forall t\in \R.
  \end{equation*}
For $|t|>1$, we recall that the operator $J(t)=x+it\nabla$ can be
factorised as 
\begin{equation*}
  J(t) f=  it\, e^{i\frac{|x|^2}{2t}}\nabla \(f\,
  e^{-i\frac{|x|^2}{2t}}\), 
\end{equation*}
so  Gagliardo-Nirenberg inequality also yields
\begin{equation*}
  \|f\|_{L^p(\R^d)}\lesssim \frac{1}{|t|^{\delta(p)}}  \|f\|_{L^2(\R^d)}^{1-\delta(p)}
\|J(t) f\|_{L^2(\R^d)}^{\delta(p)}.
\end{equation*}
Moreover, $J(t) = U_0(t)x U_0(-t)$, so, since $U_0(t)$ is unitary on
$L^2$,
\begin{equation*}
   \|U_0(t)f\|_{L^p(\R^d)}\lesssim \frac{1}{|t|^{\delta(p)}}  \|f\|_{L^2(\R^d)}^{1-\delta(p)}
\|x f\|_{L^2(\R^d)}^{\delta(p)},
\end{equation*}
hence the lemma. 
\end{proof}











\subsection{Proof of  Theorem~\ref{theo:identities}}
\label{sec:direct}



The property
\begin{equation*}
  \|U_0(-t)u(t)-u_\pm\|_\Sigma\Tend t {\pm \infty} 0,
\end{equation*}
together with
Lemma~\ref{lem:tsutsumi}, Sobolev embedding, and
Lemma~\ref{lem:disp-lin}, then easily yield \eqref{eq:mass},
\eqref{eq:energy} and \eqref{eq:moment0}. 

Formally, the centre of mass 
  \begin{equation*}
    \overline x(t)= \int_{\R^d}x|u(t,x)|^2dx
  \end{equation*}
evolves according to 
\begin{align*}
  \frac{d}{dt}   \overline x(t) &= 2\RE \int_{\R^d}x\overline
  u(t,x)\d_t u(t,x) dx=-\IM \int_{\R^d}x\overline
  u(t,x) \Delta u(t,x) dx\\
& = \IM \int_{\R^d}\overline
  u(t,x) \nabla u(t,x) dx=P,
\end{align*}
and so its derivative is constant. This identity can be made rigorous
by resuming the argument given in the proof of \cite[Lemma~6.5.2]{CazCourant}, which
consists, in the present case, in considering as an intermediate quantity
\begin{equation*}
   \overline x_\eps(t)= \int_{\R^d}x e^{-\eps|x|^2}|u(t,x)|^2dx.
\end{equation*}
Let
\begin{equation*}
  z(t) = \RE\int_{\R^d}\overline u(t,x)J(t)u(t,x)dx
  = \int_{\R^d}\overline u(t,x)J(t)u(t,x)dx,
\end{equation*}
where $J(t)=x+it\nabla$ was introduced in the proof of
Lemma~\ref{lem:disp-lin}. The reason why the imaginary part of the
above integral is zero is straightforward, by writing
\begin{equation*}
   \int_{\R^d}\overline u(t,x)J(t)u(t,x)dx=  \int_{\R^d}x \overline
   u(t,x)u(t,x)dx+  it \int_{\R^d}\overline u(t,x)\nabla u(t,x)dx.
\end{equation*}
More precisely, expanding,
\begin{equation*}
  z(t) = \overline x(t)-t P=\overline x(0)=\int_{\R^d}x|u_0(x)|^2dx.
\end{equation*}
On the other hand, the factorisation
$J(t) = U_0(t)x U_0(-t)$ and the assumption $\|U_0(-t)u(t)-
u_\pm\|_\Sigma \to 0$ yield, with $\<f,g\>=\int f\overline g$, and since
$U_0(t)^*=U_0(-t)$, 
\begin{align*}
  z(t)  & =  \int_{\R^d}
          \overline{u(t,x)}U_0(t)xU_0(-t)u(t,x)dx=\<U_0(t)xU_0(-t)
          u(t),u(t)\>\\
  &=\<xU_0(-t)u(t),U_0(-t)u(t)\>
  \Tend t {\pm \infty} \<x u_\pm,u_\pm\> = \int_{\R^d} x |u_\pm(x)|^2dx,
\end{align*}
hence \eqref{eq:center}.
\bigbreak

To prove \eqref{eq:moment}, we use the lens transform \eqref{eq:lens}.
We first emphasise
the fact that the lens transform yields an alternative proof of
\eqref{eq:moment0}-\eqref{eq:center}, since, like in the linear case
(discovered in \cite{Ehrenfest}), $v$, solution to
\eqref{eq:nlsharmo-gen}, satisfies
\begin{align*}
 & \frac{d}{dt}\IM \int_{\R^d} \overline v(t,x)\nabla v(t,x)dx =
  \int_{\R^d} x |v(t,x)|^2dx,\\ 
&\frac{d}{dt} \int_{\R^d} x
  |v(t,x)|^2dx= \IM \int_{\R^d} \overline v(t,x)\nabla v(t,x)dx . 
\end{align*}
This implies
\begin{align*}
 & \IM \int_{\R^d} \overline v(t,x)\nabla v(t,x)dx=\cos t  \times\IM \int_{\R^d}
  \overline u_0(x)\nabla u_0(x)dx +\sin t \times\int_{\R^d} x
   |u_0(x)|^2dx,\\
&\int_{\R^d} x |v(t,x)|^2dx= \cos t \times \int_{\R^d} x
   |u_0(x)|^2dx + \sin t \times\IM \int_{\R^d}
  \overline u_0(x)\nabla u_0(x)dx ,
\end{align*}
so \eqref{eq:moment0}-\eqref{eq:center} follow from Plancherel equality
and Lemma~\ref{lem:waveharmo}, since
\begin{equation*}
   \IM \int_{\R^d} \overline v(t,x)\nabla v(t,x)dx =\frac{1}{i}
   \int_{\R^d} \overline v(t,x)\nabla v(t,x)dx . 
\end{equation*}
\smallbreak

In the case $\si=2/d$, \eqref{eq:nlsharmo-gen} is autonomous, 
\begin{equation}
  \label{eq:nlsharmo}
  i\d_t v +\frac{1}{2}\Delta v = \frac{\lvert x\rvert^2}{2} v + \lvert
  v\rvert^{4/d}v,\quad v_{\mid t=0} = u_{\mid t=0}=u_0,
\end{equation}
and 
we know that if $v_{\mid t=0}\in \Sigma$, then \eqref{eq:nlsharmo} has
a unique, global solution $v\in \C(\R;\Sigma)\cap C^1(\R;\Sigma^*)$ (see
\cite[Section~9.2]{CazCourant} or \cite{CaAHP}). 






\begin{lemma}[From Lemma~3.1 in \cite{CaAHP}]
  Let $u_0\in \Sigma$: the solution $v\in C(\R;\Sigma)$ to
  \eqref{eq:nlsharmo} satisfies
  \begin{align}
    &\frac{d}{dt}\( \| xv(t)\sin t-i\cos t \nabla v(t)\|_{L^2}^2
      +\frac{2d}{2+d}\cos^2t\|v(t)\|_{L^{2+4/d}}^{2+4/d}\)
      =0, \label{eq:evol1}\\ 
   &\frac{d}{dt}\( \| xv(t)\cos t+i\sin t\nabla v(t)\|_{L^2}^2
      + \frac{2d}{2+d}\sin^2t\|v(t)\|_{L^{2+4/d}}^{2+4/d}\)
     =0. \label{eq:evol2} 
  \end{align}
\end{lemma}



We can now complete the proof of Theorem~\ref{theo:identities}.
  For $u_-\in \Sigma$, let $u\in C(\R;\Sigma)$ be
  given by the wave operator, with $u_{\mid t=0}=u_0$. We define $v$ as the solution to
  \eqref{eq:nlsharmo}. Considering the constant of motion appearing in
  \eqref{eq:evol1} at times $t=-\pi/2$, $0$ and $\pi/2$, we get
  \begin{equation*}
    \left\|x v\(-\frac{\pi}{2}\)\right\|_{L^2}^2 =
    \|\nabla u_0\|_{L^2}^2 + \frac{2d}{2+d}\|u_0\|_{L^{2+4/d}}^{2+4/d}
   =\left\|x v\( \frac{\pi}{2}\)\right\|_{L^2}^2.
 \end{equation*}
 Using Lemma~\ref{lem:waveharmo}, this yields \eqref{eq:energy}.

 Similarly, considering the constant of motion appearing in
 \eqref{eq:evol2} at times $t=-\pi/2$, $0$ and $\pi/2$,
   \begin{align*}
    \left\|\nabla v\(-\frac{\pi}{2}\)\right\|_{L^2}^2 +
     \frac{2d}{2+d}\left\|v\(-\frac{\pi}{2}\)
     \right\|_{L^{2+4/d}}^{2+4/d} &=\|x u_0\|_{L^2}^2\\
     &=
  \left\|\nabla v\(\frac{\pi}{2}\)\right\|_{L^2}^2 +
    \frac{2d}{2+d}\left\|v\(\frac{\pi}{2}\)\right\|_{L^{2+4/d}}^{2+4/d}
  , 
 \end{align*}
and Lemma~\ref{lem:waveharmo}  yields \eqref{eq:moment}.


\subsection{Rotating points for the scattering operator in the
  $L^2$-critical case}
\label{sec:rotat}

We recall the main result from \cite{CaDPDE}, and sketch the main arguments
of the proof:
\begin{proposition}[From \cite{CaDPDE}]\label{prop:CaDPDE}
  Let $d\ge 1$ and $\si=2/d$ in \eqref{eq:nls}. For any $\theta\in
  [0,2\pi)$, there exist infinitely many functions $u_-\in \Sigma$
  such that $S(u_-)=e^{i\theta}u_-$. 
\end{proposition}
As \eqref{eq:nls} is invariant under the gauge transform $u\mapsto
e^{i\omega}u$ for any constant $\omega\in \R$, we emphasise that the above
statement holds even modulo this equivalence relation. The proof
actually allows to consider $u_0=W_-u_-(=\psi$ below) real-valued. 
\begin{proof}[Sketch of the proof]
  Using the lens transform \eqref{eq:lens}, Lemma~\ref{lem:waveharmo}
  shows  that it suffices to  construct a solution $v$ to
  \eqref{eq:nlsharmo-gen} such that
  \begin{equation*}
    v\(\frac{\pi}{2},x\) = e^{i\theta}
      e^{-id\pi/2}v\(-\frac{\pi}{2},-x\),\quad \forall x\in \R^d.
  \end{equation*}
Since  \eqref{eq:nlsharmo-gen} is autonomous in the $L^2$-critical
case $\si=2/d$, we can seek such a special solution of the form
$v(t,x) = e^{-i\nu t} \psi(x)$, where $\psi$ is a radial solution to
the elliptic problem
\begin{equation}\label{eq:ell-crit}
  \nu \psi = H\psi+|\psi|^{4/d}\psi,\quad
  H=-\frac{1}{2}\Delta+\frac{|x|^2}{2}, 
\end{equation}
and $\nu$ belongs to the set
\begin{equation*}
  \left\{ \frac{d}{2}-\frac{\theta}{\pi}+2j,\quad
    j\in\N\setminus\{0\}\right\}. 
\end{equation*}
It is then easy to see that for any $\nu>d/2$ and any
$0<\si<\frac{2}{(d-2)_+}$, there exists a radial solution $\psi\in
  \Sigma$ to 
  \begin{equation}\label{eq:ell-gen}
    \nu \psi = H\psi+|\psi|^{2\si}\psi,
  \end{equation}
by minimising the action of the linear case
\begin{equation*}
  I(\psi) = \<H\psi,\psi\>-\nu\<\psi,\psi\>,
\end{equation*}
under the nonlinear constraint 
\begin{equation*}
  \psi\in M=\left\{ \psi\in \Sigma,\ \psi(x)=\psi(|x|)\ ; \
    \frac{1}{1+\si}\int_{\R^d} |\psi(x)|^{2+2\si}=1\right\}.
\end{equation*}
The uncertainty principle and the compactness of the resolvent of $H$
imply that the infimum is negative, and achieved by a function $\tilde
\psi\in M$. One concludes by examining the sign of the Lagrange
multiplier and using the homogeneity of the nonlinearity. 
\end{proof}

We emphasise that the elliptic argument does not use the fact that the
nonlinearity is $L^2$-critical, as we solve \eqref{eq:ell-gen}. This
property is crucial however to 
reduce the proof of Proposition~\ref{prop:CaDPDE} to the construction
of a (radial) solution to \eqref{eq:ell-gen}, since if $\si\not =
2/d$, the nonlinearity in the equation obtained after the lens transform,
\eqref{eq:nlsharmo-gen}, depends on time, and it is hopeless to seek a
special solution in the form of a solitary wave $v(t,x) = e^{-i\nu
  t} \psi(x)$. It is therefore unclear whether the statement of
Proposition~\ref{prop:CaDPDE} can be extended to other powers than
$\si=2/d$ or not. One might think for instance of an argument based on 
Leray-Schauder degree theory (see e.g. \cite{Cronin,Mawhin}), to
change the power of $\cos t$ from zero 
(like in the proof of Proposition~\ref{prop:CaDPDE}) to $d\si-2$ like
in \eqref{eq:nlsharmo-gen}. The numerical simulations that we present
in Section~\ref{sec:num} suggest that this strategy may not be
successful, and that Proposition~\ref{prop:CaDPDE} may be bound to the
$L^2$-critical case. 






\subsection{Long range scattering}
\label{sec:long-range}

In this section, we discuss only the one-dimensional case $d=1$. As
recalled in the introduction, when $\si=1$ (cubic nonlinearity),
\begin{equation}
  \label{eq:cubic1D}
    i\d_t u +\frac{1}{2}\d_{x}^2u = |u|^2u,\quad x\in \R, 
\end{equation}
the
solution $u$ cannot behave asymptotically like the
linear evolution of a scattering state $u_+$, unless we deal with the
zero solution. The large time dynamics of $u$ becomes more complicated
to describe than with the mere linear group $U_0(t)$.
Without entering into details, we summarise the main results from
e.g. \cite{HN98,HN06,KatoPusateri2011,Ozawa91}.
\smallbreak

Given asymptotic states $u_-$ and $u_+$, the long range phase
corrections (different whether $t\to -\infty$ of $t\to +\infty$) are
given by
\begin{equation}
  \label{eq:mod-phase}
  \Phi_\pm(t,x):=\mp \left| \widehat{u}_\pm\left( \frac{x}{t}
  \right)\right|^2 \log |t|.
\end{equation}
As proven initially in \cite{Ozawa91},  given $u_-$ (sufficiently
smooth, localised, and small), there exists a unique solution $u$ to
\eqref{eq:nls} such that   
\begin{equation*}
  u(t,x)\Eq t {-\infty} e^{i\Phi_-(t,x)}U_0(t)u_-(x)\Eq t {-\infty}
  e^{i\Phi_-(t,x)+i\frac{x^2}{2t}} \frac{1}{(it)^{1/2}}\widehat 
  u_-\(\frac{x}{t}\).
\end{equation*}
Note
that the phase modification $\Phi_-$ is by no means negligible 
as $t\to -\infty$: it encodes long range effects. The above mentionned
smallness assumption was removed very recently, in \cite{KM-p}, under
various (limited) smoothness assumptions. 
\smallbreak

The modified asymptotic completeness is similar. As proven initially
in \cite{HN98}, given $u_0$
(sufficiently smooth, localised, and small), there exists $u_+$ such
that the solution $u$ to 
\eqref{eq:cubic1D} with $u_{\mid t=0}=u_0$ satisfies
\begin{equation*}
  u(t)\Eq t {+\infty} e^{i\Phi_+(t)}U_0(t)u_+.
\end{equation*}
We note that the argument in the proof of \cite[Theorem~1.2]{HN98}
(see also \cite{KatoPusateri2011}) goes as follows:
\begin{itemize}
\item First, it is proven that, setting $f(t)  = U_0(-t)u(t)$, there
  exists $W\in L^\infty\cap L^2$ and $\beta>0$ such that
  \begin{equation*}
    \widehat f(t)\exp\( -i\int_1^t |\widehat u(s)|^2\frac{ds}{s}\)-
    W=\O\(t^{-\beta}\)\quad\text{as }t\to \infty, \text{ in }L^2\cap L^\infty.
  \end{equation*}
\item Then, it is established that there exists $\varphi\in L^\infty$
  such that
  \begin{equation*}
    \int_1^t |\widehat u(s)|^2\frac{ds}{s} - |W|^2\log t 
     -\varphi=\O\(t^{-\beta}\),\quad\text{in } L^\infty.
   \end{equation*}
\item In view of these two results,
one infers (using a refined version of Lemma~\ref{lem:tsutsumi}),
\begin{equation*}
  u(t,x)=\frac{1}{(it)^{1/2}}W\(\frac{x}{t}\) \exp\(
  i\frac{x^2}{2t} -i \left|W\(\frac{x}{t}\)\right|^2\log t
  -i\varphi\(\frac{x}{t}\)\)+\rho(t,x), 
\end{equation*}
with
\begin{equation*}
  \|\rho(t)\|_{L^2}=\O\(t^{-\beta}\),\quad
   \|\rho(t)\|_{L^\infty}=\O\(t^{-1/2-\beta}\).
\end{equation*}
\end{itemize}
In particular, Lemma~\ref{lem:tsutsumi} shows that the modified
asymptotic state $u_+$ is given by 
$\widehat u_+ = W e^{-i\varphi}$. We emphasise the fact that in the
argument from \cite{HN98} (or \cite{KatoPusateri2011}), the rate $\beta$ may depend on the size of
$u_0$.
%\begin{remark}
%  Proceeding like for the proof of \eqref{eq:center}, the identity
%  \begin{equation*}
%    \frac{d}{dt}\overline x(t) = P
%  \end{equation*}
%  remains true (scattering is not used at this step), so $z(t)\equiv
%  \overline x(0)$ still holds. On the other hand, formally,
%  \begin{equation*}
%    z(t)= \<xU_0(-t)u(t),U_0(-t)u(t)\>\Eq t {\pm\infty} \int_\R x\left|
%      \F^{-1} \(\widehat u_\pm e^{i\Phi_\pm(t)}\)(x)\right|^2dx,
%  \end{equation*}
%  and the last expression does not seem obvious to simplify, due to
%  the long range phase modification. 
%\end{remark}
\smallbreak

When using the lens transform, a feature of the cubic one-dimensional
case is that the cosine factor in the nonlinearity in
\eqref{eq:nlsharmo-gen} ceases to be integrable near $t=\pm
\pi/2$. Indeed, as the result by Barab \cite{Barab} evoked in the
introduction shows that one cannot have $u(t)\sim U_0(t)u_-$ as $t\to
-\infty$, unless $u=u_-\equiv 0$, Lemma~\ref{lem:waveharmo}
suggests that $v$ may indeed have some singularity as $t\to \pm
\pi/2$. This is consistent with the fact that a nontrivial phase shift
$\Phi_\pm$ must be introduced in order to define the modified
scattering theory in this case. 
\smallbreak

In view of the construction of $u_+$ described above, and of
Lemma~\ref{lem:waveharmo}, when dealing
with \eqref{eq:nlsharmo-gen} in the case $d=\si=1$, it is rather
natural to first consider 
\begin{equation*}
  w(t,x) = v(t,x) \exp \( i\int_0^t |v(s,x)|^2 \frac{ds}{\cos s}\).
\end{equation*}
Indeed, in view of \eqref{eq:lens},
Lemma~\ref{lem:tsutsumi},  and the construction of the modified
scattering operator, we have
\begin{align*}
 \int_0^t |v(s,x)|^2 \frac{ds}{\cos s}&\Eq t {\frac{\pi}{2}} \int_0^t
 |\widehat u_+(x)|^2 \frac{ds}{\cos s}\Eq t {\frac{\pi}{2}} |\widehat
                                       u_+(x)|^2\log\(\frac{\pi}{2}-t\)\\
&\Eq t {\frac{\pi}{2}} |\widehat u_+(x)|^2\log \tan t,
\end{align*}
as well as 
\begin{equation}\label{eq:v-long}
  v(t,x)\Eq t {\frac{\pi}{2}}\widehat u_+(x) e^{ -i |\widehat
  u_+(x)|^2 \log \tan t},
\end{equation}
which confirms the fact that $v$ is singular as $t\to \pi/2$, but
$w$ is not,
\begin{equation*}
  w(t,x)\Tend t {\frac{\pi}{2}}\widehat u_+(x).
\end{equation*}
We also check that $w$ solves
\begin{equation*}
  i\d_t w = \( Hv\) \exp \( i\int_0^t |v(s,x)|^2 \frac{ds}{\cos
    s}\)= \( Hv\) \exp \( i\int_0^t |w(s,x)|^2 \frac{ds}{\cos
    s}\),
\end{equation*}
where $H=-\frac{1}{2}\d_x^2+\frac{x^2}{2}$. As $w$ is continuous at
$t=\pm \pi/2$, this formulation could be expected to be more tractable
numerically, and compatible with iterative process. However, due to the interaction of $w$ with $v$ in the above formulation, our current numerical approach does not directly benefit from this observation. Instead, in order to
get stable numerical simulations, we have kept $v$ as the main object
of study. 




\section{Numerical computation of the scattering operator}
\label{sec:num}
\subsection{Methodology}\label{sec:methodology} As mentioned in Section~\ref{sec:approach} we can exploit the lens transform \eqref{eq:lens} to compactify time and localise solution values in space, thus providing the basis for efficient numerical computation of the scattering operator $S$ (cf. \eqref{eq:scattering_operator}). For this we can use the following procedure:
\begin{enumerate}[(I)]
	\item For a given initial condition $u_-$ we compute the initial state $v(-\pi/2,x)$ using \eqref{eq:initial_final_identities};\label{list:ouralgo1}
	\item We propagate this initial state forward to $t_{\mathrm{lens}}=\pi/2$ using \eqref{eq:nlsharmo-gen};\label{list:ouralgo2}
	\item Finally, we compute $S(u_-):=u_+$ using \eqref{eq:initial_final_identities}.\label{list:ouralgo3}
\end{enumerate}
A natural spatial discretisation for \eqref{eq:nlsharmo-gen} is a Hermite spectral method (cf. \cite{ThCaNe2009}) with the following $L^2(\R^d)$-orthonormal basis:
\begin{align*}
\mathcal{H}_m(x)=\prod_{j=1}^d\left(\mathrm{H}_{m_j}(x_j) \mathrm{e}^{-\frac{1}{2}x_j^2}\right), \quad m\in\N^{d},
\end{align*}
where $\mathrm{H}_{m_j}$ denotes the Hermite polynomial of degree $m_j\in\N$ normalised with respect to the weight $w(x)=\exp(-x^2)$. The $\mathcal{H}_m$ are eigenfunctions of the Schr\"odinger operator with Harmonic potential, $H$, with
\begin{align}\label{eq:eigenfunction_property}
	H (\mathcal{H}_m)=\left(\frac{d}{2}+\sum_{j=1}^d m_j\right) \mathcal{H}_m,
\end{align}
thus forming a convenient basis for a splitting approach to \ref{list:ouralgo2}. Moreover, this basis allows for the direct computation of $\|\cdot\|_{\Sigma}$: introducing for $k\in \N$,
\begin{equation*}
  \Sigma^k = \left\{ f\in L^2(\R^d),\quad
    \|f\|_{\Sigma^k}:=\|f\|_{H^k(\R^d)}+ \||x|^k f\|_{L^2(\R^d)}<\infty\right\},
\end{equation*}
we have the following equivalence of norms (see e.g. \cite{BCM08,Helffer1984})
\begin{equation}\label{eqn:details_sigma_norm_in_hermite_basis}
\|f\|_{\Sigma^k}^2\sim \sum_{m\in \N^d} \lambda_m^k |\alpha_m|^2,\quad
\lambda_m = \frac{d}{2}+\sum_{j=1}^d m_j,\quad
\text{for } f(x) = \sum_{m\in \N^d} \alpha_m  \mathcal{H}_m(x).
\end{equation}
We thus expand our initial conditions in this basis
\begin{align}\label{eq:expansion_of_u-}
	u_-(x)\approx\sum_{\substack{m\in\N^d\\0\le m\le
  M-1}} \alpha_m^-\mathcal{H}_m(x), 
\end{align}
and we note that the basis $\mathcal{H}_m$ satisfies a range of useful
identities which facilitate the quick computation of Fourier
transforms and derivatives of functions of the form
\eqref{eq:expansion_of_u-}. In particular, there is a numerically
stable way of transforming between Hermite coefficients and function
values introduced by \cite{bunck09} and explained in further detail in
\cite{maierhoferwebb25} (cf. also the implementation in Julia in
\cite{QuantumTimeSteppers,FastGaussQuadrature,FastTransforms}) which
is briefly recalled for completeness in
Appendix~\ref{app:hermite_transform}. Some further identities relevant
to the computations conducted in this work are listed in
Appendix~\ref{app:hermit_identities}. As a result of these identities
and of \eqref{eq:eigenfunction_property}, this basis lends itself
naturally to the integration of \eqref{eq:nlsharmo-gen}. In order to
perform step \ref{list:ouralgo2} above, we will thus resort to
Lie-splitting of \eqref{eq:nlsharmo-gen}, by considering the following
two subproblems 
\begin{align}\label{eq:splitting}
	i\partial_t v=Hv,\quad i\partial_t v=(\cos t)^{d\sigma-2}|v|^{2\sigma}v.
\end{align}
Note that there is a second natural choice for the splitting in
\eqref{eq:splitting}, which is to combine the nonlinearity and the
harmonic potential in one subproblem and keep the Laplacian part of
the linear term separate. This second approach lends itself naturally
to a Fourier pseudospectral spatial discretisation, whereby one has to
choose an appropriate bounding box for the domain $\R^d$. In
principle, it was observed by \cite{ThCaNe2009} that the numerical
performances of both methods are comparable, but we note that in our
case it is crucial to localise dispersive effects for the reliable
numerical computation of solutions as $t\rightarrow \pm\infty$ and
thus it is natural to use \eqref{eq:splitting}. 

\subsubsection{Error analysis}\label{sec:error_analysis}

Using the identities in Appendix~\ref{app:hermit_identities}, the
Fourier transforms in steps \ref{list:ouralgo1} \& \ref{list:ouralgo3}
can be performed exactly, so the only error incurred in our method for
computing $S$ is through the spatial discretisation and the splitting
method. For the splitting part, corresponding convergence results are
already available in the literature. In particular, for
high-regularity solutions the convergence of the aforementioned
splitting method was proved by Gauckler \cite{Gauckler2011}. In later
work,  discrete Strichartz estimates were used
in \cite{Ca-p} to prove
convergence of the Lie splitting method in the low-regularity
r\'egime. For completeness we recall the main theorem from
\cite{Gauckler2011}, adapted to our current setting. Note that
\cite{Gauckler2011} is focused on the Strang splitting, but the
corresponding result for the Lie splitting employed in the present
work follows straightforwardly from a similar analysis. In the
following we denote the splitting method approximation of $v_+$ by
$v_+^{M,\tau}$, where we used $M\in \N$ Hermite modes, and where $\tau$
is the timestep. 

\begin{theorem}[From Theorem 3.4 in \cite{Gauckler2011}]\label{thm:Lie_splitting_convergence}
	Suppose for a given $v(-\pi/2,x)$ the corresponding exact solution of \eqref{eq:nlsharmo-gen} is given by $v(\pi/2,x)$ and that $s>\left\lceil\frac{d+1}{2}\right\rceil+2+\frac{2 d}{3}$ is an integer. Let $R_{s+2}=\sup _{-\pi/2 \le t \le \pi/2}\|v(t,\cdot)\|_{\Sigma^{s+2}}$. Then there exist $h_0,M_0>0$ such that the following error bound holds for step sizes $0< h \le h_0$ and number of Hermite modes $M \ge M_0$ :
	$$
		\|v(\pi/2,\,\cdot\,)-v_+^{M,\tau}\|_{L^2}\le C\left(M^{1+\frac{d}{3}-\frac{1}{2} s}+\tau\right),
	$$
	where $C$ only depends on $d, s,$ and $R_{s+2}$.
\end{theorem}
\begin{remark}
	In view of \cite{Ca-p}, the restriction on $s$ in the
        above results can be significantly weakened. By using a
        spectral cut-off, which amounts to imposing a CFL condition in
        the above method (relating $M$ with $\tau$ -- typically $M=1/\tau$
        when $d=1$), it is shown in \cite{Ca-p} that
        for $v(-\pi/2,\cdot)\in \Sigma^2$, 
        the error is again $\O(\tau)$ at time $\pi/2$. 
\end{remark}
Let us now denote the numerical solution of the scattering operator
following the above process by $u_{+}^{N,\tau}$. Then we have the
following immediate corollary: 
\begin{corollary} Suppose $s$ is as in
  Theorem~\ref{thm:Lie_splitting_convergence}, then there are
  $\tilde{M}_0,\tilde{h}_0,\tilde{C}>0$ depending only on $d,s,$ and
  $R_{s+2}$ such that  for step sizes $0< h \le h_0$ and number of
  Hermite modes $M \ge M_0$,
	\begin{align*}
	\|u_+(\,\cdot\,)-u_+^{M,\tau}\|_{L^2}\le C\left(M^{1+\frac{d}{3}-\frac{1}{2} s}+\tau\right).
\end{align*}
\end{corollary}
