	\mathcal{I}_2(u) =	\|\nabla u\|^2_{L^2},\,\,\,
	\mathcal{I}_3(u) = \IM  \int_{\R^d} \overline{u}(x)\nabla u(x)dx,\\
	\mathcal{I}_4(u) &=	\int_{\R^d} x|u(x)|^2dx.
\end{align*}
