\section{Auxiliary identities for Hermite expansions}\label{app:hermit_identities}
Here we recall a few identities for Hermite expansions which are used in the efficient implementation of our algorithm for computing the lens transform (cf. Section~\ref{sec:methodology}). For the following identities, we suppose that we have a representation of a function $f$ in the form
\begin{align*}
	f(x)=\sum_{\substack{m\in\N^d\\0\le m\le M-1}} \alpha_m\mathcal{H}_m(x).
\end{align*}
\subsection{Fourier transform}
The Fourier transform of $f$ can then be written as
\begin{align*}
	\mathcal{F}f(\xi)&=\sum_{\substack{m\in\N^d\\0\le m\le M-1}} \alpha_m\mathcal{F}\mathcal{H}_m(\xi)\\
	&=\sum_{\substack{m\in\N^d\\0\le m\le M-1}} \alpha_m(-i)^m\mathcal{H}_m(\xi),
\end{align*}
where we used the well-known expression for the Fourier transform of Hermite functions (cf. \cite[18.17.21\_3]{NIST:DLMF}).
\subsection{Differentiation}
In the interest of notational simplicity, we restrict the following to
the one dimensional case. The case $d\ge 2$ can be treated similarly by
tensor product extension. In order to compute the derivative of a
Hermite expansion, we note that the normalised Hermite polynomials are
of the form 
\begin{align*}
\mathrm{H}_{m}=\frac{1}{\sqrt{2^m\sqrt{\pi}m!}} \widetilde{\mathrm{H}}_m,
\end{align*}
where $\widetilde{\mathrm{H}}_m$ satisfies the identity
\begin{equation*}
  \frac{d}{dx}\(\widetilde{\mathrm{H}}_{m}e^{-x^2/2}\)=
  x\widetilde{\mathrm{H}}_{m}
  e^{-x^2/2}-\widetilde{\mathrm{H}}_{m+1}e^{-x^2/2},\quad  
  m\ge 0,
\end{equation*}
cf. \cite[18.9.26]{NIST:DLMF}. This leads to the identity
\begin{align*}
	f'(x)=\sum_{m\ge 0}\beta_m \mathrm{H}_m e^{-x^2/2},
\end{align*}
where $\beta_m=\gamma_m-\sqrt{2(m+1)}\alpha_{m+1}$ and $\gamma_m$ are the Hermite coefficients of $xf(x)$, i.e.
\begin{align*}
	xf(x)=\sum_{m\ge 0}\gamma_m \mathrm{H}_m e^{-x^2/2}.
\end{align*}













\section{Continuity of scattering operator with respect to
          $\sigma$}\label{app:continuity_argument_sigma} 

 In this section, we sketch an analytic explanation for
  Figure~\ref{fig:rotating_points_supercritical_regime}, in the case
  $d=1$, where we consider a slightly $L^2$-supercritical
  nonlinearity, $\si=2+\eps$, $0<\eps\ll 1$. Consider the solutions
  $v$ and $v^\eps$ corresponding to the $L^2$-critical case and this
  slightly $L^2$-supercritical case, respectively, with  possibly different data
  at $-\frac{\pi}{2}$,
\begin{equation}
\label{eq:cont-si}
\left\{
  \begin{aligned}
    &i\d_t v + \frac{1}{2}\d_x^2 v = \frac{x^2}{2}v + |v|^4v,\quad
      v_{\mid t=-\pi/2}=v_-\in \Sigma,\\
    & i\d_t v^\eps + \frac{1}{2}\d_x^2 v^\eps = \frac{x^2}{2}v^\eps +
      (\cos t)^\eps |v^\eps|^{4+2\eps}v^\eps,\quad v^\eps_{\mid
      t=-\pi/2} = v^\eps_-\in \Sigma.
  \end{aligned}
\right.
\end{equation}
Since $v^\eps_-$ will eventually be close to $v_-$ ($\not\equiv 0$), we assume
\begin{equation*}
  \sup_{\eps\in (0,1)} \|v^\eps_-\|_{\Sigma} \le 2 \|v_-\|_\Sigma.
\end{equation*}
As the nonlinearity is defocusing, we infer a uniform bound of the form
  \begin{equation*}
    \sup_{-\pi/2\le t\le \pi/2}\|v(t)\|_{\Sigma} +
  \sup_{\eps\in (0,1)}   \sup_{-\pi/2\le t\le
    \pi/2}\|v^\eps(t)\|_{\Sigma}\le C\(\|v_-\|_\Sigma\). 
  \end{equation*}
Since we are in the one-dimensional case, $H^1(\R)\hookrightarrow
  L^\infty(\R)$, and we deduce that there exists $M\ge 1$ (this lower
  bound is imposed to simplify the formulas below) such that
\begin{equation}\label{eq:M}
    \sup_{-\pi/2\le t\le \pi/2}\|v(t)\|_{L^\infty} +
  \sup_{\eps\in (0,1)}   \sup_{-\pi/2\le t\le
    \pi/2}\|v^\eps(t)\|_{L^\infty}\le M. 
  \end{equation}
We readily observe that the difference $w=v-v^\eps$ solves
  \begin{align*}
   i\d_t w+ \frac{1}{2}\d_x^2 w = \frac{x^2}{2}w +|v|^4v-(\cos t)^\eps
    |v^\eps|^{4+2\eps}v^\eps\quad ;\quad w_{\mid t=-\pi/2}=v_--v_-^\eps.
  \end{align*}
  Inserting the term $\pm (\cos t)^\eps|v|^{4+2\eps}v$,  energy
  estimate yields, for $t\in
  \left[-\frac{\pi}{2},\frac{\pi}{2}\right]$,
   \begin{align*}
    \|w(t)\|_{L^2} &\le \|w(-\pi/2)\|_{L^2}+
2 \int_{-\pi/2}^t (\cos s)^\eps \left\| |v|^{4+2\eps}v -
      |v^\eps|^{4+2\eps}v^\eps\right\|_{L^2}ds \\
&\quad +2\int_{-\pi/2}^t
    \left\||v|^4v-  (\cos s)^\eps |v|^{4+2\eps}v \right\|_{L^2}ds,
  \end{align*}
where the implicit time variable for $v$ and $v^\eps$ is $s$.
  In view of \eqref{eq:M}, for all $s\in
  \left[-\frac{\pi}{2},\frac{\pi}{2}\right]$,
  \begin{equation*}
   (\cos s)^\eps \left\| |v|^{4+2\eps}v -
      |v^\eps|^{4+2\eps}v^\eps\right\|_{L^2}\le
    CM^{4+2\eps}\|w(s)\|_{L^2}\le C M^6 \|w(s)\|_{L^2},
  \end{equation*}
for some constant $C$ uniform in $\eps\in (0,1)$. In order to apply
Gr\"onwall's lemma, we therefore focus on the source term
\begin{equation*}
  |v|^4v-  (\cos s)^\eps |v|^{4+2\eps}v = |v|^4v-  
  |v|^{4+2\eps}v + \(1 - (\cos s)^\eps\) |v|^{4+2\eps}v .
\end{equation*}
With $y\ge 0$  a placeholder for $|v|^4$, and up to changing $\eps$
with $2\eps$ to lighten notations, consider the function
\begin{equation*}
  f^\eps(y)=y-y^{1+\eps}.
\end{equation*}
This function is increasing on
$\left[0,\frac{1}{(1+\eps)^{1/\eps}}\right]$, decreasing on
  $\(\frac{1}{(1+\eps)^{1/\eps}}, +\infty\)$, and so
  \begin{equation*}
    \sup_{0\le y\le M^4}|f^\eps(y)|\le \max\( f^\eps\(
    \frac{1}{(1+\eps)^{1/\eps}}\),|f^\eps(M^4)|\),
  \end{equation*}
where we have chosen for $M$ the constant from \eqref{eq:M}. We
compute
\begin{equation*}
 f^\eps\(\frac{1}{(1+\eps)^{1/\eps}}\)=
 \frac{1}{(1+\eps)^{1/\eps}}\(1- \frac{1}{1+\eps}\) = \O(\eps),
\end{equation*}
and (since $M\ge 1$)
\begin{equation*}
  |f^\eps(M^4)|= M^{4+4\eps}-M^4 = M^4\(e^{4\eps\log M}-1\)=\O(\eps). 
\end{equation*}
We infer from \eqref{eq:M} and the conservation of the $L^2$-norm for
$v$,
\begin{align*}
  \int_{-\pi/2}^{\pi/2} \left\||v|^4v-|v|^{4+2\eps}v\right\|_{L^2}ds
& \le 
  \int_{-\pi/2}^{\pi/2}
  \left\||v|^4-|v|^{4+2\eps}\right\|_{L^\infty}\|v(s)\|_{L^2}ds \\
& \le \pi \|v_-\|_{L^2}\sup_{0\le y\le M^4} |f^{\eps/2}(y)| \le C\eps.
\end{align*}
The last part of the source term is
\begin{equation*}
  \int_{-\pi/2}^t \(1-\(\cos s\)^\eps\) \left\|
    |v|^{4+2\eps}v\right\|_{L^2}ds \le M^6 \|v_-\|_{L^2}
 \int_{-\pi/2}^{\pi/2} \(1-\(\cos s\)^\eps\) ds.
\end{equation*}
Taylor formula for the function $g(\eps) = (\cos s)^\eps$ yields, for
$s\in \(-\frac{\pi}{2},\frac{\pi}{2}\)$,
\begin{equation*}
  1- (\cos s)^\eps= g(0)-g(\eps) = -\eps \log \cos s\int_0^1 \(\cos
  s\)^{\theta\eps}d\theta \le \eps \log\frac{1}{\cos s}.
\end{equation*}
Since the right hand side is integrable on
$\(-\frac{\pi}{2},\frac{\pi}{2}\)$, we conclude
\begin{equation*}
  \int_{-\pi/2}^{\pi/2}
    \left\||v|^4v-  (\cos s)^\eps |v|^{4+2\eps}v \right\|_{L^2}ds\le C\eps,
\end{equation*}
for some constant $C$ independent of $\eps$. Invoking Gr\"onwall's lemma,
we have proved:
  \begin{proposition}\label{prop:continuity}
  There exists $C$ independent of $\eps\in (0,1)$ such that the
  solutions to \eqref{eq:cont-si} satisfy
  \begin{equation*}
    \sup_{-\pi/2\le t\le \pi/2}\|v(t)-v^\eps(t)\|_{L^2}\le
    C\|v_--v^\eps_-\|_{L^2}+ C\eps.
  \end{equation*}
  \end{proposition}
This result explains why the existence of rotating points for the
scattering operator when the nonlinearity is not $L^2$-critical is
doubtful in view of our numerical experiments. More precisely, in
Figure~\ref{fig:rotating_points_supercritical_regime}, we consider
$\si=2.01$, hence $\eps = 10^{-2}$, which corresponds to the order of
magnitude in the error observed, compared to the case $\si=2$ where
the existence of rotating points is granted analytically and validated
numerically. 



